/**
 * Funnel Visualization Component
 * Displays conversion funnel with stepped bars and metrics
 */

import React, { useState, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Users,
  UserPlus,
  Music,
  Globe,
  CreditCard,
  TrendingDown,
  TrendingUp,
  ArrowDown,
  AlertTriangle,
} from "@/lib/icons";
import { useFunnelAnalytics, calculateFunnelMetrics, type FunnelStep } from "@/hooks/admin/useFunnelAnalytics";
import { cn } from "@/lib/utils";

const STEP_ICONS: Record<string, React.ReactNode> = {
  Посетители: <Users className="h-4 w-4" />,
  Регистрация: <UserPlus className="h-4 w-4" />,
  "Первый трек": <Music className="h-4 w-4" />,
  Публикация: <Globe className="h-4 w-4" />,
  Платёж: <CreditCard className="h-4 w-4" />,
};

const TIME_RANGES = [
  { label: "7д", days: 7 },
  { label: "14д", days: 14 },
  { label: "30д", days: 30 },
  { label: "90д", days: 90 },
] as const;

interface FunnelBarProps {
  step: FunnelStep;
  maxUsers: number;
  isFirst: boolean;
  isLast: boolean;
  isBiggestDropoff: boolean;
}

function FunnelBar({ step, maxUsers, isFirst, isLast, isBiggestDropoff }: FunnelBarProps) {
  const widthPercent = maxUsers > 0 ? (step.users_count / maxUsers) * 100 : 0;

  // Color based on conversion rate
  const getBarColor = () => {
    if (isFirst) return "bg-primary";
    if (step.conversion_rate >= 70) return "bg-green-500";
    if (step.conversion_rate >= 40) return "bg-yellow-500";
    if (step.conversion_rate >= 20) return "bg-orange-500";
    return "bg-red-500";
  };

  return (
    <div className="relative">
      {/* Step header */}
      <div className="flex items-center justify-between mb-1.5 sm:mb-2 gap-2">
        <div className="flex items-center gap-1.5 sm:gap-2 min-w-0 flex-1">
          <span className="text-muted-foreground shrink-0">
            {STEP_ICONS[step.step_name] || <Users className="h-3.5 w-3.5 sm:h-4 sm:w-4" />}
          </span>
          <span className="font-medium text-xs sm:text-sm truncate">{step.step_name}</span>
          {isBiggestDropoff && !isFirst && (
            <Badge
              variant="destructive"
              className="text-[0.625rem] sm:text-xs px-1 py-0 h-4 sm:h-5 shrink-0 hidden sm:flex"
            >
              <AlertTriangle className="h-2.5 w-2.5 sm:h-3 sm:w-3 mr-0.5 sm:mr-1" />
              Макс. отток
            </Badge>
          )}
        </div>
        <div className="flex items-center gap-1.5 sm:gap-3 text-xs sm:text-sm shrink-0">
          <span className="font-semibold">{step.users_count.toLocaleString()}</span>
          {!isFirst && (
            <Badge
              variant={step.conversion_rate >= 50 ? "default" : "secondary"}
              className={cn(
                "text-[0.625rem] sm:text-xs px-1 py-0 h-4 sm:h-5",
                step.conversion_rate >= 70 && "bg-green-500/20 text-green-700 dark:text-green-400",
                step.conversion_rate < 30 && "bg-red-500/20 text-red-700 dark:text-red-400",
              )}
            >
              {step.conversion_rate}%
            </Badge>
          )}
        </div>
      </div>

      {/* Funnel bar */}
      <div className="relative h-8 sm:h-10 bg-muted/30 rounded-lg overflow-hidden">
        <div
          className={cn("h-full transition-all duration-500 rounded-lg", getBarColor())}
          style={{ width: `${Math.max(widthPercent, 2)}%` }}
        />

        {/* Pattern overlay for visual effect */}
        <div
          className="absolute inset-0 opacity-20"
          style={{
            background:
              "repeating-linear-gradient(45deg, transparent, transparent 10px, rgba(255,255,255,0.1) 10px, rgba(255,255,255,0.1) 20px)",
          }}
        />
      </div>

      {/* Dropoff indicator */}
      {!isLast && step.dropoff_rate > 0 && (
        <div className="flex items-center justify-center my-1 sm:my-2 text-[0.625rem] sm:text-xs text-muted-foreground">
          <ArrowDown className="h-2.5 w-2.5 sm:h-3 sm:w-3 mr-0.5 sm:mr-1" />
          <span className={cn(step.dropoff_rate > 50 && "text-red-500 font-medium")}>-{step.dropoff_rate}%</span>
        </div>
      )}
    </div>
  );
}

export function FunnelVisualization() {
  const [selectedRange, setSelectedRange] = useState(30);

  const endDate = useMemo(() => new Date(), []);
  const startDate = useMemo(() => new Date(Date.now() - selectedRange * 24 * 60 * 60 * 1000), [selectedRange]);

  const {
    data: steps,
    isLoading,
    error,
  } = useFunnelAnalytics({
    startDate,
    endDate,
  });

  const metrics = useMemo(() => calculateFunnelMetrics(steps || []), [steps]);

  const maxUsers = steps?.[0]?.users_count || 1;

  if (error) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <TrendingDown className="h-5 w-5" />
            Воронка конверсии
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-destructive">Ошибка загрузки данных</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="pb-3 px-3 pt-3 sm:px-6 sm:pt-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div>
            <CardTitle className="flex items-center gap-2 text-sm sm:text-base">
              <TrendingDown className="h-4 w-4 sm:h-5 sm:w-5" />
              Воронка конверсии
            </CardTitle>
            <CardDescription className="text-xs mt-1 hidden sm:block">
