/**
 * Real-time Metrics Widget
 * Displays live counters and real-time activity indicators
 */

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { useQuery } from "@tanstack/react-query";
import { fetchProfileCount } from "@/api/profiles.api";
import { fetchRealTimeMetricsRaw, subscribeToRealtimeAdminMetrics } from "@/api/analytics.api";
import { Activity, Users, Music, Zap, Radio, TrendingUp, Circle, ArrowUpRight } from "@/lib/icons";
import { motion, AnimatePresence } from "@/lib/motion";

interface RealTimeStats {
  activeUsers: number;
  generationsInProgress: number;
  recentEvents: number;
  lastEventTime: Date | null;
  eventsPerMinute: number;
  newTracksToday: number;
  newUsersToday: number;
}

export function RealTimeMetrics() {
  const { data, isLoading, refetch } = useQuery({
    queryKey: ["realtime-metrics"],
    queryFn: async (): Promise<RealTimeStats> => {
      const now = new Date();
      const oneMinuteAgo = new Date(now.getTime() - 60 * 1000);
      const fifteenMinutesAgo = new Date(now.getTime() - 15 * 60 * 1000);
      const todayStart = new Date(now.setHours(0, 0, 0, 0));

      const [raw, newUsersResult] = await Promise.all([
        fetchRealTimeMetricsRaw({ oneMinuteAgo, fifteenMinutesAgo, todayStart }),
        fetchProfileCount(),
      ]);

      const uniqueSessions = new Set(raw.activeSessions.map((e) => e.session_id).filter(Boolean));

      return {
        activeUsers: uniqueSessions.size,
        generationsInProgress: raw.generationsInProgress,
        recentEvents: raw.recentEvents.length,
        lastEventTime: raw.recentEvents[0]?.created_at ? new Date(raw.recentEvents[0].created_at) : null,
        eventsPerMinute: raw.recentEvents.length,
        newTracksToday: raw.newTracksToday,
        newUsersToday: typeof newUsersResult === "number" ? newUsersResult : 0,
      };
    },
    staleTime: 5000,
    refetchInterval: 10000, // Refetch every 10 seconds
  });

  // Pulse animation on data change. The "pulse on" transition is derived during
  // render (React's "adjust state when a value changes" pattern); the timed
  // reset is an external side-effect and stays in the effect.
  const recentEventsKey = data?.recentEvents;
  const [pulse, setPulse] = useState(false);
  const [prevRecentEventsKey, setPrevRecentEventsKey] = useState(recentEventsKey);
  if (recentEventsKey !== prevRecentEventsKey) {
    setPrevRecentEventsKey(recentEventsKey);
    if (data) {
      setPulse(true);
    }
  }
  useEffect(() => {
    if (pulse) {
      const timer = setTimeout(() => setPulse(false), 500);
      return () => clearTimeout(timer);
    }
  }, [pulse]);

  // Subscribe to realtime changes via API layer
  useEffect(() => {
    const unsubscribe = subscribeToRealtimeAdminMetrics(() => refetch());
    return () => unsubscribe();
  }, [refetch]);

  // "now" is captured once per data refresh (pure — derived from the query
  // cycle rather than calling Date.now() during render). `data` refetches every
  // 10s via refetchInterval, so this stays reasonably fresh.
  const [now, setNow] = useState(() => Date.now());
  const [prevLastEventTime, setPrevLastEventTime] = useState(data?.lastEventTime);
  if (data?.lastEventTime !== prevLastEventTime) {
    setPrevLastEventTime(data?.lastEventTime);
    setNow(Date.now());
  }

  const formatTimeSince = (date: Date | null): string => {
    if (!date) return "нет данных";
    const seconds = Math.floor((now - date.getTime()) / 1000);
    if (seconds < 5) return "только что";
    if (seconds < 60) return `${seconds} сек назад`;
    return `${Math.floor(seconds / 60)} мин назад`;
  };

  return (
    <Card className="relative overflow-hidden">
      {/* Live indicator */}
      <div className="absolute top-3 sm:top-4 right-3 sm:right-4 flex items-center gap-1.5">
        <motion.div animate={{ scale: pulse ? [1, 1.2, 1] : 1 }} transition={{ duration: 0.3 }}>
          <Circle className={`h-2 w-2 fill-green-500 ${pulse ? "animate-pulse" : ""}`} />
        </motion.div>
        <span className="text-[0.625rem] sm:text-xs text-green-500 font-medium">LIVE</span>
      </div>

      <CardHeader className="pb-2 pt-3 sm:pt-6 px-3 sm:px-6">
        <CardTitle className="text-sm sm:text-base flex items-center gap-2">
          <Radio className="h-3.5 w-3.5 sm:h-4 sm:w-4 text-primary" />
          <span className="truncate">Метрики в реальном времени</span>
        </CardTitle>
      </CardHeader>

      <CardContent className="px-3 sm:px-6 pb-3 sm:pb-6">
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-4">
          {/* Active Users */}
          <RealTimeMetricCard
            icon={Users}
            label="Активных"
            value={data?.activeUsers || 0}
            subtext="за 15 мин"
            iconColor="text-blue-500"
            isLoading={isLoading}
          />

          {/* Events per minute */}
          <RealTimeMetricCard
            icon={Zap}
            label="Событий/мин"
            value={data?.eventsPerMinute || 0}
            subtext={formatTimeSince(data?.lastEventTime ?? null)}
            iconColor="text-yellow-500"
            isLoading={isLoading}
            pulse={pulse}
          />

          {/* Generations in progress */}
          <RealTimeMetricCard
            icon={Activity}
            label="Генераций"
            value={data?.generationsInProgress || 0}
            subtext="в процессе"
            iconColor="text-purple-500"
            isLoading={isLoading}
          />

          {/* Today's stats */}
          <RealTimeMetricCard
            icon={TrendingUp}
            label="Сегодня"
            value={data?.newTracksToday || 0}
            subtext={`${data?.newUsersToday || 0} юзеров`}
            iconColor="text-green-500"
            isLoading={isLoading}
          />
        </div>

        {/* Activity indicator bar */}
        <div className="mt-3 sm:mt-4 pt-3 sm:pt-4 border-t">
          <div className="flex items-center justify-between text-[0.625rem] sm:text-xs text-muted-foreground mb-1.5 sm:mb-2">
            <span>Активность за минуту</span>
            <span>{data?.eventsPerMinute || 0}</span>
          </div>
          <div className="h-1.5 sm:h-2 bg-muted rounded-full overflow-hidden">
            <motion.div
              className="h-full bg-primary rounded-full"
              initial={{ width: 0 }}
              animate={{
                width: `${Math.min((data?.eventsPerMinute || 0) * 5, 100)}%`,
              }}
              transition={{ duration: 0.5, ease: "easeOut" }}
            />
          </div>
        </div>

        {/* Recent activity feed preview - hidden on very small screens */}
        {data && data.recentEvents > 0 && (
          <div className="mt-3 sm:mt-4 pt-3 sm:pt-4 border-t hidden xs:block">
            <div className="flex items-center gap-2">
              <AnimatePresence mode="wait">
                <motion.div
                  key={data.recentEvents}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  className="flex items-center gap-2 text-xs sm:text-sm"
                >
                  <ArrowUpRight className="h-3.5 w-3.5 sm:h-4 sm:w-4 text-green-500" />
                  <span className="text-muted-foreground">{data.recentEvents} событий за минуту</span>
                </motion.div>
              </AnimatePresence>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

interface RealTimeMetricCardProps {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  value: number;
  subtext: string;
  iconColor: string;
  isLoading: boolean;
  pulse?: boolean;
}

function RealTimeMetricCard({
  icon: Icon,
  label,
  value,
  subtext,
  iconColor,
  isLoading,
  pulse,
}: RealTimeMetricCardProps) {
  return (
    <div className="p-2 sm:p-3 rounded-lg bg-muted/50">
      <div className="flex items-center gap-1.5 sm:gap-2 mb-0.5 sm:mb-1">
        <Icon className={`h-3.5 w-3.5 sm:h-4 sm:w-4 ${iconColor}`} />
        <span className="text-[0.625rem] sm:text-xs text-muted-foreground truncate">{label}</span>
      </div>
      <motion.div animate={{ scale: pulse ? [1, 1.1, 1] : 1 }} transition={{ duration: 0.2 }}>
        <p className="text-base sm:text-xl font-bold">{isLoading ? "..." : value.toLocaleString()}</p>
      </motion.div>
      <p className="text-[0.625rem] sm:text-xs text-muted-foreground truncate">{subtext}</p>
    </div>
  );
}

/**
 * Admin Tab Selector Component
 *
 * Responsive tab selector for admin dashboard.
 * Shows dropdown on mobile, horizontal tabs on desktop.
 *
 * @module components/admin/dashboard/AdminTabSelector
 */

import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Users,
  Music,
  FolderKanban,
  ListMusic,
  Activity,
  TrendingUp,
  AlertTriangle,
  Clock,
  CheckCircle,
  XCircle,
  Shield,
  RefreshCw,
  BookOpen,
  Search,
  Play,
  Globe,
  Lock,
  Coins,
  MessageSquare,
  Eye,
  Crown,
  ChevronDown,
  Menu,
  LucideIcon,
} from "@/lib/icons";
import { ADMIN_TAB_OPTIONS, type AdminTabType } from "@/hooks/admin/useAdminDashboard";

// ============================================================================
// Icon Mapping
// ============================================================================

/**
 * Map icon names to Lucide components
 *
 * NOTE: We use a string mapping instead of storing components in the config
 * to keep the config serializable and avoid circular dependencies.
 */
const ICON_MAP: Record<string, LucideIcon> = {
  Activity,
  TrendingUp,
  Music,
  Coins,
  Users,
  AlertTriangle,
  MessageSquare,
  Crown,
  Globe,
  Clock,
};

/**
 * Get icon component by name
 */
function getIcon(iconName: string): LucideIcon {
  return ICON_MAP[iconName] || Activity;
}

// ============================================================================
// Props
// ============================================================================

interface AdminTabSelectorProps {
  /** Currently active tab */
  activeTab: AdminTabType;
  /** Callback when tab changes */
  onTabChange: (tab: AdminTabType) => void;
  /** Whether to use mobile layout (dropdown) */
  isMobile: boolean;
}

// ============================================================================
// Mobile Selector Component
// ============================================================================

/**
 * Mobile dropdown selector for tabs
 */
function MobileTabSelector({ activeTab, onTabChange }: Omit<AdminTabSelectorProps, "isMobile">) {
  const currentTab = ADMIN_TAB_OPTIONS.find((t) => t.value === activeTab);
  const CurrentIcon = currentTab ? getIcon(currentTab.iconName) : Activity;

  return (
    <Select value={activeTab} onValueChange={(value) => onTabChange(value as AdminTabType)}>
      <SelectTrigger className="w-full">
        <div className="flex items-center gap-2">
          <CurrentIcon className="h-4 w-4 flex-shrink-0" />
          <span>{currentTab?.label || "Обзор"}</span>
        </div>
      </SelectTrigger>
      <SelectContent className="max-h-[300px]">
        {ADMIN_TAB_OPTIONS.map((tab) => {
          const TabIcon = getIcon(tab.iconName);
          return (
            <SelectItem key={tab.value} value={tab.value} className="pl-2">
              <div className="flex items-center gap-2">
                <TabIcon className="h-4 w-4 flex-shrink-0" />
                <span>{tab.label}</span>
              </div>
            </SelectItem>
          );
        })}
      </SelectContent>
    </Select>
  );
}

// ============================================================================
// Desktop Tabs Component
// ============================================================================

/**
 * Desktop horizontal tabs with scroll
 */
function DesktopTabSelector({ activeTab, onTabChange }: Omit<AdminTabSelectorProps, "isMobile">) {
  return (
    <Tabs value={activeTab} onValueChange={(value) => onTabChange(value as AdminTabType)} className="space-y-4">
      <ScrollArea className="w-full">
        <TabsList className="inline-flex w-max">
          {ADMIN_TAB_OPTIONS.map((tab) => {
            const TabIcon = getIcon(tab.iconName);
            return (
              <TabsTrigger key={tab.value} value={tab.value} className="flex items-center gap-1.5">
                <TabIcon className="h-4 w-4" />
                <span className="hidden lg:inline">{tab.label}</span>
              </TabsTrigger>
            );
          })}
        </TabsList>
      </ScrollArea>
    </Tabs>
  );
}

// ============================================================================
// Main Export
// ============================================================================

/**
 * Responsive admin tab selector
 *
 * Automatically switches between mobile dropdown and desktop tabs
 * based on the isMobile prop.
 *
 * @example
 * ```tsx
 * <AdminTabSelector
 *   activeTab={dashboard.activeTab}
 *   onTabChange={dashboard.setActiveTab}
 *   isMobile={dashboard.isMobile}
 * />
 * ```
 */
export function AdminTabSelector({ activeTab, onTabChange, isMobile }: AdminTabSelectorProps) {
  if (isMobile) {
    return <MobileTabSelector activeTab={activeTab} onTabChange={onTabChange} />;
  }

  return <DesktopTabSelector activeTab={activeTab} onTabChange={onTabChange} />;
}

