/**
 * AddVocalsToReferenceDialog - Add vocals or instrumental to reference audio
 */

import { useState, useEffect } from "react";
import { UnifiedDialog } from "@/components/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Loader2, Music, Mic2, Guitar } from "@/lib/icons";
import { useAddVocalsToReference } from "@/hooks/audio-reference/useAudioReferenceGeneration";
import { toast } from "sonner";
import { logger } from "@/lib/logger";
import { ScrollArea } from "@/components/ui/scroll-area";

interface ReferenceAudio {
  id: string;
  file_name: string;
  file_url: string;
  has_vocals?: boolean | null;
  has_instrumentals?: boolean | null;
  genre?: string | null;
  mood?: string | null;
  style_description?: string | null;
}

interface AddVocalsToReferenceDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  audio: ReferenceAudio;
}

type Mode = "add_vocals" | "add_instrumental";

export function AddVocalsToReferenceDialog({ open, onOpenChange, audio }: AddVocalsToReferenceDialogProps) {
  const [mode, setMode] = useState<Mode>("add_vocals");
  const [prompt, setPrompt] = useState("");
  const [customMode, setCustomMode] = useState(false);
  const [style, setStyle] = useState(audio.style_description || audio.genre || "");
  const [title, setTitle] = useState("");

  const addVocals = useAddVocalsToReference();

  // Determine default mode based on audio type
  useEffect(() => {
    if (open) {
      // If has vocals but no instrumentals -> add instrumental
      // If has instrumentals but no vocals -> add vocals
      if (audio.has_vocals && !audio.has_instrumentals) {
        setMode("add_instrumental");
      } else if (audio.has_instrumentals && !audio.has_vocals) {
        setMode("add_vocals");
      } else {
        setMode("add_vocals"); // default
      }
      setPrompt("");
      setStyle(audio.style_description || audio.genre || "");
      setTitle("");
      setCustomMode(false);
    }
  }, [open, audio]);

  const handleSubmit = async () => {
    if (!audio.file_url) {
      toast.error("URL аудио не найден");
      return;
    }

    if (customMode && !prompt) {
      toast.error("Пожалуйста, добавьте описание");
      return;
    }

    const effectiveTitle =
      customMode && title ? title : `${audio.file_name} (${mode === "add_vocals" ? "с вокалом" : "новая аранжировка"})`;
    const effectiveStyle = customMode && style ? style : audio.style_description || audio.genre || "pop";
    const effectivePrompt =
      prompt ||
      (mode === "add_vocals"
        ? "Добавить профессиональный вокал к этому инструменталу"
        : "Создать новую профессиональную аранжировку для этого вокала");

    // Default negativeTags based on mode
    const defaultNegativeTags =
      mode === "add_vocals"
        ? "instrumental only, no vocals, karaoke, low quality"
        : "acapella, vocals only, karaoke, low quality";

    try {
      const { error } = await addVocals.mutateAsync({
        mode,
        params: {
          audioUrl: audio.file_url,
          prompt: effectivePrompt,
          customMode,
          style: effectiveStyle,
          title: effectiveTitle,
          negativeTags: defaultNegativeTags,
          referenceAudioId: audio.id,
        },
      });

      if (error) throw new Error(error.message);

      const successMessage =
        mode === "add_vocals" ? "Добавление вокала началось! 🎤" : "Создание новой аранжировки началось! 🎸";

      toast.success(successMessage, {
        description: "Новый трек появится в библиотеке через 1-3 минуты",
      });

      onOpenChange(false);
    } catch (error) {
      logger.error("Add vocals/instrumental error", { error });
      const errorMessage = error instanceof Error ? error.message : "Ошибка обработки";
      toast.error(errorMessage);
    }
  };

  const content = (
    <div className="space-y-4">
      {/* Audio info */}
      <div className="p-3 bg-primary/10 rounded-lg border border-primary/20">
        <div className="flex items-center gap-2 text-sm">
          <Music className="w-4 h-4 text-primary" />
          <span>Аудио:</span>
          <span className="font-semibold truncate">{audio.file_name}</span>
        </div>
        {(audio.has_vocals !== null || audio.has_instrumentals !== null) && (
          <div className="flex items-center gap-2 mt-1.5 text-xs text-muted-foreground">
            <span>Тип:</span>
            <span>
              {audio.has_vocals && audio.has_instrumentals
                ? "🎤 Вокал + 🎸 Инструментал"
                : audio.has_vocals
                  ? "🎤 Вокал"
                  : "🎸 Инструментал"}
            </span>
          </div>
        )}
      </div>

      {/* Mode tabs */}
      <Tabs value={mode} onValueChange={(v) => setMode(v as Mode)}>
        <TabsList className="grid w-full grid-cols-2">
          <TabsTrigger value="add_vocals" className="gap-2">
            <Mic2 className="w-4 h-4" />
            Добавить вокал
          </TabsTrigger>
          <TabsTrigger value="add_instrumental" className="gap-2">
            <Guitar className="w-4 h-4" />
            Новая аранжировка
          </TabsTrigger>
        </TabsList>
      </Tabs>

      {/* Advanced mode toggle */}
      <div className="flex items-center justify-between p-3 rounded-lg bg-muted/30">
        <Label className="text-sm">Продвинутый режим</Label>
        <Switch checked={customMode} onCheckedChange={setCustomMode} />
      </div>

      {/* Prompt */}
      <div>
        <Label className="text-sm font-medium">
          {mode === "add_vocals" ? (customMode ? "Текст песни / Описание" : "Описание вокала") : "Описание аранжировки"}
        </Label>
        <Textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder={
            mode === "add_vocals"
              ? customMode
                ? "[Verse]\nТекст первого куплета...\n\n[Chorus]\nТекст припева..."
                : "Энергичный рок вокал с мощным звучанием"
              : "Рок аранжировка с электрогитарами и мощными барабанами"
          }
          rows={customMode ? 6 : 3}
          className="mt-1.5 resize-none"
        />
      </div>

      {/* Custom mode fields */}
      {customMode && (
        <>
          <div>
            <Label className="text-sm font-medium">Название (опционально)</Label>
            <Input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Название нового трека"
              className="mt-1.5"
            />
          </div>
          <div>
            <Label className="text-sm font-medium">Стиль</Label>
            <Input
              value={style}
              onChange={(e) => setStyle(e.target.value)}
              placeholder="pop, rock, electronic..."
              className="mt-1.5"
            />
          </div>
        </>
      )}

      {/* Submit button */}
      <Button onClick={handleSubmit} disabled={addVocals.isPending} className="w-full gap-2" size="lg">
        {addVocals.isPending ? (
          <>
            <Loader2 className="w-4 h-4 animate-spin" />
            Обработка...
          </>
        ) : (
          <>
            {mode === "add_vocals" ? <Mic2 className="w-4 h-4" /> : <Guitar className="w-4 h-4" />}
            {mode === "add_vocals" ? "Добавить вокал" : "Создать аранжировку"}
          </>
        )}
      </Button>
    </div>
  );

  return (
    <UnifiedDialog
      variant="modal"
      open={open}
      onOpenChange={onOpenChange}
      title={mode === "add_vocals" ? "Добавить вокал" : "Новая аранжировка"}
      description="Создайте новый трек на основе загруженного аудио"
    >
      <ScrollArea className="max-h-[70vh]">{content}</ScrollArea>
    </UnifiedDialog>
  );
}

/**
 * Inline Reference Preview Component
 * Compact preview of active audio reference in generation form with waveform
 */

import { memo, useCallback, useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Play,
  Pause,
  X,
  Music,
  Mic,
  Cloud,
  Drum,
  Radio,
  Guitar,
  FileAudio,
  Loader2,
  ChevronDown,
  Sparkles,
} from "@/lib/icons";
import { useAudioReference } from "@/hooks/useAudioReference";
import { useReferenceAudioPlayer } from "@/hooks/audio/useReferenceAudioPlayer";
import { cn } from "@/lib/utils";
import { formatTime } from "@/lib/formatters";
import { MiniWaveform } from "./MiniWaveform";
import { ReferenceAnalysisDisplay } from "./ReferenceAnalysisDisplay";
import { ReferenceModeSelector } from "./ReferenceModeSelector";
import { ExtendRangeSelector } from "./ExtendRangeSelector";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { ReferenceManager, type ReferenceMode } from "@/services/audio-reference";

interface InlineReferencePreviewProps {
  onRemove?: () => void;
  onOpenDrawer?: () => void;
  className?: string;
  showAnalysis?: boolean;
  showModeSelector?: boolean;
}

export const InlineReferencePreview = memo(function InlineReferencePreview({
  onRemove,
  onOpenDrawer,
  className,
  showAnalysis = true,
  showModeSelector = true,
}: InlineReferencePreviewProps) {
  const { activeReference, clearActive, analysisStatus } = useAudioReference();
  // Auto-expand when mode selector is shown to let user choose cover/extend
  const [isExpanded, setIsExpanded] = useState(showModeSelector);

  const { isPlaying, currentTime, duration, isLoading, isBuffering, togglePlay, seek } = useReferenceAudioPlayer({
    audioUrl: activeReference?.audioUrl ?? null,
  });

  const handleRemove = useCallback(() => {
    clearActive();
    onRemove?.();
  }, [clearActive, onRemove]);

  const handleModeChange = useCallback(
    (newMode: ReferenceMode) => {
      if (activeReference) {
        // Auto-set continueAt to near end when switching to extend mode
        const effectiveDur = duration || activeReference.durationSeconds || 60;
        const defaultContinueAt = Math.max(5, effectiveDur - 5);

        ReferenceManager.setActive({
          ...activeReference,
          intendedMode: newMode,
          // Set continueAt when switching to extend, preserve otherwise
          continueAt: newMode === "extend" ? activeReference.continueAt || defaultContinueAt : undefined,
        });
      }
    },
    [activeReference, duration],
  );

  const handleContinueAtChange = useCallback(
    (time: number) => {
      if (activeReference) {
        ReferenceManager.setActive({
          ...activeReference,
          continueAt: time,
        });
      }
    },
    [activeReference],
  );

  // Auto-set continueAt when entering extend mode
  useEffect(() => {
    if (activeReference?.intendedMode === "extend" && !activeReference.continueAt) {
      const effectiveDur = duration || activeReference.durationSeconds || 60;
      const defaultContinueAt = Math.max(5, effectiveDur - 5);
      ReferenceManager.setActive({
        ...activeReference,
        continueAt: defaultContinueAt,
      });
    }
  }, [activeReference?.intendedMode, duration]);

  if (!activeReference) return null;

  const getSourceIcon = () => {
    switch (activeReference.source) {
      case "upload":
        return <Music className="h-3.5 w-3.5" />;
      case "record":
        return <Mic className="h-3.5 w-3.5" />;
      case "cloud":
        return <Cloud className="h-3.5 w-3.5" />;
      case "drums":
        return <Drum className="h-3.5 w-3.5" />;
      case "dj":
        return <Radio className="h-3.5 w-3.5" />;
      case "guitar":
        return <Guitar className="h-3.5 w-3.5" />;
      case "stem":
        return <Sparkles className="h-3.5 w-3.5" />;
      case "track":
        return <Music className="h-3.5 w-3.5" />;
      default:
        return <FileAudio className="h-3.5 w-3.5" />;
    }
  };

  const getModeLabel = () => {
    if (activeReference.intendedMode === "cover") return "Кавер";
    if (activeReference.intendedMode === "extend") return "Расширение";
    return "Референс";
  };

  const getModeColor = () => {
    if (activeReference.intendedMode === "cover") return "bg-purple-500/20 text-purple-700 dark:text-purple-400";
    if (activeReference.intendedMode === "extend") return "bg-blue-500/20 text-blue-700 dark:text-blue-400";
    return "bg-muted";
  };

  const hasAnalysisData =
    activeReference.analysis &&
    (activeReference.analysis.genre ||
      activeReference.analysis.bpm ||
      activeReference.analysis.mood ||
      activeReference.analysis.styleDescription);

  const effectiveDuration = duration || activeReference.durationSeconds || 0;

  return (
    <Collapsible open={isExpanded} onOpenChange={setIsExpanded}>
      <div
        className={cn(
          "flex flex-col rounded-lg border bg-card/50 backdrop-blur-sm",
          "transition-all duration-200",
          isExpanded && "ring-1 ring-primary/20",
          className,
        )}
      >
        {/* Main content */}
        <div className="flex flex-col gap-2 p-3">
          {/* Header row */}
          <div className="flex items-center gap-2">
            {/* Play/Pause button */}
            <Button
              variant="ghost"
              size="icon"
              className="h-9 w-9 shrink-0 rounded-full bg-primary/10 hover:bg-primary/20"
              onClick={togglePlay}
              disabled={isLoading}
            >
              {isLoading || isBuffering ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : isPlaying ? (
                <Pause className="h-4 w-4" />
              ) : (
                <Play className="h-4 w-4 ml-0.5" />
              )}
            </Button>

            {/* Info */}
            <div className="flex-1 min-w-0 cursor-pointer" onClick={onOpenDrawer}>
              <div className="flex items-center gap-1.5">
                {getSourceIcon()}
                <span className="text-sm font-medium truncate max-w-[160px]">{activeReference.fileName}</span>
              </div>

              <div className="flex items-center gap-1.5 mt-0.5">
                <Badge variant="secondary" className={cn("text-xs px-1.5 py-0", getModeColor())}>
                  {getModeLabel()}
                </Badge>

                {analysisStatus === "processing" && (
                  <Badge variant="outline" className="text-xs px-1.5 py-0 gap-1">
                    <Loader2 className="h-2.5 w-2.5 animate-spin" />
                    Анализ
                  </Badge>
                )}

                {activeReference.analysis?.bpm && (
                  <span className="text-xs text-muted-foreground">{activeReference.analysis.bpm} BPM</span>
                )}

                {activeReference.analysis?.genre && (
                  <span className="text-xs text-muted-foreground hidden sm:inline">
                    • {activeReference.analysis.genre}
                  </span>
                )}
              </div>
            </div>

            {/* Expand button - always show when mode selector enabled or has analysis */}
            {(showModeSelector || (showAnalysis && hasAnalysisData)) && (
              <CollapsibleTrigger asChild>
                <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0">
                  <ChevronDown
                    className={cn("h-4 w-4 transition-transform duration-200", isExpanded && "rotate-180")}
                  />
                </Button>
              </CollapsibleTrigger>
            )}

            {/* Remove button */}
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 shrink-0 text-muted-foreground hover:text-destructive"
              onClick={handleRemove}
            >
              <X className="h-4 w-4" />
            </Button>
          </div>

          {/* Waveform with time */}
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground w-9 text-right shrink-0 tabular-nums">
              {formatTime(currentTime)}
            </span>

            <MiniWaveform
              audioUrl={activeReference.audioUrl}
              currentTime={currentTime}
              duration={effectiveDuration}
              isPlaying={isPlaying}
              onSeek={seek}
              height={36}
              className="flex-1"
            />

            <span className="text-xs text-muted-foreground w-9 shrink-0 tabular-nums">
              {formatTime(effectiveDuration)}
            </span>
          </div>
        </div>

        {/* Expanded section with mode selector, extend range, and analysis */}
        <CollapsibleContent>
          <div className="px-3 pb-3 pt-1 border-t border-border/50 space-y-3">
            {/* Mode selector */}
            {showModeSelector && (
              <ReferenceModeSelector
                mode={activeReference.intendedMode || "reference"}
                onModeChange={handleModeChange}
                compact={false}
              />
            )}

            {/* Extend range selector - only show in extend mode */}
            {activeReference.intendedMode === "extend" && effectiveDuration > 0 && (
              <ExtendRangeSelector
                audioUrl={activeReference.audioUrl}
                duration={effectiveDuration}
                continueAt={activeReference.continueAt || Math.max(5, effectiveDuration - 5)}
                onContinueAtChange={handleContinueAtChange}
                minTime={5}
                height={48}
              />
            )}

            {/* Analysis */}
            {showAnalysis && hasAnalysisData && (
              <ReferenceAnalysisDisplay analysis={activeReference.analysis} status={analysisStatus} compact />
            )}
          </div>
        </CollapsibleContent>
      </div>
    </Collapsible>
  );
});

