/**
 * GenerationLoadingState Component
 *
 * Enhanced loading state with visual feedback during music generation.
 * Features:
 * - Animated progress stages
 * - Estimated time remaining
 * - Cancellation support
 * - Visual progress indicators
 */

import { memo, useState, useEffect } from "react";
import { motion, AnimatePresence } from "@/lib/motion";
import { Loader2, Music, Sparkles, CheckCircle2, XCircle, AlertCircle, RefreshCw } from "@/lib/icons";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import { formatTime } from "@/lib/formatters";
import { useReducedMotion } from "@/hooks/useReducedMotion";

interface GenerationStage {
  id: string;
  label: string;
  icon: typeof Music;
  duration: number; // estimated duration in seconds
}

const GENERATION_STAGES: GenerationStage[] = [
  { id: "queue", label: "В очереди", icon: Loader2, duration: 5 },
  { id: "processing", label: "Обдумывание", icon: Sparkles, duration: 30 },
  { id: "generating", label: "Композиция", icon: Music, duration: 45 },
  { id: "finalizing", label: "Финальный микс", icon: CheckCircle2, duration: 10 },
];


interface GenerationLoadingStateProps {
  /** Current generation stage */
  stage?: "queue" | "processing" | "generating" | "finalizing" | "completed" | "failed";
  /** Optional custom progress percentage (0-100) */
  progress?: number;
  /** Callback when user clicks cancel */
  onCancel?: () => void;
  /** Show cancel button */
  showCancel?: boolean;
  /** Custom message (shown as secondary text) */
  message?: string;
  /** Error description shown when stage="failed" */
  errorMessage?: string;
  /** Callback when user clicks retry after failure */
  onRetry?: () => void;
  /** Compact mode for inline display */
  compact?: boolean;
}

export function GenerationLoadingState({
  stage = "queue",
  progress: customProgress,
  onCancel,
  showCancel = true,
  message,
  errorMessage = "Произошла ошибка при генерации",
  onRetry,
  compact = false,
}: GenerationLoadingStateProps) {
  const [elapsedTime, setElapsedTime] = useState(0);
  const [estimatedTotal, setEstimatedTotal] = useState(90);
  const reducedMotion = useReducedMotion();

  // Full-run estimate across all stages so the bar advances В очереди → Финализация.

  useEffect(() => {
    const total = GENERATION_STAGES.reduce((sum, s) => sum + s.duration, 0);
    setEstimatedTotal(total);

    // Update elapsed time every second
    const interval = setInterval(() => {
      setElapsedTime((prev) => {
        if (prev >= total) return total;
        return prev + 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [stage]);

  // Calculate progress percentage
  const progressPercentage = customProgress ?? (elapsedTime / estimatedTotal) * 100;
  const remainingSeconds = Math.max(0, estimatedTotal - elapsedTime);

  const formatRemainingTime = (seconds: number) => {
    if (seconds >= 60) {
      return formatTime(seconds);
    }
    return `${Math.floor(seconds)}с`;
  };

  // Advance the visible stage with progress. Callers (GenerateSheet) hold `stage`
  // fixed at "processing" for the whole run, so derive the display stage from the
  // elapsed-time estimate rather than the static prop.
  // ponytail: thresholds track GENERATION_STAGES durations; replace with real
  // clip-based progress (useGenerationTaskProgress) when GenerateSheet wires currentTaskId through.
  const displayStageIndex =
    stage === "completed"
      ? GENERATION_STAGES.length - 1
      : progressPercentage < 8
        ? 0
        : progressPercentage < 45
          ? 1
          : progressPercentage < 90
            ? 2
            : 3;
  const currentStage = GENERATION_STAGES[displayStageIndex];
  const StageIcon = currentStage?.icon || Loader2;

  if (stage === "failed") {
    if (compact) {
      return (
        <span className={cn("inline-flex items-center gap-1.5 text-sm text-destructive", compact ? "" : "")}>
          <AlertCircle className="h-3.5 w-3.5" />
          <span>{errorMessage}</span>
        </span>
      );
    }
    return (
      <Card className="p-6 space-y-4 border-destructive/30">
        <div className="flex flex-col items-center gap-4 text-center">
          <div className="w-14 h-14 rounded-full bg-destructive/10 flex items-center justify-center">
            <AlertCircle className="h-7 w-7 text-destructive" />
          </div>
          <div>
            <h3 className="font-semibold text-lg">Ошибка генерации</h3>
            <p className="text-sm text-muted-foreground mt-1">{errorMessage}</p>
          </div>
          <div className="flex gap-3 mt-2">
            {onRetry && (
              <Button onClick={onRetry} variant="outline" className="gap-2">
                <RefreshCw className="h-4 w-4" />
                Попробовать снова
              </Button>
            )}
            {showCancel && onCancel && (
              <Button onClick={onCancel} variant="ghost" className="gap-2 text-muted-foreground">
                <XCircle className="h-4 w-4" />
                Закрыть
              </Button>
            )}
          </div>
        </div>
      </Card>
    );
  }

  if (compact) {
    return (
      <div className="flex items-center gap-2 text-sm">
        <StageIcon className="h-4 w-4 animate-spin text-generate" />
        <span className="text-muted-foreground">
          {currentStage?.label || "Генерация"}
          {remainingSeconds > 0 && ` • ${formatRemainingTime(remainingSeconds)}`}
        </span>
      </div>
    );
  }

  return (
    <Card className="p-5 sm:p-6 space-y-4 max-w-full border-border/40 bg-sheet-card/60 backdrop-blur-sm">
      <AnimatePresence mode="wait">
        <motion.div
          key={stage}
          initial={reducedMotion ? undefined : { opacity: 0, y: 8 }}
          animate={reducedMotion ? undefined : { opacity: 1, y: 0 }}
          exit={reducedMotion ? undefined : { opacity: 0, y: -8 }}
          transition={reducedMotion ? undefined : { duration: 0.25 }}
          className="space-y-4"
        >
          {/* Stage indicator — calm, no ping halo */}
          <div className="flex items-center gap-3">
            <div className="relative bg-neon/10 border border-neon/30 p-2.5 rounded-full">
              <StageIcon
                className={cn("h-5 w-5 text-neon", stage !== "completed" && !reducedMotion && "animate-spin")}
                aria-hidden
              />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="font-semibold text-[0.9375rem] text-foreground leading-tight">
                {currentStage?.label || "Генерация музыки"}
              </h3>
              <p className="text-[0.6875rem] text-muted-foreground mt-0.5">
                {message ?? "Модель Suno подбирает звуки и структуру"}
              </p>
            </div>
          </div>

          {/* Progress bar */}
          <div className="space-y-1.5">
            <Progress value={progressPercentage} className="h-1.5" />
            <div className="flex justify-between text-[0.6875rem] text-muted-foreground tabular-nums">
              <span>{Math.round(progressPercentage)}%</span>
              {remainingSeconds > 0 && <span>~{formatRemainingTime(remainingSeconds)}</span>}
            </div>
          </div>


          {/* Stage timeline */}
          <div className="flex justify-between gap-1">
            {GENERATION_STAGES.map((s, index) => {
              const activeIndex = displayStageIndex;
              const isCompleted = index < activeIndex;
              const isActive = index === activeIndex;

              return (
                <motion.div
                  key={s.id}
                  className={cn(
                    "flex-1 h-1 rounded-full transition-colors",
                    isCompleted && "bg-generate",
                    isActive && "bg-generate/50",
                    !isCompleted && !isActive && "bg-muted",
                  )}
                  initial={reducedMotion ? undefined : false}
                  animate={
                    reducedMotion
                      ? undefined
                      : {
                          opacity: isCompleted ? 1 : isActive ? 0.8 : 0.3,
                        }
                  }
                />
              );
            })}
          </div>

          {/* Cancel button */}
          {showCancel && onCancel && (
            <div className="flex justify-center pt-2">
              <Button
                variant="ghost"
                size="sm"
                onClick={onCancel}
                className="text-muted-foreground hover:text-destructive focus-visible:text-destructive"
              >
                <XCircle className="h-4 w-4 mr-2" />
                Отменить
              </Button>
            </div>
          )}
        </motion.div>
      </AnimatePresence>
    </Card>
  );
}

/**
 * Compact inline loading indicator for use in buttons or small spaces
 */
export function GenerationLoadingInline({ stage = "processing", className }: { stage?: string; className?: string }) {
  const stageData = GENERATION_STAGES.find((s) => s.id === stage);
  const Icon = stageData?.icon || Loader2;

  return (
    <span className={cn("inline-flex items-center gap-1.5 text-sm", className)}>
      <Icon className="h-3.5 w-3.5 animate-spin" />
      <span>{stageData?.label || "Обработка"}</span>
    </span>
  );
}

/**
 * GenerationResultSheet Component
 *
 * Shows generation results with A/B version selection after track creation.
 * Provides immediate access to versions without navigating to library first.
 * Uses design system tokens (Spec 032)
 */

import { memo, useCallback, useState, useEffect } from "react";
import { useNavigate } from "react-router";
import { motion, AnimatePresence } from "@/lib/motion";
import { cn } from "@/lib/utils";
import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Skeleton } from "@/components/ui/skeleton";
import { Play, Pause, Mic, Loader2 } from "@/lib/icons";
import { useHapticFeedback } from "@/hooks/useHapticFeedback";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";
import { useVersionSwitcher } from "@/hooks/useVersionSwitcher";
import { useTrackVersionsList } from "@/hooks/generation/useTrackVersionsList";
import { useSunoPersona } from "@/hooks/studio/useSunoPersona";
import { toast } from "sonner";
import { logger } from "@/lib/logger";
import { useMashupStrings } from "@/hooks/useMashupStrings";

interface TrackVersion {
  id: string;
  label: string;
  audioUrl: string;
  duration?: number;
  isPrimary: boolean;
}

interface GenerationResultSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  trackId: string | null;
  trackTitle?: string;
}

export const GenerationResultSheet = memo(function GenerationResultSheet({
  open,
  onOpenChange,
  trackId,
  trackTitle,
}: GenerationResultSheetProps) {
  const navigate = useNavigate();
  const haptic = useHapticFeedback();
  const { activeTrack, isPlaying, playTrack, pauseTrack } = usePlayerStore();

  const [selectedVersion, setSelectedVersion] = useState<string | null>(null);
  const [playingVersionId, setPlayingVersionId] = useState<string | null>(null);
  const [settingPrimary, setSettingPrimary] = useState(false);
  // Sprint 052-B5 — Suno Persona training from a freshly generated track.
  const [personaDialogOpen, setPersonaDialogOpen] = useState(false);
  const [personaName, setPersonaName] = useState("");
  const [personaDescription, setPersonaDescription] = useState("");
  const { setPrimaryVersionAsync } = useVersionSwitcher();
  const personaMutation = useSunoPersona();
  const { data: versions = [], isLoading: loading } = useTrackVersionsList({
    trackId,
    enabled: open,
  });

  // Reset selection when versions change
  useEffect(() => {
    if (!open || !trackId) {
      setSelectedVersion(null);
      return;
    }
    const primary = versions.find((v) => v.isPrimary);
    if (primary) {
      setSelectedVersion(primary.id);
    } else if (versions.length > 0 && !selectedVersion) {
      setSelectedVersion(versions[0].id);
    }
  }, [open, trackId, versions, selectedVersion]);

  // Sprint 052-B5 — kick off Persona training. Track must have at least one
  // ready version (selectedVersionData has an audioUrl below — we check
  // against that when the user actually clicks "Train Persona").
  const t = useMashupStrings();
  const personaStrings = t.persona;
  const generationResultStrings = t.generationResult;

  const handleTrainPersona = useCallback(async () => {
    if (!trackId) return;
    const trimmed = personaName.trim();
    if (!trimmed) {
      toast.error(personaStrings.validation.specifyName);
      return;
    }
    if (trimmed.length > 80) {
      toast.error(personaStrings.validation.nameTooLong);
      return;
    }
    try {
      const result = await personaMutation.mutateAsync({
        trackId,
        name: trimmed,
        description: personaDescription.trim() || undefined,
      });
      logger.info("train_persona", { personaId: result.personaId, status: result.status });
      toast.success(personaStrings.successToastPending, {
        description:
          result.status === "pending"
            ? "Suno готовит персону — обычно 1-2 минуты. Мы сообщим, когда она будет готова."
            : personaStrings.successToastReady,
      });
      setPersonaDialogOpen(false);
      setPersonaName("");
      setPersonaDescription("");
    } catch (err) {
      logger.error("train_persona_failed", { err });
      toast.error(personaStrings.validation.trainingFailed);
    }
  }, [
    trackId,
    personaName,
    personaDescription,
    personaMutation,
    personaStrings.successToastPending,
    personaStrings.successToastReady,
    personaStrings.validation.specifyName,
    personaStrings.validation.nameTooLong,
    personaStrings.validation.trainingFailed,
  ]);

  // Handle version preview (play/pause)
  const handlePreview = useCallback(
    (version: TrackVersion) => {
      haptic.tap();

      if (playingVersionId === version.id && isPlaying) {
        pauseTrack();
        setPlayingVersionId(null);
      } else {
        // Create a minimal track object for playback - cast to Track for player compatibility
        playTrack({
          id: trackId!,
          title: trackTitle || generationResultStrings.fallbackTrackTitle,
          audio_url: version.audioUrl,
          cover_url: null,
          user_id: "",
          created_at: new Date().toISOString(),
          is_liked: false,
          likes_count: 0,
        } as never);
        setPlayingVersionId(version.id);
      }
    },
    [
      playingVersionId,
      isPlaying,
      pauseTrack,
      playTrack,
      trackId,
      trackTitle,
      haptic,
      generationResultStrings.fallbackTrackTitle,
    ],
  );

  // Handle version selection
  const handleSelect = useCallback(
    (versionId: string) => {
      haptic.select();
      setSelectedVersion(versionId);
    },
    [haptic],
  );

  // Set selected version as primary
  const handleSetPrimary = useCallback(async () => {
    if (!selectedVersion || !trackId) return;

    haptic.impact("medium");
    setSettingPrimary(true);

    try {
      await setPrimaryVersionAsync({ trackId, versionId: selectedVersion });
    } catch (error) {
      logger.error("Failed to set primary version", error);
      toast.error(generationResultStrings.versionSwitchError);
    } finally {
      setSettingPrimary(false);
    }
  }, [selectedVersion, trackId, haptic, generationResultStrings.versionSwitchError, setPrimaryVersionAsync]);

  // Navigate to studio
  const handleGoToStudio = useCallback(() => {
    haptic.impact("medium");
    pauseTrack();
    onOpenChange(false);
    navigate(`/studio-v2?trackId=${trackId}`);
  }, [trackId, navigate, onOpenChange, pauseTrack, haptic]);

  // Navigate to library
  const handleGoToLibrary = useCallback(() => {
    haptic.tap();
    pauseTrack();
    onOpenChange(false);
    navigate(`/library?track=${trackId}`);
  }, [trackId, navigate, onOpenChange, pauseTrack, haptic]);

  const selectedVersionData = versions.find((v) => v.id === selectedVersion);
  const hasMultipleVersions = versions.length > 1;

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className={cn(
          "h-auto max-h-[85dvh] flex flex-col p-0 overflow-hidden",
          "bg-background text-foreground border-t border-border/60",
        )}
        hideCloseButton={false}
      >
        <SheetTitle className="sr-only">Результат генерации</SheetTitle>

        {/* Masthead — editorial header */}
        <header className="px-6 pt-7 pb-5 border-b border-border/40">
          <div className="flex items-baseline justify-between gap-4">
            <p className="font-mono text-xs text-muted-foreground">
              {hasMultipleVersions
                ? `№ 001 · ${String(versions.length).padStart(2, "0")} takes`
                : "№ 001 · single take"}
            </p>
            <p className="font-mono text-xs text-muted-foreground">
              {new Date().toLocaleDateString("ru-RU", { day: "2-digit", month: "short" })}
            </p>
          </div>
          <h2 className="mt-3 font-display text-display-2 leading-[0.95] tracking-tight truncate">
            {trackTitle || "Untitled"}
          </h2>
          <p className="mt-2 font-mono text-xs text-muted-foreground">
            {hasMultipleVersions ? "A / B · choose your take" : "ready to ship"}
          </p>
        </header>

        {/* Versions — magazine spread */}
        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="px-6 py-8 space-y-6">
              <Skeleton className="h-24 w-full rounded-none" />
              <Skeleton className="h-24 w-full rounded-none" />
            </div>
          ) : (
            <ol className="divide-y divide-border/30">
              <AnimatePresence initial={false} mode="popLayout">
                {versions.map((version, index) => {
                  const isSelected = version.id === selectedVersion;
                  const isCurrentlyPlaying = playingVersionId === version.id && isPlaying;
                  const totalLabel = versions.length;
                  const durMin = Math.floor((version.duration ?? 0) / 60);
                  const durSec = String(Math.floor((version.duration ?? 0) % 60)).padStart(2, "0");

                  return (
                    <motion.li
                      key={version.id}
                      initial={{ opacity: 0, clipPath: "inset(0 100% 0 0)" }}
                      animate={{ opacity: 1, clipPath: "inset(0 0% 0 0)" }}
                      exit={{ opacity: 0, clipPath: "inset(0 0 0 100%)" }}
                      transition={{ delay: index * 0.12, duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
                      className={cn(
                        "relative cursor-pointer transition-colors",
                        "hover:bg-foreground/[0.02]",
                        isSelected && "bg-foreground/[0.03]",
                      )}
                      onClick={() => handleSelect(version.id)}
                    >
                      <span
                        aria-hidden
                        className={cn(
                          "absolute left-0 top-0 bottom-0 w-[2px] transition-opacity duration-300",
                          isSelected ? "bg-primary opacity-100" : "opacity-0",
                        )}
                      />

                      <div className="grid grid-cols-[auto_1fr_auto] items-center gap-5 px-6 py-6">
                        {/* Big letter — Unbounded */}
                        <div className="flex items-baseline gap-2">
                          <span className="font-mono text-xs text-muted-foreground">
                            {String(index + 1).padStart(2, "0")}/{String(totalLabel).padStart(2, "0")}
                          </span>
                          <span
                            className={cn(
                              "font-display leading-[0.85] tabular-nums",
                              "text-[4rem] sm:text-[4.5rem]",
                              isSelected ? "text-foreground" : "text-foreground/70",
                            )}
                          >
                            {version.label}
                          </span>
                        </div>

                        {/* Centre column — metadata + status */}
                        <div className="flex flex-col gap-1.5 min-w-0">
                          <div className="flex items-center gap-3 font-mono text-xs text-muted-foreground">
                            <span>Stereo</span>
                            <span aria-hidden>·</span>
                            <span>44.1 kHz</span>
                            <span aria-hidden>·</span>
                            <span>{version.duration ? `${durMin}:${durSec}` : "—:—"}</span>
                          </div>
                          <div className="flex items-center gap-2 font-mono text-xs">
                            {version.isPrimary && <span className="text-primary">★ Master take</span>}
                            {isCurrentlyPlaying && (
                              <motion.span
                                initial={{ opacity: 0 }}
                                animate={{ opacity: [0.4, 1, 0.4] }}
                                transition={{ duration: 1.6, repeat: Infinity, ease: "easeInOut" }}
                                className="text-foreground"
                              >
                                ▮▮ playing
                              </motion.span>
                            )}
                            {!version.isPrimary && !isCurrentlyPlaying && (
                              <span className="text-muted-foreground/60">take · listen &amp; choose</span>
                            )}
                          </div>
                        </div>

                        {/* Play + select — stacked, square */}
                        <div className="flex flex-col items-end gap-3">
                          <Button
                            variant="ghost"
                            size="icon"
                            aria-label={
                              isCurrentlyPlaying
                                ? generationResultStrings.pauseButtonLabel
                                : generationResultStrings.playButtonLabel
                            }
                            className={cn(
                              "h-12 w-12 rounded-none border border-foreground/20",
                              "hover:bg-foreground hover:text-background",
                              isCurrentlyPlaying && "bg-foreground text-background border-foreground",
                            )}
                            onClick={(e) => {
                              e.stopPropagation();
                              handlePreview(version);
                            }}
                          >
                            {isCurrentlyPlaying ? (
                              <Pause className="h-5 w-5" />
                            ) : (
                              <Play className="h-5 w-5 translate-x-[1px]" />
                            )}
                          </Button>
                          <span
                            className={cn(
                              "font-mono text-[0.625rem] transition-colors",
                              isSelected ? "text-foreground" : "text-muted-foreground/40",
                            )}
                          >
                            {isSelected ? "✓ chosen" : "select"}
                          </span>
                        </div>
                      </div>

                      {isCurrentlyPlaying && (
                        <motion.div
                          initial={{ opacity: 0, height: 0 }}
                          animate={{ opacity: 1, height: "auto" }}
                          exit={{ opacity: 0, height: 0 }}
                          className="overflow-hidden"
                        >
                          <div className="px-6 pb-5 flex items-end gap-[3px] h-10">
                            {Array.from({ length: 48 }).map((_, i) => (
                              <motion.span
                                key={i}
                                className="w-[2px] bg-foreground/70 block"
                                animate={{
                                  height: [`${20 + Math.sin(i * 0.7) * 12}%`, `${20 + Math.sin(i * 0.7 + 1) * 12}%`],
                                }}
                                transition={{
                                  duration: 0.8 + (i % 5) * 0.1,
                                  repeat: Infinity,
                                  repeatType: "reverse",
                                  delay: i * 0.02,
                                }}
                                style={{ height: "20%" }}
                              />
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </motion.li>
                  );
                })}
              </AnimatePresence>
            </ol>
          )}
        </div>

        {/* Colophon — footer */}
        <footer className="border-t border-border/60 px-6 pt-5 pb-[calc(1.25rem+var(--safe-area-inset-bottom,0px))] space-y-5 bg-background">
          {hasMultipleVersions && selectedVersionData && !selectedVersionData.isPrimary && (
            <button
              type="button"
              onClick={handleSetPrimary}
              disabled={settingPrimary}
              className={cn(
                "group w-full text-left",
                "flex items-baseline justify-between gap-4",
                "py-3 border-b border-foreground/30 hover:border-primary",
                "transition-colors",
              )}
            >
              <span className="font-mono text-xs text-muted-foreground">
                {settingPrimary ? "saving…" : "promote to master"}
              </span>
              <span className="font-display text-heading-3 text-foreground">Version {selectedVersionData.label} →</span>
            </button>
          )}

          <div className="grid grid-cols-3 gap-px bg-border/60 border border-border/60">
            <button
              type="button"
              onClick={handleGoToLibrary}
              className={cn(
                "group flex flex-col items-start gap-1 bg-background px-4 py-4 text-left",
                "hover:bg-foreground/[0.03] transition-colors",
              )}
            >
              <span className="font-mono text-xs text-muted-foreground">archive</span>
              <span className="font-display text-heading-3 text-foreground">Library →</span>
            </button>
            <button
              type="button"
              onClick={handleGoToStudio}
              className={cn(
                "group flex flex-col items-start gap-1 bg-background px-4 py-4 text-left",
                "hover:bg-foreground hover:text-background transition-colors",
              )}
            >
              <span className="font-mono text-xs text-muted-foreground group-hover:text-background/70">open</span>
              <span className="font-display text-heading-3">Studio →</span>
            </button>
            <button
              type="button"
              onClick={() => setPersonaDialogOpen(true)}
              disabled={!trackId}
              className={cn(
                "group flex flex-col items-start gap-1 bg-background px-4 py-4 text-left",
                "hover:bg-foreground hover:text-background transition-colors",
                !trackId && "opacity-50 cursor-not-allowed",
              )}
            >
              <span className="font-mono text-xs text-muted-foreground group-hover:text-background/70">voice</span>
              <span className="font-display text-heading-3 flex items-center gap-2">
                <Mic className="w-4 h-4" />
                Persona
              </span>
            </button>
          </div>

          <p className="font-mono text-xs text-muted-foreground/70">
            stems · mix · arrange · master · persona — all in studio
          </p>
        </footer>
      </SheetContent>

      {/* Sprint 052-B5 — Train Persona dialog. */}
      <Dialog open={personaDialogOpen} onOpenChange={setPersonaDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Mic className="w-5 h-5 text-primary" />
              {personaStrings.dialogTitle}
            </DialogTitle>
            <DialogDescription>{personaStrings.dialogDescription}</DialogDescription>
          </DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="text-sm">{personaStrings.nameLabel}</Label>
              <Input
                value={personaName}
                onChange={(e) => setPersonaName(e.target.value)}
                placeholder={personaStrings.namePlaceholder}
                maxLength={80}
                className="mt-1.5"
                autoFocus
              />
            </div>
            <div>
              <Label className="text-sm">{personaStrings.descriptionLabel}</Label>
              <Input
                value={personaDescription}
                onChange={(e) => setPersonaDescription(e.target.value)}
                placeholder={personaStrings.descriptionPlaceholder}
                maxLength={500}
                className="mt-1.5"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="ghost" onClick={() => setPersonaDialogOpen(false)} disabled={personaMutation.isPending}>
              {personaStrings.cancel}
            </Button>
            <Button onClick={handleTrainPersona} disabled={personaMutation.isPending || !personaName.trim()}>
              {personaMutation.isPending ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin mr-2" />
                  {personaStrings.submitting}
                </>
              ) : (
                personaStrings.submit
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Sheet>
  );
});

