/**
 * GuitarModeRecorder - Recording with realtime chord detection
 * Shows chords in real-time during microphone recording
 */

import { useState, useRef, useEffect, useCallback, useId } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Mic, MicOff, Guitar, Music, Waves, Copy, Check, Play, Pause, Trash2, Sparkles } from "@/lib/icons";
import { useRealtimeChordDetection } from "@/hooks/useRealtimeChordDetection";
import { ChordDiagram } from "@/components/guitar/ChordDiagram";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "@/lib/motion";
import { toast } from "sonner";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";
import { registerStudioAudio, unregisterStudioAudio, pauseAllStudioAudio } from "@/hooks/studio/useStudioAudio";

type UseMode = "style" | "audio";

interface GuitarModeRecorderProps {
  onRecordingComplete: (data: {
    audioFile: File;
    audioUrl: string;
    chordProgression: string[];
    styleDescription: string;
    useMode: UseMode; // 'style' = use description as prompt, 'audio' = use as audio reference
  }) => void;
  onCancel: () => void;
}

export function GuitarModeRecorder({ onRecordingComplete, onCancel }: GuitarModeRecorderProps) {
  const sourceId = useId();
  const { pauseTrack, isPlaying: globalIsPlaying } = usePlayerStore();
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const [recordedAudioUrl, setRecordedAudioUrl] = useState<string | null>(null);
  const [recordedFile, setRecordedFile] = useState<File | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [copiedProgression, setCopiedProgression] = useState(false);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  // Register for studio audio coordination
  useEffect(() => {
    const audio = audioRef.current;
    if (audio) {
      registerStudioAudio(sourceId, () => {
        audio.pause();
        setIsPlaying(false);
      });
    }
    return () => unregisterStudioAudio(sourceId);
  }, [sourceId]);

  // Pause if global player starts
  useEffect(() => {
    if (globalIsPlaying && isPlaying) {
      audioRef.current?.pause();
      setIsPlaying(false);
    }
  }, [globalIsPlaying, isPlaying]);

  const {
    currentChord,
    chordHistory,
    chromagram,
    isListening,
    isInitializing,
    volume,
    startListening,
    stopListening,
    clearHistory,
    exportProgression,
  } = useRealtimeChordDetection({
    minConfidence: 0.5,
    stabilityFrames: 2,
    maxHistory: 30,
  });

  // Generate style description from chord progression
  const generateStyleDescription = useCallback(() => {
    if (chordHistory.length === 0) return "";

    const uniqueChords = [...new Set(chordHistory.map((c) => c.name))];
    const hasMinorChords = uniqueChords.some((c) => c.includes("m") && !c.includes("maj"));
    const hasMajorChords = uniqueChords.some((c) => !c.includes("m") || c.includes("maj"));
    const has7thChords = uniqueChords.some((c) => c.includes("7"));
    const hasSus = uniqueChords.some((c) => c.includes("sus"));

    const characteristics: string[] = [];

    if (hasMinorChords && hasMajorChords) {
      characteristics.push("mixed major/minor tonality");
    } else if (hasMinorChords) {
      characteristics.push("minor key, melancholic");
    } else if (hasMajorChords) {
      characteristics.push("major key, uplifting");
    }

    if (has7thChords) {
      characteristics.push("jazzy, sophisticated harmony");
    }

    if (hasSus) {
      characteristics.push("suspended chords, atmospheric");
    }

    const progression = uniqueChords.slice(0, 4).join(" - ");

    return `Acoustic guitar, ${characteristics.join(", ")}. Chord progression: ${progression}`;
  }, [chordHistory]);

  // Start recording with chord detection
  const handleStartRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: false,
          noiseSuppression: false,
          autoGainControl: false,
          sampleRate: 44100,
        },
      });

      streamRef.current = stream;

      const mimeType = MediaRecorder.isTypeSupported("audio/webm;codecs=opus") ? "audio/webm;codecs=opus" : "audio/mp4";

      const mediaRecorder = new MediaRecorder(stream, { mimeType });
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: mimeType });
        const ext = mimeType.includes("webm") ? "webm" : "mp4";
        const file = new File([blob], `guitar-${Date.now()}.${ext}`, { type: mimeType });
        const url = URL.createObjectURL(blob);

        setRecordedFile(file);
        setRecordedAudioUrl(url);
      };

      mediaRecorder.start(1000);
      setIsRecording(true);
      setRecordingDuration(0);
      clearHistory();

      // Start chord detection
      await startListening();

      // Start timer
      timerRef.current = window.setInterval(() => {
        setRecordingDuration((d) => d + 1);
      }, 1000);
    } catch (error) {
      toast.error("Не удалось получить доступ к микрофону");
    }
  };

  // Stop recording
  const handleStopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      streamRef.current?.getTracks().forEach((t) => t.stop());
      setIsRecording(false);
      stopListening();

      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }
  };

  // Clear recording
  const handleClear = () => {
    if (recordedAudioUrl) {
      URL.revokeObjectURL(recordedAudioUrl);
    }
    setRecordedFile(null);
    setRecordedAudioUrl(null);
    setRecordingDuration(0);
    clearHistory();
  };

  // Toggle playback
  const handleTogglePlayback = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
      setIsPlaying(false);
    } else {
      pauseTrack();
      pauseAllStudioAudio(sourceId);
      audioRef.current.play();
      setIsPlaying(true);
    }
  };

  // Copy progression
  const handleCopyProgression = () => {
    const progression = exportProgression();
    navigator.clipboard.writeText(progression);
    setCopiedProgression(true);
    setTimeout(() => setCopiedProgression(false), 2000);
    toast.success("Прогрессия скопирована");
  };

  // Complete and pass data with selected mode
  const handleComplete = (mode: UseMode) => {
    if (recordedFile && recordedAudioUrl) {
      onRecordingComplete({
        audioFile: recordedFile,
        audioUrl: recordedAudioUrl,
        chordProgression: chordHistory.map((c) => c.name),
        styleDescription: generateStyleDescription(),
        useMode: mode,
      });
    }
  };

  // Cleanup
  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (recordedAudioUrl) URL.revokeObjectURL(recordedAudioUrl);
      stopListening();
    };
  }, []);

  const formatDuration = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  // Note labels for chromagram
  const NOTE_LABELS = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];

  return (
    <div className="space-y-3">
      {/* Recording State */}
      {!recordedAudioUrl ? (
        <div className="space-y-3">
          {/* Main Recording Button - Compact for mobile */}
          <Card
            className={cn(
              "p-4 flex flex-col items-center justify-center gap-3 transition-all",
              isRecording && "bg-destructive/10 border-destructive",
            )}
          >
            <div className="relative">
              <motion.div
                className={cn(
                  "w-16 h-16 sm:w-20 sm:h-20 rounded-full flex items-center justify-center",
                  isRecording
                    ? "bg-destructive"
                    : "bg-gradient-to-br from-primary/20 to-primary/5 border-2 border-primary/30",
                )}
                animate={isRecording ? { scale: [1, 1.05, 1] } : {}}
                transition={{ duration: 1.5, repeat: Infinity }}
              >
                {isRecording ? (
                  <MicOff className="w-7 h-7 sm:w-8 sm:h-8 text-destructive-foreground" />
                ) : (
                  <Guitar className="w-7 h-7 sm:w-8 sm:h-8 text-primary" />
                )}
              </motion.div>

              {/* Recording pulse */}
              {isRecording && (
                <motion.div
                  className="absolute inset-0 rounded-full border-2 border-destructive"
                  animate={{ scale: [1, 1.4], opacity: [0.5, 0] }}
                  transition={{ duration: 1.5, repeat: Infinity }}
                />
              )}
            </div>

            <div className="text-center">
              <h3 className="font-semibold">
                {isRecording ? (
                  <span className="text-destructive font-mono text-lg">{formatDuration(recordingDuration)}</span>
                ) : (
                  "Запись гитары"
                )}
              </h3>
              <p className="text-xs text-muted-foreground max-w-[200px]">
                {isRecording ? "Играйте — аккорды определяются" : "Запись с детектированием аккордов"}
              </p>
            </div>

            <Button
              size="default"
              variant={isRecording ? "destructive" : "default"}
              onClick={isRecording ? handleStopRecording : handleStartRecording}
              disabled={isInitializing}
              className="gap-2"
            >
              {isInitializing ? (
                <>Инициализация...</>
              ) : isRecording ? (
                <>
                  <MicOff className="w-4 h-4" />
                  Остановить
                </>
              ) : (
                <>
                  <Mic className="w-4 h-4" />
                  Начать запись
                </>
              )}
            </Button>
          </Card>

          {/* Realtime Chord Display - Compact for mobile */}
          {isListening && (
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-2">
              {/* Current Chord - Compact */}
              <Card className="p-3">
                <div className="flex items-center gap-3">
                  {/* Volume Indicator */}
                  <div className="w-1.5 h-12 bg-muted rounded-full overflow-hidden shrink-0">
                    <motion.div
                      className="w-full bg-primary rounded-full"
                      style={{ height: `${volume * 100}%` }}
                      animate={{ height: `${volume * 100}%` }}
                    />
                  </div>

                  {/* Current Chord Display */}
                  <div className="flex-1 text-center min-w-0">
                    <AnimatePresence mode="wait">
                      {currentChord ? (
                        <motion.div
                          key={currentChord.name}
                          initial={{ scale: 0.8, opacity: 0 }}
                          animate={{ scale: 1, opacity: 1 }}
                          exit={{ scale: 0.8, opacity: 0 }}
                        >
                          <div className="text-2xl font-bold text-primary">{currentChord.name}</div>
                          <span className="text-[0.625rem] text-muted-foreground">
                            {Math.round(currentChord.confidence * 100)}%
                          </span>
                        </motion.div>
                      ) : (
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="text-muted-foreground">
                          <Waves className="w-6 h-6 mx-auto animate-pulse" />
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>

                  {/* Chord Diagram - Hidden on very small screens */}
                  {currentChord && (
                    <div className="hidden xs:block shrink-0">
                      <ChordDiagram chord={currentChord.name} size="sm" />
                    </div>
                  )}
                </div>
              </Card>

              {/* Chromagram Visualization - Smaller */}
              <div className="flex gap-px h-6">
                {chromagram.map((value, i) => (
                  <div key={i} className="flex-1 flex flex-col items-center">
                    <div className="flex-1 w-full bg-muted rounded-sm overflow-hidden">
                      <motion.div
                        className="w-full bg-primary/70 rounded-sm"
                        style={{ height: `${value * 100}%` }}
                        animate={{ height: `${value * 100}%` }}
                        transition={{ duration: 0.05 }}
                      />
                    </div>
                  </div>
                ))}
              </div>

              {/* Chord History - Compact */}
              {chordHistory.length > 0 && (
                <div className="flex flex-wrap gap-1">
                  {chordHistory.slice(0, 8).map((chord, i) => (
                    <Badge
                      key={`${chord.name}-${i}`}
                      variant={i === 0 ? "default" : "secondary"}
                      className="text-[0.625rem] px-1.5 py-0"
                    >
                      {chord.name}
                    </Badge>
                  ))}
                  {chordHistory.length > 8 && (
                    <Badge variant="outline" className="text-[0.625rem] px-1.5 py-0">
                      +{chordHistory.length - 8}
                    </Badge>
                  )}
                </div>
              )}
            </motion.div>
          )}
        </div>
      ) : (
        /* Recorded Audio Preview - Choice between style or audio reference */
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-3">
          {/* Audio Player - Compact */}
          <Card className="p-3">
            <div className="flex items-center gap-2">
              <Button
                size="icon"
                variant={isPlaying ? "secondary" : "default"}
                onClick={handleTogglePlayback}
                className="h-10 w-10 rounded-full shrink-0"
              >
                {isPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4 ml-0.5" />}
              </Button>

              <div className="flex-1 min-w-0">
                <p className="font-medium text-sm truncate">Записано</p>
                <p className="text-xs text-muted-foreground">
                  {formatDuration(recordingDuration)} • {chordHistory.length} аккордов
                </p>
              </div>

              <Button
                size="icon"
                variant="ghost"
                onClick={handleClear}
                className="h-8 w-8 min-h-[44px] min-w-[44px] text-destructive hover:text-destructive hover:bg-destructive/10 shrink-0"
              >
                <Trash2 className="w-4 h-4" />
              </Button>
            </div>

            <audio ref={audioRef} src={recordedAudioUrl} onEnded={() => setIsPlaying(false)} className="hidden" />
          </Card>

          {/* Chord Progression - Compact */}
          {chordHistory.length > 0 && (
            <Card className="p-3 space-y-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-1.5">
                  <Music className="w-3.5 h-3.5 text-primary" />
                  <span className="font-medium text-xs">Аккорды</span>
                </div>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={handleCopyProgression}
                  className="h-6 gap-1 text-[0.625rem] px-2"
                >
                  {copiedProgression ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                </Button>
              </div>

              <div className="flex flex-wrap gap-1">
                {[...new Set(chordHistory.map((c) => c.name))].slice(0, 6).map((chord, i) => (
                  <Badge key={i} variant="secondary" className="text-[0.625rem] px-1.5 py-0">
                    {chord}
                  </Badge>
                ))}
              </div>
            </Card>
          )}

          {/* Choice: Use Style Description or Audio Reference */}
          <div className="space-y-2">
            <p className="text-xs text-muted-foreground text-center">Как использовать запись?</p>

            {/* Option 1: Style Description */}
            <Card
              className="p-3 cursor-pointer hover:bg-primary/5 border-primary/20 transition-colors"
              onClick={() => handleComplete("style")}
            >
              <div className="flex items-start gap-3">
                <div className="p-2 rounded-lg bg-primary/10 shrink-0">
                  <Sparkles className="w-4 h-4 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-medium text-sm">Описание стиля</p>
                  <p className="text-[0.6875rem] text-muted-foreground line-clamp-2">
                    {generateStyleDescription() || "Acoustic guitar melody"}
                  </p>
                </div>
              </div>
            </Card>

            {/* Option 2: Audio Reference */}
            <Card
              className="p-3 cursor-pointer hover:bg-accent/50 transition-colors"
              onClick={() => handleComplete("audio")}
            >
              <div className="flex items-start gap-3">
                <div className="p-2 rounded-lg bg-accent shrink-0">
                  <Waves className="w-4 h-4" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-medium text-sm">Аудио референс</p>
                  <p className="text-[0.6875rem] text-muted-foreground">
                    Использовать запись как аудио для генерации похожего трека
                  </p>
                </div>
              </div>
            </Card>
          </div>

          {/* Cancel button */}
          <Button variant="ghost" onClick={onCancel} className="w-full text-muted-foreground" size="sm">
            Отмена
          </Button>
        </motion.div>
      )}
    </div>
  );
}

/* eslint-disable react-refresh/only-export-components */
import { useState, useEffect, useMemo } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  History,
  Search,
  Trash2,
  Copy,
  Clock,
  Music2,
  Bookmark,
  BookmarkPlus,
  Plus,
  Sparkles,
  X,
  TrendingUp,
  Loader2,
} from "@/lib/icons";
import { toast } from "sonner";
import { format, ru } from "@/lib/date-utils";
import { INSPIRATION_PROMPTS, getPromptUsageCount, incrementPromptUsage } from "./inspirationPrompts";
import { cn } from "@/lib/utils";
import { logger } from "@/lib/logger";
import { clearPromptHistoryForUser, deletePromptHistoryEntry } from "@/api/prompt-history.api";
import { useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { usePromptHistorySync } from "@/hooks/usePromptHistorySync";
import { scrollbarStyles, type PromptMode, type PromptHistoryItem, type SavedPrompt } from "./promptHistoryTypes";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Re-export for backward compatibility
export type { PromptMode, PromptHistoryItem, SavedPrompt };

interface PromptHistoryProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelectPrompt: (prompt: PromptHistoryItem) => void;
}

export function PromptHistory({ open, onOpenChange, onSelectPrompt }: PromptHistoryProps) {
  const [localHistory, setLocalHistory] = useState<PromptHistoryItem[]>([]);
  const [savedPrompts, setSavedPrompts] = useState<SavedPrompt[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTab, setActiveTab] = useState<"history" | "inspiration" | "saved">("history");
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [newPrompt, setNewPrompt] = useState<Partial<SavedPrompt>>({
    mode: "simple",
    model: "V4_5ALL",
  });
  const [inspirationUsage, setInspirationUsage] = useState<Record<string, number>>({});
  const [confirmClearOpen, setConfirmClearOpen] = useState(false);
  const [clearing, setClearing] = useState(false);

  const { user } = useAuth();
  const queryClient = useQueryClient();

  // Use sync hook for merged DB + localStorage history
  const { history: dbMergedHistory, savedPrompts: dbSavedPrompts, isLoading: historyLoading } = usePromptHistorySync();

  // Merge sources when available
  const history = dbMergedHistory.length > 0 ? dbMergedHistory : localHistory;

  // Load data from localStorage (fallback and for saved prompts)
  useEffect(() => {
    const loadData = () => {
      try {
        // Load local history as fallback
        const storedHistory = localStorage.getItem("musicverse_prompt_history");
        if (storedHistory) {
          const parsed = JSON.parse(storedHistory) as Array<
            Omit<PromptHistoryItem, "timestamp"> & { timestamp: string }
          >;
          const items = parsed.map((item) => ({
            ...item,
            timestamp: new Date(item.timestamp),
          }));
          setLocalHistory(items);
        }

        // Load saved prompts from localStorage
        const storedSaved = localStorage.getItem("musicverse_saved_prompts");
        if (storedSaved) {
          const parsed = JSON.parse(storedSaved) as Array<Omit<SavedPrompt, "createdAt"> & { createdAt: string }>;
          const items = parsed.map((item) => ({
            ...item,
            createdAt: new Date(item.createdAt),
          }));
          setSavedPrompts(items);
        }

        // Load inspiration usage
        const usage: Record<string, number> = {};
        INSPIRATION_PROMPTS.forEach((p) => {
          usage[p.id] = getPromptUsageCount(p.id);
        });
        setInspirationUsage(usage);
      } catch (error) {
        logger.error("Failed to load data", { error });
      }
    };

    if (open) {
      loadData();
    }
  }, [open]);

  // Filter items based on search
  const filteredHistory = history.filter((item) => {
    if (!searchQuery) return true;
    const query = searchQuery.toLowerCase();
    return (
      item.description?.toLowerCase().includes(query) ||
      item.title?.toLowerCase().includes(query) ||
      item.style?.toLowerCase().includes(query)
    );
  });

  const filteredInspiration = INSPIRATION_PROMPTS.filter((item) => {
    if (!searchQuery) return true;
    const query = searchQuery.toLowerCase();
    return (
      item.description?.toLowerCase().includes(query) ||
      item.genre?.toLowerCase().includes(query) ||
      item.style?.toLowerCase().includes(query) ||
      item.mood?.toLowerCase().includes(query)
    );
  });

  const filteredSaved = savedPrompts.filter((item) => {
    if (!searchQuery) return true;
    const query = searchQuery.toLowerCase();
    return (
      item.name?.toLowerCase().includes(query) ||
      item.description?.toLowerCase().includes(query) ||
      item.style?.toLowerCase().includes(query)
    );
  });

  const handleSelectHistory = (item: PromptHistoryItem) => {
    // Update usage count in local storage
    const localHistoryRaw = localStorage.getItem("musicverse_prompt_history");
    if (localHistoryRaw) {
      const parsed = JSON.parse(localHistoryRaw) as PromptHistoryItem[];
      const updated = parsed.map((h) =>
        h.id === item.id ? { ...h, usageCount: (h.usageCount || 0) + 1, lastUsed: new Date().toISOString() } : h,
      );
      localStorage.setItem("musicverse_prompt_history", JSON.stringify(updated));
    }

    onSelectPrompt(item);
    onOpenChange(false);
    toast.success("Промпт загружен");
  };

  const handleSelectInspiration = (item: (typeof INSPIRATION_PROMPTS)[0]) => {
    incrementPromptUsage(item.id);
    setInspirationUsage((prev) => ({
      ...prev,
      [item.id]: (prev[item.id] || 0) + 1,
    }));

    const prompt: PromptHistoryItem = {
      id: `inspiration-${Date.now()}`,
      timestamp: new Date(),
      usageCount: 1,
      mode: "simple",
      description: item.description,
      style: item.style,
      model: "V4_5ALL",
    };
    onSelectPrompt(prompt);
    onOpenChange(false);
    toast.success("Промпт для вдохновения загружен");
  };

  const handleSelectSaved = (item: SavedPrompt) => {
    const prompt: PromptHistoryItem = {
      id: item.id,
      timestamp: item.createdAt,
      usageCount: 1,
      mode: item.mode,
      description: item.description,
      title: item.title,
      style: item.style,
      lyrics: item.lyrics,
      model: item.model,
    };
    onSelectPrompt(prompt);
    onOpenChange(false);
    toast.success("Сохраненный промпт загружен");
  };

  const handleDeleteHistory = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();

    // If it's a DB row (uuid) — delete from DB and refresh sync query
    if (UUID_RE.test(id) && user?.id) {
      try {
        await deletePromptHistoryEntry(id);
        await queryClient.invalidateQueries({ queryKey: ["db-generation-history", user.id] });
        toast.success("Промпт удалён из истории");
      } catch (error) {
        logger.error("Failed to delete history entry", { error });
        toast.error("Не удалось удалить промпт");
      }
      return;
    }

    // Otherwise remove from localStorage
    const localHistoryRaw = localStorage.getItem("musicverse_prompt_history");
    if (localHistoryRaw) {
      const parsed = JSON.parse(localHistoryRaw) as PromptHistoryItem[];
      const updated = parsed.filter((item) => item.id !== id);
      localStorage.setItem("musicverse_prompt_history", JSON.stringify(updated));
      setLocalHistory((items) => items.filter((item) => item.id !== id));
    }
    toast.success("Промпт удалён из истории");
  };

  const handleDeleteSaved = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = savedPrompts.filter((item) => item.id !== id);
    setSavedPrompts(updated);
