/**
 * CloudAudioPicker - Select audio from cloud reference library
 * Integrates with studio audio coordination
 */

import { useState, useEffect, useId } from "react";
import { Cloud, Search, Play, Pause, Check, Music2, Loader2, Clock, Tag } from "@/lib/icons";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useAuth } from "@/hooks/useAuth";
import { logger } from "@/lib/logger";
import { usePreviewAudio } from "@/hooks/audio/usePreviewAudio";
import { useCloudAudioList } from "@/hooks/audio-reference/useCloudAudioList";
import { AudioPriority } from "@/lib/audioElementPool";
import { cn } from "@/lib/utils";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";
import { registerStudioAudio, unregisterStudioAudio, pauseAllStudioAudio } from "@/hooks/studio/useStudioAudio";

interface CloudAudio {
  id: string;
  file_name: string;
  file_url: string;
  duration_seconds: number | null;
  genre: string | null;
  mood: string | null;
  bpm: number | null;
  instruments: string[] | null;
  source: string;
  created_at: string;
}

interface CloudAudioPickerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelect: (audio: CloudAudio) => void;
}

export function CloudAudioPicker({ open, onOpenChange, onSelect }: CloudAudioPickerProps) {
  const { user } = useAuth();
  const [searchQuery, setSearchQuery] = useState("");
  const [playingId, setPlayingId] = useState<string | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string>("");
  const sourceId = useId();

  const { pauseTrack } = usePlayerStore();

  // Пул-аудио с динамическим src. Регистрация в useStudioAudio координаторе
  // уже встроена в хук.
  const { playUrl, pause } = usePreviewAudio({
    id: `lyrics-cloud-picker-${sourceId}`,
    src: previewUrl,
    priority: AudioPriority.LOW,
    onEnded: () => setPlayingId(null),
    onError: () => {
      setPlayingId(null);
      logger.warn("Failed to load audio", { url: previewUrl });
    },
  });

  const { data: audioList = [], isLoading, error } = useCloudAudioList({ enabled: open });

  useEffect(() => {
    if (error) {
      logger.error("Failed to fetch audio list", error instanceof Error ? error : new Error(String(error)));
    }
  }, [error]);

  // Cleanup audio on close
  useEffect(() => {
    if (!open) {
      pause();
      setPlayingId(null);
      setPreviewUrl("");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const handlePlay = async (audio: CloudAudio) => {
    if (playingId === audio.id) {
      pause();
      setPlayingId(null);
      return;
    }

    // Pause global player and other studio audio
    pauseTrack();
    pauseAllStudioAudio(`lyrics-cloud-picker-${sourceId}`);

    setPlayingId(audio.id);
    setPreviewUrl(audio.file_url);
    await playUrl(audio.file_url);
  };

  const handleSelect = (audio: CloudAudio) => {
    pause();
    setPlayingId(null);
    onSelect(audio);
    onOpenChange(false);
  };

  const formatDuration = (seconds: number | null) => {
    if (!seconds) return "--:--";
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  const filteredList = audioList.filter(
    (audio) =>
      audio.file_name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      audio.genre?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      audio.mood?.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg max-h-[80vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Cloud className="w-5 h-5 text-primary" />
            Выбрать из облака
          </DialogTitle>
          <DialogDescription>Выберите аудио-референс из вашей библиотеки</DialogDescription>
        </DialogHeader>

        {/* Search */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Поиск по названию, жанру..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>

        {/* Audio List */}
        <ScrollArea className="flex-1 -mx-6 px-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
            </div>
          ) : filteredList.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-muted-foreground">
              <Music2 className="w-10 h-10 mb-2 opacity-50" />
              <p className="text-sm">{searchQuery ? "Ничего не найдено" : "Нет аудио в библиотеке"}</p>
            </div>
          ) : (
            <div className="space-y-2 pb-4">
              {filteredList.map((audio) => (
                <div
                  key={audio.id}
                  className={cn(
                    "p-3 rounded-xl border bg-card hover:bg-accent/50 transition-colors",
                    "flex items-center gap-3",
                  )}
                >
                  {/* Play Button */}
                  <Button variant="ghost" size="icon" className="shrink-0" onClick={() => handlePlay(audio)}>
                    {playingId === audio.id ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4" />}
                  </Button>

                  {/* Info */}
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium truncate">{audio.file_name}</p>
                    <div className="flex items-center gap-2 mt-1">
                      {audio.duration_seconds && (
                        <span className="text-xs text-muted-foreground flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          {formatDuration(audio.duration_seconds)}
                        </span>
                      )}
                      {audio.bpm && (
                        <Badge variant="outline" className="text-xs px-1.5 py-0">
                          {audio.bpm} BPM
                        </Badge>
                      )}
                      {audio.genre && (
                        <Badge variant="secondary" className="text-xs px-1.5 py-0">
                          {audio.genre}
                        </Badge>
                      )}
                    </div>
                  </div>

                  {/* Select Button */}
                  <Button size="sm" className="shrink-0 gap-1" onClick={() => handleSelect(audio)}>
                    <Check className="w-3 h-3" />
                    Выбрать
                  </Button>
                </div>
              ))}
            </div>
          )}
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}

