import { useState, useEffect } from "react";
import { ImagePlus, Loader2 } from "@/lib/icons";
import { UnifiedDialog } from "@/components/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { usePlaylists, type Playlist } from "@/hooks/usePlaylists";
import { invokeGeneratePlaylistCover } from "@/services/playlists.service";
import { toast } from "sonner";
import { logger } from "@/lib/logger";

interface EditPlaylistDialogProps {
  playlist: Playlist | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function EditPlaylistDialog({ playlist, open, onOpenChange }: EditPlaylistDialogProps) {
  const { updatePlaylist } = usePlaylists();
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [isPublic, setIsPublic] = useState(false);
  const [coverUrl, setCoverUrl] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);

  useEffect(() => {
    if (playlist) {
      setTitle(playlist.title);
      setDescription(playlist.description || "");
      setIsPublic(playlist.is_public ?? false);
      setCoverUrl(playlist.cover_url);
    }
  }, [playlist]);

  const handleGenerateCover = async () => {
    if (!title.trim()) {
      toast.error("Введите название плейлиста");
      return;
    }

    setIsGeneratingCover(true);
    try {
      const { data, error } = await invokeGeneratePlaylistCover({
        playlistTitle: title,
        trackCount: playlist?.track_count,
      });

      if (error) throw error;
      if (data?.imageUrl) {
        setCoverUrl(data.imageUrl);
        toast.success("Обложка сгенерирована");
      }
    } catch (error) {
      logger.error("Error generating cover", error);
      toast.error("Ошибка генерации обложки");
    } finally {
      setIsGeneratingCover(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!playlist || !title.trim()) return;

    setIsSubmitting(true);
    try {
      await updatePlaylist({
        id: playlist.id,
        title: title.trim(),
        description: description.trim() || undefined,
        cover_url: coverUrl || undefined,
        is_public: isPublic,
      });
      onOpenChange(false);
    } catch (error) {
      // Error handled in hook
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <UnifiedDialog
      variant="modal"
      open={open}
      onOpenChange={onOpenChange}
      title="Редактировать плейлист"
      size="sm"
      footer={
        <div className="flex justify-end gap-2">
          <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
            Отмена
          </Button>
          <Button type="submit" form="edit-playlist-form" disabled={!title.trim() || isSubmitting}>
            {isSubmitting ? "Сохранение..." : "Сохранить"}
          </Button>
        </div>
      }
    >
      <form id="edit-playlist-form" onSubmit={handleSubmit} className="space-y-4">
        {/* Cover */}
        <div className="space-y-2">
          <Label>Обложка</Label>
          <div className="flex gap-3 items-center">
            <div className="w-20 h-20 rounded-lg overflow-hidden bg-muted shrink-0">
              {coverUrl ? (
                <img
                  loading="lazy"
                  decoding="async"
                  src={coverUrl}
                  alt="Cover"
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-muted-foreground">
                  <ImagePlus className="h-8 w-8" />
                </div>
              )}
            </div>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleGenerateCover}
              disabled={isGeneratingCover}
            >
              {isGeneratingCover ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Генерация...
                </>
              ) : (
                "Сгенерировать обложку"
              )}
            </Button>
          </div>
        </div>

        <div className="space-y-2">
          <Label htmlFor="edit-title">Название</Label>
          <Input
            id="edit-title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Мой плейлист"
            required
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="edit-description">Описание</Label>
          <Textarea
            id="edit-description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Опишите плейлист..."
            rows={3}
          />
        </div>

        <div className="flex items-center justify-between">
          <div className="space-y-0.5">
            <Label htmlFor="edit-public">Публичный</Label>
            <p className="text-sm text-muted-foreground">Другие пользователи смогут видеть плейлист</p>
          </div>
          <Switch id="edit-public" checked={isPublic} onCheckedChange={setIsPublic} />
        </div>
      </form>
    </UnifiedDialog>
  );
}

