import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Drawer, DrawerContent, DrawerHeader, DrawerTitle, DrawerDescription } from "@/components/ui/drawer";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { LazyImage } from "@/components/ui/lazy-image";
import {
  Image,
  Square,
  RectangleVertical,
  Wand2,
  Download,
  Check,
  Loader2,
  Sparkles,
  Music,
  RefreshCw,
} from "@/lib/icons";
import { invokeGenerateProjectMedia, applyProjectMedia } from "@/services/projects.service";
import { useIsMobile } from "@/hooks/use-mobile";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { logger } from "@/lib/logger";

interface ProjectMediaGeneratorProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  project: {
    id: string;
    title: string;
    genre?: string | null;
    mood?: string | null;
    concept?: string | null;
    cover_url?: string | null;
    banner_url?: string | null;
  };
  track?: {
    id: string;
    title: string;
    style_prompt?: string | null;
    notes?: string | null;
  } | null;
  onCoverGenerated?: (url: string) => void;
  initialAssetType?: AssetType;
}

type AssetType = "cover" | "banner" | "story";

interface AssetTypeConfig {
  value: AssetType;
  label: string;
  description: string;
  icon: React.ReactNode;
  dimensions: string;
  aspect: string;
  usage: string;
}

const ASSET_TYPES: AssetTypeConfig[] = [
  {
    value: "cover",
    label: "Обложка",
    description: "Квадратная обложка для плеера и библиотеки",
    icon: <Square className="w-4 h-4" />,
    dimensions: "1024x1024",
    aspect: "1:1",
    usage: "Плеер • Библиотека • Плейлисты",
  },
  {
    value: "banner",
    label: "Баннер",
    description: "Широкоформатный баннер для ленты и страницы проекта",
    icon: <RectangleVertical className="w-4 h-4 rotate-90" />,
    dimensions: "1920x1080",
    aspect: "16:9",
    usage: "Главная • Страница проекта • Поделиться",
  },
  {
    value: "story",
    label: "История",
    description: "Вертикальный формат для социальных сетей",
    icon: <RectangleVertical className="w-4 h-4" />,
    dimensions: "1080x1920",
    aspect: "9:16",
    usage: "Instagram • TikTok • Stories",
  },
];

const STYLE_PRESETS = [
  {
    label: "MusicVerse",
    value: "abstract musical visualization, deep vibrant colors, futuristic design, no text, cosmic energy",
  },
  { label: "Минимализм", value: "minimalist, clean lines, single color accent, geometric shapes, modern art" },
  { label: "Граффити", value: "street art style, graffiti, urban, spray paint texture, bold colors" },
  { label: "Неон", value: "neon lights, cyberpunk, glowing effects, dark background, synthwave" },
  { label: "Винтаж", value: "vintage vinyl record aesthetic, retro, film grain, warm tones, nostalgic" },
  { label: "Природа", value: "natural elements, organic shapes, earth tones, flowing water, peaceful" },
];

export function ProjectMediaGenerator({
  open,
  onOpenChange,
  project,
  track,
  onCoverGenerated,
  initialAssetType = "cover",
}: ProjectMediaGeneratorProps) {
  const isMobile = useIsMobile();
  const [assetType, setAssetType] = useState<AssetType>(initialAssetType);
  const [customPrompt, setCustomPrompt] = useState("");
  const [selectedPreset, setSelectedPreset] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedUrl, setGeneratedUrl] = useState<string | null>(null);

  // Update asset type when initialAssetType changes (e.g., opening for banner)
  useEffect(() => {
    if (open) {
      setAssetType(initialAssetType);
    }
  }, [open, initialAssetType]);

  const targetEntity = track ? "трека" : "проекта";
  const entityTitle = track?.title || project.title;

  // Get current media URL based on selected asset type
  const getCurrentMediaUrl = () => {
    switch (assetType) {
      case "cover":
        return project.cover_url || null;
      case "banner":
        return project.banner_url || null;
      case "story":
        return null; // Stories are not persisted
      default:
        return null;
    }
  };

  const currentMediaUrl = getCurrentMediaUrl();

  // Default to 'current' tab if media exists, otherwise 'generate'
  const [activeTab, setActiveTab] = useState<"generate" | "result" | "current">(
    project.cover_url ? "current" : "generate",
  );

  const buildPrompt = () => {
    const parts: string[] = [];

    // Base style
    if (selectedPreset) {
      parts.push(selectedPreset);
    }

    // Genre influence
    if (project.genre) {
      parts.push(`${project.genre} music genre atmosphere`);
    }

    // Mood influence
    if (project.mood) {
      parts.push(`${project.mood} mood`);
    }

    // Track style if available
    if (track?.style_prompt) {
      parts.push(`inspired by: ${track.style_prompt}`);
    }

    // Project concept
    if (project.concept) {
      parts.push(`theme: ${project.concept}`);
    }

    // Custom additions
    if (customPrompt.trim()) {
      parts.push(customPrompt.trim());
    }

    // Asset type specific
    const assetConfig = ASSET_TYPES.find((a) => a.value === assetType);
    if (assetConfig) {
      parts.push(`${assetConfig.aspect} aspect ratio`);
    }

    // Quality suffix
    parts.push("ultra high resolution, professional album artwork, no text, no watermarks");

    return parts.join(", ");
  };

  const handleGenerate = async () => {
    setIsGenerating(true);
    setGeneratedUrl(null);

    try {
      const prompt = buildPrompt();
      const assetConfig = ASSET_TYPES.find((a) => a.value === assetType)!;
      const [width, height] = assetConfig.dimensions.split("x").map(Number);

      const { data, error } = await invokeGenerateProjectMedia({
        prompt,
        width,
        height,
        projectId: project.id,
        trackId: track?.id,
        assetType,
      });

      if (error) throw error;

      if (data?.url) {
        setGeneratedUrl(data.url);
        setActiveTab("result");
        toast.success("Изображение сгенерировано");
      }
    } catch (err: unknown) {
      logger.error("Error generating media", err instanceof Error ? err : new Error(String(err)));
      toast.error(err instanceof Error ? err.message : "Ошибка генерации");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleApply = async () => {
    if (!generatedUrl) return;

    try {
      if (track) {
        // Apply to track - would need to update track cover
        toast.success("Обложка трека обновлена");
      } else {
        // Apply to project based on asset type
        const updateField = assetType === "banner" ? "banner_url" : "cover_url";
        await applyProjectMedia({
          projectId: project.id,
          field: updateField,
          url: generatedUrl,
        });

        const successMessage =
          assetType === "banner"
            ? "Баннер проекта обновлён"
            : assetType === "story"
              ? "История сохранена"
              : "Обложка проекта обновлена";
        toast.success(successMessage);
      }

      onCoverGenerated?.(generatedUrl);
      onOpenChange(false);
    } catch (err: unknown) {
      logger.error("Error applying cover", err instanceof Error ? err : new Error(String(err)));
      toast.error("Ошибка сохранения");
    }
  };

  const handleDownload = async () => {
    if (!generatedUrl) return;

    try {
      const response = await fetch(generatedUrl);
      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${entityTitle.replace(/\s+/g, "_")}_${assetType}.png`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success("Загрузка началась");
    } catch {
      toast.error("Ошибка загрузки");
    }
  };

  const content = (
    <div className="flex flex-col h-full min-h-0">
      <Tabs
        value={activeTab}
        onValueChange={(v) => setActiveTab(v as typeof activeTab)}
        className="flex flex-col h-full min-h-0"
      >
        <TabsList
          className={cn("w-full shrink-0 mx-4 mt-2", currentMediaUrl ? "grid grid-cols-3" : "grid grid-cols-2")}
          style={{ width: "calc(100% - 32px)" }}
        >
          {currentMediaUrl && (
            <TabsTrigger value="current" className="gap-1.5">
              <Image className="w-3.5 h-3.5" />
              Текущее
            </TabsTrigger>
          )}
          <TabsTrigger value="generate" className="gap-1.5">
            <Wand2 className="w-3.5 h-3.5" />
            Создать
          </TabsTrigger>
          <TabsTrigger value="result" disabled={!generatedUrl} className="gap-1.5">
            <Sparkles className="w-3.5 h-3.5" />
            Результат
          </TabsTrigger>
        </TabsList>

        {/* Current Media Tab */}
        {currentMediaUrl && (
          <TabsContent value="current" className="flex-1 overflow-hidden mt-0">
            <ScrollArea className="h-full">
              <div className="p-4 space-y-4">
                <div className="space-y-2">
                  <Label className="text-sm flex items-center gap-2">
                    <Check className="w-3.5 h-3.5 text-green-500" />
                    {assetType === "cover"
                      ? "Текущая обложка"
                      : assetType === "banner"
                        ? "Текущий баннер"
                        : "Текущая история"}
                  </Label>
                  <div
                    className={cn(
                      "relative rounded-lg overflow-hidden bg-muted border",
                      assetType === "cover"
                        ? "aspect-square"
                        : assetType === "banner"
                          ? "aspect-video"
                          : "aspect-[9/16]",
                    )}
                  >
                    <LazyImage src={currentMediaUrl} alt="Current media" className="w-full h-full object-cover" />
                  </div>
                </div>

                <div className="flex gap-2">
                  <Button variant="outline" className="flex-1 gap-2" onClick={() => setActiveTab("generate")}>
                    <RefreshCw className="w-4 h-4" />
                    Заменить
                  </Button>
                  <Button
                    variant="outline"
                    className="gap-2"
                    onClick={() => {
                      if (currentMediaUrl) {
                        window.open(currentMediaUrl, "_blank");
                      }
                    }}
                  >
                    <Download className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </ScrollArea>
          </TabsContent>
        )}

        <TabsContent value="generate" className="flex-1 overflow-hidden mt-0">
          <ScrollArea className="h-full">
            <div className="p-4 space-y-4">
              {/* Entity Info */}
              <div className="flex items-center gap-3 p-3 bg-muted/50 rounded-lg">
                <div className="w-10 h-10 rounded bg-primary/10 flex items-center justify-center">
                  <Music className="w-5 h-5 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-medium text-sm truncate">{entityTitle}</p>
                  <p className="text-xs text-muted-foreground">
                    {project.genre && <span>{project.genre}</span>}
                    {project.genre && project.mood && <span> • </span>}
                    {project.mood && <span>{project.mood}</span>}
                  </p>
                </div>
              </div>

              {/* Asset Type Selection */}
              <div className="space-y-3">
                <Label className="text-sm">Выберите тип изображения</Label>
                <div className="space-y-2">
                  {ASSET_TYPES.map((type) => (
                    <button
                      key={type.value}
                      onClick={() => setAssetType(type.value)}
                      className={cn(
                        "w-full flex items-start gap-3 p-3 rounded-lg border transition-all text-left",
                        assetType === type.value
                          ? "border-primary bg-primary/5 ring-1 ring-primary/20"
                          : "border-border hover:border-primary/50 hover:bg-muted/30",
                      )}
                    >
                      <div
                        className={cn(
                          "shrink-0 w-10 h-10 rounded-lg flex items-center justify-center",
                          assetType === type.value ? "bg-primary text-primary-foreground" : "bg-muted",
                        )}
                      >
                        {type.icon}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="font-medium text-sm">{type.label}</span>
                          <Badge variant="secondary" className="text-[0.625rem] px-1.5 py-0">
                            {type.aspect}
                          </Badge>
                        </div>
                        <p className="text-xs text-muted-foreground mt-0.5">{type.description}</p>
                        <p className="text-[0.625rem] text-muted-foreground/70 mt-1">{type.usage}</p>
                      </div>
                      <span className="text-[0.625rem] text-muted-foreground shrink-0">{type.dimensions}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* Style Presets */}
              <div className="space-y-2">
                <Label className="text-sm">Стиль</Label>
                <div className="flex flex-wrap gap-1.5">
                  {STYLE_PRESETS.map((preset) => (
                    <Badge
                      key={preset.label}
                      variant={selectedPreset === preset.value ? "default" : "outline"}
                      className="cursor-pointer transition-all"
                      onClick={() => setSelectedPreset(selectedPreset === preset.value ? null : preset.value)}
                    >
                      {preset.label}
                    </Badge>
                  ))}
                </div>
              </div>

              {/* Custom Prompt */}
              <div className="space-y-2">
                <Label className="text-sm">Дополнительные детали</Label>
                <Textarea
                  value={customPrompt}
                  onChange={(e) => setCustomPrompt(e.target.value)}
                  placeholder="Опишите дополнительные элементы, цвета, атмосферу..."
                  className="min-h-[80px] resize-none"
                />
                <p className="text-xs text-muted-foreground">Контекст проекта и трека будет добавлен автоматически</p>
              </div>

              {/* Generate Button */}
              <Button onClick={handleGenerate} disabled={isGenerating} className="w-full gap-2" size="lg">
                {isGenerating ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    Генерация...
                  </>
                ) : (
                  <>
                    <Sparkles className="w-4 h-4" />
                    Сгенерировать
                  </>
                )}
              </Button>
            </div>
          </ScrollArea>
        </TabsContent>

        <TabsContent value="result" className="flex-1 overflow-hidden mt-0">
          <ScrollArea className="h-full">
            <div className="p-4 space-y-4">
              {generatedUrl && (
                <>
                  {/* Preview */}
                  <div
                    className={cn(
                      "relative rounded-lg overflow-hidden bg-muted",
                      assetType === "cover"
                        ? "aspect-square"
                        : assetType === "banner"
                          ? "aspect-video"
                          : "aspect-[9/16]",
                    )}
                  >
                    <LazyImage src={generatedUrl} alt="Generated media" className="w-full h-full object-cover" />
                  </div>

                  {/* Actions */}
                  <div className="grid grid-cols-2 gap-2">
                    <Button onClick={handleApply} className="gap-2">
                      <Check className="w-4 h-4" />
                      Применить
                    </Button>
                    <Button variant="outline" onClick={handleDownload} className="gap-2">
                      <Download className="w-4 h-4" />
                      Скачать
                    </Button>
                  </div>

                  {/* Regenerate */}
                  <Button variant="ghost" onClick={() => setActiveTab("generate")} className="w-full gap-2">
                    <RefreshCw className="w-4 h-4" />
                    Сгенерировать другое
                  </Button>
                </>
              )}
            </div>
          </ScrollArea>
        </TabsContent>
      </Tabs>
    </div>
  );

  if (isMobile) {
    return (
      <Drawer open={open} onOpenChange={onOpenChange}>
        <DrawerContent className="h-[85vh] max-h-[85vh]">
          <DrawerHeader className="pb-2">
            <DrawerTitle className="flex items-center gap-2">
              <Image className="w-5 h-5 text-primary" />
              Медиа ассеты
            </DrawerTitle>
            <DrawerDescription>Генерация обложки, баннера или истории для {targetEntity}</DrawerDescription>
          </DrawerHeader>
          {content}
        </DrawerContent>
      </Drawer>
    );
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md max-h-[80vh] flex flex-col p-0 gap-0">
        <DialogHeader className="p-4 pb-2">
          <DialogTitle className="flex items-center gap-2">
            <Image className="w-5 h-5 text-primary" />
            Медиа ассеты
          </DialogTitle>
          <DialogDescription>Генерация обложки, баннера или истории для {targetEntity}</DialogDescription>
        </DialogHeader>
        <div className="flex-1 overflow-hidden">{content}</div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * PromptDJ Mixer - Improved UI with Quick Start, compact visualizer, and essentials mode
 * Enhanced UX with editable prompt, progress tracking, waveform history, and smart suggestions
 */

import { memo, useCallback, useEffect, useState, useMemo, useRef } from "react";
import { AnimatePresence } from "@/lib/motion";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Slider } from "@/components/ui/slider";
import { Play, Square, Loader2, Settings2, Zap, Radio, HelpCircle, Rocket } from "@/lib/icons";
import { EssentialsKnobGrid } from "./EssentialsKnobGrid";
import { CompactVisualizer } from "./CompactVisualizer";
import { EditablePromptPreview } from "./EditablePromptPreview";
import { GenerateButton } from "./GenerateButton";
import { TrackHistoryItem } from "./TrackHistoryItem";
import { QuickStartSheet, type QuickStartPreset } from "./QuickStartSheet";
import { SmartSuggestions } from "./SmartSuggestions";
import { PromptDJOnboarding, usePromptDJOnboarding } from "./PromptDJOnboarding";
import { PromptDJErrorBoundary } from "./PromptDJErrorBoundary";
import { toast } from "sonner";
import { useNavigate } from "react-router";
import { useIsMobile } from "@/hooks/use-mobile";
import { useHapticFeedback } from "@/hooks/useHapticFeedback";
import { insertReferenceAudio } from "@/api/recordings.api";
import { useAuth } from "@/hooks/useAuth";
import { usePredictiveGeneration } from "@/hooks/usePredictiveGeneration";
import { logger } from "@/lib/logger";
import { useTelegramMainButton } from "@/hooks/telegram";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { usePromptDJEnhanced, GeneratedTrack, ChannelType, PromptChannel } from "@/hooks/usePromptDJEnhanced";
import { usePreviewAudio } from "@/hooks/audio/usePreviewAudio";
import { AudioPriority } from "@/lib/audioElementPool";

// Quick presets for header chips
const QUICK_PRESETS = [
  { id: "lofi", label: "🎧 Lo-Fi", values: { genre: "Lo-Fi", instrument: "Piano", mood: "Calm", texture: "Vintage" } },
  { id: "edm", label: "⚡ EDM", values: { genre: "EDM", instrument: "Synth", mood: "Energetic", energy: "High" } },
  {
    id: "cinema",
    label: "🎬 Кино",
    values: { genre: "Classical", instrument: "Strings", mood: "Epic", style: "Cinematic" },
  },
  { id: "trap", label: "🔥 Trap", values: { genre: "Trap", instrument: "Bass", mood: "Dark", energy: "Intense" } },
];

const PromptDJMixerInner = memo(function PromptDJMixerInner() {
  const navigate = useNavigate();
  const isMobile = useIsMobile();
  const { user } = useAuth();
  const haptic = useHapticFeedback();
  const [showSettings, setShowSettings] = useState(false);
  const [showQuickStart, setShowQuickStart] = useState(false);
  const [selectedChannel, setSelectedChannel] = useState<string | null>(null);
  const [savingTrackId, setSavingTrackId] = useState<string | null>(null);
  const [isKnobAdjusting, setIsKnobAdjusting] = useState(false);
  const [dismissedSuggestions, setDismissedSuggestions] = useState<Set<string>>(new Set());

  // Onboarding
  const { showOnboarding, setShowOnboarding, resetOnboarding } = usePromptDJOnboarding();

  const {
    channels,
    updateChannel,
    globalSettings,
    updateGlobalSettings,
    isGenerating,
    generatedTracks,
    generateMusic,
    previewWithSynth,
    stopPreview,
    isPreviewPlaying,
    isPlaying,
    currentTrack,
    playTrack,
    stopPlayback,
    currentPrompt,
    analyzerNode,
    removeTrack,
    isLiveMode,
    liveStatus,
    startLiveMode,
    stopLiveMode,
    forceRegenerateInLive,
  } = usePromptDJEnhanced();

  // Predictive pre-generation - check cache
  const { hasPrediction } = usePredictiveGeneration(currentPrompt, {
    enabled: !isLiveMode && !isGenerating,
    duration: globalSettings.duration,
  });

  // Telegram MainButton - show "СГЕНЕРИРОВАТЬ" when not in Live mode
  const { shouldShowUIButton, showProgress, hideProgress } = useTelegramMainButton({
    text: isGenerating ? "Генерация..." : "СГЕНЕРИРОВАТЬ",
    onClick: generateMusic,
    enabled: !isGenerating && !isLiveMode && !!currentPrompt,
    visible: !isLiveMode, // Hide MainButton in Live mode
  });

  // Show/hide progress on MainButton when generating
  useEffect(() => {
    if (isGenerating) {
      showProgress(true);
    } else {
      hideProgress();
    }
  }, [isGenerating, showProgress, hideProgress]);

  // Show quick start on first visit
  useEffect(() => {
    const hasSeenQuickStart = localStorage.getItem("promptdj-seen-quickstart");
    if (!hasSeenQuickStart && !showOnboarding) {
      setShowQuickStart(true);
      localStorage.setItem("promptdj-seen-quickstart", "true");
    }
  }, [showOnboarding]);

  // Knob change handlers for Live mode with haptic feedback
  const handleKnobChangeStart = useCallback(() => {
    setIsKnobAdjusting(true);
    haptic.tap();
  }, [haptic]);

  const handleKnobChangeEnd = useCallback(() => {
    setIsKnobAdjusting(false);
    haptic.select();
    if (isLiveMode && liveStatus === "playing") {
      setTimeout(() => forceRegenerateInLive?.(), 100);
    }
  }, [isLiveMode, liveStatus, forceRegenerateInLive, haptic]);

  // Smart suggestions handlers
  const handleApplySuggestion = useCallback(
    (suggestion: { action?: { channelType?: string; value?: string; setting?: Partial<typeof globalSettings> } }) => {
      if (!suggestion.action) return;

      haptic.success();

      if (suggestion.action.channelType && suggestion.action.value) {
        const channel = channels.find((c) => c.type === suggestion.action!.channelType);
        if (channel) {
          updateChannel(channel.id, { value: suggestion.action.value, enabled: true, weight: 0.7 });
        }
      }

      if (suggestion.action.setting) {
        updateGlobalSettings(suggestion.action.setting);
      }

      toast.success("Рекомендация применена");
    },
    [channels, updateChannel, updateGlobalSettings, haptic],
  );

  const handleDismissSuggestion = useCallback((id: string) => {
    setDismissedSuggestions((prev) => new Set(prev).add(id));
  }, []);

  // Apply quick preset from chips
  const applyPreset = useCallback(
    (preset: (typeof QUICK_PRESETS)[0]) => {
      haptic.success();
      const appliedTypes = new Set<string>();
      Object.entries(preset.values).forEach(([type, value]) => {
        const channel = channels.find((c) => c.type === type && !appliedTypes.has(c.id));
        if (channel) {
          appliedTypes.add(channel.id);
          updateChannel(channel.id, { value: value as string, enabled: true, weight: 1 });
        }
      });
      toast.success(`Пресет "${preset.label}" применён`);
    },
    [channels, updateChannel, haptic],
  );

  // Apply quick start preset
  const handleApplyQuickStart = useCallback(
    (preset: QuickStartPreset) => {
      haptic.success();
      // Apply channel settings
      Object.entries(preset.channels).forEach(([type, config]) => {
        const channel = channels.find((c) => c.type === type);
        if (channel && config) {
          updateChannel(channel.id, {
            value: config.value,
            enabled: true,
            weight: config.weight,
          });
        }
      });
      // Apply global settings
      updateGlobalSettings(preset.settings);
      toast.success(`Пресет "${preset.label}" применён`);
    },
    [channels, updateChannel, updateGlobalSettings, haptic],
  );

  // Channel handlers
  const handleTypeChange = useCallback(
    (channelId: string, newType: ChannelType) => {
      updateChannel(channelId, { type: newType, value: "" });
      setSelectedChannel(null);
    },
    [updateChannel],
  );

  const handleSelectChannel = useCallback((id: string | null) => {
    setSelectedChannel(id);
  }, []);

  // Save track to cloud — staged via render-side usePreviewAudio probe to keep element pool count low.
  const [pendingSaveUrl, setPendingSaveUrl] = useState<string | null>(null);
  const completedSaveRef = useRef<string | null>(null);
  const { duration: saveDuration, error: saveError } = usePreviewAudio({
    id: pendingSaveUrl ? `promptdj-save-${pendingSaveUrl}` : "promptdj-save-none",
    src: pendingSaveUrl ?? "",
    priority: AudioPriority.LOW,
  });

  const handleSaveToCloud = useCallback(
    (track: GeneratedTrack) => {
      if (!user) {
        toast.error("Авторизуйтесь для сохранения");
        return;
      }
      if (savingTrackId) return; // already saving
      setSavingTrackId(track.id);
      completedSaveRef.current = null;
      setPendingSaveUrl(track.audioUrl);
    },
    [user, savingTrackId],
  );

  // Run the actual DB insert once the pool reports the duration (or fails).
  useEffect(() => {
    if (!pendingSaveUrl || !savingTrackId || !user) return;
    if (completedSaveRef.current === pendingSaveUrl) return;
    if (!saveDuration && !saveError) return;

    completedSaveRef.current = pendingSaveUrl;
    const url = pendingSaveUrl;
    const duration = saveDuration || 0;

    (async () => {
      try {
        await insertReferenceAudio({
          userId: user.id,
          fileUrl: url,
          fileName: `PromptDJ Mix - ${new Date().toLocaleDateString("ru")}`,
          source: "promptdj",
          durationSeconds: duration,
        });
        toast.success("Трек сохранён в облако");
      } catch (error: unknown) {
        logger.error("Save error", error instanceof Error ? error : new Error(String(error)));
        toast.error("Ошибка сохранения");
      } finally {
        setSavingTrackId(null);
        setPendingSaveUrl(null);
      }
    })();
  }, [pendingSaveUrl, saveDuration, saveError, savingTrackId, user]);

  // Use as reference (unified system)
  const handleUseAsReference = useCallback(
    (track: GeneratedTrack) => {
      import("@/services/audio-reference").then(({ ReferenceManager }) => {
        ReferenceManager.createFromCreativeTool("dj", track.audioUrl, {
          prompt: track.prompt,
          bpm: globalSettings.bpm,
        });
        toast.success("Трек добавлен как референс");
        navigate("/");
      });
    },
    [navigate, globalSettings.bpm],
  );

  // Download track
  const handleDownload = useCallback(async (track: GeneratedTrack) => {
    try {
      const response = await fetch(track.audioUrl);
      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `promptdj-${Date.now()}.wav`;
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      toast.error("Ошибка скачивания");
    }
  }, []);

  // Load drum pattern from session
  useEffect(() => {
    const drumData = sessionStorage.getItem("drumPatternForDJ");
    if (drumData) {
      try {
        const { description, bpm } = JSON.parse(drumData);
        const customChannel = channels.find((c) => c.type === "custom");
        if (customChannel) {
          updateChannel(customChannel.id, { value: description, enabled: true, weight: 1 });
        }
        if (bpm) updateGlobalSettings({ bpm });
        toast.success("Паттерн из драм-машины загружен");
        sessionStorage.removeItem("drumPatternForDJ");
      } catch {}
    }
  }, []);

  // Compute active state
  const isKnobsActive = useMemo(
    () => isPlaying || isPreviewPlaying || isLiveMode,
    [isPlaying, isPreviewPlaying, isLiveMode],
  );

  // Live status text
  const getLiveStatusText = () => {
    switch (liveStatus) {
      case "generating":
        return "Генерация...";
      case "transitioning":
        return "Переход...";
      case "playing":
        return "Меняйте настройки";
      default:
        return "";
    }
  };

  return (
    <div className="flex flex-col gap-3">
      {/* Onboarding */}
      <AnimatePresence>
        {showOnboarding && (
          <PromptDJOnboarding onComplete={() => setShowOnboarding(false)} onSkip={() => setShowOnboarding(false)} />
        )}
      </AnimatePresence>

      {/* Quick Start Sheet */}
      <QuickStartSheet
        isOpen={showQuickStart}
        onClose={() => setShowQuickStart(false)}
        onApplyPreset={handleApplyQuickStart}
      />

      {/* Header with compact visualizer */}
      <div className="relative rounded-xl overflow-hidden bg-gradient-to-br from-purple-500/5 via-background to-blue-500/5 border border-border/30">
        {/* Compact visualizer - 40px height */}
        <CompactVisualizer analyzerNode={analyzerNode} isActive={isKnobsActive} className="absolute inset-x-0 top-0" />

        <div className="relative z-10 p-3 pt-12">
          {/* Live mode indicator */}
          {isLiveMode && (
            <div className="flex items-center gap-2 mb-2 px-2 py-1 rounded-lg bg-red-500/20 border border-red-500/30">
              <div
                className={cn(
                  "w-2 h-2 rounded-full",
                  liveStatus === "generating" || liveStatus === "transitioning"
                    ? "bg-amber-500 animate-pulse"
                    : "bg-red-500 animate-pulse",
                )}
              />
              <span className="text-xs font-medium text-red-400">LIVE</span>
              <span className="text-[0.625rem] text-muted-foreground flex-1">{getLiveStatusText()}</span>
              {(liveStatus === "generating" || liveStatus === "transitioning") && (
                <Loader2 className="w-3 h-3 animate-spin text-amber-500" />
              )}
            </div>
          )}

          {/* Quick presets row */}
          <div className="flex items-center gap-1.5 overflow-x-auto pb-2 scrollbar-hide">
            <Button
              variant="ghost"
              size="sm"
              className="shrink-0 h-7 px-2.5 text-[0.6875rem] rounded-full bg-primary/20 hover:bg-primary/30 text-primary"
              onClick={() => setShowQuickStart(true)}
            >
              <Rocket className="w-3 h-3 mr-1" />
              Quick Start
            </Button>
            {QUICK_PRESETS.map((preset) => (
              <Button
                key={preset.id}
                variant="ghost"
                size="sm"
                className="shrink-0 h-7 px-2.5 text-[0.6875rem] rounded-full bg-muted/20 hover:bg-muted/40"
                onClick={() => applyPreset(preset)}
                disabled={isGenerating}
              >
                {preset.label}
              </Button>
            ))}
          </div>

          {/* Editable prompt preview */}
          <EditablePromptPreview prompt={currentPrompt} isGenerating={isGenerating} />
        </div>
      </div>

      {/* Essentials Knob Grid (4 essential + expandable advanced) */}
      <EssentialsKnobGrid
        channels={channels}
        isActive={isKnobsActive}
        selectedChannel={selectedChannel}
        onSelect={handleSelectChannel}
        onUpdate={updateChannel}
        onTypeChange={handleTypeChange}
        onChangeStart={handleKnobChangeStart}
        onChangeEnd={handleKnobChangeEnd}
      />

      {/* Smart Suggestions */}
      <SmartSuggestions
        channels={channels}
        globalSettings={globalSettings}
        onApplySuggestion={handleApplySuggestion}
        onDismiss={handleDismissSuggestion}
        dismissedIds={dismissedSuggestions}
      />

      {/* Controls */}
      <div className="flex flex-col gap-2 p-3 rounded-xl bg-card/30 border border-border/30">
        {/* Transport row */}
        <div className="flex items-center justify-center gap-2">
          {/* Preview button */}
          <Button
            variant="outline"
            size="icon"
            className={cn(
              "h-10 w-10 rounded-full",
              isPreviewPlaying && !isLiveMode && "bg-amber-500/20 border-amber-500",
            )}
            onClick={isPreviewPlaying ? stopPreview : previewWithSynth}
            disabled={isGenerating || isLiveMode}
            title="Превью с синтезатором"
          >
            <Zap className="w-4 h-4" />
          </Button>

          {/* Live/Stop button */}
          {isLiveMode ? (
            <Button size="lg" variant="destructive" className="h-12 w-12 rounded-full" onClick={stopLiveMode}>
              <Square className="w-5 h-5" />
            </Button>
          ) : (
            <Button
              size="lg"
              className={cn(
                "h-12 w-12 rounded-full",
                "bg-gradient-to-br from-red-500 to-orange-500",
                "hover:from-red-600 hover:to-orange-600",
                "shadow-lg shadow-red-500/20",
              )}
              onClick={startLiveMode}
              disabled={isGenerating || !currentPrompt}
              title="Запустить Live сессию"
            >
              <Radio className="w-5 h-5" />
            </Button>
          )}

          {/* Generate single track with progress - only show UI button for test users */}
          {shouldShowUIButton && (
            <GenerateButton
              onClick={generateMusic}
              isGenerating={isGenerating}
              isLiveMode={isLiveMode}
              disabled={!currentPrompt}
              hasCachedResult={hasPrediction(currentPrompt)}
              estimatedTime={globalSettings.duration + 5}
            />
          )}
        </div>

        {/* BPM & Settings row */}
        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center gap-1.5">
            <span className="text-[0.625rem] text-muted-foreground">BPM</span>
            <div className="flex items-center bg-muted/20 rounded-lg">
              <button
                className="w-6 h-6 flex items-center justify-center text-sm hover:bg-muted/30 rounded-l-lg"
                onClick={() => updateGlobalSettings({ bpm: Math.max(60, globalSettings.bpm - 5) })}
              >
                −
              </button>
              <span className="w-8 text-center font-mono text-xs font-bold">{globalSettings.bpm}</span>
              <button
                className="w-6 h-6 flex items-center justify-center text-sm hover:bg-muted/30 rounded-r-lg"
                onClick={() => updateGlobalSettings({ bpm: Math.min(180, globalSettings.bpm + 5) })}
              >
                +
              </button>
            </div>
          </div>

