source:
/**
 * Compact Studio Lyrics Panel
 *
 * Optimized for mobile - collapsed by default, minimal height
 * Shows only 2 lines at a time with current line highlighted
 * Supports expand/collapse with custom scrollbar
 */

import { useState, useEffect, useRef, useMemo, useCallback } from "react";
import { motion, AnimatePresence } from "@/lib/motion";
import { Music2, ChevronDown, ChevronUp, Scissors, Check } from "@/lib/icons";
import { cn } from "@/lib/utils";
import { useTimestampedLyrics, AlignedWord } from "@/hooks/useTimestampedLyrics";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { SYNC_CONSTANTS } from "@/hooks/lyrics/useLyricsSynchronization";
import "@/styles/lyrics-sync.css";

interface StudioLyricsPanelCompactProps {
  taskId: string | null;
  audioId: string | null;
  plainLyrics?: string | null;
  currentTime: number;
  isPlaying: boolean;
  onSeek?: (time: number) => void;
  selectionMode?: boolean;
  onSectionSelect?: (startTime: number, endTime: number, lyrics: string) => void;
  highlightedSection?: { start: number; end: number } | null;
}

interface LyricLine {
  words: AlignedWord[];
  startTime: number;
  endTime: number;
  text: string;
  sectionTag?: string;
}

// Section tag types for styling
type SectionTagType =
  "verse" | "chorus" | "bridge" | "intro" | "outro" | "pre-chorus" | "hook" | "instrumental" | "unknown";

const SECTION_TAG_COLORS: Record<SectionTagType, string> = {
  verse: "bg-blue-500/20 text-blue-400 border-blue-500/30",
  chorus: "bg-purple-500/20 text-purple-400 border-purple-500/30",
  bridge: "bg-amber-500/20 text-amber-400 border-amber-500/30",
  intro: "bg-green-500/20 text-green-400 border-green-500/30",
  outro: "bg-rose-500/20 text-rose-400 border-rose-500/30",
  "pre-chorus": "bg-cyan-500/20 text-cyan-400 border-cyan-500/30",
  hook: "bg-pink-500/20 text-pink-400 border-pink-500/30",
  instrumental: "bg-orange-500/20 text-orange-400 border-orange-500/30",
  unknown: "bg-muted/30 text-muted-foreground border-border",
};

// Normalize tag to standard type
function normalizeTag(tag: string): string {
  const lower = tag.toLowerCase();
  if (lower === "куплет") return "verse";
  if (lower === "припев") return "chorus";
  if (lower === "бридж") return "bridge";
  if (lower === "интро") return "intro";
  if (lower === "аутро") return "outro";
  if (lower.includes("пре") || lower.includes("pre")) return "pre-chorus";
  if (lower === "хук") return "hook";
  if (lower === "инструментал") return "instrumental";
  return lower;
}

// Extract section tag type from text - handles both exact match and prefix match
function extractSectionTag(text: string): string | null {
  const trimmed = text.trim();

  // Pattern for section tags (captures the tag name)
  const tagPattern =
    /[[(](verse|chorus|bridge|intro|outro|pre-?chorus|hook|куплет|припев|бридж|интро|аутро|пре-?припев|хук|instrumental|инструментал)(?:\s*\d+)?[\])]/i;

  // 1. Exact match - whole text is just a tag
  const exactMatch = trimmed.match(new RegExp(`^${tagPattern.source}$`, "i"));
  if (exactMatch) {
    return normalizeTag(exactMatch[1]);
  }

  // 2. Prefix match - tag at the beginning (possibly with text after)
  const prefixMatch = trimmed.match(new RegExp(`^${tagPattern.source}`, "i"));
  if (prefixMatch) {
    return normalizeTag(prefixMatch[1]);
  }

  return null;
}

// Extract tag and remainder from text
function extractSectionTagWithRemainder(text: string): { tag: string; type: string; remainder: string } | null {
  const trimmed = text.trim();
  const tagPattern =
    /^([[(](?:verse|chorus|bridge|intro|outro|pre-?chorus|hook|куплет|припев|бридж|интро|аутро|пре-?припев|хук|instrumental|инструментал)(?:\s*\d+)?[\])])\s*/i;

  const match = trimmed.match(tagPattern);
  if (match) {
    const tagText = match[1].replace(/[[\]()]/g, "").trim();
    return {
      tag: match[1],
      type: normalizeTag(tagText),
      remainder: trimmed.slice(match[0].length).trim(),
    };
  }
  return null;
}

// Clean lyrics text from tags (but keep backing vocals)
function cleanLyricsText(text: string): string {
  return text
    .replace(
      /[[(](verse|chorus|bridge|intro|outro|pre-?chorus|hook|куплет|припев|бридж|интро|аутро|пре-?припев|хук|instrumental|инструментал)(?:\s*\d+)?[\])]/gi,
      "",
    )
    .trim();
}

// Check if text in parentheses is a backing vocal (not a section tag)
function isBackingVocal(text: string): boolean {
  const content = text
    .replace(/[()]/g, "")
    .toLowerCase()
    .trim();
  const structureTags = [
    "verse",
    "chorus",
    "bridge",
    "intro",
    "outro",
    "pre-chorus",
    "hook",
    "куплет",
    "припев",
    "бридж",
    "интро",
    "аутро",
    "пре-припев",
    "хук",
    "instrumental",
    "инструментал",
  ];
  return !structureTags.some((tag) => content.includes(tag));
}

// Extract backing vocal from word
function extractBackingVocal(word: string): { backing: string; remainder: string } | null {
  // Match text in parentheses at start or end of word
  const startMatch = word.match(/^\(([^)]+)\)\s*(.*)$/);
  if (startMatch && isBackingVocal(startMatch[1])) {
    return { backing: startMatch[1], remainder: startMatch[2] };
  }
  const endMatch = word.match(/^(.*?)\s*\(([^)]+)\)$/);
  if (endMatch && isBackingVocal(endMatch[2])) {
    return { backing: endMatch[2], remainder: endMatch[1] };
  }
  return null;
}

// Group words into lines based on newlines or time gaps
function groupWordsIntoLines(words: AlignedWord[]): LyricLine[] {
  const lines: LyricLine[] = [];
  let currentLineWords: AlignedWord[] = [];
  let currentSectionTag: string | undefined;

  const finishLine = () => {
    if (currentLineWords.length === 0) return;

    const lineText = currentLineWords
      .map((w) => w.word.replace(/\n/g, "").trim())
      .filter(Boolean)
      .join(" ")
      .trim();

    if (lineText) {
      lines.push({
        words: [...currentLineWords],
        startTime: currentLineWords[0].startS,
        endTime: currentLineWords[currentLineWords.length - 1].endS,
        text: lineText,
        sectionTag: currentSectionTag,
      });
    }
    currentLineWords = [];
  };

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    const wordText = word.word.trim();

    // Check for tag with possible remainder text
    const tagResult = extractSectionTagWithRemainder(wordText);
    if (tagResult) {
      // Finish current line
      finishLine();

      // Add section tag as its own line
      lines.push({
        words: [{ ...word, word: tagResult.tag }],
        startTime: word.startS,
        endTime: word.endS,
        text: "",
        sectionTag: tagResult.type,
      });
      currentSectionTag = tagResult.type;

      // If there's remaining text after the tag, add it as a new word
      if (tagResult.remainder) {
        currentLineWords.push({ ...word, word: tagResult.remainder });
      }
      continue;
    }

    // Check if this is just a section tag (no remainder)
    const tagMatch = extractSectionTag(wordText);
    if (
      tagMatch &&
      !wordText
        .replace(/[[\]()]/g, "")
        .replace(
          /verse|chorus|bridge|intro|outro|pre-?chorus|hook|куплет|припев|бридж|интро|аутро|пре-?припев|хук|instrumental|инструментал|\d+/gi,
          "",
        )
        .trim()
    ) {
      finishLine();

      lines.push({
        words: [word],
        startTime: word.startS,
        endTime: word.endS,
        text: "",
        sectionTag: tagMatch,
      });
      currentSectionTag = tagMatch;
      continue;
    }

    currentLineWords.push(word);

    const nextWord = words[i + 1];
    const hasNewline = word.word.includes("\n");
    const hasTimeGap = nextWord ? nextWord.startS - word.endS > 0.5 : true;
    const isLongLine = currentLineWords.length >= 10;

    if (hasNewline || hasTimeGap || isLongLine || !nextWord) {
      finishLine();
    }
  }

  // Finish any remaining line
  finishLine();

  return lines;
}

// Section tag badge component
function SectionTagBadge({ type }: { type: string }) {
  const normalizedType = (type.toLowerCase() as SectionTagType) || "unknown";
  const colors = SECTION_TAG_COLORS[normalizedType] || SECTION_TAG_COLORS.unknown;

  const labels: Record<string, string> = {
    verse: "Куплет",
    chorus: "Припев",
    bridge: "Бридж",
    intro: "Интро",
    outro: "Аутро",
    "pre-chorus": "Пре-припев",
    hook: "Хук",
    instrumental: "Инструментал",
  };

  return (
    <span
      className={cn("inline-flex items-center px-2 py-0.5 rounded-md text-[0.625rem] font-mono uppercase border", colors)}
    >
      {labels[normalizedType] || type}
    </span>
  );
}

export function StudioLyricsPanelCompact({
  taskId,
  audioId,
  plainLyrics,
  currentTime,
  isPlaying,
  onSeek,
  selectionMode,
  onSectionSelect,
  highlightedSection,
}: StudioLyricsPanelCompactProps) {
  const { data: lyricsData, isLoading: loading } = useTimestampedLyrics(taskId, audioId);
  const [isExpanded, setIsExpanded] = useState(false);
  const [activeLineIndex, setActiveLineIndex] = useState(0);
  const scrollAreaRef = useRef<HTMLDivElement>(null);
  const activeLineRef = useRef<HTMLDivElement>(null);

  // Process lyrics into lines
  const lines = useMemo(() => {
    if (!lyricsData?.alignedWords?.length) return [];
    return groupWordsIntoLines(lyricsData.alignedWords);
  }, [lyricsData]);

  // Filter out section tag lines for display count
  const contentLines = useMemo(() => lines.filter((l) => !l.sectionTag || l.text), [lines]);

  // Find active line based on current time
  useEffect(() => {
    if (!contentLines.length) return;

    const activeIdx = contentLines.findIndex(
      (line) => currentTime >= line.startTime && currentTime <= line.endTime + 0.5,
    );

    if (activeIdx !== -1 && activeIdx !== activeLineIndex) {
      setActiveLineIndex(activeIdx);
    }
  }, [currentTime, contentLines, activeLineIndex]);

  // Find current section tag for collapsed header display
  const currentSectionTag = useMemo(() => {
    // Find the active line index in the full lines array
    const activeContentLine = contentLines[activeLineIndex];
    if (!activeContentLine) return null;

    const activeLineIdx = lines.findIndex((l) => l === activeContentLine);

    // Search backwards from current line for nearest section tag
    for (let i = activeLineIdx; i >= 0; i--) {
      if (lines[i]?.sectionTag) {
        return lines[i].sectionTag;
      }
    }
    return null;
  }, [lines, contentLines, activeLineIndex]);

  // Auto-scroll to active line in expanded mode
  useEffect(() => {
    if (isExpanded && activeLineRef.current) {
      activeLineRef.current.scrollIntoView({
        behavior: "smooth",
        block: "center",
      });
    }
  }, [activeLineIndex, isExpanded]);

  const handleLineClick = useCallback(
    (line: LyricLine) => {
      if (onSeek && line.startTime > 0) {
        onSeek(line.startTime);
      }
    },
    [onSeek],
  );

  // Get current and next line for compact view
  const currentLine = contentLines[activeLineIndex];
  const nextLine = contentLines[activeLineIndex + 1];

  // No lyrics available
  if (!loading && !lyricsData?.alignedWords?.length && !plainLyrics) {
    return null;
  }

  // Loading state
  if (loading) {
    return (
      <div className="px-4 py-2 border-b border-border/30">
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <Music2 className="w-3.5 h-3.5 animate-pulse" />
          <span>Загрузка...</span>
        </div>
      </div>
    );
  }

  // No timestamped lyrics - show plain text preview (cleaned from tags)
  if (!lines.length && plainLyrics) {
    const cleanedLyrics = cleanLyricsText(plainLyrics);
    const firstLine = cleanedLyrics.split("\n").find((l) => l.trim()) || "";

    return (
      <div className="px-4 py-2 border-b border-border/30">
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="flex items-center gap-2 text-xs text-muted-foreground w-full"
        >
          <Music2 className="w-3.5 h-3.5" />
          <span className="truncate flex-1 text-left">{firstLine}...</span>
          {isExpanded ? (
            <ChevronUp className="w-3.5 h-3.5 shrink-0" />
          ) : (
            <ChevronDown className="w-3.5 h-3.5 shrink-0" />
          )}
        </button>
        <AnimatePresence>
          {isExpanded && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="overflow-hidden mt-2"
            >
              <ScrollArea className="max-h-[200px]">
                <p className="text-xs text-muted-foreground whitespace-pre-wrap pr-4">{cleanedLyrics}</p>
              </ScrollArea>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    );
  }

  return (
    <div className={cn("px-4 py-2 border-b border-border/30 transition-colors", selectionMode && "bg-amber-500/5")}>
      {/* Header with expand/collapse */}
      <div className="flex items-center justify-between mb-1">
        <div className="flex items-center gap-2">
          <Music2 className="w-3.5 h-3.5 text-primary" />
          <span className="text-xs font-medium text-muted-foreground">Текст песни</span>
          {/* Show current section in collapsed mode */}
          {!isExpanded && currentSectionTag && <SectionTagBadge type={currentSectionTag} />}
        </div>
        <div className="flex items-center gap-2">
          <Badge variant="outline" className="text-[0.625rem] px-1.5 py-0 h-4">
            {activeLineIndex + 1}/{contentLines.length}
          </Badge>
          <Button variant="ghost" size="sm" onClick={() => setIsExpanded(!isExpanded)} className="h-6 w-6 p-0 shrink-0">
            {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </Button>
        </div>
      </div>

      {/* Compact view - current + next line */}
      {!isExpanded && (
        <div className="space-y-1">
          {currentLine && (
            <motion.div
              key={currentLine.startTime}
              initial={{ opacity: 0, y: 5 }}
              animate={{ opacity: 1, y: 0 }}
              onClick={() => handleLineClick(currentLine)}
              className={cn("text-sm py-1 px-2 rounded-lg cursor-pointer", "bg-primary/10 font-medium")}
            >
              {currentLine.sectionTag && !currentLine.text && <SectionTagBadge type={currentLine.sectionTag} />}
              {currentLine.text &&
                currentLine.words.map((word, wordIdx) => {
                  const adjustedTime = currentTime + SYNC_CONSTANTS.WORD_LOOK_AHEAD_MS / 1000;
                  const endTolerance = SYNC_CONSTANTS.WORD_END_TOLERANCE_MS / 1000;
                  const isWordActive =
                    isPlaying && adjustedTime >= word.startS && adjustedTime <= word.endS + endTolerance;

                  const cleanWord = word.word.replace("\n", "").trim();
                  if (!cleanWord || extractSectionTag(cleanWord)) return null;

                  // Check for backing vocals (text in parentheses)
                  const backingVocal = extractBackingVocal(cleanWord);

                  if (backingVocal) {
                    return (
                      <span key={wordIdx} className="inline">
                        {backingVocal.remainder && (
                          <span
                            className={cn(
                              "transition-all duration-150",
                              isWordActive &&
                                "text-primary font-bold bg-gradient-to-r from-primary/20 to-transparent px-0.5 rounded",
                            )}
                          >
                            {backingVocal.remainder}{" "}
                          </span>
                        )}
                        <span className="text-muted-foreground italic text-[0.85em] opacity-75">
                          ({backingVocal.backing}){" "}
                        </span>
                      </span>
                    );
                  }

                  return (
                    <span
                      key={wordIdx}
                      className={cn(
                        "inline transition-all duration-150",
                        isWordActive && [
                          "text-primary font-bold",
                          "bg-gradient-to-r from-primary/20 to-transparent",
                          "px-0.5 rounded",
                        ],
                      )}
                    >
                      {cleanWord}{" "}
                    </span>
                  );
                })}
            </motion.div>
          )}

          {nextLine && nextLine.text && (
            <motion.div
              key={nextLine.startTime}
              initial={{ opacity: 0 }}
              animate={{ opacity: 0.5 }}
              onClick={() => handleLineClick(nextLine)}
              className="text-xs text-muted-foreground py-1 px-2 truncate cursor-pointer hover:opacity-70"
            >
              {nextLine.text}
            </motion.div>
          )}
        </div>
      )}

      {/* Expanded view with custom scrollbar */}
      <AnimatePresence>
        {isExpanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2 }}
            className="overflow-hidden"
          >
            <ScrollArea className="max-h-[200px] mt-2 pt-2 border-t border-border/20" ref={scrollAreaRef}>
              <div className="space-y-1 pr-4">
                {lines.map((line, idx) => {
                  const isTagLine = line.sectionTag && !line.text;
                  const contentIdx = contentLines.findIndex((l) => l.startTime === line.startTime);
                  const isActive = contentIdx === activeLineIndex;
                  const isPast = line.endTime < currentTime;

                  return (
                    <div
                      key={idx}
                      ref={isActive ? activeLineRef : null}
                      onClick={() => handleLineClick(line)}
                      className={cn(
                        "py-1.5 px-2 rounded-lg cursor-pointer text-xs transition-all",
                        isTagLine && "py-2",
                        isActive && "bg-primary/10 font-medium",
                        !isActive && isPast && "opacity-40",
                        !isActive && !isPast && "opacity-60 hover:opacity-80",
                      )}
                    >
                      {isTagLine ? <SectionTagBadge type={line.sectionTag!} /> : <span>{line.text}</span>}
                    </div>
                  );
                })}
              </div>
            </ScrollArea>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default StudioLyricsPanelCompact;

import { useState, useEffect } from "react";
import { UnifiedDialog } from "@/components/dialog";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Play, Pause, Scissors, Download, Save, RotateCcw, Volume2, VolumeX } from "@/lib/icons";
import { TrimRegionSelector } from "./TrimRegionSelector";
import { useTrimExport } from "@/hooks/studio/useTrimExport";
import { useIsMobile } from "@/hooks/use-mobile";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { formatTimePrecise } from "@/lib/player-utils";
import { usePreviewAudio } from "@/hooks/audio/usePreviewAudio";
import { AudioPriority } from "@/lib/audioElementPool";

interface TrimDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  track: {
    id: string;
    title?: string | null;
    audio_url?: string | null;
    duration_seconds?: number | null;
    style?: string | null;
    tags?: string | null;
  };
  onTrimComplete?: (newTrackId: string) => void;
}

export const TrimDialog = ({ open, onOpenChange, track, onTrimComplete }: TrimDialogProps) => {
  const { user } = useAuth();
  const isMobile = useIsMobile();
  const [region, setRegion] = useState<{ start: number; end: number } | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [muted, setMuted] = useState(false);
  const [previewMode, setPreviewMode] = useState<"full" | "region">("region");

  const { trimAudio, saveAsNewTrack, downloadTrimmed, isExporting, progress } = useTrimExport();

  const duration = track.duration_seconds || 0;

  // Пул-аудио вместо `new Audio(...)` — элемент живёт в audioElementPool.
  const {
    audioRef,
    currentTime: hookTime,
    toggle,
  } = usePreviewAudio({
    id: track.audio_url ? `trim-${track.id}` : "trim-none",
    src: track.audio_url ?? "",
    priority: AudioPriority.MEDIUM,
  });

  // Sync time-update from hook.
  useEffect(() => {
    if (Number.isFinite(hookTime)) setCurrentTime(hookTime);
  }, [hookTime]);

  // Append `ended` listener for region-restart behaviour.
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const handleEnded = () => {
      setIsPlaying(false);
      if (region && previewMode === "region") {
        audio.currentTime = region.start;
        setCurrentTime(region.start);
      }
    };

    audio.addEventListener("ended", handleEnded);
    return () => audio.removeEventListener("ended", handleEnded);
  }, [audioRef, region, previewMode]);

  // Check region bounds during playback
  useEffect(() => {
    if (!audioRef.current || !isPlaying || !region || previewMode !== "region") return;

    const checkBounds = () => {
      if (audioRef.current && audioRef.current.currentTime >= region.end) {
        audioRef.current.pause();
        audioRef.current.currentTime = region.start;
        setCurrentTime(region.start);
        setIsPlaying(false);
      }
    };

    const interval = setInterval(checkBounds, 100);
    return () => clearInterval(interval);
  }, [audioRef, isPlaying, region, previewMode]);

  // Update mute state
  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.muted = muted;
    }
  }, [audioRef, muted]);

  const togglePlay = async () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
      setIsPlaying(false);
      return;
    }
    if (region && previewMode === "region") {
      audioRef.current.currentTime = region.start;
    }
    await toggle();
    setIsPlaying(true);
  };

  const handleSeek = (time: number) => {
    if (audioRef.current) {
      audioRef.current.currentTime = time;
      setCurrentTime(time);
    }
  };

  const handleRegionChange = (start: number, end: number) => {
    if (end > start) {
      setRegion({ start, end });
    } else {
      setRegion(null);
    }
  };

  const handleReset = () => {
    setRegion(null);
    if (audioRef.current) {
      audioRef.current.currentTime = 0;
      setCurrentTime(0);
    }
    setIsPlaying(false);
  };

  const handleExport = async () => {
    if (!region || !track.audio_url) return;

    const result = await trimAudio({
      audioUrl: track.audio_url,
      startTime: region.start,
      endTime: region.end,
      trackId: track.id,
    });

    if (result) {
      downloadTrimmed(result, track.title || "track");
      URL.revokeObjectURL(result.url);
    }
  };

  const handleSaveAsTrack = async () => {
    if (!region || !track.audio_url) return;

    if (!user) {
      toast.error("Необходима авторизация");
      return;
    }

    const result = await trimAudio({
      audioUrl: track.audio_url,
      startTime: region.start,
      endTime: region.end,
      trackId: track.id,
    });

    if (result) {
      const newTrackId = await saveAsNewTrack(result, track, user.id);
      URL.revokeObjectURL(result.url);
      if (newTrackId) {
        onTrimComplete?.(newTrackId);
        onOpenChange(false);
      }
    }
  };

  // Use formatTimePrecise for millisecond precision
  const formatTime = formatTimePrecise;

  const content = (
    <div className="space-y-6">
      {/* Instructions */}
      <div className="text-sm text-muted-foreground">
        Выделите регион для обрезки, перетаскивая мышью по таймлайну. Используйте ручки для точной настройки.
      </div>

      {/* Trim Region Selector */}
      <TrimRegionSelector
        duration={duration}
        currentTime={currentTime}
        onRegionChange={handleRegionChange}
        onSeek={handleSeek}
      />

      {/* Region Info */}
      {region && (
        <div className="flex items-center justify-between p-3 bg-primary/10 rounded-lg">
          <div className="flex items-center gap-4 text-sm">
            <div>
              <span className="text-muted-foreground">Начало:</span>{" "}
              <span className="font-mono">{formatTime(region.start)}</span>
            </div>
            <div>
              <span className="text-muted-foreground">Конец:</span>{" "}
              <span className="font-mono">{formatTime(region.end)}</span>
            </div>
            <div>
              <span className="text-muted-foreground">Длительность:</span>{" "}
              <span className="font-mono font-semibold">{formatTime(region.end - region.start)}</span>
            </div>
          </div>
        </div>
      )}

      {/* Playback Controls */}
      <div className="flex items-center justify-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => setMuted(!muted)} className="h-10 w-10">
          {muted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
        </Button>

        <Button variant="ghost" size="icon" onClick={handleReset} className="h-10 w-10" disabled={!region}>
          <RotateCcw className="w-5 h-5" />
        </Button>

        <Button size="lg" onClick={togglePlay} className="h-14 w-14 rounded-full" disabled={!track.audio_url}>
          {isPlaying ? <Pause className="w-6 h-6" /> : <Play className="w-6 h-6 ml-1" />}
        </Button>

        <div className="flex gap-2">
          <Button
            variant={previewMode === "full" ? "default" : "outline"}
            size="sm"
            onClick={() => setPreviewMode("full")}
          >
            Весь трек
          </Button>
          <Button
            variant={previewMode === "region" ? "default" : "outline"}
            size="sm"
            onClick={() => setPreviewMode("region")}
            disabled={!region}
          >
            Только выбранное
          </Button>
        </div>
      </div>

      {/* Export Progress */}
      {isExporting && (
        <div className="space-y-2">
          <div className="flex items-center justify-between text-sm">
            <span>Экспорт...</span>
            <span>{progress}%</span>
          </div>
          <Progress value={progress} />
        </div>
      )}

      {/* Action Buttons */}
      <div className={cn("flex gap-3", isMobile ? "flex-col" : "justify-end")}>
        <Button variant="outline" onClick={handleExport} disabled={!region || isExporting} className="gap-2">
          <Download className="w-4 h-4" />
          Скачать WAV
        </Button>
        <Button onClick={handleSaveAsTrack} disabled={!region || isExporting} className="gap-2">
          <Save className="w-4 h-4" />
          Сохранить как новый трек
        </Button>
      </div>
    </div>
  );

  return (
    <UnifiedDialog
      variant="modal"
      open={open}
      onOpenChange={onOpenChange}
      title={`Обрезка: ${track.title || "Трек"}`}
      size="lg"
    >
      {content}
    </UnifiedDialog>
  );
};

