                  {transcription?.mxml_url && (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleDownload(transcription.mxml_url, `${stemType}.musicxml`)}
                    >
                      <FileCode2 className="w-4 h-4 mr-1.5" />
                      MusicXML
                    </Button>
                  )}
                </div>
              </div>
            )}
          </ScrollArea>
        </SheetContent>
      </Sheet>
    );
  }

  // Desktop - use Dialog with full tabs
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl h-[80vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Music2 className="w-5 h-5 text-primary" />
            Ноты: {stemType}
            {transcription?.model && (
              <Badge variant="secondary" className="ml-2">
                {transcription.model}
              </Badge>
            )}
          </DialogTitle>
        </DialogHeader>
        <div className="flex-1 min-h-0 overflow-auto">{renderContent()}</div>
      </DialogContent>
    </Dialog>
  );
}

