/**
 * ReplacementTimelineOverlay
 *
 * Shows replacement variants on the timeline with A/B comparison
 * Allows quick preview and selection of variants
 * Integrates with studio audio coordination
 */

import { useState, useCallback, useEffect, useId } from "react";
import { motion, AnimatePresence } from "@/lib/motion";
import { Play, Pause, Check, X, Volume2 } from "@/lib/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { formatTime } from "@/lib/player-utils";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";
import { pauseAllStudioAudio } from "@/hooks/studio/useStudioAudio";
import { usePreviewAudio } from "@/hooks/audio/usePreviewAudio";
import { AudioPriority } from "@/lib/audioElementPool";

interface ReplacementVariant {
  id: "A" | "B";
  audioUrl: string;
  label: string;
}

interface ReplacementTimelineOverlayProps {
  originalAudioUrl: string;
  variants: ReplacementVariant[];
  sectionStart: number;
  sectionEnd: number;
  duration: number;
  onApply: (variantId: "A" | "B") => void;
  onDiscard: () => void;
  className?: string;
}

export function ReplacementTimelineOverlay({
  originalAudioUrl,
  variants,
  sectionStart,
  sectionEnd,
  duration,
  onApply,
  onDiscard,
  className,
}: ReplacementTimelineOverlayProps) {
  const [activeVariant, setActiveVariant] = useState<"original" | "A" | "B">("A");
  const [isPlaying, setIsPlaying] = useState(false);
  const [previewUrl, setPreviewUrl] = useState<string>("");
  const sourceId = useId();

  const { pauseTrack } = usePlayerStore();

  // Пул-аудио с динамическим src.
  // Регистрация в useStudioAudio координаторе уже встроена в хук.
  const { playUrl, pause, currentTime, seek } = usePreviewAudio({
    id: `replacement-overlay-${sourceId}`,
    src: previewUrl,
    priority: AudioPriority.MEDIUM,
    onEnded: () => setIsPlaying(false),
  });

  // Calculate position percentages
  const startPercent = (sectionStart / duration) * 100;
  const widthPercent = ((sectionEnd - sectionStart) / duration) * 100;

  // Pause when reaching sectionEnd (interval → useEffect).
  useEffect(() => {
    if (isPlaying && currentTime >= sectionEnd) {
      pause();
      setIsPlaying(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isPlaying, currentTime, sectionEnd]);

  // Регистрация в useStudioAudio координаторе уже встроена в хук.
  // Pause when global player starts: useStudioAudio координатор дёргает наш pause.

  const getCurrentAudioUrl = useCallback(() => {
    if (activeVariant === "original") return originalAudioUrl;
    return variants.find((v) => v.id === activeVariant)?.audioUrl || originalAudioUrl;
  }, [activeVariant, variants, originalAudioUrl]);

  const togglePlay = useCallback(async () => {
    if (isPlaying) {
      pause();
      setIsPlaying(false);
      return;
    }

    // Pause global player and other studio audio
    pauseTrack();
    pauseAllStudioAudio(`replacement-overlay-${sourceId}`);

    // Меняем src на pool-элементе + перемотка к sectionStart.
    setIsPlaying(true);
    setPreviewUrl(getCurrentAudioUrl());
    await playUrl(getCurrentAudioUrl());
    seek(sectionStart);
    // Заметка: пауза на sectionEnd происходит через useEffect выше.
  }, [isPlaying, getCurrentAudioUrl, sectionStart, pauseTrack, sourceId, playUrl, seek, pause]);

  const switchVariant = (variantId: "original" | "A" | "B") => {
    pause();
    setIsPlaying(false);
    setActiveVariant(variantId);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 10 }}
      className={cn(
        "relative bg-card/95 backdrop-blur-sm border border-primary/30 rounded-xl overflow-hidden shadow-xl",
        className,
      )}
    >
      {/* Timeline visualization */}
      <div className="relative h-12 bg-muted/30 border-b border-border/50">
        {/* Full track bar */}
        <div className="absolute inset-x-2 top-1/2 -translate-y-1/2 h-2 bg-muted rounded-full" />

        {/* Replacement section highlight */}
        <motion.div
          className="absolute top-1/2 -translate-y-1/2 h-6 rounded-lg"
          style={{
            left: `calc(${startPercent}% + 8px)`,
            width: `${widthPercent}%`,
          }}
          animate={{
            backgroundColor:
              activeVariant === "original" ? "hsl(var(--muted-foreground) / 0.3)" : "hsl(var(--primary) / 0.3)",
            borderColor:
              activeVariant === "original" ? "hsl(var(--muted-foreground) / 0.5)" : "hsl(var(--primary) / 0.7)",
          }}
          transition={{ duration: 0.2 }}
        />

        {/* Section time labels */}
        <div
          className="absolute bottom-0.5 text-[0.5625rem] font-mono text-muted-foreground"
          style={{ left: `calc(${startPercent}% + 8px)` }}
        >
          {formatTime(sectionStart)}
        </div>
        <div
          className="absolute bottom-0.5 text-[0.5625rem] font-mono text-muted-foreground"
          style={{ left: `calc(${startPercent + widthPercent}% + 8px)` }}
        >
          {formatTime(sectionEnd)}
        </div>
      </div>

      {/* Controls */}
      <div className="p-3 space-y-3">
        {/* Variant selector */}
        <div className="flex items-center gap-2">
          <Button
            variant={activeVariant === "original" ? "secondary" : "ghost"}
            size="sm"
            onClick={() => switchVariant("original")}
            className="h-8 text-xs gap-1"
          >
            Оригинал
          </Button>
          {variants.map((variant) => (
            <Button
              key={variant.id}
              variant={activeVariant === variant.id ? "default" : "outline"}
              size="sm"
              onClick={() => switchVariant(variant.id)}
              className={cn(
                "h-8 text-xs gap-1 transition-all",
                activeVariant === variant.id && "ring-2 ring-primary/30",
              )}
            >
              {variant.label}
            </Button>
          ))}
        </div>

        {/* Playback & actions */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Button variant="outline" size="icon" onClick={togglePlay} className="h-9 w-9 rounded-full">
              {isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4 ml-0.5" />}
            </Button>
            <div className="flex items-center gap-1 text-xs text-muted-foreground">
              <Volume2 className="w-3 h-3" />
              <span>Прослушать {activeVariant === "original" ? "оригинал" : `вариант ${activeVariant}`}</span>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={onDiscard} className="h-8 text-xs gap-1">
              <X className="w-3 h-3" />
              Отменить
            </Button>
            <Button
              size="sm"
              onClick={() => onApply(activeVariant === "original" ? "A" : activeVariant)}
              disabled={activeVariant === "original"}
              className="h-8 text-xs gap-1"
            >
              <Check className="w-3 h-3" />
              Применить {activeVariant !== "original" && activeVariant}
            </Button>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

/**
 * SynchronizedSectionLyrics
 *
 * Displays section lyrics with synchronized word highlighting
 * Supports edit mode for modifying lyrics
 */

import { useState, useMemo, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "@/lib/motion";
import { Edit2, Check, X } from "@/lib/icons";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { AlignedWord } from "@/hooks/useTimestampedLyrics";

const normalizeLyrics = (value: string) => value.replace(/\s+/g, " ").trim();

interface SynchronizedSectionLyricsProps {
  words: AlignedWord[];
  startTime: number;
  endTime: number;
  currentTime: number;
  isPlaying: boolean;
  initialLyrics?: string;
  onBaselineLyricsChange?: (lyrics: string) => void;
  onLyricsChange: (lyrics: string) => void;
  className?: string;
  compact?: boolean;
}

export function SynchronizedSectionLyrics({
  words,
  startTime,
  endTime,
  currentTime,
  isPlaying,
  initialLyrics,
  onBaselineLyricsChange,
  onLyricsChange,
  className,
  compact = false,
}: SynchronizedSectionLyricsProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editedText, setEditedText] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);
  const activeWordRef = useRef<HTMLSpanElement>(null);

  // Filter words within section range with tolerance for boundary changes
  const sectionWords = useMemo(() => {
    if (!words.length) return [];

    // Use slightly wider tolerance to catch words near boundaries
    const tolerance = 0.3; // 300ms tolerance
    return words.filter((w) => {
      // Word overlaps with section range
      const wordMid = (w.startS + w.endS) / 2;
      return wordMid >= startTime - tolerance && wordMid <= endTime + tolerance;
    });
  }, [words, startTime, endTime]);

  // Get lyrics text from words or use initial - update when range changes
  const timedLyricsText = useMemo(() => {
    if (sectionWords.length > 0) {
      return sectionWords
        .map((w) => w.word)
        .join(" ")
        .replace(/\s+/g, " ")
        .trim();
    }
    return "";
  }, [sectionWords]);

  const lyricsText = initialLyrics?.trim() || timedLyricsText;
  const hasEditedLyricsOverride = Boolean(
    initialLyrics?.trim() && timedLyricsText && normalizeLyrics(initialLyrics) !== normalizeLyrics(timedLyricsText),
  );
  const rangeKey = `${startTime.toFixed(2)}-${endTime.toFixed(2)}`;

  // Track if we've already synced lyrics for this range to prevent loops
  const lastSyncedRangeRef = useRef<string>("");
  const userEditedRangeRef = useRef<string | null>(null);

  // Notify parent when detected baseline lyrics change due to range change.
  // Important: `initialLyrics` is the editable value from the parent, not the
  // immutable baseline. Never use it to reset the baseline after the user saves,
  // otherwise a remount can make the edited text look like the "original" text
  // and the replace-section payload becomes a no-op.
  useEffect(() => {
    if (rangeKey === lastSyncedRangeRef.current || !timedLyricsText) {
      return;
    }

    lastSyncedRangeRef.current = rangeKey;
    onBaselineLyricsChange?.(timedLyricsText);

    if (!initialLyrics?.trim() && userEditedRangeRef.current !== rangeKey) {
      onLyricsChange(timedLyricsText);
    }
  }, [rangeKey, timedLyricsText, initialLyrics, onBaselineLyricsChange, onLyricsChange]);

  // Update edited text when the parent value or detected baseline changes.
  useEffect(() => {
    setEditedText(lyricsText);
  }, [lyricsText]);

  // Find active word based on current time
  const activeWordIndex = useMemo(() => {
    if (!isPlaying || currentTime < startTime || currentTime > endTime) {
      return -1;
    }
    return sectionWords.findIndex((w) => currentTime >= w.startS && currentTime <= w.endS);
  }, [sectionWords, currentTime, isPlaying, startTime, endTime]);

  // Auto-scroll to active word
  useEffect(() => {
    if (activeWordRef.current && containerRef.current && !isEditing) {
      activeWordRef.current.scrollIntoView({
        behavior: "smooth",
        block: "center",
        inline: "center",
      });
    }
  }, [activeWordIndex, isEditing]);

  const handleStartEdit = () => {
    setEditedText(lyricsText);
    setIsEditing(true);
  };

  const handleSaveEdit = () => {
    userEditedRangeRef.current = rangeKey;
    onLyricsChange(editedText);
    setIsEditing(false);
  };

  const handleCancelEdit = () => {
    setEditedText(lyricsText);
    setIsEditing(false);
  };

  // Edit mode
  if (isEditing) {
    return (
      <div className={cn("space-y-2", className)}>
        <Textarea
          value={editedText}
          onChange={(e) => setEditedText(e.target.value)}
          placeholder="Введите текст секции..."
          className={cn(
            "font-mono resize-none",
            compact ? "min-h-[80px] text-xs" : "min-h-[120px] text-sm",
            "bg-background/50 border-primary/30 focus:border-primary focus:ring-primary/20",
          )}
          autoFocus
        />
        <div className="flex items-center gap-2">
          <Button type="button" variant="ghost" size="sm" onClick={handleCancelEdit} className="h-7 text-xs">
            <X className="w-3 h-3 mr-1" />
            Отмена
          </Button>
          <Button type="button" size="sm" onClick={handleSaveEdit} className="h-7 text-xs">
            <Check className="w-3 h-3 mr-1" />
            Сохранить
          </Button>
        </div>
      </div>
    );
  }

  // Display mode with synchronized words
  return (
    <div className={cn("relative", className)}>
      {/* Header with edit button */}
      <div className="flex items-center justify-between mb-2">
        <span className={cn("font-medium text-muted-foreground", compact ? "text-[0.625rem]" : "text-xs")}>
          Текст секции
        </span>
        <Button
          variant="ghost"
          size="sm"
          type="button"
          onClick={handleStartEdit}
          className="h-6 px-2 text-xs gap-1 text-muted-foreground hover:text-foreground"
        >
          <Edit2 className="w-3 h-3" />
          Изменить
        </Button>
      </div>

      {/* Synchronized words display */}
      <div
        ref={containerRef}
        className={cn(
          "overflow-y-auto rounded-lg border border-border/50 bg-muted/20",
          compact ? "max-h-[80px] p-2" : "max-h-[120px] p-3",
        )}
      >
        {sectionWords.length > 0 && !hasEditedLyricsOverride ? (
          <div className="flex flex-wrap gap-x-1 gap-y-0.5">
            <AnimatePresence mode="sync">
              {sectionWords.map((word, idx) => {
                const isActive = idx === activeWordIndex;
                const isPast = activeWordIndex > -1 && idx < activeWordIndex;

                return (
                  <motion.span
                    key={`${word.word}-${idx}`}
                    ref={isActive ? activeWordRef : undefined}
                    initial={{ opacity: 0.7 }}
                    animate={{
                      opacity: 1,
                      scale: isActive ? 1.05 : 1,
                      color: isActive
                        ? "hsl(var(--primary))"
                        : isPast
                          ? "hsl(var(--muted-foreground))"
                          : "hsl(var(--foreground))",
                    }}
                    transition={{ duration: 0.15 }}
                    className={cn(
                      "inline-block transition-all",
                      compact ? "text-xs" : "text-sm",
                      isActive && "font-semibold bg-primary/10 px-1 rounded",
                      isPast && "opacity-60",
                    )}
                  >
                    {word.word}
                  </motion.span>
                );
              })}
            </AnimatePresence>
          </div>
        ) : (
          <p className={cn("whitespace-pre-wrap", !lyricsText && "text-muted-foreground italic", compact ? "text-xs" : "text-sm")}>
            {lyricsText || "Нет текста для этой секции"}
          </p>
        )}
      </div>

      {/* Changed indicator */}
      {editedText !== lyricsText && editedText !== initialLyrics && (
        <div className="absolute -top-1 -right-1">
          <span className="flex h-2 w-2">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75" />
            <span className="relative inline-flex rounded-full h-2 w-2 bg-amber-500" />
          </span>
        </div>
      )}
    </div>
  );
}

