/**
 * ImportAudioDialog - Upload local audio files to the studio
 * Supports drag-and-drop and file picker
 */

import { useState, useRef, useCallback, useEffect } from "react";
import { motion, AnimatePresence } from "@/lib/motion";
import { UnifiedDialog } from "@/components/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Upload, FileAudio, Loader2, Check, X, Music } from "@/lib/icons";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { uploadFile } from "@/api/storage.api";
import { useAuth } from "@/hooks/useAuth";
import { TrackType, TRACK_COLORS } from "@/stores/useUnifiedStudioStore";
import { logger } from "@/lib/logger";
import { usePreviewAudio } from "@/hooks/audio/usePreviewAudio";
import { AudioPriority } from "@/lib/audioElementPool";

interface ImportAudioDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onImport: (audioUrl: string, name: string, type: TrackType, duration?: number) => void;
  projectId?: string;
}

const TRACK_TYPE_OPTIONS: { value: TrackType; label: string; emoji: string }[] = [
  { value: "vocal", label: "Вокал", emoji: "🎤" },
  { value: "instrumental", label: "Инструментал", emoji: "🎸" },
  { value: "drums", label: "Ударные", emoji: "🥁" },
  { value: "bass", label: "Бас", emoji: "🎸" },
  { value: "sfx", label: "Эффекты", emoji: "✨" },
  { value: "other", label: "Другое", emoji: "🎵" },
];

const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB
const ACCEPTED_TYPES = ["audio/mpeg", "audio/wav", "audio/ogg", "audio/mp4", "audio/webm", "audio/flac"];

export function ImportAudioDialog({ open, onOpenChange, onImport, projectId }: ImportAudioDialogProps) {
  const { user } = useAuth();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);

  const [isDragging, setIsDragging] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [duration, setDuration] = useState<number | null>(null);
  const [trackName, setTrackName] = useState("");
  const [trackType, setTrackType] = useState<TrackType>("other");
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isComplete, setIsComplete] = useState(false);

  // Pool-based duration probe keyed off the selected file URL.
  const { duration: probedDuration } = usePreviewAudio({
    id: audioUrl ? `import-audio-${file?.name ?? audioUrl}` : "import-audio-none",
    src: audioUrl ?? "",
    priority: AudioPriority.LOW,
  });

  useEffect(() => {
    if (probedDuration && Number.isFinite(probedDuration)) {
      setDuration(probedDuration);
    }
  }, [probedDuration, audioUrl]);

  const resetState = useCallback(() => {
    if (audioUrl) {
      URL.revokeObjectURL(audioUrl);
    }
    setFile(null);
    setAudioUrl(null);
    setDuration(null);
    setTrackName("");
    setTrackType("other");
    setIsUploading(false);
    setUploadProgress(0);
    setIsComplete(false);
    setIsDragging(false);
  }, [audioUrl]);

  const handleClose = useCallback(
    (open: boolean) => {
      if (!open) {
        resetState();
      }
      onOpenChange(open);
    },
    [onOpenChange, resetState],
  );

  const handleFileSelect = useCallback(
    (selectedFile: File) => {
      if (!ACCEPTED_TYPES.includes(selectedFile.type)) {
        toast.error("Неподдерживаемый формат файла", {
          description: "Используйте MP3, WAV, OGG, M4A, WebM или FLAC",
        });
        return;
      }

      if (selectedFile.size > MAX_FILE_SIZE) {
        toast.error("Файл слишком большой", {
          description: "Максимальный размер: 50 МБ",
        });
        return;
      }

      // Cleanup previous
      if (audioUrl) {
        URL.revokeObjectURL(audioUrl);
      }

      const url = URL.createObjectURL(selectedFile);
      setFile(selectedFile);
      setAudioUrl(url);
      setTrackName(selectedFile.name.replace(/\.[^/.]+$/, "")); // Remove extension

      // Duration is read reactively by the usePreviewAudio probe above.
    },
    [audioUrl],
  );

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      setIsDragging(false);

      const droppedFile = e.dataTransfer.files[0];
      if (droppedFile) {
        handleFileSelect(droppedFile);
      }
    },
    [handleFileSelect],
  );

  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const selectedFile = e.target.files?.[0];
      if (selectedFile) {
        handleFileSelect(selectedFile);
      }
    },
    [handleFileSelect],
  );

  const handleUpload = async () => {
    if (!file) return;

    setIsUploading(true);
    setUploadProgress(10);

    try {
      if (!user) throw new Error("Не авторизован");

      // Sanitize filename
      const sanitizedName = file.name.replace(/[^a-zA-Z0-9.-]/g, "_");
      const fileName = `${user.id}/studio/${projectId || "import"}/${Date.now()}-${sanitizedName}`;

      setUploadProgress(30);

      // Upload to storage
      const { data: uploadData, error: uploadError } = await uploadFile({
        bucket: "project-assets",
        path: fileName,
        file,
        upsert: false,
      });

      if (uploadError) {
        throw new Error(`Ошибка загрузки: ${uploadError.message}`);
      }

      setUploadProgress(80);

      // Get public URL
      const publicUrl = uploadData!.publicUrl;

      setUploadProgress(100);
      setIsComplete(true);

      logger.info("Audio imported to studio", { fileName, duration });

      // Notify parent
      onImport(publicUrl, trackName || "Imported Track", trackType, duration || undefined);

      toast.success("Аудио импортировано!");

      // Close after short delay
      setTimeout(() => {
        handleClose(false);
      }, 800);
    } catch (error) {
      const message = error instanceof Error ? error.message : "Неизвестная ошибка";
      logger.error("Import failed", { error: message });
      toast.error("Ошибка импорта", { description: message });
      setIsUploading(false);
      setUploadProgress(0);
    }
  };

  const content = (
    <div className="space-y-4">
      {/* Drop Zone */}
      {!file ? (
        <div
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
          className={cn(
            "relative flex flex-col items-center justify-center gap-3 p-8 rounded-xl border-2 border-dashed cursor-pointer transition-all",
            isDragging
              ? "border-primary bg-primary/10 scale-[1.02]"
              : "border-border/50 hover:border-primary/50 hover:bg-muted/30",
          )}
        >
          <input ref={fileInputRef} type="file" accept="audio/*" onChange={handleInputChange} className="hidden" />

          <motion.div
            animate={{ scale: isDragging ? 1.1 : 1 }}
            className={cn(
              "w-14 h-14 rounded-full flex items-center justify-center",
              isDragging ? "bg-primary text-primary-foreground" : "bg-muted",
            )}
          >
            <Upload className="w-6 h-6" />
          </motion.div>

          <div className="text-center">
            <p className="font-medium">{isDragging ? "Отпустите файл" : "Перетащите аудио сюда"}</p>
            <p className="text-sm text-muted-foreground">или нажмите для выбора файла</p>
          </div>

          <p className="text-xs text-muted-foreground">MP3, WAV, OGG, FLAC • до 50 МБ</p>
        </div>
      ) : (
        <AnimatePresence mode="wait">
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="space-y-4"
          >
            {/* Selected File Info */}
            <div className="flex items-center gap-3 p-3 rounded-lg bg-muted/50 border border-border/30">
              <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                <FileAudio className="w-5 h-5 text-primary" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="font-medium truncate">{file.name}</p>
                <p className="text-xs text-muted-foreground">
                  {(file.size / (1024 * 1024)).toFixed(1)} МБ
                  {duration && ` • ${Math.floor(duration / 60)}:${String(Math.floor(duration % 60)).padStart(2, "0")}`}
                </p>
              </div>
              {!isUploading && (
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8"
                  onClick={() => {
                    if (audioUrl) URL.revokeObjectURL(audioUrl);
                    setFile(null);
                    setAudioUrl(null);
                    setDuration(null);
                    setTrackName("");
                  }}
                >
                  <X className="w-4 h-4" />
                </Button>
              )}
            </div>

            {/* Track Name */}
            <div className="space-y-2">
              <Label htmlFor="track-name">Название дорожки</Label>
              <Input
                id="track-name"
                value={trackName}
                onChange={(e) => setTrackName(e.target.value)}
                placeholder="Введите название..."
                disabled={isUploading}
              />
            </div>

            {/* Track Type */}
            <div className="space-y-2">
              <Label>Тип дорожки</Label>
              <div className="grid grid-cols-3 gap-2">
                {TRACK_TYPE_OPTIONS.map((option) => (
                  <button
                    key={option.value}
                    type="button"
                    onClick={() => setTrackType(option.value)}
                    disabled={isUploading}
                    className={cn(
                      "flex flex-col items-center gap-1 p-2 rounded-lg border transition-all",
                      trackType === option.value
                        ? "border-primary bg-primary/10 ring-1 ring-primary/30"
                        : "border-border/50 hover:bg-muted/50",
                      isUploading && "opacity-50 cursor-not-allowed",
                    )}
                  >
                    <span className="text-lg">{option.emoji}</span>
                    <span className="text-xs">{option.label}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Upload Progress */}
            {isUploading && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-2">
                <div className="flex items-center gap-2">
                  {isComplete ? (
                    <Check className="w-4 h-4 text-green-500" />
                  ) : (
                    <Loader2 className="w-4 h-4 animate-spin text-primary" />
                  )}
                  <span className="text-sm">{isComplete ? "Готово!" : "Загрузка..."}</span>
                </div>
                <Progress value={uploadProgress} className="h-2" />
              </motion.div>
            )}

            {/* Actions */}
            {!isUploading && (
              <div className="flex gap-2 pt-2">
                <Button variant="outline" className="flex-1" onClick={() => handleClose(false)}>
                  Отмена
                </Button>
                <Button className="flex-1" onClick={handleUpload} disabled={!trackName.trim()}>
                  <Upload className="w-4 h-4 mr-2" />
                  Импортировать
                </Button>
              </div>
            )}
          </motion.div>
        </AnimatePresence>
      )}
    </div>
  );

  return (
    <UnifiedDialog
      variant="modal"
      open={open}
      onOpenChange={handleClose}
      title="Импорт аудио"
      description="Загрузите аудиофайл для добавления в проект"
      size="sm"
    >
      {content}
    </UnifiedDialog>
  );
}

/**
 * InstrumentalResultHandler
 * Dialog for handling generated instrumental results
 * Allows A/B version listening and choosing action: replace/add version/new track
 */

import { memo, useState, useCallback, useEffect } from "react";
import { motion, AnimatePresence } from "@/lib/motion";
import { cn } from "@/lib/utils";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Play, Pause, Music2, Replace, GitBranch, PlusCircle, Volume2, Check } from "@/lib/icons";
import { StudioTrackVersion } from "@/stores/useUnifiedStudioStore";
import { usePreviewAudio } from "@/hooks/audio/usePreviewAudio";
import { AudioPriority } from "@/lib/audioElementPool";

export interface InstrumentalResultData {
  newTrackId: string;
  existingInstrumentalId?: string;
  versions: StudioTrackVersion[];
  trackName?: string;
}

interface InstrumentalResultHandlerProps {
  open: boolean;
  onClose: () => void;
  data: InstrumentalResultData | null;
  onApply: (action: "replace" | "version" | "new", selectedVersionLabel: string) => void;
}

export const InstrumentalResultHandler = memo(function InstrumentalResultHandler({
  open,
  onClose,
  data,
  onApply,
}: InstrumentalResultHandlerProps) {
  const [selectedVersion, setSelectedVersion] = useState<string>("A");
  const [saveAction, setSaveAction] = useState<"replace" | "version" | "new">(
    data?.existingInstrumentalId ? "replace" : "new",
  );
  const [playingVersion, setPlayingVersion] = useState<string | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string>("");

  // Пул-аудио с динамическим src. Активно только когда previewUrl непустой.
  const { playUrl, pause } = usePreviewAudio({
    id: "instrumental-result-preview",
    src: previewUrl,
    priority: AudioPriority.MEDIUM,
    volume: 0.8,
    onEnded: () => setPlayingVersion(null),
    onError: () => setPlayingVersion(null),
  });

  // Reset state when data changes
  useEffect(() => {
    if (data) {
      setSelectedVersion(data.versions[0]?.label || "A");
      setSaveAction(data.existingInstrumentalId ? "replace" : "new");
      setPlayingVersion(null);
      setPreviewUrl("");
    }
  }, [data]);

  // Cleanup on unmount or close: гарантируем паузу.
  useEffect(() => {
    return () => {
      pause();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handlePlayVersion = useCallback(
    async (version: StudioTrackVersion) => {
      if (playingVersion === version.label) {
        // Toggle off
        pause();
        setPlayingVersion(null);
        return;
      }

      // Меняем src и запускаем через единый пул-элемент.
      setPlayingVersion(version.label);
      setPreviewUrl(version.audioUrl);
      await playUrl(version.audioUrl);
    },
    [playingVersion, pause, playUrl],
  );

  const handleApply = useCallback(() => {
    if (!data) return;

    // Stop playback
    pause();

    onApply(saveAction, selectedVersion);
  }, [data, saveAction, selectedVersion, onApply]);

  const handleClose = useCallback(() => {
    // Stop playback on close
    pause();
    onClose();
  }, [onClose, pause]);

  if (!data) return null;

  const hasExisting = !!data.existingInstrumentalId;
  const hasMultipleVersions = data.versions.length > 1;

  return (
    <Dialog open={open} onOpenChange={(o) => !o && handleClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Music2 className="w-5 h-5 text-green-400" />
            Инструментал готов!
          </DialogTitle>
          <DialogDescription>
            {hasMultipleVersions ? "Выберите версию и действие" : "Выберите что сделать с результатом"}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Version Selection */}
          {hasMultipleVersions && (
            <div className="space-y-2">
              <Label className="text-xs text-muted-foreground">Версия</Label>
              <div className="flex gap-2">
                {data.versions.map((version) => (
                  <button
                    key={version.label}
                    onClick={() => {
                      setSelectedVersion(version.label);
                      handlePlayVersion(version);
                    }}
                    className={cn(
                      "flex-1 flex items-center justify-center gap-2 p-3 rounded-lg border transition-all",
                      selectedVersion === version.label
                        ? "border-primary bg-primary/10"
                        : "border-border hover:border-primary/50",
                    )}
                  >
                    <div
                      className={cn(
                        "w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold",
                        selectedVersion === version.label
                          ? "bg-primary text-primary-foreground"
                          : "bg-muted text-muted-foreground",
                      )}
                    >
                      {version.label}
                    </div>
                    <AnimatePresence mode="wait">
                      {playingVersion === version.label ? (
                        <motion.div key="pause" initial={{ scale: 0 }} animate={{ scale: 1 }} exit={{ scale: 0 }}>
                          <Pause className="w-4 h-4 text-green-400" />
                        </motion.div>
                      ) : (
                        <motion.div key="play" initial={{ scale: 0 }} animate={{ scale: 1 }} exit={{ scale: 0 }}>
                          <Play className="w-4 h-4" />
                        </motion.div>
                      )}
                    </AnimatePresence>
                    {selectedVersion === version.label && <Check className="w-4 h-4 text-primary ml-auto" />}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Single version play button */}
          {!hasMultipleVersions && data.versions[0] && (
            <div className="flex justify-center">
              <Button variant="outline" size="lg" onClick={() => handlePlayVersion(data.versions[0])} className="gap-2">
                {playingVersion === data.versions[0].label ? (
                  <>
                    <Pause className="w-5 h-5" />
                    Пауза
                  </>
                ) : (
                  <>
                    <Play className="w-5 h-5" />
                    Прослушать
                  </>
                )}
              </Button>
            </div>
          )}

          {/* Action Selection */}
          <div className="space-y-2">
            <Label className="text-xs text-muted-foreground">Действие</Label>
            <RadioGroup
              value={saveAction}
              onValueChange={(v) => setSaveAction(v as typeof saveAction)}
              className="space-y-2"
            >
              {/* Replace option - only if existing instrumental */}
              {hasExisting && (
                <label
                  htmlFor="action-replace"
                  className={cn(
                    "flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all",
                    saveAction === "replace" ? "border-primary bg-primary/5" : "border-border hover:border-primary/50",
                  )}
                >
                  <RadioGroupItem value="replace" id="action-replace" className="mt-0.5" />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <Replace className="w-4 h-4 text-orange-400" />
                      <span className="font-medium text-sm">Заменить текущий</span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">Заменит аудио текущего инструментала</p>
                  </div>
                </label>
              )}

              {/* Add as version - only if existing instrumental */}
              {hasExisting && (
                <label
                  htmlFor="action-version"
                  className={cn(
                    "flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all",
                    saveAction === "version" ? "border-primary bg-primary/5" : "border-border hover:border-primary/50",
                  )}
                >
                  <RadioGroupItem value="version" id="action-version" className="mt-0.5" />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <GitBranch className="w-4 h-4 text-blue-400" />
                      <span className="font-medium text-sm">Добавить как версию</span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">Сохранит оригинал, добавит новую версию</p>
                  </div>
                </label>
              )}

              {/* Create new track */}
              <label
                htmlFor="action-new"
                className={cn(
                  "flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all",
                  saveAction === "new" ? "border-primary bg-primary/5" : "border-border hover:border-primary/50",
                )}
              >
                <RadioGroupItem value="new" id="action-new" className="mt-0.5" />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <PlusCircle className="w-4 h-4 text-green-400" />
                    <span className="font-medium text-sm">
                      {hasExisting ? "Создать новый трек" : "Добавить в проект"}
                    </span>
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {hasExisting ? "Добавит как отдельную дорожку" : "Добавит инструментал в проект"}
                  </p>
                </div>
              </label>
            </RadioGroup>
          </div>
        </div>

        <DialogFooter className="gap-2 sm:gap-0">
          <Button variant="outline" onClick={handleClose}>
            Отмена
          </Button>
          <Button onClick={handleApply} className="gap-2">
            <Check className="w-4 h-4" />
            Применить
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
});

