}) {
  if (sections.length === 0) return null;

  const getSectionIcon = (type: LyricsSection["type"]) => {
    switch (type) {
      case "verse":
        return <BookOpen className="w-3.5 h-3.5" />;
      case "chorus":
        return <Sparkles className="w-3.5 h-3.5" />;
      default:
        return <Hash className="w-3.5 h-3.5" />;
