  };

  const getSectionColor = (type: LyricsSection["type"]) => {
    switch (type) {
      case "verse":
        return "text-blue-500 bg-blue-500/10";
      case "chorus":
        return "text-purple-500 bg-purple-500/10";
      case "bridge":
        return "text-amber-500 bg-amber-500/10";
      default:
        return "text-muted-foreground bg-muted/50";
