export const LyricsPanel = memo(function LyricsPanel({
  trackId,
  initialLyrics = "",
  isOpen,
  onClose,
  onLyricsSaved,
}: LyricsPanelProps) {
  const { hapticFeedback } = useTelegram();
  const { user } = useAuth();

  // State
  const [lyrics, setLyrics] = useState(initialLyrics);
  const [viewMode, setViewMode] = useState<ViewMode>("editor");
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [selectedSectionIndex, setSelectedSectionIndex] = useState<number>(-1);

  // Queries and Mutations
  const { data: versionsData, isLoading: versionsLoading } = useLyricVersions(trackId);
  const { createVersion, isCreating } = useCreateLyricVersion();
  const { restoreVersion, isRestoring } = useRestoreLyricVersion();

  // Format lyrics for section detection
  const formattedLyrics = useMemo<FormattedLyrics>(() => {
    return formatLyricsForDisplay(lyrics);
  }, [lyrics]);

  // Calculate statistics
  const stats = useMemo<LyricsStats>(() => {
    const statistics = getLyricsStatistics(lyrics);
    return {
      wordCount: statistics.wordCount,
      lineCount: statistics.lineCount,
      characterCount: statistics.characterCount,
      sectionsCount: statistics.sectionsCount,
    };
  }, [lyrics]);

  // Update lyrics when initialLyrics changes
  useEffect(() => {
    if (initialLyrics && initialLyrics !== lyrics) {
      setLyrics(initialLyrics);
    }
  }, [initialLyrics]);

  // Handle save lyrics
  const handleSave = useCallback(async () => {
    if (!user?.id) {
      toast.error("Не авторизован");
      return;
    }

    hapticFeedback("success");
    setIsSaving(true);

    try {
      await createVersion(
        {
          trackId,
          request: {
            content: lyrics,
            changeType: "manual_edit",
            changeSummary: "Изменено через панель текста",
          },
        },
        {
          onSuccess: () => {
            setLastSaved(new Date());
            onLyricsSaved?.(lyrics);
            toast.success("Текст сохранён", {
              description: `${stats.wordCount} слов, ${stats.sectionsCount} секций`,
            });
          },
        },
      );
    } catch (error) {
      logger.error("Failed to save lyrics", error);
      toast.error("Не удалось сохранить текст");
    } finally {
      setIsSaving(false);
    }
  }, [trackId, lyrics, user, createVersion, hapticFeedback, stats, onLyricsSaved]);

  // Handle restore version
  const handleRestoreVersion = useCallback(
    async (versionId: string) => {
      hapticFeedback("medium");
      try {
        const result = await restoreVersion({ versionId });
        setLyrics(result.restoredVersion.content);
        toast.success("Версия восстановлена", {
          description: `Версия ${result.restoredVersion.versionNumber}`,
        });
        setViewMode("editor");
      } catch (error) {
        logger.error("Failed to restore version", error);
        toast.error("Не удалось восстановить версию");
      }
    },
    [restoreVersion, hapticFeedback],
  );

  // Handle section marker click
  const handleSectionClick = useCallback(
    (section: LyricsSection) => {
      hapticFeedback("selection");
      const lines = lyrics.split("\n");
      const targetLine = lines[section.startIndex];

      // Scroll to section in textarea
      const textarea = document.querySelector("textarea[data-lyrics-editor]");
      if (textarea) {
        const lineHeight = 24; // Approximate line height
        const scrollTop = section.startIndex * lineHeight;
        (textarea as HTMLTextAreaElement).scrollTop = scrollTop;
      }

      setSelectedSectionIndex(section.startIndex);
    },
    [lyrics, hapticFeedback],
  );

  // Handle AI assistant
  const handleAIAssistant = useCallback(() => {
    hapticFeedback("light");
    toast.info("AI-ассистент в разработке", {
      description: "Скоро сможете улучшать текст с помощью ИИ",
    });
  }, [hapticFeedback]);

  // Handle textarea change with auto-resize
  const handleTextareaChange = useCallback((e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setLyrics(value);

    // Auto-resize textarea
    const textarea = e.target;
    textarea.style.height = "auto";
    textarea.style.height = `${textarea.scrollHeight}px`;
  }, []);

  return (
    <Sheet open={isOpen} onOpenChange={onClose}>
      <SheetContent side="bottom" className="h-[90dvh] rounded-t-2xl p-0 gap-0" hideCloseButton>
        {/* Header */}
        <PanelHeader stats={stats} viewMode={viewMode} onViewModeChange={setViewMode} onClose={onClose} />

        {/* Content */}
        <AnimatePresence mode="wait">
          {viewMode === "editor" && (
            <motion.div
              key="editor"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className="flex flex-col h-full"
            >
              {/* Section Markers */}
              <SectionMarkers sections={formattedLyrics.sections} onSectionClick={handleSectionClick} />

              {/* Textarea */}
              <div className="flex-1 px-4 py-3">
                <Textarea
                  data-lyrics-editor
                  value={lyrics}
                  onChange={handleTextareaChange}
                  placeholder="[Verse 1]&#10;&#10;Введите текст песни здесь...&#10;&#10;Используйте разметку секций: [Verse], [Chorus], [Bridge], [Outro]"
                  className="w-full min-h-full resize-none border-0 focus-visible:ring-0 text-sm leading-relaxed p-0"
                  style={{
                    fieldSizing: "content",
                  }}
                />
              </div>

              {/* Action Bar */}
              <div className="flex items-center gap-2 px-4 py-3 border-t border-border/30 bg-muted/30 safe-bottom">
                <Button variant="outline" size="sm" onClick={handleAIAssistant} className="flex-1 h-11">
                  <Sparkles className="w-4 h-4 mr-2" />
                  AI-ассистент
                </Button>

                <Button
                  size="sm"
                  onClick={handleSave}
                  disabled={isSaving || isCreating}
                  className="flex-1 h-11 min-h-11"
                >
                  {isSaving || isCreating ? (
                    <>
                      <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                      Сохранение...
                    </>
                  ) : (
                    <>
                      <Save className="w-4 h-4 mr-2" />
                      Сохранить
                    </>
                  )}
                </Button>
              </div>

              {/* Last saved indicator */}
              {lastSaved && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="px-4 pb-2 text-center"
                >
                  <p className="text-xs text-muted-foreground flex items-center justify-center gap-1">
                    <Clock className="w-3 h-3" />
                    Сохранено{" "}
                    {lastSaved.toLocaleTimeString("ru-RU", {
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </p>
                </motion.div>
              )}
            </motion.div>
          )}

          {viewMode === "history" && (
            <motion.div
              key="history"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className="flex flex-col h-full"
            >
              {versionsLoading ? (
                <div className="flex-1 flex items-center justify-center">
                  <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
                </div>
              ) : (
                <VersionHistoryView
                  versions={versionsData?.versions || []}
                  onRestore={handleRestoreVersion}
                  isRestoring={isRestoring}
                  onClose={() => setViewMode("editor")}
                />
              )}
            </motion.div>
          )}

          {viewMode === "notes" && (
            <motion.div
              key="notes"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className="flex flex-col h-full"
            >
              <SectionNotesView trackId={trackId} onClose={() => setViewMode("editor")} />
            </motion.div>
          )}
        </AnimatePresence>
      </SheetContent>
    </Sheet>
  );
});

/**
 * SaveVersionDialog
 * Dialog for saving current studio mix as a new track version
 */

import { memo, useState, useCallback } from "react";
import { Save, Loader2, Volume2, Layers, Download, Check, AlertCircle } from "@/lib/icons";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Progress } from "@/components/ui/progress";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { ensureTrackVersion, invokeMergeStems } from "@/api/studio.api";
import type { StudioTrack } from "@/stores/useUnifiedStudioStore";
import { logger } from "@/lib/logger";

interface SaveVersionDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  projectId: string;
  sourceTrackId?: string;
  tracks: StudioTrack[];
  masterVolume: number;
  onVersionSaved?: (version: { id: string; audioUrl: string; label: string }) => void;
}

type SaveMode = "snapshot" | "merge" | "export";

export const SaveVersionDialog = memo(function SaveVersionDialog({
  open,
  onOpenChange,
  projectId,
  sourceTrackId,
  tracks,
  masterVolume,
  onVersionSaved,
}: SaveVersionDialogProps) {
  const [mode, setMode] = useState<SaveMode>("snapshot");
  const [versionLabel, setVersionLabel] = useState("");
  const [description, setDescription] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const defaultLabel = `Version ${String.fromCharCode(65 + Math.floor(Math.random() * 26))}`;

  const handleSave = useCallback(async () => {
    if (!sourceTrackId) {
      toast.error("Нет исходного трека");
      return;
    }

    setIsSaving(true);
    setProgress(10);
    setError(null);

    try {
      const label = versionLabel.trim() || defaultLabel;

      if (mode === "snapshot") {
        setProgress(30);

        const mainTrack = tracks.find((t) => t.type === "main") || tracks[0];
        const audioUrl = mainTrack?.audioUrl || mainTrack?.clips?.[0]?.audioUrl;

        if (!audioUrl) {
          throw new Error("Нет аудио для сохранения");
        }

        setProgress(50);

        // Use ensure_track_version RPC which handles duplicates
        const versionId = await ensureTrackVersion({
          trackId: sourceTrackId,
          audioUrl,
          label,
          versionType: "snapshot",
        });

        setProgress(100);
        toast.success("Версия сохранена");

        // BUGFIX: Don't call onVersionSaved to avoid duplicate version creation
        // The realtime listener in useProjectTrackSync will handle syncing
        // Just close the dialog - version is already saved to DB
        onOpenChange(false);
      } else if (mode === "merge") {
        setProgress(20);

        const stemsToMerge = tracks
          .filter((t) => t.status !== "pending" && t.status !== "failed")
          .map((t) => ({
            audioUrl: t.audioUrl || t.clips?.[0]?.audioUrl,
            volume: t.muted ? 0 : t.volume,
            pan: t.pan,
            solo: t.solo,
          }))
          .filter((s) => s.audioUrl);

        if (stemsToMerge.length === 0) {
          throw new Error("Нет стемов для объединения");
        }

        setProgress(40);

        const { data, error: mergeError } = await invokeMergeStems({
          stems: stemsToMerge,
          masterVolume,
          trackId: sourceTrackId,
          versionLabel: label,
          projectId,
        });

        if (mergeError) throw mergeError;
        if (!data?.audioUrl) throw new Error("merge-stems не вернул audioUrl");

        setProgress(80);

        const versionId = await ensureTrackVersion({
          trackId: sourceTrackId,
          audioUrl: data.audioUrl,
          label,
          versionType: "merged",
        });

        setProgress(100);
        toast.success("Микс сохранён как новая версия");
        onVersionSaved?.({
          id: versionId,
          audioUrl: data.audioUrl,
          label,
        });
        onOpenChange(false);
      } else if (mode === "export") {
        setProgress(20);

        const stemsToMerge = tracks
          .filter((t) => t.status !== "pending" && t.status !== "failed")
          .map((t) => ({
            audioUrl: t.audioUrl || t.clips?.[0]?.audioUrl,
            volume: t.muted ? 0 : t.volume,
            pan: t.pan,
            solo: t.solo,
          }))
          .filter((s) => s.audioUrl);

        setProgress(40);

        const { data, error: mergeError } = await invokeMergeStems({
          stems: stemsToMerge,
          masterVolume,
          format: "wav",
        });

        if (mergeError) throw mergeError;
        if (!data?.audioUrl) throw new Error("merge-stems не вернул audioUrl");

        setProgress(80);

        const response = await fetch(data.audioUrl);
        const blob = await response.blob();
        const url = URL.createObjectURL(blob);

        const a = document.createElement("a");
        a.href = url;
        a.download = `${label || "mix"}.wav`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        setProgress(100);
        toast.success("Микс экспортирован");
        onOpenChange(false);
      }
    } catch (err: unknown) {
      logger.error("Save version error", err instanceof Error ? err : new Error(String(err)));
      const message = err instanceof Error ? err.message : "Ошибка сохранения";
      setError(message);
      toast.error(message);
    } finally {
      setIsSaving(false);
      setProgress(0);
    }
  }, [
    mode,
    versionLabel,
    description,
    tracks,
    masterVolume,
    sourceTrackId,
    projectId,
    onVersionSaved,
    onOpenChange,
    defaultLabel,
  ]);

  const stemCount = tracks.filter(
    (t) => ["vocal", "instrumental", "drums", "bass", "other"].includes(t.type) && t.status !== "pending",
  ).length;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Save className="w-5 h-5" />
            Сохранить версию
          </DialogTitle>
          <DialogDescription>Сохраните текущее состояние как новую версию трека</DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <RadioGroup value={mode} onValueChange={(v) => setMode(v as SaveMode)}>
            <div className="space-y-3">
              <div
                className={cn(
                  "flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors",
                  mode === "snapshot" ? "border-primary bg-primary/5" : "border-border hover:border-primary/50",
                )}
                onClick={() => setMode("snapshot")}
              >
                <RadioGroupItem value="snapshot" id="snapshot" className="mt-0.5" />
                <div className="flex-1">
                  <Label htmlFor="snapshot" className="font-medium cursor-pointer">
                    Сохранить snapshot
                  </Label>
                  <p className="text-xs text-muted-foreground mt-0.5">Сохранить текущий основной аудио как версию</p>
                </div>
                <Layers className="w-4 h-4 text-muted-foreground" />
              </div>

              <div
                className={cn(
                  "flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors",
                  mode === "merge" ? "border-primary bg-primary/5" : "border-border hover:border-primary/50",
                  stemCount === 0 && "opacity-50 cursor-not-allowed",
                )}
                onClick={() => stemCount > 0 && setMode("merge")}
              >
                <RadioGroupItem value="merge" id="merge" className="mt-0.5" disabled={stemCount === 0} />
                <div className="flex-1">
                  <Label
                    htmlFor="merge"
                    className={cn("font-medium", stemCount === 0 ? "cursor-not-allowed" : "cursor-pointer")}
                  >
                    Объединить стемы
                  </Label>
                  <p className="text-xs text-muted-foreground mt-0.5">Смикшировать {stemCount} стемов в одно аудио</p>
                </div>
                <Volume2 className="w-4 h-4 text-muted-foreground" />
              </div>

              <div
                className={cn(
                  "flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors",
                  mode === "export" ? "border-primary bg-primary/5" : "border-border hover:border-primary/50",
                  stemCount === 0 && "opacity-50 cursor-not-allowed",
                )}
                onClick={() => stemCount > 0 && setMode("export")}
              >
                <RadioGroupItem value="export" id="export" className="mt-0.5" disabled={stemCount === 0} />
                <div className="flex-1">
                  <Label
                    htmlFor="export"
                    className={cn("font-medium", stemCount === 0 ? "cursor-not-allowed" : "cursor-pointer")}
                  >
                    Экспорт мастера
                  </Label>
                  <p className="text-xs text-muted-foreground mt-0.5">Скачать микс как WAV (без создания версии)</p>
                </div>
                <Download className="w-4 h-4 text-muted-foreground" />
              </div>
            </div>
          </RadioGroup>

          {mode !== "export" && (
            <div className="space-y-2">
              <Label htmlFor="versionLabel">Название версии</Label>
              <Input
                id="versionLabel"
                placeholder={defaultLabel}
                value={versionLabel}
                onChange={(e) => setVersionLabel(e.target.value)}
              />
            </div>
          )}

          {mode !== "export" && (
            <div className="space-y-2">
              <Label htmlFor="description">Описание (опционально)</Label>
              <Textarea
                id="description"
                placeholder="Например: После редактирования вокала"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={2}
              />
            </div>
          )}

          {isSaving && (
            <div className="space-y-2">
              <div className="flex justify-between text-sm">
                <span className="flex items-center gap-2">
                  <Loader2 className="w-4 h-4 animate-spin" />
                  {mode === "merge" ? "Микширование..." : mode === "export" ? "Экспорт..." : "Сохранение..."}
                </span>
                <span>{progress}%</span>
              </div>
              <Progress value={progress} className="h-2" />
            </div>
          )}

          {error && (
            <div className="flex items-center gap-2 text-destructive text-sm">
              <AlertCircle className="w-4 h-4" />
              {error}
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isSaving}>
            Отмена
          </Button>
          <Button onClick={handleSave} disabled={isSaving}>
            {isSaving ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : mode === "export" ? (
              <Download className="w-4 h-4 mr-2" />
            ) : (
              <Check className="w-4 h-4 mr-2" />
            )}
            {mode === "export" ? "Скачать" : "Сохранить"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
});

