import { useState, useEffect } from "react";
import { UnifiedDialog } from "@/components/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import type { Track } from "@/types/track";
import { updateTrack } from "@/api/tracks.api";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { invalidateTrack } from "@/lib/query-utils";

interface RenameTrackDialogProps {
  track: Track;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function RenameTrackDialog({ track, open, onOpenChange }: RenameTrackDialogProps) {
  const [title, setTitle] = useState(track.title || "");
  const [isLoading, setIsLoading] = useState(false);
  const queryClient = useQueryClient();

  useEffect(() => {
    if (open) {
      setTitle(track.title || "");
    }
  }, [open, track.title]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      toast.error("Введите название трека");
      return;
    }

    if (trimmedTitle === track.title) {
      onOpenChange(false);
      return;
    }

    setIsLoading(true);
    try {
      await updateTrack(track.id, { title: trimmedTitle });

      // Invalidate all track-related queries for immediate UI update
      invalidateTrack(queryClient, track.id);

      // Invalidate tracks list queries (with and without filters)
      await queryClient.invalidateQueries({
        queryKey: ["tracks"],
        refetchType: "all",
      });

      // Invalidate public tracks if applicable
      queryClient.invalidateQueries({ queryKey: ["public-tracks"] });

      toast.success("Трек переименован");
      onOpenChange(false);
    } catch (error) {
      toast.error("Не удалось переименовать трек");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <UnifiedDialog variant="modal" open={open} onOpenChange={onOpenChange} title="Переименовать трек" size="md">
      <form onSubmit={handleSubmit}>
        <div className="space-y-3 py-3">
          <Label htmlFor="track-title">Название</Label>
          <Input
            id="track-title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Название трека"
            autoFocus
            maxLength={200}
          />
        </div>
        <div className="flex justify-end gap-2 sm:gap-0">
          <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={isLoading}>
            Отмена
          </Button>
          <Button type="submit" disabled={isLoading || !title.trim()}>
            {isLoading ? "Сохранение..." : "Сохранить"}
          </Button>
        </div>
      </form>
    </UnifiedDialog>
  );
}

