/**
 * Hook for fetching retention cohorts data
 * Uses the get_retention_cohorts RPC function
 */

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { logger } from "@/lib/logger";

export interface RetentionCohort {
  cohort_date: string;
  cohort_size: number;
  d1_retained: number;
  d7_retained: number;
  d14_retained: number;
  d30_retained: number;
  d1_rate: number;
  d7_rate: number;
  d14_rate: number;
  d30_rate: number;
}

interface UseRetentionCohortsOptions {
  startDate?: Date;
  endDate?: Date;
  enabled?: boolean;
}

export function useRetentionCohorts(options: UseRetentionCohortsOptions = {}) {
  const { startDate = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), endDate = new Date(), enabled = true } = options;

  return useQuery({
    queryKey: ["retention-cohorts", startDate.toISOString(), endDate.toISOString()],
    queryFn: async (): Promise<RetentionCohort[]> => {
      const { data, error } = await supabase.rpc("get_retention_cohorts", {
        start_date: startDate.toISOString().split("T")[0],
        end_date: endDate.toISOString().split("T")[0],
      });

      if (error) {
        logger.error("Failed to fetch retention cohorts", error);
        throw error;
      }

      return (data || []) as RetentionCohort[];
    },
    enabled,
    staleTime: 5 * 60 * 1000, // 5 minutes
    gcTime: 30 * 60 * 1000, // 30 minutes
  });
}

/**
 * Calculate average retention rates across all cohorts
 */
export function calculateAverageRetention(cohorts: RetentionCohort[]) {
  if (!cohorts.length) {
    return { d1: 0, d7: 0, d14: 0, d30: 0 };
  }

  const totalCohortSize = cohorts.reduce((sum, c) => sum + c.cohort_size, 0);

  // Weighted average by cohort size
  const d1 = cohorts.reduce((sum, c) => sum + (c.d1_rate || 0) * c.cohort_size, 0) / totalCohortSize;
  const d7 = cohorts.reduce((sum, c) => sum + (c.d7_rate || 0) * c.cohort_size, 0) / totalCohortSize;
  const d14 = cohorts.reduce((sum, c) => sum + (c.d14_rate || 0) * c.cohort_size, 0) / totalCohortSize;
  const d30 = cohorts.reduce((sum, c) => sum + (c.d30_rate || 0) * c.cohort_size, 0) / totalCohortSize;

  return {
    d1: Math.round(d1 * 10) / 10,
    d7: Math.round(d7 * 10) / 10,
    d14: Math.round(d14 * 10) / 10,
    d30: Math.round(d30 * 10) / 10,
  };
}

/**
 * useFeatureUsageTracking - Track feature engagement metrics
 *
 * Provides utilities for tracking how users interact with specific features.
 * Useful for A/B testing, feature adoption analysis, and UX improvements.
 */

import { useCallback, useRef, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { trackFeatureUsed, trackEvent } from "@/services/analytics";
import { logger } from "@/lib/logger";

export type FeatureCategory = "generation" | "studio" | "library" | "player" | "social" | "settings" | "onboarding";

export interface FeatureUsageEvent {
  feature: string;
  category: FeatureCategory;
  action: "view" | "click" | "complete" | "error" | "abandon";
  metadata?: Record<string, unknown>;
  duration?: number;
}

interface FeatureSession {
  startTime: number;
  feature: string;
  category: FeatureCategory;
}

/**
 * Hook for tracking feature usage with session timing
 */
export function useFeatureUsageTracking() {
  const { user } = useAuth();
  const activeSession = useRef<FeatureSession | null>(null);

  /**
   * Track a feature usage event
   */
  const trackFeature = useCallback(
    async (event: FeatureUsageEvent) => {
      try {
        await trackFeatureUsed(
          event.feature,
          {
            category: event.category,
            action: event.action,
            duration: event.duration,
            ...event.metadata,
          },
          user?.id,
        );
      } catch (error) {
        // Silent fail - analytics shouldn't break the app
        logger.debug("[FeatureTracking] Error", { error: error instanceof Error ? error.message : String(error) });
      }
    },
    [user?.id],
  );

  /**
   * Start a feature session (for timing)
   */
  const startFeatureSession = useCallback(
    (feature: string, category: FeatureCategory) => {
      activeSession.current = {
        startTime: Date.now(),
        feature,
        category,
      };

      trackFeature({
        feature,
        category,
        action: "view",
      });
    },
    [trackFeature],
  );

  /**
   * End a feature session and track duration
   */
  const endFeatureSession = useCallback(
    (action: "complete" | "abandon" = "complete", metadata?: Record<string, unknown>) => {
      if (!activeSession.current) return;

      const duration = Date.now() - activeSession.current.startTime;

      trackFeature({
        feature: activeSession.current.feature,
        category: activeSession.current.category,
        action,
        duration,
        metadata,
      });

      activeSession.current = null;
    },
    [trackFeature],
  );

  /**
   * Track a quick action (no session needed)
   */
  const trackAction = useCallback(
    (
      feature: string,
      category: FeatureCategory,
      action: "click" | "complete" | "error",
      metadata?: Record<string, unknown>,
    ) => {
      trackFeature({ feature, category, action, metadata });
    },
    [trackFeature],
  );

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (activeSession.current) {
        endFeatureSession("abandon");
      }
    };
  }, [endFeatureSession]);

  return {
    trackFeature,
    trackAction,
    startFeatureSession,
    endFeatureSession,
    hasActiveSession: !!activeSession.current,
  };
}

/**
 * Predefined feature tracking events
 */
export const FeatureEvents = {
  // Generation
  GENERATION_STARTED: (mode: string) => ({
    feature: "generation",
    category: "generation" as FeatureCategory,
    action: "click" as const,
    metadata: { mode },
  }),
  GENERATION_COMPLETED: (duration: number, success: boolean) => ({
    feature: "generation",
    category: "generation" as FeatureCategory,
    action: success ? ("complete" as const) : ("error" as const),
    duration,
  }),
  PRESET_USED: (presetId: string) => ({
    feature: "quick_preset",
    category: "generation" as FeatureCategory,
    action: "click" as const,
    metadata: { presetId },
  }),

  // Studio
  STUDIO_OPENED: (source: string) => ({
    feature: "studio",
    category: "studio" as FeatureCategory,
    action: "view" as const,
    metadata: { source },
  }),
  STEM_SEPARATION: (mode: "simple" | "detailed") => ({
    feature: "stem_separation",
    category: "studio" as FeatureCategory,
    action: "click" as const,
    metadata: { mode },
  }),
  RECORDING_STARTED: (type: string) => ({
    feature: "recording",
    category: "studio" as FeatureCategory,
    action: "click" as const,
    metadata: { type },
  }),

  // Library
  TRACK_PLAYED: (source: string) => ({
    feature: "playback",
    category: "library" as FeatureCategory,
    action: "click" as const,
    metadata: { source },
  }),
  SWIPE_ACTION: (action: string) => ({
    feature: "swipe_gesture",
    category: "library" as FeatureCategory,
    action: "click" as const,
    metadata: { swipeAction: action },
  }),

  // Player
  PLAYER_EXPANDED: () => ({
    feature: "player_expand",
    category: "player" as FeatureCategory,
    action: "click" as const,
  }),
  QUEUE_MODIFIED: (action: "add" | "remove" | "reorder") => ({
    feature: "queue",
    category: "player" as FeatureCategory,
    action: "click" as const,
    metadata: { queueAction: action },
  }),

  // Social
  TRACK_SHARED: (platform: string) => ({
    feature: "share",
    category: "social" as FeatureCategory,
    action: "complete" as const,
    metadata: { platform },
  }),
  TRACK_LIKED: () => ({
    feature: "like",
    category: "social" as FeatureCategory,
    action: "click" as const,
  }),

  // Onboarding
  ONBOARDING_STEP: (step: number, action: "view" | "complete" | "abandon") => ({
    feature: "onboarding",
    category: "onboarding" as FeatureCategory,
    action,
    metadata: { step },
  }),
  TIP_SHOWN: (tipId: string) => ({
    feature: "contextual_tip",
    category: "onboarding" as FeatureCategory,
    action: "view" as const,
    metadata: { tipId },
  }),
  TIP_DISMISSED: (tipId: string) => ({
    feature: "contextual_tip",
    category: "onboarding" as FeatureCategory,
    action: "complete" as const,
    metadata: { tipId },
  }),
};

export default useFeatureUsageTracking;

import { useEffect } from "react";
import type { RefObject, MutableRefObject } from "react";
import { clampPlayerVolume, usePlayerStore } from "@/hooks/audio/usePlayerState";
import { setGlobalAudioRef } from "@/hooks/audio/useAudioTime";
import { logAudioDiagnostics } from "@/lib/audioFormatUtils";
import { logger } from "@/lib/logger";

interface AudioInitOptions {
  audioRef: MutableRefObject<HTMLAudioElement | null>;
  initialVolume: number;
  isMobileBrowser: boolean;
  mobileBrowserInfo: RefObject<{ browserName: string; osName: string }>;
}

export function useAudioInit({ audioRef, initialVolume, isMobileBrowser, mobileBrowserInfo }: AudioInitOptions) {
  useEffect(() => {
    const storedActiveTrack = usePlayerStore.getState().activeTrack;
    if (
      storedActiveTrack &&
      !storedActiveTrack.audio_url &&
      !storedActiveTrack.streaming_url &&
      !storedActiveTrack.local_audio_url
    ) {
      logger.info("Clearing invalid track from localStorage on startup", {
        trackId: storedActiveTrack.id,
        title: storedActiveTrack.title,
        status: storedActiveTrack.status,
      });
      usePlayerStore.getState().closePlayer();
    }

    try {
      const oldPlayerData = localStorage.getItem("player-storage");
      if (oldPlayerData) {
        localStorage.removeItem("player-storage");
        logger.info("Removed legacy player-storage from localStorage");
      }
    } catch {
      // Ignore localStorage errors
    }

    if (!audioRef.current) {
      audioRef.current = new Audio();
      audioRef.current.preload = "auto";
      audioRef.current.volume = clampPlayerVolume(initialVolume);
      audioRef.current.muted = false;

      logger.info("Audio element initialized", {
        volume: audioRef.current.volume,
        muted: audioRef.current.muted,
        readyState: audioRef.current.readyState,
        isMobile: isMobileBrowser,
        browser: mobileBrowserInfo.current?.browserName,
        os: mobileBrowserInfo.current?.osName,
      });

      if (isMobileBrowser) {
        logAudioDiagnostics();
      }

      setGlobalAudioRef(audioRef.current);
    }

    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
        // Don't set src="" — causes "Empty src attribute" error on some browsers
        audioRef.current.removeAttribute("src");
        audioRef.current.load();
        logger.debug("Audio element cleaned up");
      }
    };
  }, []); // intentionally empty — init runs once only
}

import { useEffect } from "react";
import type { MutableRefObject } from "react";
import type { Track } from "@/types/track";
import { clampPlayerVolume } from "@/hooks/audio/usePlayerState";
import { logger } from "@/lib/logger";
import { toast } from "@/lib/toast";
import { playerAnalytics } from "@/lib/telemetry";

interface AudioPlaybackOptions {
  audioRef: MutableRefObject<HTMLAudioElement | null>;
  isLoadingRef: MutableRefObject<boolean>;
  isPlayingRef: MutableRefObject<boolean>;
  playPromiseRef: MutableRefObject<Promise<void> | null>;
  isPlaying: boolean;
  activeTrack: Track | null;
  volume: number;
  /** Bumped when the same track must be reloaded (e.g. A/B version switch) */
  loadNonce?: number;
  pauseTrack: () => void;
  isStartupPeriod: () => boolean;
}

export function useAudioPlayback({
  audioRef,
  isLoadingRef,
  isPlayingRef,
  playPromiseRef,
  isPlaying,
  activeTrack,
  volume,
  loadNonce = 0,
  pauseTrack,
  isStartupPeriod,
}: AudioPlaybackOptions) {
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio || !audio.src) return;

    let isCleanedUp = false;
    let playTimeoutId: NodeJS.Timeout | null = null;

    const attemptPlay = async () => {
      if (isCleanedUp) return;

      if (isLoadingRef.current) {
        logger.debug("Waiting for audio to load before playing");
        const waitForLoad = new Promise<void>((resolve) => {
          const checkReady = () => {
            if (!isLoadingRef.current || audio.readyState >= 2) {
              resolve();
              return;
            }
            setTimeout(checkReady, 50);
          };
          checkReady();
        });
        await Promise.race([waitForLoad, new Promise((resolve) => setTimeout(resolve, 3000))]);
      }

      logger.debug("Attempting to play", {
        trackId: activeTrack?.id,
        readyState: audio.readyState,
        volume: audio.volume,
        muted: audio.muted,
        paused: audio.paused,
      });

      const safeVolume = clampPlayerVolume(volume);
      if (audio.volume !== safeVolume) audio.volume = safeVolume;
      if (audio.muted) audio.muted = false;

      try {
        const { resumeAudioContext, ensureAudioRoutedToDestination } = await import("@/lib/audioContextManager");
        const contextResumed = await resumeAudioContext(3);
        if (!contextResumed) await ensureAudioRoutedToDestination();
      } catch {
        logger.warn("AudioContext resume issue");
      }

      if (playPromiseRef.current) {
        try {
          await playPromiseRef.current;
        } catch {
          /* ignore */
        }
        playPromiseRef.current = null;
      }

      try {
        playPromiseRef.current = audio.play();
        await playPromiseRef.current;
        logger.info("Playback started successfully", { trackId: activeTrack?.id });
        playerAnalytics.trackPlay(activeTrack?.id || "", "global_provider");
      } catch (error: unknown) {
        const err = error as { name?: string };
        if (err.name === "AbortError" || isCleanedUp) return;
        logger.error("Playback failed", error, { errorName: err.name, trackId: activeTrack?.id });
        if (err.name === "NotAllowedError" && !isStartupPeriod()) {
          toast.error("Воспроизведение заблокировано", { description: "Нажмите на экран и попробуйте снова" });
        } else if (err.name === "NotSupportedError" && !isStartupPeriod()) {
          toast.error("Формат аудио не поддерживается");
        }
        pauseTrack();
      } finally {
        playPromiseRef.current = null;
      }
    };

    if (isPlaying) {
      if (audio.readyState >= 2 && !isLoadingRef.current) {
        attemptPlay();
      } else {
        const handleCanPlay = () => {
          if (!isCleanedUp && isPlayingRef.current) attemptPlay();
          audio.removeEventListener("canplay", handleCanPlay);
        };
        audio.addEventListener("canplay", handleCanPlay);

        playTimeoutId = setTimeout(() => {
          audio.removeEventListener("canplay", handleCanPlay);
          if (!isCleanedUp && isPlayingRef.current && audio.src) {
            isLoadingRef.current = false;
            attemptPlay();
          }
        }, 5000);

        return () => {
          isCleanedUp = true;
          audio.removeEventListener("canplay", handleCanPlay);
          if (playTimeoutId) clearTimeout(playTimeoutId);
        };
      }
    } else {
      playPromiseRef.current = null;
      audio.pause();
    }

    return () => {
      isCleanedUp = true;
      if (playTimeoutId) clearTimeout(playTimeoutId);
    };
  }, [isPlaying, activeTrack?.id, loadNonce, volume, pauseTrack, isStartupPeriod]);
}

