/**
 * Audio Time Hook
 *
 * Subscribes to current audio time updates from global audio element.
 * Optimized to avoid unnecessary re-renders.
 */

import { useState, useEffect, useCallback } from "react";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";

// Singleton reference to global audio
let globalAudio: HTMLAudioElement | null = null;

export function setGlobalAudioRef(audio: HTMLAudioElement) {
  globalAudio = audio;
}

export function getGlobalAudioRef(): HTMLAudioElement | null {
  return globalAudio;
}

export function useAudioTime() {
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [buffered, setBuffered] = useState(0);
  const { isPlaying, activeTrack } = usePlayerStore();

  useEffect(() => {
    // Capture audio reference at effect setup to ensure cleanup uses same reference.
    // globalAudio is set once by GlobalAudioProvider and never changes, but capturing
    // it here follows React best practices for stable effect cleanup.
    const audio = globalAudio;

    if (!audio) {
      // Reset state if audio not available
      setCurrentTime(0);
      setDuration(0);
      setBuffered(0);
      return;
    }

    const handleTimeUpdate = () => {
      setCurrentTime(audio.currentTime);
    };

    const handleLoadedMetadata = () => {
      setDuration(audio.duration || 0);
    };

    const handleProgress = () => {
      if (audio.buffered.length > 0 && audio.duration) {
        const bufferedEnd = audio.buffered.end(audio.buffered.length - 1);
        setBuffered((bufferedEnd / audio.duration) * 100);
      }
    };

    const handleDurationChange = () => {
      setDuration(audio.duration || 0);
    };

    audio.addEventListener("timeupdate", handleTimeUpdate);
    audio.addEventListener("loadedmetadata", handleLoadedMetadata);
    audio.addEventListener("durationchange", handleDurationChange);
    audio.addEventListener("progress", handleProgress);

    // Get initial values
    if (audio.duration) {
      setDuration(audio.duration);
    }
    setCurrentTime(audio.currentTime);

    return () => {
      // Cleanup uses captured reference
      audio.removeEventListener("timeupdate", handleTimeUpdate);
      audio.removeEventListener("loadedmetadata", handleLoadedMetadata);
      audio.removeEventListener("durationchange", handleDurationChange);
      audio.removeEventListener("progress", handleProgress);
    };
  }, [activeTrack?.id]);

  const seek = useCallback((time: number) => {
    if (globalAudio) {
      globalAudio.currentTime = time;
      setCurrentTime(time);
    }
  }, []);

  const setVolume = useCallback((volume: number) => {
    if (globalAudio) {
      globalAudio.volume = Math.max(0, Math.min(1, volume));
    }
  }, []);

  return { currentTime, duration, buffered, seek, setVolume, isPlaying };
}

/**
 * Audio Visualizer Hook
 *
 * Provides audio frequency data for visualization.
 * Uses Web Audio API AnalyserNode.
 *
 * IMPORTANT: MediaElementSourceNode can only be created once per audio element.
 * This hook uses the centralized audioContextManager to prevent conflicts.
 */

import { useEffect, useRef, useState, useCallback } from "react";
import { logger } from "@/lib/logger";
import { resumeAudioContext, getOrCreateAudioNodes, ensureAudioRoutedToDestination } from "@/lib/audioContextManager";

/**
 * Re-export resumeAudioContext from the centralized manager
 */
export { resumeAudioContext } from "@/lib/audioContextManager";

interface UseAudioVisualizerOptions {
  barCount?: number;
  smoothing?: number;
  fftSize?: number;
}

interface VisualizerData {
  frequencies: number[];
  waveform: number[];
  average: number;
  peak: number;
  isFallback: boolean; // Indicates if using fake data
}

export function useAudioVisualizer(
  audioElement: HTMLAudioElement | null,
  isPlaying: boolean,
  options: UseAudioVisualizerOptions = {},
) {
  const { barCount = 32, smoothing = 0.8, fftSize = 128 } = options;

  const animationRef = useRef<number | null>(null);

  const [data, setData] = useState<VisualizerData>({
    frequencies: new Array(barCount).fill(0),
    waveform: new Array(barCount).fill(0.5),
    average: 0,
    peak: 0,
    isFallback: false,
  });

  // Get analyser node using centralized manager
  const getAnalyser = useCallback(async () => {
    if (!audioElement) return null;

    try {
      const nodes = await getOrCreateAudioNodes(audioElement, fftSize, smoothing);
      return nodes?.analyser || null;
    } catch (err) {
      logger.warn("Failed to get audio nodes", { error: err });
      // Ensure audio is still routed even if visualizer fails
      ensureAudioRoutedToDestination();
      return null;
    }
  }, [audioElement, fftSize, smoothing]);

  // Animation loop
  useEffect(() => {
    if (!isPlaying) {
      // Decay frequencies when paused
      setData((prev) => ({
        ...prev,
        frequencies: prev.frequencies.map((f) => f * 0.92),
        average: prev.average * 0.92,
        peak: prev.peak * 0.95,
        isFallback: prev.isFallback,
      }));

      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
        animationRef.current = null;
      }
      return;
    }

    // Initialize analyser asynchronously
    let analyser: AnalyserNode | null = null;
    let isActive = true;

    const initAnalyser = async () => {
      if (!isActive) return;

      try {
        analyser = await getAnalyser();
      } catch (err) {
        logger.warn("Failed to get analyser, using fallback", { error: err });
        analyser = null;
      }

      if (!isActive) return; // Effect cleanup happened during await

      // Fallback animation if analyser unavailable
      if (!analyser) {
        logger.debug("Using fallback visualizer (no analyser available)");

        const fakeAnimate = () => {
          if (!isPlaying || !isActive) return;

          const time = Date.now() / 1000;
          // More subtle animation for fallback to indicate it's not real data
          const fakeFreqs = new Array(barCount).fill(0).map((_, i) => {
            const base = Math.sin(time * 1.5 + i * 0.2) * 0.2 + 0.3;
            const noise = Math.random() * 0.1;
            return Math.min(0.7, Math.max(0.1, base + noise));
          });

          const avg = fakeFreqs.reduce((a, b) => a + b, 0) / barCount;
          const peak = Math.max(...fakeFreqs);

          setData({
            frequencies: fakeFreqs,
            waveform: fakeFreqs.map((f) => 0.5 + (f - 0.5) * 0.3),
            average: avg,
            peak,
            isFallback: true, // Mark as fallback data
          });

          animationRef.current = requestAnimationFrame(fakeAnimate);
        };

        fakeAnimate();
        return;
      }

      // Real analyser animation
      const bufferLength = analyser.frequencyBinCount;
      const frequencyData = new Uint8Array(bufferLength);
      const timeDomainData = new Uint8Array(bufferLength);

      const animate = () => {
        if (!isPlaying || !isActive || !analyser) return;

        analyser.getByteFrequencyData(frequencyData);
        analyser.getByteTimeDomainData(timeDomainData);

        // Sample frequencies
        const step = Math.max(1, Math.floor(bufferLength / barCount));
        const frequencies: number[] = [];

        for (let i = 0; i < barCount; i++) {
          let sum = 0;
          for (let j = 0; j < step; j++) {
            const idx = i * step + j;
            if (idx < bufferLength) {
              sum += frequencyData[idx];
            }
          }
          frequencies.push(Math.min(1, (sum / step / 255) * 1.3));
        }

        // Sample waveform
        const waveStep = Math.floor(bufferLength / barCount);
        const waveform = new Array(barCount).fill(0).map((_, i) => {
          const idx = i * waveStep;
          return (timeDomainData[idx] || 128) / 255;
        });

        const average = frequencies.reduce((a, b) => a + b, 0) / barCount;
        const peak = Math.max(...frequencies);

        setData({ frequencies, waveform, average, peak, isFallback: false });

        animationRef.current = requestAnimationFrame(animate);
      };

      animate();
    };

    initAnalyser();

    return () => {
      isActive = false;
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [isPlaying, getAnalyser, barCount]);

  return data;
}

/**
 * Global Audio Player Hook
 *
 * Singleton audio player that syncs with Zustand store.
 * Provides actual audio playback connected to global player state.
 * Includes audio caching with 14-day expiry for optimized playback.
 * Plays from cache when available for instant playback.
 */

import { useEffect, useRef, useCallback } from "react";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";
import { getGlobalAudioRef } from "@/hooks/audio/useAudioTime";
import { logger } from "@/lib/logger";
import { cleanupExpiredEntries, prefetchQueue, shouldPrefetch, getCachedAudio, cacheAudio } from "@/lib/audioCache";

// Run cache cleanup on module load (once per session)
let cacheCleanupRun = false;
if (!cacheCleanupRun) {
  cacheCleanupRun = true;
  // Delay cleanup to not block initial load
  setTimeout(() => {
    cleanupExpiredEntries().catch(() => {});
  }, 5000);
}

export function useGlobalAudioPlayer() {
  const { activeTrack, isPlaying, repeat, pauseTrack, nextTrack, queue, currentIndex } = usePlayerStore();

  const lastTrackIdRef = useRef<string | null>(null);
  const lastAudioSourceRef = useRef<string | null>(null);
  // Track current blob URL to manage lifecycle properly
  const currentBlobUrlRef = useRef<string | null>(null);

  // Get audio source from track
  const getAudioSource = useCallback(() => {
    if (!activeTrack) return null;
    return activeTrack.streaming_url || activeTrack.local_audio_url || activeTrack.audio_url;
  }, [activeTrack]);

  // Prefetch next tracks when current track changes
  useEffect(() => {
    if (!activeTrack || queue.length === 0 || !shouldPrefetch()) return;

    const audioUrls = queue.map((t) => t.streaming_url || t.audio_url).filter((url): url is string => !!url);

    if (audioUrls.length > 0) {
      prefetchQueue(audioUrls, currentIndex);
    }
  }, [activeTrack?.id, queue, currentIndex]);

  // Cleanup blob URL helper - revokes previous blob before setting new source
  const cleanupCurrentBlobUrl = useCallback(() => {
    if (currentBlobUrlRef.current) {
      logger.debug("Revoking previous blob URL", {
        url: currentBlobUrlRef.current.substring(0, 50),
      });
      URL.revokeObjectURL(currentBlobUrlRef.current);
      currentBlobUrlRef.current = null;
    }
  }, []);

  // Handle track change - load new source
  // CRITICAL: Reload audio when track ID OR audio source changes (for version switching)
  // Prioritize cached audio for instant playback
  useEffect(() => {
    const audio = getGlobalAudioRef();
    if (!audio) return;

    const trackId = activeTrack?.id;
    const source = getAudioSource();

    // Skip if neither track ID nor audio source has changed
    const sourceChanged = source !== lastAudioSourceRef.current;
    const trackChanged = trackId !== lastTrackIdRef.current;

    if (!sourceChanged && !trackChanged) {
      return;
    }

    // Cleanup previous blob URL before setting new source
    cleanupCurrentBlobUrl();

    // Update refs before any state changes
    lastTrackIdRef.current = trackId || null;
    lastAudioSourceRef.current = source || null;

    if (!source) {
      // Only clear src if no track is active
      if (!trackId) {
        audio.src = "";
      }
      return;
    }

    // Try to load from cache first for instant playback
    const loadAudio = async () => {
      try {
        const cachedBlob = await getCachedAudio(source);

        if (cachedBlob) {
          // Play from cache - instant playback
          const blobUrl = URL.createObjectURL(cachedBlob);
          // Store blob URL for proper lifecycle management
          currentBlobUrlRef.current = blobUrl;

          logger.debug("Playing from cache", {
            trackId,
            source: source.substring(0, 50),
            blobUrl: blobUrl.substring(0, 50),
          });
          audio.src = blobUrl;
          audio.load();
          // NOTE: Do NOT revoke blob URL on 'emptied' - it causes format errors
          // Blob URL will be revoked when source changes or component unmounts
        } else {
          // Load from network and cache for future use
          logger.debug("Loading from network", {
            trackId,
            sourceChanged,
            trackChanged,
            source: source.substring(0, 50),
          });
          audio.src = source;
          audio.load();

          // Cache the audio in background after it loads
          fetch(source)
            .then((response) => {
              if (response.ok) return response.blob();
              throw new Error("Failed to fetch audio");
            })
            .then((blob) => cacheAudio(source, blob))
            .catch((err) => logger.debug("Cache fetch failed", { error: err.message }));
        }
      } catch (error) {
        // Fallback to direct load if cache fails
        logger.debug("Cache error, loading directly", { error });
        audio.src = source;
        audio.load();
      }
    };

    loadAudio();

    // Cleanup on unmount or source change
    return () => {
      cleanupCurrentBlobUrl();
    };
  }, [activeTrack?.id, getAudioSource, cleanupCurrentBlobUrl]);

  // NOTE: Play/pause is handled by GlobalAudioProvider to avoid race conditions
  // This hook only provides utility functions and audio element access

  // Handle track ended - backup handler (GlobalAudioProvider is primary)
  useEffect(() => {
    const audio = getGlobalAudioRef();
    if (!audio) return;

    const handleEnded = () => {
      if (repeat === "one") {
        audio.currentTime = 0;
        audio.play().catch(() => nextTrack());
      } else {
        nextTrack();
      }
    };

    audio.addEventListener("ended", handleEnded);
    return () => audio.removeEventListener("ended", handleEnded);
  }, [repeat, nextTrack]);

  // Playback controls
  const seek = useCallback((time: number) => {
    const audio = getGlobalAudioRef();
    if (audio && audio.src) {
      audio.currentTime = time;
    }
  }, []);

  const setVolume = useCallback((volume: number) => {
    const audio = getGlobalAudioRef();
    if (audio) {
      audio.volume = Math.max(0, Math.min(1, volume));
    }
  }, []);

  // Get current playback state
  const getCurrentTime = useCallback(() => {
    const audio = getGlobalAudioRef();
    return audio ? audio.currentTime : 0;
  }, []);

  const getDuration = useCallback(() => {
    const audio = getGlobalAudioRef();
    return audio ? audio.duration || 0 : 0;
  }, []);

  const getBuffered = useCallback(() => {
    const audio = getGlobalAudioRef();
    if (audio && audio.buffered.length > 0 && audio.duration) {
      return (audio.buffered.end(audio.buffered.length - 1) / audio.duration) * 100;
    }
    return 0;
  }, []);

  return {
    seek,
    setVolume,
    getCurrentTime,
    getDuration,
    getBuffered,
    audioElement: getGlobalAudioRef(),
  };
}

/**
 * Playback Position Persistence Hook
 *
 * Saves and restores playback position for tracks.
 * Allows users to resume where they left off.
 *
 * Features:
 * - Auto-save position every 5 seconds when playing
 * - Restore position on track load
 * - Clean up old positions (>7 days)
 * - Skip saving for very short positions (<10s)
 */

import { useEffect, useCallback, useRef } from "react";
import { usePlayerStore } from "./usePlayerState";
import { getGlobalAudioRef } from "./useAudioTime";
import { logger } from "@/lib/logger";

const log = logger.child({ module: "PlaybackPosition" });

const POSITION_STORAGE_KEY = "musicverse-playback-positions";
const SAVE_INTERVAL = 5000; // Save every 5 seconds
const MIN_SAVE_POSITION = 10; // Don't save positions < 10 seconds
const MAX_AGE_DAYS = 7; // Clean up positions older than 7 days
const MAX_STORED_POSITIONS = 50; // Limit storage size

interface PlaybackPosition {
  trackId: string;
  position: number; // in seconds
  duration: number; // total duration
  timestamp: number; // when saved
}

/**
 * Load all saved positions from localStorage
 */
function loadPositions(): Map<string, PlaybackPosition> {
  try {
    const stored = localStorage.getItem(POSITION_STORAGE_KEY);
    if (!stored) return new Map();

    const positions = JSON.parse(stored) as PlaybackPosition[];
    const now = Date.now();
    const maxAge = MAX_AGE_DAYS * 24 * 60 * 60 * 1000;

    // Filter out old positions and convert to Map
    const validPositions = positions.filter((pos) => now - pos.timestamp < maxAge);

    return new Map(validPositions.map((pos) => [pos.trackId, pos]));
  } catch (error) {
    log.error("Failed to load playback positions", error);
    return new Map();
  }
}

/**
 * Save positions to localStorage
 */
function savePositions(positions: Map<string, PlaybackPosition>): void {
  try {
    // Convert Map to array and limit size
    const positionsArray = Array.from(positions.values())
      .sort((a, b) => b.timestamp - a.timestamp) // Most recent first
      .slice(0, MAX_STORED_POSITIONS);

    localStorage.setItem(POSITION_STORAGE_KEY, JSON.stringify(positionsArray));
  } catch (error) {
    log.error("Failed to save playback positions", error);
  }
}

/**
 * Hook for playback position persistence
 */
export function usePlaybackPosition() {
  const { activeTrack, isPlaying } = usePlayerStore();
  const positionsRef = useRef<Map<string, PlaybackPosition>>(loadPositions());
  const saveTimerRef = useRef<NodeJS.Timeout | null>(null);
  const hasRestoredRef = useRef<Set<string>>(new Set());

  /**
   * Save current position
   */
  const saveCurrentPosition = useCallback(() => {
    const audio = getGlobalAudioRef();
    if (!audio || !activeTrack) return;

    const position = audio.currentTime;
    const duration = audio.duration;

    // Don't save if position is too early or track is finished
    if (position < MIN_SAVE_POSITION || position >= duration - 5) {
      return;
    }

    const positionData: PlaybackPosition = {
      trackId: activeTrack.id,
      position,
      duration,
      timestamp: Date.now(),
    };

    positionsRef.current.set(activeTrack.id, positionData);
    savePositions(positionsRef.current);

    log.debug("Saved playback position", {
      trackId: activeTrack.id,
      position: Math.floor(position),
      duration: Math.floor(duration),
    });
  }, [activeTrack]);

  /**
   * Get saved position for a track
   */
  const getSavedPosition = useCallback((trackId: string): number | null => {
    const position = positionsRef.current.get(trackId);
    if (!position) return null;

    // Only restore if position is meaningful (>10s and <90% of duration)
    if (position.position < MIN_SAVE_POSITION) return null;
    if (position.position >= position.duration * 0.9) return null;

    return position.position;
  }, []);

  /**
   * Restore position for current track
   */
  const restorePosition = useCallback(() => {
    const audio = getGlobalAudioRef();
    if (!audio || !activeTrack) return;

    // Don't restore if already restored for this track in this session
    if (hasRestoredRef.current.has(activeTrack.id)) return;

    const savedPosition = getSavedPosition(activeTrack.id);
    if (savedPosition !== null && audio.readyState >= 2) {
      audio.currentTime = savedPosition;
      hasRestoredRef.current.add(activeTrack.id);

      log.info("Restored playback position", {
        trackId: activeTrack.id,
        position: Math.floor(savedPosition),
      });
    }
  }, [activeTrack, getSavedPosition]);

  /**
   * Clear saved position for a track
   */
  const clearPosition = useCallback((trackId: string) => {
    positionsRef.current.delete(trackId);
    savePositions(positionsRef.current);
  }, []);

  /**
   * Clear all saved positions
   */
  const clearAllPositions = useCallback(() => {
    positionsRef.current.clear();
    savePositions(positionsRef.current);
  }, []);

  /**
   * Auto-save effect - save position periodically when playing
   */
  useEffect(() => {
    if (isPlaying && activeTrack) {
      // Save immediately on track change
      saveCurrentPosition();

      // Then save periodically
      saveTimerRef.current = setInterval(saveCurrentPosition, SAVE_INTERVAL);

      return () => {
        if (saveTimerRef.current) {
          clearInterval(saveTimerRef.current);
          saveTimerRef.current = null;
        }
        // Save one last time when stopping
        saveCurrentPosition();
      };
    } else {
      // Clear interval if paused
      if (saveTimerRef.current) {
        clearInterval(saveTimerRef.current);
        saveTimerRef.current = null;
      }
    }
  }, [isPlaying, activeTrack?.id, saveCurrentPosition]);

  /**
   * Restore position when track loads
   */
  useEffect(() => {
    if (activeTrack) {
      const audio = getGlobalAudioRef();
      if (!audio) return;

      // Wait for metadata to be loaded
      const handleLoadedMetadata = () => {
        restorePosition();
      };

      if (audio.readyState >= 2) {
        // Already loaded
        restorePosition();
      } else {
        audio.addEventListener("loadedmetadata", handleLoadedMetadata);
        return () => {
          audio.removeEventListener("loadedmetadata", handleLoadedMetadata);
        };
      }
    }
  }, [activeTrack?.id, restorePosition]);

  /**
   * Clean up on unmount
   */
  useEffect(() => {
    return () => {
      if (saveTimerRef.current) {
        clearInterval(saveTimerRef.current);
      }
      saveCurrentPosition();
    };
  }, [saveCurrentPosition]);

  return {
    getSavedPosition,
    clearPosition,
    clearAllPositions,
  };
}

/**
 * Player Analytics Hook
 *
 * Tracks player interactions for analytics without modifying core player state.
 * Uses effect-based tracking to avoid circular dependencies.
 *
 * P2 Enhancement: Added milestone tracking (25/50/75/100%) and skip events
 */

import { useEffect, useRef, useCallback } from "react";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";
import { useAudioTime } from "@/hooks/audio/useAudioTime";
import { trackTrackPlayed, trackFeatureUsed, trackEvent } from "@/services/analytics";
import { trackConversionStage, hasReachedStage } from "@/lib/analytics/deeplink-tracker";
import { useAuth } from "@/hooks/useAuth";

const PLAY_DURATION_THRESHOLD = 10; // seconds before counting as "played"
const SKIP_THRESHOLD = 10; // seconds - if user leaves before this, it's a skip

// Milestones to track (percentage of track listened)
const PLAY_MILESTONES = [25, 50, 75, 100] as const;
type PlayMilestone = (typeof PLAY_MILESTONES)[number];

export function usePlayerAnalytics() {
  const activeTrack = usePlayerStore((s) => s.activeTrack);
  const isPlaying = usePlayerStore((s) => s.isPlaying);

  // Get currentTime and duration from useAudioTime hook
  const { currentTime, duration } = useAudioTime();
  const { user } = useAuth();

  const lastTrackedId = useRef<string | null>(null);
  const playStartTime = useRef<number | null>(null);
  const hasTrackedPlay = useRef(false);
  const trackedMilestones = useRef<Set<PlayMilestone>>(new Set());
  const playStartPosition = useRef<number>(0);
  const totalListenTime = useRef<number>(0);
  const lastTimeUpdate = useRef<number>(0);

  // Reset tracking for new track
  const resetTrackingState = useCallback(() => {
    hasTrackedPlay.current = false;
    trackedMilestones.current.clear();
    playStartPosition.current = 0;
    totalListenTime.current = 0;
    lastTimeUpdate.current = 0;
  }, []);

  // Track skip event when user leaves track early
  const trackSkipEvent = useCallback(
    (trackId: string, trackTitle: string, listenedSeconds: number) => {
      if (listenedSeconds < SKIP_THRESHOLD && listenedSeconds > 0) {
        trackFeatureUsed("track_skip", {
          track_id: trackId,
          track_title: trackTitle,
          listened_seconds: Math.round(listenedSeconds),
          has_user: !!user?.id,
        }).catch(() => {});
      }
    },
    [user?.id],
  );

  // Track when a new track starts playing
  useEffect(() => {
    if (!activeTrack || !isPlaying) {
      // Track skip if user stopped playing early
      if (!isPlaying && lastTrackedId.current && totalListenTime.current > 0) {
        const prevTrackId = lastTrackedId.current;
        trackSkipEvent(prevTrackId, activeTrack?.title || "Unknown", totalListenTime.current);
      }

      // Reset tracking when not playing
      if (!isPlaying && playStartTime.current) {
        playStartTime.current = null;
      }
      return;
    }

    // New track started
    if (activeTrack.id !== lastTrackedId.current) {
      // Track skip for previous track if applicable
      if (lastTrackedId.current && totalListenTime.current > 0 && totalListenTime.current < SKIP_THRESHOLD) {
        trackSkipEvent(lastTrackedId.current, "Previous Track", totalListenTime.current);
      }

      lastTrackedId.current = activeTrack.id;
      playStartTime.current = Date.now();
      playStartPosition.current = currentTime || 0;
      resetTrackingState();

      // Track immediate play event
      trackFeatureUsed("track_play_start", {
        track_id: activeTrack.id,
        track_title: activeTrack.title,
        start_position: Math.round(playStartPosition.current),
        has_user: !!user?.id,
      }).catch(() => {});
    }
  }, [activeTrack?.id, isPlaying, user?.id, currentTime, trackSkipEvent, resetTrackingState]);

  // Track meaningful play after threshold
  useEffect(() => {
    if (!activeTrack || !isPlaying || hasTrackedPlay.current) return;

    const timer = setTimeout(() => {
      if (isPlaying && activeTrack && !hasTrackedPlay.current) {
        hasTrackedPlay.current = true;

        // Track as actual play
        trackTrackPlayed(
          activeTrack.id,
          {
            track_title: activeTrack.title,
            duration_threshold: PLAY_DURATION_THRESHOLD,
          },
          user?.id,
        ).catch(() => {});

        // Track first action conversion if user's first meaningful play
        if (!hasReachedStage("first_action")) {
          trackConversionStage("first_action", {
            action_type: "play",
            track_id: activeTrack.id,
          }).catch(() => {});
        }

        // Track engagement if not yet engaged
        if (!hasReachedStage("engaged")) {
          trackConversionStage("engaged", {
            trigger: "track_play",
            track_id: activeTrack.id,
          }).catch(() => {});
        }
      }
    }, PLAY_DURATION_THRESHOLD * 1000);

    return () => clearTimeout(timer);
  }, [activeTrack?.id, isPlaying, user?.id]);

  // P2 Enhancement: Track listening progress milestones (25%, 50%, 75%, 100%)
  useEffect(() => {
    if (!activeTrack || !isPlaying || !duration || duration <= 0) return;

    // Update total listen time
    if (lastTimeUpdate.current > 0 && currentTime > lastTimeUpdate.current) {
      totalListenTime.current += currentTime - lastTimeUpdate.current;
    }
    lastTimeUpdate.current = currentTime;

    // Calculate current percentage
    const currentPercent = (currentTime / duration) * 100;

    // Check each milestone
    for (const milestone of PLAY_MILESTONES) {
      if (currentPercent >= milestone && !trackedMilestones.current.has(milestone)) {
        trackedMilestones.current.add(milestone);

        // Track milestone event
        trackEvent(
          {
            eventType: "feature_used",
            eventName: `track_listen_${milestone}`,
            metadata: {
              track_id: activeTrack.id,
              track_title: activeTrack.title,
              milestone_percent: milestone,
              actual_percent: Math.round(currentPercent),
              listen_time_seconds: Math.round(totalListenTime.current),
              duration_seconds: Math.round(duration),
            },
          },
          user?.id,
        ).catch(() => {});

        // Special handling for 100% completion
        if (milestone === 100) {
          trackFeatureUsed("track_completed", {
            track_id: activeTrack.id,
            track_title: activeTrack.title,
            total_listen_time: Math.round(totalListenTime.current),
            track_duration: Math.round(duration),
          }).catch(() => {});
        }
      }
    }
  }, [activeTrack?.id, currentTime, duration, isPlaying, user?.id]);

  // Track repeat play (when user plays same track again)
  useEffect(() => {
    if (!activeTrack || !isPlaying) return;

    // If we're back to the start of a track we already completed
    if (trackedMilestones.current.has(100) && currentTime < 5 && playStartPosition.current > 5) {
      trackFeatureUsed("track_repeat", {
        track_id: activeTrack.id,
        track_title: activeTrack.title,
      }).catch(() => {});

      // Reset milestones for new playthrough
      trackedMilestones.current.clear();
      totalListenTime.current = 0;
    }
  }, [activeTrack?.id, currentTime, isPlaying]);

  return null; // This hook is for side effects only
}

/**
 * Hook to track share events
 */
export function useShareAnalytics() {
  const trackShare = async (
    trackId: string,
    method: "telegram" | "story" | "copy" | "native",
    metadata?: Record<string, unknown>,
  ) => {
    await trackFeatureUsed("track_share", {
      track_id: trackId,
      share_method: method,
      ...metadata,
    });

    // Track engagement if not yet engaged
    if (!hasReachedStage("engaged")) {
      await trackConversionStage("engaged", {
        trigger: "share",
        track_id: trackId,
      });
    }
  };

  return { trackShare };
}

