/**
 * usePreviewAudio — единый хук для превью-аудио в UI (диалоги, кнопки play, версии, стемы).
 *
 * Проблема: 28+ мест в `src/` создают `new Audio(...)` напрямую, минуя `audioElementPool`.
 * iOS Safari ограничивает количество одновременных `<audio>` элементов до 6-8 — при превышении
 * лимита плейер крашится.
 *
 * Решение: `usePreviewAudio` оборачивает `audioElementPool` + `useStudioAudio` и предоставляет
 * простой API `play/pause/seek/setVolume/onEnded`. При размонтировании элемент
 * автоматически возвращается в пул.
 *
 * Использование:
 * ```tsx
 * function PreviewButton({ url }: { url: string }) {
 *   const { isPlaying, play, pause } = usePreviewAudio({
 *     id: `preview-${url}`,
 *     src: url,
 *     priority: AudioPriority.LOW,
 *   });
 *   return <Button onClick={isPlaying ? pause : play}>{isPlaying ? "Stop" : "Play"}</Button>;
 * }
 * ```
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { audioElementPool, AudioPriority, useAudioElement } from "@/lib/audioElementPool";
import { registerStudioAudio, unregisterStudioAudio } from "@/hooks/studio/useStudioAudio";
import { logger } from "@/lib/logger";
import { recordError } from "@/lib/telemetry";

const truncateUrl = (s: string, max = 200): string => (s.length > max ? `${s.slice(0, max)}…` : s);

export interface UsePreviewAudioOptions {
  /** Уникальный ID (например, `preview-track-${trackId}`). Используется для acquire/release в пуле. */
  id: string;
  /** URL аудио. */
  src: string;
  /** Приоритет в пуле. LOW для превью, MEDIUM/HIGH для стемов. */
  priority?: AudioPriority;
  /** Автоплей при монтировании. */
  autoPlay?: boolean;
  /** Громкость 0..1. */
  volume?: number;
  /** Коллбэк завершения. */
  onEnded?: () => void;
  /** Коллбэк ошибки. */
  onError?: (message: string) => void;
}

export interface UsePreviewAudioReturn {
  /** Текущее состояние воспроизведения. */
  isPlaying: boolean;
  /** Текущая позиция (секунды). */
  currentTime: number;
  /** Длительность (секунды, 0 если не загружено). */
  duration: number;
  /** true пока идёт загрузка метаданных. */
  isLoading: boolean;
  /** Сообщение об ошибке или null. */
  error: string | null;
  /** Начать воспроизведение текущего src. */
  play: () => Promise<void>;
  /** Переключить src и сразу запустить воспроизведение. Для динамических плейлистов. */
  playUrl: (url: string) => Promise<void>;
  /** Поставить на паузу. */
  pause: () => void;
  /** Переключить play/pause. */
  toggle: () => Promise<void>;
  /** Перемотать на time (секунды). */
  seek: (time: number) => void;
  /** Установить громкость 0..1. */
  setVolume: (volume: number) => void;
  /** Ref на элемент (для waveform/visualizer). */
  audioRef: React.RefObject<HTMLAudioElement | null>;
}

/**
 * Drop-in замена `new Audio()` для превью-кнопок в UI.
 *
 * - Берёт элемент из `audioElementPool` (защита от iOS Safari лимита).
 * - Регистрируется в `useStudioAudio` (пауза при старте глобального плейера).
 * - Освобождает ресурсы при unmount.
 */
export function usePreviewAudio({
  id,
  src,
  priority = AudioPriority.LOW,
  autoPlay = false,
  volume = 1,
  onEnded,
  onError,
}: UsePreviewAudioOptions): UsePreviewAudioReturn {
  const audioElement = useAudioElement(id, priority);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Храним callback-и через ref, чтобы не пересоздавать audio element при их изменении.
  const onEndedRef = useRef(onEnded);
  const onErrorRef = useRef(onError);
  useEffect(() => {
    onEndedRef.current = onEnded;
    onErrorRef.current = onError;
  }, [onEnded, onError]);

  // Привязка событий + установка src.
  useEffect(() => {
    if (!audioElement) {
      audioRef.current = null;
      return;
    }
    const isValidSrc = typeof src === "string" && /^(https?:|blob:|data:audio\/|\/)/i.test(src.trim());
    if (!src || !isValidSrc) {
      // Нет валидного URL — не трогаем элемент, не грузим, не роняем ошибку.
      audioRef.current = audioElement;
      setIsLoading(false);
      setError(null);
      if (src && !isValidSrc) {
        logger.warn("usePreviewAudio: invalid src rejected", { id, src: truncateUrl(String(src)) });
        recordError("preview_audio:invalid_src", "Invalid preview audio source", {
          id,
          src: truncateUrl(String(src)),
        });
      } else if (src === "") {
        logger.debug("usePreviewAudio: empty src, skipping load", { id });
      }
      return;
    }
    audioRef.current = audioElement;

    // Регистрация в координаторе studio audio (пауза при старте глобального плейера).
    registerStudioAudio(
      id,
      () => {
        audioElement.pause();
        setIsPlaying(false);
      },
      () => !audioElement.paused,
    );

    const handleLoadedMetadata = () => {
      setDuration(audioElement.duration || 0);
      setIsLoading(false);
      setError(null);
    };
    const handleTimeUpdate = () => setCurrentTime(audioElement.currentTime);
    const handleEnded = () => {
      setIsPlaying(false);
      setCurrentTime(0);
      onEndedRef.current?.();
    };
    const handleError = () => {
      const code = audioElement.error?.code ?? null;
      const nativeMsg = audioElement.error?.message ?? null;
      const msg = "Не удалось загрузить аудио";
      setIsLoading(false);
      setIsPlaying(false);
      setError(msg);
      onErrorRef.current?.(msg);
      logger.warn("usePreviewAudio: load failed", {
        id,
        src: truncateUrl(src),
        mediaErrorCode: code,
        nativeMessage: nativeMsg,
      });
      recordError(`preview_audio:load_failed:${code ?? "unknown"}`, nativeMsg ?? msg, {
        id,
        src: truncateUrl(src),
        mediaErrorCode: code,
      });
    };
    const handlePlay = () => setIsPlaying(true);
    const handlePause = () => setIsPlaying(false);

    audioElement.addEventListener("loadedmetadata", handleLoadedMetadata);
    audioElement.addEventListener("timeupdate", handleTimeUpdate);
    audioElement.addEventListener("ended", handleEnded);
    audioElement.addEventListener("error", handleError);
    audioElement.addEventListener("play", handlePlay);
    audioElement.addEventListener("pause", handlePause);

    try {
      audioElement.volume = Math.max(0, Math.min(1, volume));
      audioElement.src = src;
      audioElement.load();
    } catch (err) {
      logger.warn("usePreviewAudio: failed to set src", { id, src: truncateUrl(src), err });
      recordError("preview_audio:set_src_failed", err instanceof Error ? err.message : String(err), {
        id,
        src: truncateUrl(src),
      });
      setError("Не удалось загрузить аудио");
      setIsLoading(false);
    }

    if (autoPlay) {
      audioElement.play().catch(() => {
        // autoplay заблокирован — это норма, ничего не делаем
      });
    }

    return () => {
      audioElement.pause();
      audioElement.removeEventListener("loadedmetadata", handleLoadedMetadata);
      audioElement.removeEventListener("timeupdate", handleTimeUpdate);
      audioElement.removeEventListener("ended", handleEnded);
      audioElement.removeEventListener("error", handleError);
      audioElement.removeEventListener("play", handlePlay);
      audioElement.removeEventListener("pause", handlePause);
      unregisterStudioAudio(id);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [audioElement, id, src]);

  const play = useCallback(async () => {
    const el = audioRef.current;
    if (!el) return;
    try {
      await el.play();
    } catch (err) {
      const msg = "Воспроизведение заблокировано";
      setError(msg);
      onErrorRef.current?.(msg);
      logger.warn("usePreviewAudio: play blocked", { id, err });
    }
  }, [id]);

  /**
   * Переключает src на новый URL и запускает воспроизведение.
   * Используется в динамических списках (TrackVersionsTab, CloudAudioPicker и т.п.),
   * где один пул-элемент используется для проигрывания разных треков по клику.
   */
  const playUrl = useCallback(
    async (newUrl: string) => {
      const el = audioRef.current;
      if (!el || !newUrl) return;
      try {
        el.src = newUrl;
        el.load();
        setCurrentTime(0);
        setError(null);
        await el.play();
      } catch (err) {
        const msg = "Воспроизведение заблокировано";
        setError(msg);
        onErrorRef.current?.(msg);
        logger.warn("usePreviewAudio: playUrl blocked", { id, newUrl, err });
      }
    },
    [id],
  );

  const pause = useCallback(() => {
    audioRef.current?.pause();
  }, []);

  const toggle = useCallback(async () => {
    if (isPlaying) pause();
    else await play();
  }, [isPlaying, play, pause]);

  const seek = useCallback((time: number) => {
    const el = audioRef.current;
    if (!el) return;
    const target = Math.max(0, Math.min(time, el.duration || 0));
    el.currentTime = target;
    setCurrentTime(target);
  }, []);

  const setVolume = useCallback((v: number) => {
    const el = audioRef.current;
    if (!el) return;
    el.volume = Math.max(0, Math.min(1, v));
  }, []);

  return {
    isPlaying,
    currentTime,
    duration,
    isLoading,
    error,
    play,
    playUrl,
    pause,
    toggle,
    seek,
    setVolume,
    audioRef,
  };
}

/**
 * Утилита для получения pool-статистики (для дев-тулзов и мониторинга).
 */
export function getPreviewPoolStats() {
  return audioElementPool.getStats();
}

/**
 * Radio Mode Hook
 *
 * Auto-queues similar tracks when the current queue is about to end.
 * Uses the current track's style/tags to find similar tracks.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { usePlayerStore } from "./usePlayerState";
import { supabase } from "@/integrations/supabase/client";
import { logger } from "@/lib/logger";
import type { Track } from "@/types/track";
import { toast } from "sonner";

const log = logger.child({ module: "RadioMode" });

const RADIO_FETCH_LIMIT = 5; // Number of tracks to fetch at a time
const TRACKS_THRESHOLD = 2; // When remaining tracks <= this, fetch more

interface UseRadioModeOptions {
  /** Whether radio mode is enabled */
  enabled?: boolean;
  /** Show toast when adding tracks */
  showToast?: boolean;
}

interface RadioModeState {
  isEnabled: boolean;
  isFetching: boolean;
  autoAddedCount: number;
}

/**
 * Hook for Radio Mode functionality
 * Automatically adds similar tracks when queue is running low
 */
export function useRadioMode(options: UseRadioModeOptions = {}) {
  const { showToast = true } = options;

  const [isEnabled, setIsEnabled] = useState(false);
  const [isFetching, setIsFetching] = useState(false);
  const [autoAddedCount, setAutoAddedCount] = useState(0);

  const fetchedTrackIds = useRef<Set<string>>(new Set());
  const lastFetchRef = useRef<number>(0);

  const queue = usePlayerStore((s) => s.queue);
  const currentIndex = usePlayerStore((s) => s.currentIndex);
  const activeTrack = usePlayerStore((s) => s.activeTrack);
  const repeat = usePlayerStore((s) => s.repeat);
  const addToQueue = usePlayerStore((s) => s.addToQueue);

  /**
   * Fetch similar tracks based on current track's style/tags
   */
  const fetchSimilarTracks = useCallback(
    async (track: Track): Promise<Track[]> => {
      try {
        // Build query for similar tracks
        let query = supabase
          .from("tracks")
          .select("*")
          .eq("status", "completed")
          .neq("id", track.id)
          .limit(RADIO_FETCH_LIMIT * 2); // Fetch extra to filter duplicates

        // Match by style if available
        if (track.style) {
          query = query.ilike("style", `%${track.style.split(" ")[0]}%`);
        }

        // Exclude already queued and fetched tracks
        const excludeIds = [...queue.map((t) => t.id), ...Array.from(fetchedTrackIds.current)];

        if (excludeIds.length > 0) {
          query = query.not("id", "in", `(${excludeIds.join(",")})`);
        }

        // Order by random for variety
        query = query.order("created_at", { ascending: false });

        const { data, error } = await query;

        if (error) {
          log.error("Failed to fetch similar tracks", { error });
          return [];
        }

        // Filter and limit results
        const filteredTracks = (data || []).filter((t) => t.audio_url || t.streaming_url).slice(0, RADIO_FETCH_LIMIT);

        // Mark as fetched to avoid duplicates
        filteredTracks.forEach((t) => fetchedTrackIds.current.add(t.id));

        return filteredTracks as Track[];
      } catch (error) {
        log.error("Error fetching similar tracks", { error });
        return [];
      }
    },
    [queue],
  );

  /**
   * Check if we need to fetch more tracks
   */
  const checkAndFetchMore = useCallback(async () => {
    if (!isEnabled || isFetching || !activeTrack || repeat === "one") {
      return;
    }

    // Calculate remaining tracks
    const remainingTracks = queue.length - currentIndex - 1;

    // If we're at "repeat all", don't auto-add
    if (repeat === "all" && remainingTracks <= 0) {
      return;
    }

    // Check if we need more tracks
    if (remainingTracks > TRACKS_THRESHOLD) {
      return;
    }

    // Debounce fetching
    const now = Date.now();
    if (now - lastFetchRef.current < 5000) {
      return;
    }
    lastFetchRef.current = now;

    log.info("Radio mode: fetching more tracks", { remainingTracks });
    setIsFetching(true);

    try {
      const newTracks = await fetchSimilarTracks(activeTrack);

      if (newTracks.length > 0) {
        // Add tracks to queue
        newTracks.forEach((track) => {
          addToQueue(track);
        });

        setAutoAddedCount((prev) => prev + newTracks.length);

        if (showToast) {
          toast.info("🎵 Радио", {
            description: `Добавлено ${newTracks.length} похожих треков`,
          });
        }

        log.info("Radio mode: added tracks", { count: newTracks.length });
      } else {
        log.info("Radio mode: no similar tracks found");
      }
    } finally {
      setIsFetching(false);
    }
  }, [
    isEnabled,
    isFetching,
    activeTrack,
    queue.length,
    currentIndex,
    repeat,
    fetchSimilarTracks,
    addToQueue,
    showToast,
  ]);

  /**
   * Toggle radio mode
   */
  const toggleRadioMode = useCallback(() => {
    setIsEnabled((prev) => {
      const newState = !prev;

      if (newState) {
        // Reset counters when enabling
        fetchedTrackIds.current.clear();
        setAutoAddedCount(0);
        toast.success("🎵 Радио включено", {
          description: "Похожие треки будут добавляться автоматически",
        });
      } else {
        toast.info("Радио выключено");
      }

      return newState;
    });
  }, []);

  /**
   * Enable radio mode
   */
  const enableRadioMode = useCallback(() => {
    if (!isEnabled) {
      toggleRadioMode();
    }
  }, [isEnabled, toggleRadioMode]);

  /**
   * Disable radio mode
   */
  const disableRadioMode = useCallback(() => {
    if (isEnabled) {
      toggleRadioMode();
    }
  }, [isEnabled, toggleRadioMode]);

  // Auto-check when queue state changes
  useEffect(() => {
    if (isEnabled) {
      checkAndFetchMore();
    }
  }, [isEnabled, currentIndex, queue.length, checkAndFetchMore]);

  // Clear fetched IDs when track changes significantly
  useEffect(() => {
    if (activeTrack && fetchedTrackIds.current.size > 50) {
      // Reset to prevent memory leak
      fetchedTrackIds.current.clear();
    }
  }, [activeTrack?.id]);

  return {
    // State
    isEnabled,
    isFetching,
    autoAddedCount,

    // Actions
    toggleRadioMode,
    enableRadioMode,
    disableRadioMode,

    // Manual trigger
    fetchMore: checkAndFetchMore,
  };
}

