/**
 * useProsodyReport — debounced, incremental prosody analysis for the editor.
 *
 * - Debounces recomputation (default 150ms) so the analyzer doesn't run on
 *   every keystroke while the user is actively typing.
 * - Reuses per-run `AnalyzedLine` objects from the previous report via
 *   `analyzeProsodyIncremental`, keeping list items in `<LyricsProsodyPanel>`
 *   referentially stable. That prevents the panel from re-rendering
 *   unchanged rows (no flicker) and lets React keep textarea selection
 *   intact between updates.
 */

import { useEffect, useRef, useState } from "react";
import { analyzeProsody, analyzeProsodyIncremental, type ProsodyReport } from "@/lib/lyrics/prosody";

interface Options {
  debounceMs?: number;
}

export function useProsodyReport(lyrics: string, opts: Options = {}): ProsodyReport {
  const { debounceMs = 150 } = opts;
  const [report, setReport] = useState<ProsodyReport>(() => analyzeProsody(lyrics));
  const prevRef = useRef<ProsodyReport>(report);

  useEffect(() => {
    // Empty text short-circuits — cheap, no timer needed.
    if (!lyrics) {
      const empty = analyzeProsody("");
      prevRef.current = empty;
      setReport(empty);
      return;
    }
    const handle = setTimeout(() => {
      const next = analyzeProsodyIncremental(lyrics, prevRef.current);
      prevRef.current = next;
      setReport(next);
    }, debounceMs);
    return () => clearTimeout(handle);
  }, [lyrics, debounceMs]);

  return report;
}

/**
 * useMusicLabStudio - Comprehensive hook for MusicLab functionality in Studio
 * Integrates vocal/guitar recording, chord detection, and PromptDJ
 */

import { useState, useCallback, useRef, useMemo } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useHaptic } from "@/hooks/useHaptic";
import { useRealtimeChordDetection } from "@/hooks/useRealtimeChordDetection";
import { usePromptDJ } from "@/hooks/usePromptDJ";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { logger } from "@/lib/logger";

export type RecordingType = "vocal" | "guitar" | "instrument";
export type MusicLabMode = "record" | "chords" | "promptdj";

export interface RecordedTrack {
  id: string;
  audioUrl: string;
  type: RecordingType;
  duration: number;
  name: string;
  chords?: Array<{ chord: string; time: number }>;
  waveformData?: number[];
}

export interface MusicLabStats {
  totalRecordings: number;
  totalDuration: number;
  chordsDetected: number;
  djTracksGenerated: number;
}

interface UseMusicLabStudioOptions {
  projectId: string;
  onRecordingComplete?: (track: RecordedTrack) => void;
  onDJTrackGenerated?: (audioUrl: string) => void;
}

export function useMusicLabStudio(options: UseMusicLabStudioOptions) {
  const { projectId, onRecordingComplete, onDJTrackGenerated } = options;
  const { user } = useAuth();
  const haptic = useHaptic();

  // Active mode
  const [mode, setMode] = useState<MusicLabMode>("record");
  const [recordingType, setRecordingType] = useState<RecordingType>("vocal");

  // Recording state
  const [isRecording, setIsRecording] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const [audioLevel, setAudioLevel] = useState(0);
  const [hasPermission, setHasPermission] = useState<boolean | null>(null);

  // Recorded tracks in session
  const [sessionRecordings, setSessionRecordings] = useState<RecordedTrack[]>([]);

  // Refs for recording
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const streamRef = useRef<MediaStream | null>(null);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const startTimeRef = useRef<number>(0);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const levelAnimationRef = useRef<number | null>(null);
  const detectedChordsRef = useRef<Array<{ chord: string; time: number }>>([]);

  // Chord detection
  const chordDetection = useRealtimeChordDetection({
    onChordChange: (chord) => {
      if (isRecording && recordingType === "guitar") {
        const elapsed = (Date.now() - startTimeRef.current) / 1000;
        detectedChordsRef.current.push({
          chord: chord.name,
          time: elapsed,
        });
        haptic.impact("medium");
      }
    },
    minConfidence: 0.5,
    stabilityFrames: 2,
  });

  // PromptDJ integration
  const promptDJ = usePromptDJ();

  // Statistics
  const stats = useMemo(
    (): MusicLabStats => ({
      totalRecordings: sessionRecordings.length,
      totalDuration: sessionRecordings.reduce((sum, r) => sum + r.duration, 0),
      chordsDetected: detectedChordsRef.current.length,
      djTracksGenerated: promptDJ.generatedTracks.length,
    }),
    [sessionRecordings, promptDJ.generatedTracks.length],
  );

  // Audio level monitoring
  const startAudioLevelMonitoring = useCallback((stream: MediaStream) => {
    try {
      const AudioContextClass =
        window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      const audioContext = new AudioContextClass();
      const analyser = audioContext.createAnalyser();
      const source = audioContext.createMediaStreamSource(stream);

      analyser.fftSize = 256;
      analyser.smoothingTimeConstant = 0.8;
      source.connect(analyser);

      audioContextRef.current = audioContext;
      analyserRef.current = analyser;

      const dataArray = new Uint8Array(analyser.frequencyBinCount);

      const updateLevel = () => {
        if (!analyserRef.current) return;

        analyserRef.current.getByteFrequencyData(dataArray);

        let sum = 0;
        for (let i = 0; i < dataArray.length; i++) {
          sum += dataArray[i];
        }
        const average = sum / dataArray.length;
        const normalized = Math.min(1, average / 128);
        setAudioLevel(normalized);

        levelAnimationRef.current = requestAnimationFrame(updateLevel);
      };

      updateLevel();
    } catch (error) {
      logger.error("Audio level monitoring failed", error);
    }
  }, []);

  const stopAudioLevelMonitoring = useCallback(() => {
    if (levelAnimationRef.current) {
      cancelAnimationFrame(levelAnimationRef.current);
      levelAnimationRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    analyserRef.current = null;
    setAudioLevel(0);
  }, []);

  // Check microphone permission
  const checkPermission = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach((track) => track.stop());
      setHasPermission(true);
      return true;
    } catch {
      setHasPermission(false);
      return false;
    }
  }, []);

  // Start recording
  const startRecording = useCallback(async () => {
    try {
      haptic.patterns.select();

      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: recordingType === "vocal",
          noiseSuppression: recordingType === "vocal",
          autoGainControl: false,
        },
      });

      streamRef.current = stream;
      audioChunksRef.current = [];
      detectedChordsRef.current = [];

      // Start audio level monitoring
      startAudioLevelMonitoring(stream);

      // Start chord detection for guitar
      if (recordingType === "guitar") {
        chordDetection.startListening();
      }

      const mediaRecorder = new MediaRecorder(stream, {
        mimeType: MediaRecorder.isTypeSupported("audio/webm;codecs=opus") ? "audio/webm;codecs=opus" : "audio/webm",
      });

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.start(1000);

      startTimeRef.current = Date.now();
      setIsRecording(true);
      setRecordingDuration(0);

      timerRef.current = setInterval(() => {
        setRecordingDuration((Date.now() - startTimeRef.current) / 1000);
      }, 100);

      logger.info("Recording started", { type: recordingType, projectId });
    } catch (error) {
      logger.error("Failed to start recording", error);
      toast.error("Не удалось начать запись");
      haptic.patterns.error();
    }
  }, [recordingType, haptic, startAudioLevelMonitoring, chordDetection, projectId]);

  // Stop recording and upload
  const stopRecording = useCallback(async (): Promise<RecordedTrack | null> => {
    if (!mediaRecorderRef.current || !isRecording) return null;

    haptic.patterns.tap();

    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    stopAudioLevelMonitoring();

    if (recordingType === "guitar") {
      chordDetection.stopListening();
    }

    setIsRecording(false);

    return new Promise((resolve) => {
      const recorder = mediaRecorderRef.current!;

      recorder.onstop = async () => {
        if (streamRef.current) {
          streamRef.current.getTracks().forEach((t) => t.stop());
          streamRef.current = null;
        }

        const audioBlob = new Blob(audioChunksRef.current, { type: "audio/webm" });

        if (audioBlob.size < 1000) {
          toast.error("Запись слишком короткая");
          resolve(null);
          return;
        }

        setIsUploading(true);

        try {
          const fileName = `${user?.id}/${Date.now()}-${recordingType}.webm`;

          const { error: uploadError } = await supabase.storage.from("reference-audio").upload(fileName, audioBlob, {
            contentType: "audio/webm",
            upsert: false,
          });

          if (uploadError) throw uploadError;

          const { data: urlData } = supabase.storage.from("reference-audio").getPublicUrl(fileName);

          const audioUrl = urlData.publicUrl;
          const duration = recordingDuration;

          const typeLabels: Record<RecordingType, string> = {
            vocal: "Вокал",
            guitar: "Гитара",
            instrument: "Инструмент",
          };

          const track: RecordedTrack = {
            id: crypto.randomUUID(),
            audioUrl,
            type: recordingType,
            duration,
            name: `${typeLabels[recordingType]} (${formatDuration(duration)})`,
            chords: recordingType === "guitar" ? [...detectedChordsRef.current] : undefined,
          };

          // Add to session recordings
          setSessionRecordings((prev) => [...prev, track]);

          haptic.patterns.success();
          toast.success("Запись сохранена");

          onRecordingComplete?.(track);

          logger.info("Recording uploaded", {
            type: recordingType,
            duration,
            chordsCount: detectedChordsRef.current.length,
          });

          resolve(track);
        } catch (error) {
          logger.error("Upload failed", error);
          toast.error("Ошибка загрузки записи");
          haptic.patterns.error();
          resolve(null);
        } finally {
          setIsUploading(false);
        }
      };

      recorder.stop();
    });
  }, [
    isRecording,
    recordingType,
    recordingDuration,
    user?.id,
    haptic,
    stopAudioLevelMonitoring,
    chordDetection,
    onRecordingComplete,
  ]);

  // Cancel recording without saving
  const cancelRecording = useCallback(() => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
    }

    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }

    stopAudioLevelMonitoring();

    if (recordingType === "guitar") {
      chordDetection.stopListening();
    }

    setIsRecording(false);
    setRecordingDuration(0);
    audioChunksRef.current = [];
    detectedChordsRef.current = [];

    haptic.patterns.warning();
    toast.info("Запись отменена");
  }, [isRecording, recordingType, haptic, stopAudioLevelMonitoring, chordDetection]);

  // Generate with PromptDJ and add to project
  const generateWithDJ = useCallback(async () => {
    await promptDJ.generateMusic();

    // The latest track should be in generatedTracks after generation
    const latestTrack = promptDJ.generatedTracks[0];
    if (latestTrack?.audioUrl) {
      onDJTrackGenerated?.(latestTrack.audioUrl);
    }
  }, [promptDJ, onDJTrackGenerated]);

  // Remove session recording
  const removeSessionRecording = useCallback((id: string) => {
    setSessionRecordings((prev) => prev.filter((r) => r.id !== id));
  }, []);

  // Cleanup
  const cleanup = useCallback(() => {
    if (isRecording) {
      cancelRecording();
    }
    chordDetection.stopListening();
    promptDJ.stopPlayback();
    promptDJ.stopPreview();
  }, [isRecording, cancelRecording, chordDetection, promptDJ]);

  return {
    // Mode
    mode,
    setMode,
    recordingType,
    setRecordingType,

    // Recording state
    isRecording,
    isUploading,
    recordingDuration,
    audioLevel,
    hasPermission,

    // Recording actions
    checkPermission,
    startRecording,
    stopRecording,
    cancelRecording,

    // Session recordings
    sessionRecordings,
    removeSessionRecording,

    // Chord detection
    chordDetection: {
      currentChord: chordDetection.currentChord,
      chordHistory: chordDetection.chordHistory,
      chromagram: chordDetection.chromagram,
      isListening: chordDetection.isListening,
      isInitializing: chordDetection.isInitializing,
      error: chordDetection.error,
      volume: chordDetection.volume,
      startListening: chordDetection.startListening,
      stopListening: chordDetection.stopListening,
      clearHistory: chordDetection.clearHistory,
      exportProgression: chordDetection.exportProgression,
    },

    // PromptDJ
    promptDJ: {
      channels: promptDJ.channels,
      updateChannel: promptDJ.updateChannel,
      crossfaderPosition: (promptDJ as unknown as { crossfaderPosition?: number }).crossfaderPosition,
      setCrossfaderPosition: (promptDJ as unknown as { setCrossfaderPosition?: (n: number) => void })
        .setCrossfaderPosition,

      globalSettings: promptDJ.globalSettings,
      updateGlobalSettings: promptDJ.updateGlobalSettings,
      isGenerating: promptDJ.isGenerating,
      generatedTracks: promptDJ.generatedTracks,
      generateMusic: generateWithDJ,
      removeTrack: promptDJ.removeTrack,
      isPlaying: promptDJ.isPlaying,
      currentTrack: promptDJ.currentTrack,
      playTrack: promptDJ.playTrack,
      stopPlayback: promptDJ.stopPlayback,
      previewPrompt: (promptDJ as unknown as { previewPrompt?: (p: string) => void }).previewPrompt,
      stopPreview: promptDJ.stopPreview,
      isPreviewPlaying: promptDJ.isPreviewPlaying,
      currentPrompt: promptDJ.currentPrompt,
    },

    // Stats
    stats,

    // Cleanup
    cleanup,
  };
}

// Helper function
function formatDuration(seconds: number): string {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs.toString().padStart(2, "0")}`;
}

export type UseMusicLabStudioReturn = ReturnType<typeof useMusicLabStudio>;

/**
 * usePromptEffects — внутренний хук PromptDJ.
 *
 * Owns the live Tone.js pipeline:
 * - AnalyserNode lifecycle (init on mount, dispose on unmount)
 * - PolySynth + Filter + Reverb + FeedbackDelay chain (previewWithSynth)
 * - Real-time parameter ramps: BPM, brightness osc, filter freq, reverb wet
 * - Scale notes + pattern regeneration derived from deck state changes
 * - Transport start/stop for preview mode
 *
 * Wires onto deck state (channels + globalSettings) via the `decks` argument.
 *
 * Извлечено из src/hooks/usePromptDJEnhanced.ts в Sprint 042 / Task B2
 * (god-hook декомпозиция 879 → <500 LOC).
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { logger } from "@/lib/logger";
import { computeScaleNotes } from "./promptBuilder";
import type { PromptChannel, GlobalSettings } from "./types";

// Tone.js types - loaded dynamically to prevent "Cannot access 't' before initialization" error
type ToneType = typeof import("tone");
type PlayerType = import("tone").Player;
type PolySynthType = import("tone").PolySynth;
type SequenceType = import("tone").Sequence;
type AnalyserType = import("tone").Analyser;
type ReverbType = import("tone").Reverb;
type FilterType = import("tone").Filter;
type FeedbackDelayType = import("tone").FeedbackDelay;

/**
 * Module-level Tone cache. Imported once on first use, then reused.
 * Survives hook unmount so subsequent mounts skip the dynamic import.
 */
let ToneModule: ToneType | null = null;

export interface UsePromptEffectsParams {
  channels: PromptChannel[];
  globalSettings: GlobalSettings;
}

export interface UsePromptEffectsResult {
  /** Initialised FFT analyser node (live while mounted; null before init). */
  analyzerNode: AnalyserType | null;
  /** True while the synth preview is actively playing. */
  isPreviewPlaying: boolean;
  /** Start the PolySynth+Filter+Reverb+Delay preview chain. */
  previewWithSynth: () => Promise<void>;
  /** Stop the preview, dispose the chain, stop the Transport. */
  stopPreview: () => void;
}

export function usePromptEffects({ channels, globalSettings }: UsePromptEffectsParams): UsePromptEffectsResult {
  const [isPreviewPlaying, setIsPreviewPlaying] = useState(false);
  const [, setAnalyserState] = useState<0 | 1>(0); // tick used to re-render when analyser becomes available

  // Tone.js refs (kept alive across renders)
  const playerRef = useRef<PlayerType | null>(null);
  const synthRef = useRef<PolySynthType | null>(null);
  const sequenceRef = useRef<SequenceType | null>(null);
  const analyzerRef = useRef<AnalyserType | null>(null);
  const reverbRef = useRef<ReverbType | null>(null);
  const filterRef = useRef<FilterType | null>(null);
  const delayRef = useRef<FeedbackDelayType | null>(null);

  // Pattern state for real-time updates
  const patternRef = useRef<(string | null)[]>([]);
  const scaleNotesRef = useRef<string[]>([]);

  // Initialize analyzer with dynamic import
  useEffect(() => {
    let cancelled = false;
    const initAnalyzer = async () => {
      if (!ToneModule) {
        ToneModule = await import("tone");
      }
      if (cancelled) return;
      analyzerRef.current = new ToneModule.Analyser("fft", 64);
      // bump tick so consumers reading `analyzerNode` re-render
      setAnalyserState((t) => (t === 0 ? 1 : 0));
    };
    initAnalyzer();

    return () => {
      cancelled = true;
      analyzerRef.current?.dispose();
      playerRef.current?.dispose();
      synthRef.current?.dispose();
      sequenceRef.current?.dispose();
      reverbRef.current?.dispose();
      filterRef.current?.dispose();
      delayRef.current?.dispose();
      analyzerRef.current = null;
    };
  }, []);

  // REAL-TIME: Update BPM when it changes
  useEffect(() => {
    if (isPreviewPlaying && ToneModule) {
      ToneModule.getTransport().bpm.rampTo(globalSettings.bpm, 0.2);
    }
  }, [globalSettings.bpm, isPreviewPlaying]);

  // REAL-TIME: Update synth sound when brightness changes
  useEffect(() => {
    if (isPreviewPlaying && synthRef.current && ToneModule) {
      const oscType =
        globalSettings.brightness > 0.7 ? "sawtooth" : globalSettings.brightness > 0.4 ? "triangle" : "sine";

      synthRef.current.set({
        oscillator: { type: oscType as "sawtooth" | "triangle" | "sine" },
        envelope: {
          attack: 0.02 + (1 - globalSettings.brightness) * 0.1,
          release: 0.3 + (1 - globalSettings.brightness) * 0.4,
        },
      });
    }
  }, [globalSettings.brightness, isPreviewPlaying]);

  // REAL-TIME: Update filter based on brightness
  useEffect(() => {
    if (isPreviewPlaying && filterRef.current) {
      const freq = 200 + globalSettings.brightness * 4000;
      filterRef.current.frequency.rampTo(freq, 0.1);
    }
  }, [globalSettings.brightness, isPreviewPlaying]);

  // REAL-TIME: Update reverb based on mood/texture
  useEffect(() => {
    if (isPreviewPlaying && reverbRef.current) {
      const moodChannel = channels.find((c) => c.type === "mood");
      const textureChannel = channels.find((c) => c.type === "texture");

      const isDreamy =
        moodChannel?.value?.toLowerCase().includes("dreamy") ||
        textureChannel?.value?.toLowerCase().includes("airy") ||
        textureChannel?.value?.toLowerCase().includes("ambient");

      reverbRef.current.wet.rampTo(isDreamy ? 0.6 : 0.2, 0.3);
    }
  }, [channels, isPreviewPlaying]);

  // REAL-TIME: Update scale notes when key/scale changes
  useEffect(() => {
    scaleNotesRef.current = computeScaleNotes(globalSettings.key, globalSettings.scale);
  }, [globalSettings.key, globalSettings.scale]);

  // REAL-TIME: Regenerate pattern when density changes
  useEffect(() => {
    if (isPreviewPlaying && scaleNotesRef.current.length > 0) {
      const energyChannel = channels.find((c) => c.type === "energy");
      const isHighEnergy =
        energyChannel?.enabled &&
        (energyChannel?.weight > 0.6 ||
          energyChannel?.value?.toLowerCase().includes("high") ||
          energyChannel?.value?.toLowerCase().includes("intense"));

      const stepCount = isHighEnergy ? 16 : 8;
      const noteDensity = 0.2 + globalSettings.density * 0.6;

      const newPattern: (string | null)[] = [];
      for (let i = 0; i < stepCount; i++) {
        if (Math.random() < noteDensity) {
          newPattern.push(scaleNotesRef.current[Math.floor(Math.random() * scaleNotesRef.current.length)]);
        } else {
          newPattern.push(null);
        }
      }
      patternRef.current = newPattern;

      // Update sequence events
      if (sequenceRef.current) {
        sequenceRef.current.events = newPattern;
      }
    }
  }, [globalSettings.density, channels, isPreviewPlaying]);

  // Start real-time preview with synth
  const previewWithSynth = useCallback(async () => {
    try {
      if (!ToneModule) {
        ToneModule = await import("tone");
      }
      const Tone = ToneModule;

      await Tone.start();
      // Stop any running preview first
      if (sequenceRef.current) {
        sequenceRef.current.stop();
        sequenceRef.current.dispose();
        sequenceRef.current = null;
      }
      if (synthRef.current) {
        synthRef.current.dispose();
        synthRef.current = null;
      }
      if (reverbRef.current) {
        reverbRef.current.dispose();
        reverbRef.current = null;
      }
      if (filterRef.current) {
        filterRef.current.dispose();
        filterRef.current = null;
      }
      if (delayRef.current) {
        delayRef.current.dispose();
        delayRef.current = null;
      }

      // Create filter for brightness control
      const filter = new Tone.Filter({
        frequency: 200 + globalSettings.brightness * 4000,
        type: "lowpass",
        rolloff: -12,
      });
      filterRef.current = filter;

      // Create reverb
      const reverb = new Tone.Reverb({
        decay: 2.5,
        wet: 0.2,
        preDelay: 0.01,
      });
      await reverb.generate();
      reverbRef.current = reverb;

      // Create delay for texture
      const delay = new Tone.FeedbackDelay({
        delayTime: "8n",
        feedback: 0.2,
        wet: 0.15,
      });
      delayRef.current = delay;

      // Create synth based on settings
      const oscType =
        globalSettings.brightness > 0.7 ? "sawtooth" : globalSettings.brightness > 0.4 ? "triangle" : "sine";

      const synth = new Tone.PolySynth(Tone.Synth, {
        oscillator: { type: oscType as "sawtooth" | "triangle" | "sine" },
        envelope: {
          attack: 0.02 + (1 - globalSettings.brightness) * 0.1,
          decay: 0.2,
          sustain: 0.4,
          release: 0.3 + (1 - globalSettings.brightness) * 0.4,
        },
      });

      // Connect chain: synth -> filter -> delay -> reverb -> analyzer -> destination
      synth.connect(filter);
      filter.connect(delay);
      delay.connect(reverb);

      if (analyzerRef.current) {
        reverb.connect(analyzerRef.current);
      }
      reverb.toDestination();

      synthRef.current = synth;

      // Generate initial scale notes
      scaleNotesRef.current = computeScaleNotes(globalSettings.key, globalSettings.scale);

      // Generate initial pattern
      const energyChannel = channels.find((c) => c.type === "energy");
      const isHighEnergy =
        energyChannel?.enabled &&
        (energyChannel?.weight > 0.6 ||
          energyChannel?.value?.toLowerCase().includes("high") ||
          energyChannel?.value?.toLowerCase().includes("intense"));

      const stepCount = isHighEnergy ? 16 : 8;
      const noteDensity = 0.2 + globalSettings.density * 0.6;

      const pattern: (string | null)[] = [];
      for (let i = 0; i < stepCount; i++) {
        if (Math.random() < noteDensity) {
          pattern.push(scaleNotesRef.current[Math.floor(Math.random() * scaleNotesRef.current.length)]);
        } else {
          pattern.push(null);
        }
      }
      patternRef.current = pattern;

      Tone.getTransport().bpm.value = globalSettings.bpm;

      const sequence = new Tone.Sequence(
        (time, note) => {
          if (note && synthRef.current) {
            const noteLength = isHighEnergy ? "16n" : "8n";
            synthRef.current.triggerAttackRelease(note, noteLength, time);
          }
        },
        pattern,
        isHighEnergy ? "16n" : "8n",
      );

      sequence.loop = true;
      sequence.start(0);
      sequenceRef.current = sequence;

      Tone.getTransport().start();
      setIsPreviewPlaying(true);
    } catch (error) {
      logger.error("Preview error", error instanceof Error ? error : new Error(String(error)));
      toast.error("Ошибка запуска превью");
    }
  }, [globalSettings, channels]);

  // Stop preview
  const stopPreview = useCallback(() => {
    if (!ToneModule) return;
    const Tone = ToneModule;

    if (sequenceRef.current) {
      sequenceRef.current.stop();
      sequenceRef.current.dispose();
      sequenceRef.current = null;
    }
    if (synthRef.current) {
      synthRef.current.dispose();
      synthRef.current = null;
    }
    if (reverbRef.current) {
      reverbRef.current.dispose();
      reverbRef.current = null;
    }
    if (filterRef.current) {
      filterRef.current.dispose();
      filterRef.current = null;
    }
    if (delayRef.current) {
      delayRef.current.dispose();
      delayRef.current = null;
    }
    Tone.getTransport().stop();
    setIsPreviewPlaying(false);
  }, []);

  return {
    analyzerNode: analyzerRef.current,
    isPreviewPlaying,
    previewWithSynth,
    stopPreview,
  };
}

