/**
 * useLoopRegion Hook
 *
 * Manages loop region state and provides automatic loop functionality
 * for audio playback in the stem studio.
 *
 * @author MusicVerse AI
 * @task T064 - Add loop region selection
 */

import { useState, useCallback, useEffect, useRef } from "react";

export interface LoopRegion {
  /** Loop start time in seconds */
  start: number;
  /** Loop end time in seconds */
  end: number;
  /** Whether loop is enabled */
  enabled: boolean;
}

interface UseLoopRegionOptions {
  /** Total duration of the audio */
  duration: number;
  /** Reference to the audio element */
  audioRef?: React.RefObject<HTMLAudioElement>;
  /** Callback when seeking is needed */
  onSeek?: (time: number) => void;
  /** Initial loop region */
  initialRegion?: Partial<LoopRegion>;
}

interface UseLoopRegionReturn {
  /** Current loop region settings */
  loopRegion: LoopRegion;
  /** Update loop region */
  setLoopRegion: (region: LoopRegion) => void;
  /** Toggle loop on/off */
  toggleLoop: () => void;
  /** Clear loop region */
  clearLoop: () => void;
  /** Set loop start point */
  setLoopStart: (time: number) => void;
  /** Set loop end point */
  setLoopEnd: (time: number) => void;
  /** Check if current time is within loop region */
  isInLoopRegion: (time: number) => boolean;
  /** Handle time update (for auto-looping) */
  handleTimeUpdate: (currentTime: number) => boolean;
}

/**
 * Hook for managing loop region state and auto-loop functionality
 */
export function useLoopRegion({
  duration,
  audioRef,
  onSeek,
  initialRegion,
}: UseLoopRegionOptions): UseLoopRegionReturn {
  // Initialize loop region state
  const [loopRegion, setLoopRegionState] = useState<LoopRegion>({
    start: initialRegion?.start ?? 0,
    end: initialRegion?.end ?? duration,
    enabled: initialRegion?.enabled ?? false,
  });

  // Track if we just looped to prevent infinite loops
  const justLoopedRef = useRef(false);

  /**
   * Update loop region with validation
   */
  const setLoopRegion = useCallback(
    (region: LoopRegion) => {
      setLoopRegionState({
        start: Math.max(0, Math.min(region.start, duration - 0.5)),
        end: Math.max(0.5, Math.min(region.end, duration)),
        enabled: region.enabled,
      });
    },
    [duration],
  );

  /**
   * Toggle loop on/off
   */
  const toggleLoop = useCallback(() => {
    setLoopRegionState((prev) => ({
      ...prev,
      enabled: !prev.enabled,
    }));
  }, []);

  /**
   * Clear loop region and disable
   */
  const clearLoop = useCallback(() => {
    setLoopRegionState({
      start: 0,
      end: duration,
      enabled: false,
    });
  }, [duration]);

  /**
   * Set loop start point
   */
  const setLoopStart = useCallback((time: number) => {
    setLoopRegionState((prev) => ({
      ...prev,
      start: Math.max(0, Math.min(time, prev.end - 0.5)),
      enabled: true,
    }));
  }, []);

  /**
   * Set loop end point
   */
  const setLoopEnd = useCallback(
    (time: number) => {
      setLoopRegionState((prev) => ({
        ...prev,
        end: Math.max(prev.start + 0.5, Math.min(time, duration)),
        enabled: true,
      }));
    },
    [duration],
  );

  /**
   * Check if a time is within the loop region
   */
  const isInLoopRegion = useCallback(
    (time: number): boolean => {
      if (!loopRegion.enabled) return false;
      return time >= loopRegion.start && time <= loopRegion.end;
    },
    [loopRegion],
  );

  /**
   * Handle time updates for auto-looping
   * Returns true if loop was triggered
   */
  const handleTimeUpdate = useCallback(
    (currentTime: number): boolean => {
      if (!loopRegion.enabled) return false;

      // Check if we've passed the loop end point
      if (currentTime >= loopRegion.end && !justLoopedRef.current) {
        justLoopedRef.current = true;

        // Seek back to loop start
        if (audioRef?.current) {
          audioRef.current.currentTime = loopRegion.start;
        } else if (onSeek) {
          onSeek(loopRegion.start);
        }

        // Reset the flag after a short delay
        setTimeout(() => {
          justLoopedRef.current = false;
        }, 100);

        return true;
      }

      // Reset flag when we're clearly before the end
      if (currentTime < loopRegion.end - 0.5) {
        justLoopedRef.current = false;
      }

      return false;
    },
    [loopRegion, audioRef, onSeek],
  );

  // Update loop end when duration changes
  useEffect(() => {
    if (duration > 0 && loopRegion.end > duration) {
      setLoopRegionState((prev) => ({
        ...prev,
        end: duration,
      }));
    }
  }, [duration, loopRegion.end]);

  // Set up automatic loop handling via audio element timeupdate event
  useEffect(() => {
    const audio = audioRef?.current;
    if (!audio || !loopRegion.enabled) return;

    const handleAudioTimeUpdate = () => {
      handleTimeUpdate(audio.currentTime);
    };

    audio.addEventListener("timeupdate", handleAudioTimeUpdate);
    return () => {
      audio.removeEventListener("timeupdate", handleAudioTimeUpdate);
    };
  }, [audioRef, loopRegion.enabled, handleTimeUpdate]);

  return {
    loopRegion,
    setLoopRegion,
    toggleLoop,
    clearLoop,
    setLoopStart,
    setLoopEnd,
    isInLoopRegion,
    handleTimeUpdate,
  };
}

/**
 * Master Clock Hook for Audio Synchronization
 *
 * Uses AudioContext.currentTime as the authoritative timing source
 * for all audio stems, ensuring perfect synchronization.
 */

import { useRef, useCallback, useEffect, useState } from "react";
import { logger } from "@/lib/logger";

// Shared AudioContext singleton for timing
let sharedAudioContext: AudioContext | null = null;

function getAudioContext(): AudioContext {
  if (!sharedAudioContext || sharedAudioContext.state === "closed") {
    sharedAudioContext = new AudioContext();
  }
  return sharedAudioContext;
}

interface UseMasterClockProps {
  audioRefs: Record<string, HTMLAudioElement>;
  onTimeUpdate: (time: number) => void;
}

interface MasterClockState {
  isPlaying: boolean;
  startTime: number; // AudioContext time when playback started
  pauseOffset: number; // Position in track when paused
}

export function useMasterClock({ audioRefs, onTimeUpdate }: UseMasterClockProps) {
  const animationFrameRef = useRef<number | undefined>(undefined);
  const clockStateRef = useRef<MasterClockState>({
    isPlaying: false,
    startTime: 0,
    pauseOffset: 0,
  });
  const [isPlaying, setIsPlaying] = useState(false);

  // Drift correction thresholds
  const DRIFT_THRESHOLD = 0.03; // 30ms - very tight for precise sync
  const CRITICAL_DRIFT = 0.1; // 100ms - requires immediate correction

  /**
   * Get current master time based on AudioContext
   */
  const getMasterTime = useCallback((): number => {
    const state = clockStateRef.current;
    if (!state.isPlaying) {
      return state.pauseOffset;
    }

    const ctx = getAudioContext();
    return state.pauseOffset + (ctx.currentTime - state.startTime);
  }, []);

  /**
   * Sync all audio elements to master time
   */
  const syncToMasterTime = useCallback(() => {
    const audios = Object.values(audioRefs);
    if (audios.length === 0) return;

    const masterTime = getMasterTime();
    onTimeUpdate(masterTime);

    // Only sync if playing
    if (!clockStateRef.current.isPlaying) return;

    audios.forEach((audio) => {
      if (audio.duration <= 0 || audio.error || audio.readyState < 2) return;

      const drift = Math.abs(audio.currentTime - masterTime);

      if (drift > CRITICAL_DRIFT) {
        logger.debug(`Critical drift: ${drift.toFixed(3)}s, forcing sync`);
        audio.currentTime = masterTime;
      } else if (drift > DRIFT_THRESHOLD) {
        // Gentle correction for minor drift
        audio.currentTime = masterTime;
      }
    });

    animationFrameRef.current = requestAnimationFrame(syncToMasterTime);
  }, [audioRefs, getMasterTime, onTimeUpdate]);

  /**
   * Start playback from current position
   */
  const play = useCallback(
    async (fromTime?: number) => {
      const ctx = getAudioContext();

      // Resume AudioContext if suspended (browser autoplay policy)
      if (ctx.state === "suspended") {
        await ctx.resume();
      }

      const startPosition = fromTime ?? clockStateRef.current.pauseOffset;

      // Set all audios to the start position
      const audios = Object.values(audioRefs);
      audios.forEach((audio) => {
        if (audio.readyState >= 2) {
          audio.currentTime = startPosition;
        }
      });

      // Record start time
      clockStateRef.current = {
        isPlaying: true,
        startTime: ctx.currentTime,
        pauseOffset: startPosition,
      };

      // Start all audios simultaneously
      const playPromises = audios.map((audio) => audio.play().catch(() => {}));
      await Promise.allSettled(playPromises);

      setIsPlaying(true);

      // Start sync loop
      animationFrameRef.current = requestAnimationFrame(syncToMasterTime);

      return true;
    },
    [audioRefs, syncToMasterTime],
  );

  /**
   * Pause all playback
   */
  const pause = useCallback(() => {
    // Record current position before pausing
    clockStateRef.current = {
      isPlaying: false,
      startTime: 0,
      pauseOffset: getMasterTime(),
    };

    // Pause all audios
    Object.values(audioRefs).forEach((audio) => audio.pause());

    // Stop sync loop
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = undefined;
    }

    setIsPlaying(false);
  }, [audioRefs, getMasterTime]);

  /**
   * Seek to specific time
   */
  const seek = useCallback(
    (time: number) => {
      const wasPlaying = clockStateRef.current.isPlaying;

      // Update clock state
      const ctx = getAudioContext();
      clockStateRef.current = {
        isPlaying: wasPlaying,
        startTime: wasPlaying ? ctx.currentTime : 0,
        pauseOffset: time,
      };

      // Seek all audios
      Object.values(audioRefs).forEach((audio) => {
        if (audio.readyState >= 2) {
          audio.currentTime = time;
        }
      });

      onTimeUpdate(time);
    },
    [audioRefs, onTimeUpdate],
  );

  /**
   * Toggle play/pause
   */
  const toggle = useCallback(async () => {
    if (clockStateRef.current.isPlaying) {
      pause();
    } else {
      await play();
    }
  }, [play, pause]);

  /**
   * Get current playback time
   */
  const getCurrentTime = useCallback((): number => {
    return getMasterTime();
  }, [getMasterTime]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, []);

  return {
    isPlaying,
    play,
    pause,
    seek,
    toggle,
    getCurrentTime,
    getMasterTime,
  };
}

/**
 * Hook for synchronized MIDI playback with audio
 * Plays MIDI notes in real-time as audio plays
 */
import { useRef, useCallback, useEffect, useState } from "react";
import { logger } from "@/lib/logger";
import type { MidiNote } from "@/hooks/useMidiVisualization";

// Tone.js types - loaded dynamically to prevent "Cannot access 't' before initialization" error
type ToneType = typeof import("tone");
type PolySynthType = import("tone").PolySynth;

// Cached Tone module reference
let ToneModule: ToneType | null = null;

interface UseMidiSyncOptions {
  notes: MidiNote[];
  currentTime: number;
  isPlaying: boolean;
  enabled?: boolean;
}

interface UseMidiSyncReturn {
  isReady: boolean;
  isSyncEnabled: boolean;
  isMuted: boolean;
  volume: number;
  setVolume: (vol: number) => void;
  setMuted: (muted: boolean) => void;
  setSyncEnabled: (enabled: boolean) => void;
  initialize: () => Promise<void>;
  playNotePreview: (note: MidiNote) => void;
  stopAll: () => void;
}

// Convert MIDI note number to note name
function midiToNoteName(midi: number): string {
  const noteNames = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
  const octave = Math.floor(midi / 12) - 1;
  const note = noteNames[midi % 12];
  return `${note}${octave}`;
}

export function useMidiSync({ notes, currentTime, isPlaying, enabled = true }: UseMidiSyncOptions): UseMidiSyncReturn {
  const synthRef = useRef<PolySynthType | null>(null);
  const playedNotesRef = useRef<Set<string>>(new Set());
  const lastTimeRef = useRef<number>(0);

  const [isReady, setIsReady] = useState(false);
  const [isSyncEnabled, setIsSyncEnabled] = useState(enabled);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolumeState] = useState(-12); // dB

  // Initialize synth with dynamic Tone.js import
  const initialize = useCallback(async () => {
    if (synthRef.current) return;

    try {
      // Dynamically import Tone.js only when needed
      if (!ToneModule) {
        ToneModule = await import("tone");
      }
      const Tone = ToneModule;

      await Tone.start();

      // Create a pleasant sounding polyphonic synth
      const synth = new Tone.PolySynth(Tone.Synth, {
        oscillator: {
          type: "sine4",
        },
        envelope: {
          attack: 0.01,
          decay: 0.2,
          sustain: 0.4,
          release: 0.5,
        },
      }).toDestination();

      synth.volume.value = volume;
      synthRef.current = synth;
      setIsReady(true);
      logger.debug("MIDI sync synth initialized");
    } catch (err) {
      logger.error("Failed to initialize MIDI sync synth", err);
    }
  }, [volume]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (synthRef.current) {
        synthRef.current.dispose();
        synthRef.current = null;
      }
    };
  }, []);

  // Play notes that fall within the current time window
  useEffect(() => {
    if (!isPlaying || !isSyncEnabled || isMuted || !synthRef.current || !ToneModule || notes.length === 0) {
      return;
    }

    // Time window for note triggering (50ms lookahead)
    const windowStart = lastTimeRef.current;
    const windowEnd = currentTime;

    // Find notes that should be triggered in this window
    const notesToPlay = notes.filter((note) => {
      const noteId = `${note.pitch}_${note.time.toFixed(3)}`;

      // Check if note starts within window and hasn't been played yet
      if (note.time >= windowStart && note.time < windowEnd && !playedNotesRef.current.has(noteId)) {
        return true;
      }
      return false;
    });

    const Tone = ToneModule;

    // Play the notes
    notesToPlay.forEach((note) => {
      const noteId = `${note.pitch}_${note.time.toFixed(3)}`;
      const noteName = midiToNoteName(note.pitch);
      const velocity = note.velocity / 127;
      const duration = Math.min(note.duration, 1.5); // Cap duration

      try {
        synthRef.current?.triggerAttackRelease(noteName, duration, Tone.now(), velocity);
        playedNotesRef.current.add(noteId);
      } catch (err) {
        // Silently ignore errors for individual notes
      }
    });

    lastTimeRef.current = currentTime;
  }, [currentTime, isPlaying, isSyncEnabled, isMuted, notes]);

  // Reset played notes when playback stops or seeks
  useEffect(() => {
    if (!isPlaying) {
      playedNotesRef.current.clear();
      lastTimeRef.current = currentTime;
    }
  }, [isPlaying]);

  // Reset when seeking backwards significantly
  useEffect(() => {
    if (Math.abs(currentTime - lastTimeRef.current) > 0.5) {
      playedNotesRef.current.clear();
      lastTimeRef.current = currentTime;
    }
  }, [currentTime]);

  // Play a single note preview
  const playNotePreview = useCallback(
    (note: MidiNote) => {
      if (!synthRef.current || isMuted || !ToneModule) return;

      const noteName = midiToNoteName(note.pitch);
      const velocity = note.velocity / 127;

      try {
        synthRef.current.triggerAttackRelease(noteName, Math.min(note.duration, 0.5), ToneModule.now(), velocity);
      } catch (err) {
        logger.error("Failed to play note preview", err);
      }
    },
    [isMuted],
  );

  // Stop all notes
  const stopAll = useCallback(() => {
    if (synthRef.current) {
      synthRef.current.releaseAll();
    }
    playedNotesRef.current.clear();
  }, []);

  // Set volume
  const setVolume = useCallback((vol: number) => {
    setVolumeState(vol);
    if (synthRef.current) {
      synthRef.current.volume.value = vol;
    }
  }, []);

  // Set muted
  const setMuted = useCallback(
    (muted: boolean) => {
      setIsMuted(muted);
      if (synthRef.current) {
        synthRef.current.volume.value = muted ? -Infinity : volume;
      }
    },
    [volume],
  );

  // Set sync enabled
  const setSyncEnabled = useCallback(
    (enabled: boolean) => {
      setIsSyncEnabled(enabled);
      if (!enabled) {
        stopAll();
      }
    },
    [stopAll],
  );

  return {
    isReady,
    isSyncEnabled,
    isMuted,
    volume,
    setVolume,
    setMuted,
    setSyncEnabled,
    initialize,
    playNotePreview,
    stopAll,
  };
}

/**
 * Mobile Audio Fallback Hook
 *
 * Detects mobile device audio element limits and provides
 * automatic fallback for devices with limited concurrent audio support.
 */

import { useState, useEffect, useCallback, useRef } from "react";
import { logger } from "@/lib/logger";
import { getAudioContextClass, safeCloseAudioContext } from "@/lib/audio/audioContextHelper";
import { TrackStem } from "@/hooks/useTrackStems";

// Mobile browsers typically limit concurrent audio elements
const MOBILE_AUDIO_LIMIT = 6;
const DESKTOP_AUDIO_LIMIT = 16;

interface AudioCapabilities {
  maxConcurrentAudio: number;
  isLimited: boolean;
  platform: "mobile" | "desktop";
  supportsWebAudio: boolean;
  audioContextState: AudioContextState | "unavailable";
}

interface UseMobileAudioFallbackProps {
  stems: TrackStem[];
  enabled?: boolean;
}

interface UseMobileAudioFallbackReturn {
  capabilities: AudioCapabilities;
  activeStems: TrackStem[];
  limitedStems: TrackStem[];
  isLimited: boolean;
  prioritizeStems: (stems: TrackStem[]) => TrackStem[];
  showFallbackWarning: boolean;
  dismissWarning: () => void;
}

// Priority order for stems when limiting
const STEM_PRIORITY: Record<string, number> = {
  vocals: 1,
  vocal: 1,
  drums: 2,
  bass: 3,
  guitar: 4,
  piano: 5,
  keyboard: 5,
  strings: 6,
  synth: 7,
  instrumental: 8,
  other: 9,
};

function detectPlatform(): "mobile" | "desktop" {
  if (typeof navigator === "undefined") return "desktop";

  const ua = navigator.userAgent.toLowerCase();
  const isMobile = /android|webos|iphone|ipad|ipod|blackberry|iemobile|opera mini/i.test(ua);

  // Also check for touch capability and screen size
  const isTouchDevice = "ontouchstart" in window || navigator.maxTouchPoints > 0;
  const isSmallScreen = window.innerWidth < 768;

  return isMobile || (isTouchDevice && isSmallScreen) ? "mobile" : "desktop";
}

async function detectAudioCapabilities(): Promise<AudioCapabilities> {
  const platform = detectPlatform();
  let supportsWebAudio = false;
  let audioContextState: AudioContextState | "unavailable" = "unavailable";

  try {
    const AudioContextClass = getAudioContextClass();
    if (AudioContextClass) {
      supportsWebAudio = true;
      const testContext = new AudioContextClass();
      audioContextState = testContext.state;
      await safeCloseAudioContext(testContext);
    }
  } catch {
    supportsWebAudio = false;
  }

  const maxConcurrentAudio = platform === "mobile" ? MOBILE_AUDIO_LIMIT : DESKTOP_AUDIO_LIMIT;

  return {
    maxConcurrentAudio,
    isLimited: platform === "mobile",
    platform,
    supportsWebAudio,
    audioContextState,
  };
}

function prioritizeStemsByType(stems: TrackStem[]): TrackStem[] {
  return [...stems].sort((a, b) => {
    const priorityA = STEM_PRIORITY[a.stem_type.toLowerCase()] ?? 10;
    const priorityB = STEM_PRIORITY[b.stem_type.toLowerCase()] ?? 10;
    return priorityA - priorityB;
  });
}

export function useMobileAudioFallback({
  stems,
  enabled = true,
}: UseMobileAudioFallbackProps): UseMobileAudioFallbackReturn {
  const [capabilities, setCapabilities] = useState<AudioCapabilities>({
    maxConcurrentAudio: DESKTOP_AUDIO_LIMIT,
    isLimited: false,
    platform: "desktop",
    supportsWebAudio: true,
    audioContextState: "unavailable",
  });

  const [showFallbackWarning, setShowFallbackWarning] = useState(false);
  const warningDismissedRef = useRef(false);

  // Detect capabilities on mount
  useEffect(() => {
    detectAudioCapabilities().then((caps) => {
      setCapabilities(caps);
      logger.info("Audio capabilities detected", {
        maxConcurrentAudio: caps.maxConcurrentAudio,
        isLimited: caps.isLimited,
        platform: caps.platform,
        supportsWebAudio: caps.supportsWebAudio,
      });
    });
  }, []);

  // Calculate which stems are active vs limited
  const prioritizedStems = prioritizeStemsByType(stems);
  const needsLimiting = enabled && capabilities.isLimited && stems.length > capabilities.maxConcurrentAudio;

  const activeStems = needsLimiting ? prioritizedStems.slice(0, capabilities.maxConcurrentAudio) : stems;

  const limitedStems = needsLimiting ? prioritizedStems.slice(capabilities.maxConcurrentAudio) : [];

  // Show warning when stems are limited
  useEffect(() => {
    if (needsLimiting && limitedStems.length > 0 && !warningDismissedRef.current) {
      setShowFallbackWarning(true);
      logger.warn("Stems limited due to mobile audio constraints", {
        total: stems.length,
        active: activeStems.length,
        limited: limitedStems.length,
        limitedTypes: limitedStems.map((s) => s.stem_type),
      });
    } else {
      setShowFallbackWarning(false);
    }
  }, [needsLimiting, limitedStems.length, stems.length, activeStems.length]);

  const dismissWarning = useCallback(() => {
    setShowFallbackWarning(false);
    warningDismissedRef.current = true;
  }, []);

  const prioritizeStems = useCallback((stemsToSort: TrackStem[]) => {
    return prioritizeStemsByType(stemsToSort);
  }, []);

  return {
    capabilities,
    activeStems,
    limitedStems,
    isLimited: needsLimiting,
    prioritizeStems,
    showFallbackWarning,
    dismissWarning,
  };
}

/**
 * Component to show mobile audio warning
 */
export { MobileAudioWarning } from "@/components/studio/MobileAudioWarning";

