source:
/**
 * useStudioOperationLock
 *
 * Manages operation availability based on track state:
 * - Fresh track: all operations available
 * - After extend/replace_section: still available (operates on updated track)
 * - After separate_stems: blocks extend/replace_section (requires save as new version)
 *
 * @see ADR-011 for architecture decisions
 */

import { useMemo, useCallback } from "react";
import { StudioProject, StudioTrack } from "@/stores/useUnifiedStudioStore";

export type StudioOperation =
  | "generate"
  | "extend"
  | "replace_section"
  | "add_instrumental"
  | "add_vocals"
  | "separate_stems"
  | "cover"
  | "replace_instrumental"
  | "save_as_version";

interface OperationLockResult {
  /** Whether stems exist in the project */
  hasStems: boolean;
  /** Whether any track is pending/processing */
  hasPendingTracks: boolean;
  /** Whether any section has been replaced */
  hasReplacedSections: boolean;
  /** Current track version (for versioning) */
  trackVersion: number;
  /** Check if operation is allowed */
  isOperationAllowed: (op: StudioOperation) => boolean;
  /** Get reason why operation is blocked (null if allowed) */
  getBlockReason: (op: StudioOperation) => string | null;
  /** List of currently blocked operations */
  blockedOperations: StudioOperation[];
  /** Whether user can save as new version to bypass blocks */
  canSaveAsNewVersion: boolean;
  /** Get all operations with their availability status */
  getOperationStates: () => OperationState[];
}

export interface OperationState {
  operation: StudioOperation;
  allowed: boolean;
  reason: string | null;
  label: string;
}

const STEM_TYPES = ["vocal", "instrumental", "drums", "bass", "other"] as const;

const OPERATION_LABELS: Record<StudioOperation, string> = {
  generate: "Создать",
  extend: "Расширить",
  replace_section: "Заменить секцию",
  add_instrumental: "Добавить инструментал",
  add_vocals: "Добавить вокал",
  separate_stems: "Разделить на стемы",
  cover: "Кавер",
  replace_instrumental: "Заменить инструментал",
  save_as_version: "Сохранить как версию",
};

export function useStudioOperationLock(project: StudioProject | null): OperationLockResult {
  // Check if project has separated stems
  const hasStems = useMemo(() => {
    if (!project?.tracks) return false;
    return project.tracks.some((t) => STEM_TYPES.includes(t.type as (typeof STEM_TYPES)[number]));
  }, [project?.tracks]);

  // Check if any track is pending/processing
  const hasPendingTracks = useMemo(() => {
    if (!project?.tracks) return false;
    return project.tracks.some((t) => t.status === "pending" || t.status === "processing");
  }, [project?.tracks]);

  // Check if any section has been replaced (would be tracked via metadata)
  const hasReplacedSections = useMemo(() => {
    if (!project?.tracks) return false;
    // Check for tracks that have version history indicating replace_section
    return project.tracks.some(
      (t) => t.versions && t.versions.some((v) => v.metadata?.version_type === "replace_section"),
    );
  }, [project?.tracks]);

  // Get current track version number
  const trackVersion = useMemo(() => {
    if (!project?.tracks) return 1;
    const mainTrack = project.tracks.find((t) => t.type === "main");
    return mainTrack?.versions?.length || 1;
  }, [project?.tracks]);

  // Whether save as new version is available
  const canSaveAsNewVersion = useMemo(() => {
    // Can save as new version if stems exist (to bypass stem blocks)
    return hasStems;
  }, [hasStems]);

  // Get list of blocked operations
  const blockedOperations = useMemo((): StudioOperation[] => {
    const blocked: StudioOperation[] = [];

    // When stems exist, extending or replacing sections would invalidate stems
    if (hasStems) {
      blocked.push("extend", "replace_section");
      // Already have stems, can't separate again
      blocked.push("separate_stems");
    }

    // When pending tracks exist, block most generation operations
    if (hasPendingTracks) {
      blocked.push(
        "generate",
        "extend",
        "replace_section",
        "add_instrumental",
        "add_vocals",
        "cover",
        "replace_instrumental",
        "separate_stems",
      );
    }

    return [...new Set(blocked)];
  }, [hasStems, hasPendingTracks]);

  // Check if specific operation is allowed
  const isOperationAllowed = useCallback(
    (op: StudioOperation): boolean => {
      return !blockedOperations.includes(op);
    },
    [blockedOperations],
  );

  // Get human-readable block reason
  const getBlockReason = useCallback(
    (op: StudioOperation): string | null => {
      // Pending tracks block everything
      if (hasPendingTracks) {
        const pendingOps: StudioOperation[] = [
          "generate",
          "extend",
          "replace_section",
          "add_instrumental",
          "add_vocals",
          "cover",
          "replace_instrumental",
          "separate_stems",
        ];
        if (pendingOps.includes(op)) {
          return "Дождитесь завершения текущей генерации.";
        }
      }

      // Stems block structural changes
      if (hasStems) {
        if (op === "extend" || op === "replace_section") {
          return "Стемы блокируют изменение структуры трека. Создайте новую версию для продолжения редактирования.";
        }
        if (op === "separate_stems") {
          return "Стемы уже разделены.";
        }
      }

      return null;
    },
    [hasStems, hasPendingTracks],
  );

  // Get all operations with their states
  const getOperationStates = useCallback((): OperationState[] => {
    const allOps: StudioOperation[] = [
      "generate",
      "extend",
      "replace_section",
      "cover",
      "add_vocals",
      "add_instrumental",
      "separate_stems",
      "replace_instrumental",
      "save_as_version",
    ];

    return allOps.map((op) => ({
      operation: op,
      allowed: isOperationAllowed(op),
      reason: getBlockReason(op),
      label: OPERATION_LABELS[op],
    }));
  }, [isOperationAllowed, getBlockReason]);

  return {
    hasStems,
    hasPendingTracks,
    hasReplacedSections,
    trackVersion,
    isOperationAllowed,
    getBlockReason,
    blockedOperations,
    canSaveAsNewVersion,
    getOperationStates,
  };
}

import { useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import {
  useUnifiedStudioStore,
  StudioTrack,
  StudioProject,
  TrackType,
  TRACK_COLORS,
} from "@/stores/useUnifiedStudioStore";
import { toast } from "sonner";

interface UseStudioProjectReturn {
  isLoading: boolean;
  isSaving: boolean;
  error: string | null;
  project: StudioProject | null;
  loadProject: (projectId: string) => Promise<boolean>;
  createFromTrack: (trackId: string) => Promise<string | null>;
  createEmptyProject: (name: string) => Promise<string | null>;
  addTrackFromUrl: (url: string, name: string, type: TrackType) => void;
  deleteProject: (projectId: string) => Promise<boolean>;
  saveProject: () => Promise<boolean>;
}

export function useStudioProject(): UseStudioProjectReturn {
  const { user } = useAuth();
  const store = useUnifiedStudioStore();
  const {
    project,
    isLoading,
    isSaving,
    loadProject: storeLoadProject,
    createProject: storeCreateProject,
    saveProject: storeSaveProject,
    deleteProject: storeDeleteProject,
    addTrack,
  } = store;

  const loadProject = useCallback(
    async (projectId: string): Promise<boolean> => {
      return await storeLoadProject(projectId);
    },
    [storeLoadProject],
  );

  const createFromTrack = useCallback(
    async (trackId: string): Promise<string | null> => {
      try {
        // Fetch track data
        const { data: track, error: trackError } = await supabase
          .from("tracks")
          .select("title, audio_url, streaming_url, local_audio_url, duration_seconds")
          .eq("id", trackId)
          .single();

        if (trackError) throw trackError;
        if (!track) throw new Error("Track not found");

        const audioUrl = track.streaming_url || track.local_audio_url || track.audio_url || undefined;

        const projectId = await storeCreateProject({
          name: `Проект: ${track.title || "Без названия"}`,
          userId: user?.id,
          sourceTrackId: trackId,
          sourceAudioUrl: audioUrl,
          duration: track.duration_seconds || undefined,
          tracks: audioUrl
            ? [
                {
                  name: track.title || "Основной трек",
                  type: "main",
                  audioUrl,
                  volume: 0.85,
                  pan: 0,
                  muted: false,
                  solo: false,
                  color: TRACK_COLORS.main,
                  status: "ready",
                },
              ]
            : [],
        });

        if (projectId) {
          toast.success("Проект создан");
        }
        return projectId;
      } catch (err) {
        const message = err instanceof Error ? err.message : "Failed to create project";
        toast.error("Ошибка создания проекта", { description: message });
        return null;
      }
    },
    [storeCreateProject, user?.id],
  );

  const createEmptyProject = useCallback(
    async (name: string): Promise<string | null> => {
      try {
        const projectId = await storeCreateProject({
          name: name || "Новый проект",
          userId: user?.id,
        });

        if (projectId) {
          toast.success("Проект создан");
        }
        return projectId;
      } catch (err) {
        const message = err instanceof Error ? err.message : "Failed to create project";
        toast.error("Ошибка создания проекта", { description: message });
        return null;
      }
    },
    [storeCreateProject],
  );

  const addTrackFromUrl = useCallback(
    (url: string, name: string, type: TrackType): void => {
      if (!project) {
        toast.error("Нет активного проекта");
        return;
      }

      addTrack({
        name,
        type,
        audioUrl: url,
        volume: 0.8,
        pan: 0,
        muted: false,
        solo: false,
        color: TRACK_COLORS[type] || TRACK_COLORS.other,
      });

      toast.success(`Дорожка "${name}" добавлена`);
    },
    [project, addTrack],
  );

  const deleteProject = useCallback(
    async (projectId: string): Promise<boolean> => {
      const success = await storeDeleteProject(projectId);
      if (success) {
        toast.success("Проект удалён");
      } else {
        toast.error("Ошибка удаления");
      }
      return success;
    },
    [storeDeleteProject],
  );

  const saveProject = useCallback(async (): Promise<boolean> => {
    return await storeSaveProject();
  }, [storeSaveProject]);

  return {
    isLoading,
    isSaving,
    error: null,
    project,
    loadProject,
    createFromTrack,
    createEmptyProject,
    addTrackFromUrl,
    deleteProject,
    saveProject,
  };
}

/**
 * useTransportSync - Synchronize multiple audio sources with transport controls
 *
 * Features:
 * - Sample-accurate playback sync
 * - Drift correction
 * - Loop region support
 * - Seek with preroll
 */

import { useRef, useCallback, useEffect, useState } from "react";
import { logger } from "@/lib/logger";

export interface AudioSource {
  id: string;
  element: HTMLAudioElement;
  offset?: number; // Start offset in seconds
  gain?: number;
}

export interface TransportState {
  isPlaying: boolean;
  currentTime: number;
  duration: number;
  loopStart: number | null;
  loopEnd: number | null;
  isLooping: boolean;
}

export interface UseTransportSyncOptions {
  /** Maximum allowed drift in seconds before correction */
  maxDrift?: number;
  /** How often to check for drift (ms) */
  syncInterval?: number;
  /** Preroll time when seeking (seconds) */
  prerollTime?: number;
  /** Enable loop region */
  enableLoop?: boolean;
}

const DEFAULT_OPTIONS: Required<UseTransportSyncOptions> = {
  maxDrift: 0.05, // 50ms
  syncInterval: 100,
  prerollTime: 0.1,
  enableLoop: true,
};

export function useTransportSync(options: UseTransportSyncOptions = {}) {
  const opts = { ...DEFAULT_OPTIONS, ...options };

  const sourcesRef = useRef<Map<string, AudioSource>>(new Map());
  const masterTimeRef = useRef(0);
  const isPlayingRef = useRef(false);
  const animationFrameRef = useRef<number | null>(null);
  const syncIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const [transportState, setTransportState] = useState<TransportState>({
    isPlaying: false,
    currentTime: 0,
    duration: 0,
    loopStart: null,
    loopEnd: null,
    isLooping: false,
  });

  // Register an audio source
  const registerSource = useCallback((source: AudioSource) => {
    sourcesRef.current.set(source.id, source);

    // Update duration based on longest source
    const maxDuration = Math.max(...Array.from(sourcesRef.current.values()).map((s) => s.element.duration || 0));

    setTransportState((prev) => ({ ...prev, duration: maxDuration }));

    logger.debug("[TransportSync] Source registered", { id: source.id });
  }, []);

  // Unregister an audio source
  const unregisterSource = useCallback((id: string) => {
    sourcesRef.current.delete(id);
    logger.debug("[TransportSync] Source unregistered", { id });
  }, []);

  // Get current master time
  const getCurrentTime = useCallback((): number => {
    return masterTimeRef.current;
  }, []);

  // Sync all sources to master time
  const syncSources = useCallback(() => {
    const masterTime = masterTimeRef.current;
    const sources = Array.from(sourcesRef.current.values());

    for (const source of sources) {
      const targetTime = masterTime + (source.offset || 0);
      const currentTime = source.element.currentTime;
      const drift = Math.abs(currentTime - targetTime);

      if (drift > opts.maxDrift) {
        source.element.currentTime = targetTime;
        logger.debug("[TransportSync] Drift corrected", {
          id: source.id,
          drift,
          target: targetTime,
        });
      }
    }
  }, [opts.maxDrift]);

  // Update loop
  const updateLoop = useCallback(() => {
    if (!opts.enableLoop) return;

    const { loopStart, loopEnd, isLooping } = transportState;

    if (isLooping && loopStart !== null && loopEnd !== null) {
      if (masterTimeRef.current >= loopEnd) {
        masterTimeRef.current = loopStart;

        // Sync all sources to loop start
        for (const source of sourcesRef.current.values()) {
          const targetTime = loopStart + (source.offset || 0);
          source.element.currentTime = targetTime;
        }

        logger.debug("[TransportSync] Loop triggered");
      }
    }
  }, [opts.enableLoop, transportState]);

  // Animation frame update
  const updateFrame = useCallback(() => {
    if (!isPlayingRef.current) return;

    // Get time from first source
    const sources = Array.from(sourcesRef.current.values());
    if (sources.length > 0) {
      const firstSource = sources[0];
      masterTimeRef.current = firstSource.element.currentTime - (firstSource.offset || 0);
    }

    // Check loop
    updateLoop();

    // Update state
    setTransportState((prev) => ({
      ...prev,
      currentTime: masterTimeRef.current,
    }));

    animationFrameRef.current = requestAnimationFrame(updateFrame);
  }, [updateLoop]);

  // Play
  const play = useCallback(async () => {
    const sources = Array.from(sourcesRef.current.values());

    // Start all sources
    const playPromises = sources.map(async (source) => {
      try {
        await source.element.play();
      } catch (error) {
        logger.warn("[TransportSync] Play failed", { id: source.id, error });
      }
    });

    await Promise.all(playPromises);

    isPlayingRef.current = true;
    setTransportState((prev) => ({ ...prev, isPlaying: true }));

    // Start update loop
    animationFrameRef.current = requestAnimationFrame(updateFrame);

    // Start sync interval
    syncIntervalRef.current = setInterval(syncSources, opts.syncInterval);

    logger.debug("[TransportSync] Play started");
  }, [updateFrame, syncSources, opts.syncInterval]);

  // Pause
  const pause = useCallback(() => {
    const sources = Array.from(sourcesRef.current.values());

    for (const source of sources) {
      source.element.pause();
    }

    isPlayingRef.current = false;
    setTransportState((prev) => ({ ...prev, isPlaying: false }));

    // Stop update loop
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }

    // Stop sync interval
    if (syncIntervalRef.current) {
      clearInterval(syncIntervalRef.current);
      syncIntervalRef.current = null;
    }

    logger.debug("[TransportSync] Paused");
  }, []);

  // Toggle play/pause
  const toggle = useCallback(() => {
    if (isPlayingRef.current) {
      pause();
    } else {
      play();
    }
  }, [play, pause]);

  // Seek to time
  const seek = useCallback((time: number) => {
    masterTimeRef.current = time;

    const sources = Array.from(sourcesRef.current.values());
    for (const source of sources) {
      const targetTime = time + (source.offset || 0);
      source.element.currentTime = Math.max(0, targetTime);
    }

    setTransportState((prev) => ({ ...prev, currentTime: time }));

    logger.debug("[TransportSync] Seeked", { time });
  }, []);

  // Set loop region
  const setLoop = useCallback((start: number | null, end: number | null, enabled: boolean = true) => {
    setTransportState((prev) => ({
      ...prev,
      loopStart: start,
      loopEnd: end,
      isLooping: enabled && start !== null && end !== null,
    }));

    logger.debug("[TransportSync] Loop set", { start, end, enabled });
  }, []);

  // Clear loop
  const clearLoop = useCallback(() => {
    setTransportState((prev) => ({
      ...prev,
      loopStart: null,
      loopEnd: null,
      isLooping: false,
    }));
  }, []);

  // Stop and reset
  const stop = useCallback(() => {
    pause();
    seek(0);
    logger.debug("[TransportSync] Stopped");
  }, [pause, seek]);

  // Cleanup
  useEffect(() => {
    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (syncIntervalRef.current) {
        clearInterval(syncIntervalRef.current);
      }
    };
  }, []);

  return {
    // State
    transportState,
    isPlaying: transportState.isPlaying,
    currentTime: transportState.currentTime,
    duration: transportState.duration,

    // Controls
    play,
    pause,
    toggle,
    stop,
    seek,

    // Loop
    setLoop,
    clearLoop,
    isLooping: transportState.isLooping,

    // Source management
    registerSource,
    unregisterSource,
    getCurrentTime,

    // Utils
    syncSources,
  };
}

/**
 * useUnifiedStudio - Unified Studio Hook
 *
 * Consolidates logic from multiple studio stores and hooks into a single
 * interface for both track and project modes.
 *
 * This hook provides:
 * - Project/Track data access
 * - Playback controls
 * - Track controls (mute/solo/volume)
 * - AI actions (stems, extend, cover, replace)
 * - Effects management
 * - History (undo/redo)
 * - Export functionality
 *
 * @see ADR-011 for architecture decisions
 */

import { useCallback, useMemo } from "react";
import { useUnifiedStudioStore } from "@/stores/useUnifiedStudioStore";
import type { StudioTrack, StudioProject, TrackType } from "@/stores/useUnifiedStudioStore";
import type { StemEffects } from "@/hooks/studio/types";

export interface UseUnifiedStudioOptions {
  mode: "track" | "project";
  id: string;
}

export interface UnifiedStudioAPI {
  // Data
  project: StudioProject | null;
  tracks: StudioTrack[];
  isLoading: boolean;
  isSaving: boolean;
  hasUnsavedChanges: boolean;

  // Playback
  isPlaying: boolean;
  currentTime: number;
  duration: number;
  masterVolume: number;
  play: () => void;
  pause: () => void;
  stop: () => void;
  seek: (time: number) => void;
  setMasterVolume: (volume: number) => void;

  // Track controls
  toggleMute: (trackId: string) => void;
  toggleSolo: (trackId: string) => void;
  setVolume: (trackId: string, volume: number) => void;
  setPan: (trackId: string, pan: number) => void;
  removeTrack: (trackId: string) => void;
  reorderTracks: (fromIndex: number, toIndex: number) => void;

  // Version management
  setActiveVersion: (trackId: string, versionLabel: string) => void;

  // History
  canUndo: boolean;
  canRedo: boolean;
  undo: () => void;
  redo: () => void;

  // Save/Export
  save: () => Promise<boolean>;

  // Helpers
  getTrackById: (trackId: string) => StudioTrack | undefined;
  getTracksByType: (type: TrackType) => StudioTrack[];
  hasStems: boolean;
  hasPendingTracks: boolean;
}

/**
 * Hook that provides unified access to studio functionality
 * for both track and project modes.
 */
export function useUnifiedStudio(options: UseUnifiedStudioOptions): UnifiedStudioAPI {
  const {
    project,
    isLoading,
    isSaving,
    hasUnsavedChanges,
    isPlaying,
    currentTime,
    play,
    pause,
    stop,
    seek,
    toggleTrackMute,
    toggleTrackSolo,
    setTrackVolume,
    setTrackPan,
    setMasterVolume,
    removeTrack,
    reorderTracks,
    setTrackActiveVersion,
    saveProject,
    canUndo: canUndoFn,
    canRedo: canRedoFn,
    undo,
    redo,
  } = useUnifiedStudioStore();

  // Evaluate undo/redo state
  const canUndo = typeof canUndoFn === "function" ? canUndoFn() : !!canUndoFn;
  const canRedo = typeof canRedoFn === "function" ? canRedoFn() : !!canRedoFn;

  // Derived state with stem sorting (vocals always first)
  const tracks = useMemo(() => {
    const rawTracks = project?.tracks ?? [];

    // Sort tracks: vocals first, then by type priority
    const typeOrder: Record<string, number> = {
      // Vocals always first (priority 0-1)
      vocal: 0,
      vocals: 0,
      voice: 0,
      lead_vocal: 0,
      main_vocal: 0,
      backing_vocals: 1,
      backing_vocal: 1,
      harmonies: 1,
      // Instrumental next
      instrumental: 2,
      // Then by instrument
      drums: 3,
      bass: 4,
      guitar: 5,
      piano: 6,
      keyboard: 7,
      synth: 8,
      strings: 9,
      brass: 10,
      woodwinds: 11,
      percussion: 12,
      fx: 13,
      atmosphere: 14,
      other: 15,
      main: -1, // Main track always first if present
    };

    return [...rawTracks].sort((a, b) => {
      // Check both type and stemType (some tracks may use stemType)
      const typeA = (a as { stemType?: string }).stemType || a.type || "other";
      const typeB = (b as { stemType?: string }).stemType || b.type || "other";

      // Normalize to lowercase
      const normalizedA = typeA.toLowerCase();
      const normalizedB = typeB.toLowerCase();

      // Check if either contains 'vocal' anywhere in the name
      const isVocalA = normalizedA.includes("vocal") || normalizedA === "voice";
      const isVocalB = normalizedB.includes("vocal") || normalizedB === "voice";

      // Vocals always come first
      if (isVocalA && !isVocalB) return -1;
      if (!isVocalA && isVocalB) return 1;

      // Then sort by type order
      const orderA = typeOrder[normalizedA] ?? 99;
      const orderB = typeOrder[normalizedB] ?? 99;
      return orderA - orderB;
    });
  }, [project?.tracks]);

  const duration = useMemo(() => {
    if (project?.durationSeconds) return project.durationSeconds;
    // Calculate from tracks if not set
    const maxDuration = tracks.reduce((max, track) => {
      const trackDuration =
        track.clips?.reduce((clipMax, clip) => {
          return Math.max(clipMax, clip.startTime + clip.duration);
        }, 0) ?? 0;
      return Math.max(max, trackDuration);
    }, 0);
    return maxDuration || 180; // Default 3 minutes
  }, [project?.durationSeconds, tracks]);

  const masterVolume = project?.masterVolume ?? 0.85;

  // Check if stems exist
  const hasStems = useMemo(() => {
    const stemTypes = ["vocal", "instrumental", "drums", "bass", "other"];
    return tracks.some((t) => stemTypes.includes(t.type));
  }, [tracks]);

  // Check for pending tracks
  const hasPendingTracks = useMemo(() => {
    return tracks.some((t) => t.status === "pending" || t.status === "processing");
  }, [tracks]);

  // Helper functions
  const getTrackById = useCallback(
    (trackId: string) => {
      return tracks.find((t) => t.id === trackId);
    },
    [tracks],
  );

  const getTracksByType = useCallback(
    (type: TrackType) => {
      return tracks.filter((t) => t.type === type);
    },
    [tracks],
  );

  // Wrapped actions with mode-aware behavior
  const toggleMute = useCallback(
    (trackId: string) => {
      toggleTrackMute(trackId);
    },
    [toggleTrackMute],
  );

  const toggleSolo = useCallback(
    (trackId: string) => {
      toggleTrackSolo(trackId);
    },
    [toggleTrackSolo],
  );

  const setVolume = useCallback(
    (trackId: string, volume: number) => {
      setTrackVolume(trackId, volume);
    },
    [setTrackVolume],
  );

  const setPan = useCallback(
    (trackId: string, pan: number) => {
      setTrackPan(trackId, pan);
    },
    [setTrackPan],
  );

  const setActiveVersion = useCallback(
    (trackId: string, versionLabel: string) => {
      setTrackActiveVersion(trackId, versionLabel);
    },
    [setTrackActiveVersion],
  );

  const save = useCallback(async () => {
    return saveProject();
  }, [saveProject]);

  return {
    // Data
    project,
    tracks,
    isLoading,
    isSaving,
    hasUnsavedChanges,

    // Playback
    isPlaying,
    currentTime,
    duration,
    masterVolume,
    play,
    pause,
    stop,
    seek,
    setMasterVolume,

    // Track controls
    toggleMute,
    toggleSolo,
    setVolume,
    setPan,
    removeTrack,
    reorderTracks,

    // Version management
    setActiveVersion,

    // History
    canUndo,
    canRedo,
    undo,
    redo,

    // Save
    save,

    // Helpers
    getTrackById,
    getTracksByType,
    hasStems,
    hasPendingTracks,
  };
}

export type { StudioTrack, StudioProject, TrackType };

/**
 * Telegram Fullscreen Hook
 *
 * Provides fullscreen mode control for Telegram Mini Apps
 * Available in Telegram Mini App 2.0+
 *
 * Features:
 * - Enter/exit fullscreen mode
 * - Track fullscreen state
 * - Automatic cleanup
 * - Event listeners for fullscreen changes
 *
 * @example
 * ```tsx
 * const { isFullscreen, enterFullscreen, exitFullscreen, toggleFullscreen } = useTelegramFullscreen();
 *
 * <Button onClick={toggleFullscreen}>
 *   {isFullscreen ? 'Exit Fullscreen' : 'Enter Fullscreen'}
 * </Button>
 * ```
 */

import { useState, useEffect, useCallback } from "react";
import { useTelegram } from "@/contexts/TelegramContext";
import { logger } from "@/lib/logger";

const log = logger.child({ module: "TelegramFullscreen" });

interface UseTelegramFullscreenReturn {
  isFullscreen: boolean;
  isSupported: boolean;
  /** True if the last fullscreen request failed */
  isFullscreenFailed: boolean;
  /** Error message from failed fullscreen request */
  fullscreenError: string | null;
  enterFullscreen: () => void;
  exitFullscreen: () => void;
  toggleFullscreen: () => void;
}

export function useTelegramFullscreen(): UseTelegramFullscreenReturn {
  const { webApp } = useTelegram();
  const [isFullscreen, setIsFullscreen] = useState(() => {
    // Initialize from current webApp state
    return webApp?.isFullscreen || false;
  });
  const [isFullscreenFailed, setIsFullscreenFailed] = useState(false);
  const [fullscreenError, setFullscreenError] = useState<string | null>(null);

  const isSupported = !!(webApp && typeof webApp.requestFullscreen === "function");

  const enterFullscreen = useCallback(() => {
    if (!webApp || typeof webApp.requestFullscreen !== "function") {
      log.warn("Fullscreen not supported");
      return;
    }

    // Reset error state before attempting
    setIsFullscreenFailed(false);
    setFullscreenError(null);

    try {
      webApp.requestFullscreen();
      log.info("Requested fullscreen mode");
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      setIsFullscreenFailed(true);
      setFullscreenError(errorMsg);
      log.error("Error entering fullscreen", { error: errorMsg });
    }
  }, [webApp]);

  const exitFullscreen = useCallback(() => {
    if (!webApp || typeof webApp.exitFullscreen !== "function") {
      log.warn("Fullscreen exit not supported");
      return;
    }

    try {
      webApp.exitFullscreen();
      log.info("Exited fullscreen mode");
    } catch (error) {
      log.error("Error exiting fullscreen", { error: String(error) });
    }
  }, [webApp]);

  const toggleFullscreen = useCallback(() => {
    if (isFullscreen) {
      exitFullscreen();
    } else {
      enterFullscreen();
    }
  }, [isFullscreen, enterFullscreen, exitFullscreen]);

  // Listen for fullscreen change and failed events
  useEffect(() => {
    if (!webApp) return;

    const handleFullscreenChanged = () => {
      const newState = webApp.isFullscreen || false;
      setIsFullscreen(newState);
      // Clear error state on successful change
      if (newState) {
        setIsFullscreenFailed(false);
        setFullscreenError(null);
      }
      log.debug("Fullscreen state changed", { isFullscreen: newState });
    };

    // Handle fullscreen failed event (Mini App 2.0+)
    const handleFullscreenFailed = (event: { error?: string } | undefined) => {
      setIsFullscreenFailed(true);
      const errorMsg = event?.error || "Unknown fullscreen error";
      setFullscreenError(errorMsg);
      log.warn("Fullscreen request failed", { error: errorMsg });
    };

    // Subscribe to events
    if (typeof webApp.onEvent === "function") {
      webApp.onEvent("fullscreenChanged", handleFullscreenChanged);
      webApp.onEvent("fullscreenFailed", handleFullscreenFailed);
    }

    // Initialize state from current webApp
    setIsFullscreen(webApp.isFullscreen || false);

    return () => {
      if (typeof webApp.offEvent === "function") {
        webApp.offEvent("fullscreenChanged", handleFullscreenChanged);
        webApp.offEvent("fullscreenFailed", handleFullscreenFailed);
      }
    };
  }, [webApp]);

  return {
    isFullscreen,
    isSupported,
    isFullscreenFailed,
    fullscreenError,
    enterFullscreen,
    exitFullscreen,
    toggleFullscreen,
  };
}

