/**
 * Telegram Orientation Lock Hook
 *
 * Automatically locks orientation when component mounts (e.g., Studio)
 * and unlocks when unmounting.
 *
 * @example
 * ```tsx
 * // In Studio component
 * useTelegramOrientationLock({ lockOnMount: true });
 * ```
 */

import { useEffect, useCallback, useState, useRef } from "react";
import { useTelegram } from "@/contexts/TelegramContext";
import { logger } from "@/lib/logger";

const log = logger.child({ module: "TelegramOrientationLock" });

interface UseTelegramOrientationLockOptions {
  /** Lock orientation when component mounts */
  lockOnMount?: boolean;
  /** Unlock orientation when component unmounts */
  unlockOnUnmount?: boolean;
}

interface UseTelegramOrientationLockReturn {
  /** Whether orientation lock is supported */
  isSupported: boolean;
  /** Whether orientation is currently locked */
  isLocked: boolean;
  /** Lock orientation to current position */
  lock: () => void;
  /** Unlock orientation */
  unlock: () => void;
  /** Toggle orientation lock */
  toggle: () => void;
}

export function useTelegramOrientationLock(
  options: UseTelegramOrientationLockOptions = {},
): UseTelegramOrientationLockReturn {
  const { lockOnMount = false, unlockOnUnmount = true } = options;
  const { webApp } = useTelegram();
  const [isLocked, setIsLocked] = useState(false);

  // Track if we locked orientation (to properly unlock on unmount)
  const didLockRef = useRef(false);

  const isSupported = !!(webApp && typeof webApp.lockOrientation === "function");

  const lock = useCallback(() => {
    if (!webApp || typeof webApp.lockOrientation !== "function") {
      log.debug("Orientation lock not supported");
      return;
    }

    try {
      webApp.lockOrientation();
      setIsLocked(true);
      didLockRef.current = true;
      log.info("Orientation locked");
    } catch (error) {
      log.warn("Failed to lock orientation", { error: String(error) });
    }
  }, [webApp]);

  const unlock = useCallback(() => {
    if (!webApp || typeof webApp.unlockOrientation !== "function") {
      log.debug("Orientation unlock not supported");
      return;
    }

    try {
      webApp.unlockOrientation();
      setIsLocked(false);
      didLockRef.current = false;
      log.info("Orientation unlocked");
    } catch (error) {
      log.warn("Failed to unlock orientation", { error: String(error) });
    }
  }, [webApp]);

  const toggle = useCallback(() => {
    if (isLocked) {
      unlock();
    } else {
      lock();
    }
  }, [isLocked, lock, unlock]);

  // Auto lock on mount
  useEffect(() => {
    if (lockOnMount && isSupported) {
      lock();
    }
  }, [lockOnMount, isSupported, lock]);

  // Cleanup: unlock on unmount using ref to avoid stale closure
  useEffect(() => {
    return () => {
      if (unlockOnUnmount && didLockRef.current && webApp) {
        try {
          webApp.unlockOrientation?.();
          log.info("Orientation unlocked on unmount");
        } catch (error) {
          log.warn("Failed to unlock orientation on unmount", { error: String(error) });
        }
      }
    };
  }, [unlockOnUnmount, webApp]);

  return {
    isSupported,
    isLocked,
    lock,
    unlock,
    toggle,
  };
}

// @ts-nocheck — Telegram WebApp SDK callbacks lack TS types; all callers are internal
/**
 * Telegram Storage Hook
 *
 * Provides unified access to CloudStorage, DeviceStorage, and SecureStorage
 * with Promise-based API for easier usage
 *
 * Storage Types:
 * - CloudStorage: Synced across devices (up to 1024 keys, 4KB per value)
 * - DeviceStorage: Local only (~5 MB total)
 * - SecureStorage: Encrypted (up to 10 items, for sensitive data)
 *
 * @example
 * ```tsx
 * const { cloud, device, secure } = useTelegramStorage();
 *
 * // Cloud storage (synced)
 * await cloud.set('settings', JSON.stringify(settings));
 * const data = await cloud.get('settings');
 *
 * // Secure storage (encrypted)
 * if (secure.isAvailable) {
 *   await secure.set('token', refreshToken);
 * }
 * ```
 */

import { useCallback } from "react";
import { useTelegram } from "@/contexts/TelegramContext";
import { logger } from "@/lib/logger";

// Telegram CloudStorage callback types
type StorageError = Error | null;
type StorageCallback<T> = (error: StorageError, value: T) => void;

const log = logger.child({ module: "TelegramStorage" });

interface StorageAPI {
  get: (key: string) => Promise<string | null>;
  set: (key: string, value: string) => Promise<boolean>;
  remove: (key: string) => Promise<boolean>;
  getMultiple: (keys: string[]) => Promise<Record<string, string>>;
  removeMultiple: (keys: string[]) => Promise<boolean>;
  getKeys: () => Promise<string[]>;
  clear?: () => Promise<boolean>;
}

interface SecureStorageAPI {
  isAvailable: boolean;
  get: (key: string) => Promise<string | null>;
  set: (key: string, value: string) => Promise<boolean>;
  remove: (key: string) => Promise<boolean>;
}

interface UseTelegramStorageReturn {
  cloud: StorageAPI;
  device: StorageAPI;
  secure: SecureStorageAPI;
  isCloudSupported: boolean;
  isDeviceSupported: boolean;
  isSecureSupported: boolean;
}

export function useTelegramStorage(): UseTelegramStorageReturn {
  const { webApp } = useTelegram();

  const isCloudSupported = !!webApp?.CloudStorage;
  const isDeviceSupported = !!webApp?.DeviceStorage;
  const isSecureSupported = !!(webApp?.SecureStorage && webApp.SecureStorage.isAvailable);

  // Cloud Storage API
  const cloud: StorageAPI = {
    get: useCallback(
      (key: string): Promise<string | null> => {
        if (!webApp?.CloudStorage) {
          return Promise.resolve(null);
        }

        return new Promise((resolve) => {
          try {
            webApp.CloudStorage.getItem(key, (error, value) => {
              if (error) {
                log.error("CloudStorage get error", { key, error });
                resolve(null);
              } else {
                resolve(value || null);
              }
            });
          } catch (error) {
            log.error("CloudStorage get exception", error);
            resolve(null);
          }
        });
      },
      [webApp],
    ),

    set: useCallback(
      (key: string, value: string): Promise<boolean> => {
        if (!webApp?.CloudStorage) {
          return Promise.resolve(false);
        }

        return new Promise((resolve) => {
          try {
            webApp.CloudStorage.setItem(key, value, (error, success) => {
              if (error) {
                log.error("CloudStorage set error", { key, error });
                resolve(false);
              } else {
                resolve(success);
              }
            });
          } catch (error) {
            log.error("CloudStorage set exception", error);
            resolve(false);
          }
        });
      },
      [webApp],
    ),

    remove: useCallback(
      (key: string): Promise<boolean> => {
        if (!webApp?.CloudStorage) {
          return Promise.resolve(false);
        }

        return new Promise((resolve) => {
          try {
            webApp.CloudStorage.removeItem(key, (error, success) => {
              if (error) {
                log.error("CloudStorage remove error", { key, error });
                resolve(false);
              } else {
                resolve(success);
              }
            });
          } catch (error) {
            log.error("CloudStorage remove exception", error);
            resolve(false);
          }
        });
      },
      [webApp],
    ),

    getMultiple: useCallback(
      (keys: string[]): Promise<Record<string, string>> => {
        if (!webApp?.CloudStorage) {
          return Promise.resolve({});
        }

        return new Promise((resolve) => {
          try {
            webApp.CloudStorage.getItems(keys, (error, values) => {
              if (error) {
                log.error("CloudStorage getMultiple error", { keys, error });
                resolve({});
              } else {
                resolve(values);
              }
            });
          } catch (error) {
            log.error("CloudStorage getMultiple exception", error);
            resolve({});
          }
        });
      },
      [webApp],
    ),

    removeMultiple: useCallback(
      (keys: string[]): Promise<boolean> => {
        if (!webApp?.CloudStorage) {
          return Promise.resolve(false);
        }

        return new Promise((resolve) => {
          try {
            webApp.CloudStorage.removeItems(keys, (error, success) => {
              if (error) {
                log.error("CloudStorage removeMultiple error", { keys, error });
                resolve(false);
              } else {
                resolve(success);
              }
            });
          } catch (error) {
            log.error("CloudStorage removeMultiple exception", error);
            resolve(false);
          }
        });
      },
      [webApp],
    ),

    getKeys: useCallback((): Promise<string[]> => {
      if (!webApp?.CloudStorage) {
        return Promise.resolve([]);
      }

      return new Promise((resolve) => {
        try {
          webApp.CloudStorage.getKeys((error, keys) => {
            if (error) {
              log.error("CloudStorage getKeys error", error);
              resolve([]);
            } else {
              resolve(keys);
            }
          });
        } catch (error) {
          log.error("CloudStorage getKeys exception", error);
          resolve([]);
        }
      });
    }, [webApp]),
  };

  // Device Storage API (same structure as Cloud)
  const device: StorageAPI = {
    get: useCallback(
      (key: string): Promise<string | null> => {
        if (!webApp?.DeviceStorage) {
          return Promise.resolve(null);
        }

        return new Promise((resolve) => {
          try {
            webApp.DeviceStorage!.getItem(key, (error, value) => {
              if (error) {
                log.error("DeviceStorage get error", { key, error });
                resolve(null);
              } else {
                resolve(value || null);
              }
            });
          } catch (error) {
            log.error("DeviceStorage get exception", error);
            resolve(null);
          }
        });
      },
      [webApp],
    ),

    set: useCallback(
      (key: string, value: string): Promise<boolean> => {
        if (!webApp?.DeviceStorage) {
          return Promise.resolve(false);
        }

        return new Promise((resolve) => {
          try {
            webApp.DeviceStorage!.setItem(key, value, (error, success) => {
              if (error) {
                log.error("DeviceStorage set error", { key, error });
                resolve(false);
              } else {
                resolve(success);
              }
            });
          } catch (error) {
            log.error("DeviceStorage set exception", error);
            resolve(false);
          }
        });
      },
      [webApp],
    ),

    remove: useCallback(
      (key: string): Promise<boolean> => {
        if (!webApp?.DeviceStorage) {
          return Promise.resolve(false);
        }

        return new Promise((resolve) => {
          try {
            webApp.DeviceStorage!.removeItem(key, (error: unknown, success: boolean) => {
              if (error) {
                log.error("DeviceStorage remove error", { key, error });
                resolve(false);
              } else {
                resolve(success);
              }
            });
          } catch (error) {
            log.error("DeviceStorage remove exception", error);
            resolve(false);
          }
        });
      },
      [webApp],
    ),

    getMultiple: useCallback(
      (keys: string[]): Promise<Record<string, string>> => {
        if (!webApp?.DeviceStorage) {
          return Promise.resolve({});
        }

        return new Promise((resolve) => {
          try {
            webApp.DeviceStorage!.getItems(keys, (error: unknown, values: Record<string, string>) => {
              if (error) {
                log.error("DeviceStorage getMultiple error", { keys, error });
                resolve({});
              } else {
                resolve(values);
              }
            });
          } catch (error) {
            log.error("DeviceStorage getMultiple exception", error);
            resolve({});
          }
        });
      },
      [webApp],
    ),

    removeMultiple: useCallback(
      (keys: string[]): Promise<boolean> => {
        if (!webApp?.DeviceStorage) {
          return Promise.resolve(false);
        }

        return new Promise((resolve) => {
          try {
            webApp.DeviceStorage!.removeItems(keys, (error, success) => {
              if (error) {
                log.error("DeviceStorage removeMultiple error", { keys, error });
                resolve(false);
              } else {
                resolve(success);
              }
            });
          } catch (error) {
            log.error("DeviceStorage removeMultiple exception", error);
            resolve(false);
          }
        });
      },
      [webApp],
    ),

    getKeys: useCallback((): Promise<string[]> => {
      if (!webApp?.DeviceStorage) {
        return Promise.resolve([]);
      }

      return new Promise((resolve) => {
        try {
          webApp.DeviceStorage!.getKeys((error: unknown, keys: string[]) => {
            if (error) {
              log.error("DeviceStorage getKeys error", error);
              resolve([]);
            } else {
              resolve(keys);
            }
          });
        } catch (error) {
          log.error("DeviceStorage getKeys exception", error);
          resolve([]);
        }
      });
    }, [webApp]),
  };

  // Secure Storage API
  const secure: SecureStorageAPI = {
    isAvailable: isSecureSupported,

    get: useCallback(
      (key: string): Promise<string | null> => {
        if (!webApp?.SecureStorage?.isAvailable) {
          return Promise.resolve(null);
        }

        return new Promise((resolve) => {
          try {
            webApp.SecureStorage!.getItem(key, (error: unknown, value: string | null) => {
              if (error) {
                log.error("SecureStorage get error", { key, error });
                resolve(null);
              } else {
                resolve(value || null);
              }
            });
          } catch (error) {
            log.error("SecureStorage get exception", error);
            resolve(null);
          }
        });
      },
      [webApp],
    ),

    set: useCallback(
      (key: string, value: string): Promise<boolean> => {
        if (!webApp?.SecureStorage?.isAvailable) {
          return Promise.resolve(false);
        }

        return new Promise((resolve) => {
          try {
            webApp.SecureStorage!.setItem(key, value, (error: unknown) => {
              if (error) {
                log.error("SecureStorage set error", { key, error });
                resolve(false);
              } else {
                resolve(true);
              }
            });
          } catch (error) {
            log.error("SecureStorage set exception", error);
            resolve(false);
          }
        });
      },
      [webApp],
    ),

    remove: useCallback(
      (key: string): Promise<boolean> => {
        if (!webApp?.SecureStorage?.isAvailable) {
          return Promise.resolve(false);
        }

        return new Promise((resolve) => {
          try {
            webApp.SecureStorage!.removeItem(key, (error: unknown) => {
              if (error) {
                log.error("SecureStorage remove error", { key, error });
                resolve(false);
              } else {
                resolve(true);
              }
            });
          } catch (error) {
            log.error("SecureStorage remove exception", error);
            resolve(false);
          }
        });
      },
      [webApp],
    ),
  };

  return {
    cloud,
    device,
    secure,
    isCloudSupported,
    isDeviceSupported,
    isSecureSupported,
  };
}

/**
 * Responsive design hook for media query matching
 *
 * Per research.md Task 5: Mobile component strategy requires
 * reliable media query detection for responsive components.
 *
 * @example
 * ```tsx
 * const isMobile = useMediaQuery('(max-width: 767px)');
 * const isTablet = useMediaQuery('(min-width: 768px) and (max-width: 1023px)');
 * const prefersDark = useMediaQuery('(prefers-color-scheme: dark)');
 * ```
 */

import { useEffect, useState } from "react";

/**
 * Hook to match media queries
 *
 * @param query - CSS media query string
 * @param defaultValue - Default value if SSR (default: false)
 * @returns Whether the media query matches
 */
export function useMediaQuery(query: string, defaultValue: boolean = false): boolean {
  const [matches, setMatches] = useState(() => {
    if (typeof window === "undefined" || !window.matchMedia) {
      return defaultValue;
    }

    try {
      return window.matchMedia(query).matches;
    } catch {
      return defaultValue;
    }
  });

  useEffect(() => {
    // Check if window is available (SSR check)
    if (typeof window === "undefined" || !window.matchMedia) {
      return;
    }

    // Create MediaQueryList
    const mediaQuery = window.matchMedia(query);

    // Set initial value
    setMatches(mediaQuery.matches);

    // Define event handler
    const handleChange = (event: MediaQueryListEvent) => {
      setMatches(event.matches);
    };

    // Listen for changes
    mediaQuery.addEventListener("change", handleChange);

    // Cleanup
    return () => {
      mediaQuery.removeEventListener("change", handleChange);
    };
  }, [query]);

  return matches;
}

/**
 * Pre-defined breakpoint hooks per Tailwind config
 *
 * Per CLAUDE.md: Tailwind breakpoints
 * - xs: 375px (small phones)
 * - sm: 640px
 * - md: 768px
 * - lg: 1024px
 * - xl: 1280px
 * - 2xl: 1536px
 */

/**
 * Match mobile breakpoint (max-width: 767px)
 * Aligned with Tailwind's md: breakpoint (768px) — the standard mobile
 * threshold used in src/lib/design-tokens.ts and throughout the app.
 */
export function useIsMobile(): boolean {
  return useMediaQuery("(max-width: 767px)");
}

/**
 * Match tablet breakpoint (min-width: 768px and max-width: 1023px)
 */
export function useIsTablet(): boolean {
  return useMediaQuery("(min-width: 768px) and (max-width: 1023px)");
}

/**
 * Match desktop breakpoint (min-width: 1024px)
 */
export function useIsDesktop(): boolean {
  return useMediaQuery("(min-width: 1024px)");
}

/**
 * Match small phone breakpoint (max-width: 374px)
 */
export function useIsSmallPhone(): boolean {
  return useMediaQuery("(max-width: 374px)");
}

/**
 * Get current breakpoint
 */
export type Breakpoint = "xs" | "sm" | "md" | "lg" | "xl" | "2xl";

export function useBreakpoint(): Breakpoint {
  const is2xl = useMediaQuery("(min-width: 1536px)");
  const isXl = useMediaQuery("(min-width: 1280px)");
  const isLg = useMediaQuery("(min-width: 1024px)");
  const isMd = useMediaQuery("(min-width: 768px)");
  const isSm = useMediaQuery("(min-width: 640px)");
  const isXs = useMediaQuery("(min-width: 375px)");

  if (is2xl) return "2xl";
  if (isXl) return "xl";
  if (isLg) return "lg";
  if (isMd) return "md";
  if (isSm) return "sm";
  return "xs";
}

/**
 * Match orientation
 */
export function useOrientation(): "portrait" | "landscape" {
  return useMediaQuery("(orientation: landscape)") ? "landscape" : "portrait";
}

/**
 * Match reduced motion preference
 */
export function usePrefersReducedMotion(): boolean {
  return useMediaQuery("(prefers-reduced-motion: reduce)");
}

/**
 * Analytics Tracking Hook
 *
 * Unified hook for tracking user behavior and analytics events.
 * Uses modular analytics services for better maintainability.
 */

import { useCallback, useEffect, useRef } from "react";
import { useLocation } from "react-router";
import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/contexts/AuthContext";
import { logger } from "@/lib/logger";

// Import from modular services
import {
  getOrCreateSessionId,
  hasSessionStartedBeenTracked,
  markSessionStartedAsTracked,
  trackEvent as trackAnalyticsEvent,
  trackPageView,
  trackGeneration as trackGenerationEvent,
  trackFeatureUsed as trackFeatureUsedEvent,
  trackButtonClick as trackButtonClickEvent,
  trackTrackPlayed,
  trackTrackShared,
  trackUserReturn,
  trackFirstGeneration,
  fetchUserBehaviorStats,
} from "@/services/analytics";

import type { UserBehaviorStats } from "@/services/analytics";

interface TrackEventParams {
  eventType:
    | "page_view"
    | "generation_started"
    | "generation_completed"
    | "track_played"
    | "track_liked"
    | "track_shared"
    | "feature_used"
    | "button_clicked"
    | "session_started"
    | "session_ended";
  eventName?: string;
  pagePath?: string;
  metadata?: Record<string, unknown>;
}

/**
 * Main analytics tracking hook
 * Auto-tracks page views and provides convenience methods for event tracking
 */
export function useAnalyticsTracking() {
  const location = useLocation();
  const { user } = useAuth();
  const sessionId = useRef(getOrCreateSessionId());
  const lastPagePath = useRef<string | null>(null);
  const hasTrackedSession = useRef(false);

  // Track event function - unified wrapper
  const trackEvent = useCallback(
    async (params: TrackEventParams) => {
      try {
        await trackAnalyticsEvent(
          {
            eventType: params.eventType,
            eventName: params.eventName,
            pagePath: params.pagePath || location.pathname,
            metadata: params.metadata,
          },
          user?.id,
        );
      } catch (error) {
        // Silent fail - analytics should never break the app
        logger.debug("[Analytics] Tracking error", { error: error instanceof Error ? error.message : String(error) });
      }
    },
    [location.pathname, user?.id],
  );

  // Auto-track page views
  useEffect(() => {
    if (location.pathname !== lastPagePath.current) {
      lastPagePath.current = location.pathname;
      trackPageView(
        location.pathname,
        {
          search: location.search,
          hash: location.hash,
          referrer: document.referrer,
        },
        user?.id,
      ).catch(() => {});
    }
  }, [location, user?.id]);

  // Track session start on mount (once per session, with deduplication)
  useEffect(() => {
    if (hasTrackedSession.current) return;

    // P1 Fix: Check if session_started was already tracked in this session
    if (hasSessionStartedBeenTracked()) {
      hasTrackedSession.current = true;
      return;
    }

    hasTrackedSession.current = true;
    markSessionStartedAsTracked(); // Mark as tracked to prevent duplicates

    trackEvent({
      eventType: "session_started",
      metadata: {
        userAgent: navigator.userAgent,
        language: navigator.language,
        screenWidth: window.innerWidth,
        screenHeight: window.innerHeight,
        platform: navigator.platform,
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      },
    });

    // Track user return frequency
    const { isReturning, daysSinceLastVisit } = trackUserReturn();

    if (isReturning && daysSinceLastVisit > 0) {
      trackEvent({
        eventType: "session_started",
        eventName: "user_returned",
        metadata: {
          daysSinceLastVisit,
          isReturningUser: true,
        },
      });
    }

    // Track session end on unmount via beacon
    return () => {
      const payload = JSON.stringify({
        session_id: sessionId.current,
        event_type: "session_ended",
        page_path: window.location.pathname,
        created_at: new Date().toISOString(),
      });

      navigator.sendBeacon?.(`${import.meta.env.VITE_SUPABASE_URL}/rest/v1/user_analytics_events`, payload);
    };
  }, [trackEvent]);

  // Convenience methods
  const trackGeneration = useCallback(
    (status: "started" | "completed", metadata?: Record<string, unknown>) => {
      const eventMetadata = { ...metadata };

      if (status === "completed") {
        const isFirst = trackFirstGeneration();
        if (isFirst) {
          eventMetadata.isFirstGeneration = true;
        }
      }

      trackGenerationEvent(status, eventMetadata, user?.id).catch(() => {});
    },
    [user?.id],
  );

  const trackPlay = useCallback(
    (trackId: string, metadata?: Record<string, unknown>) => {
      trackTrackPlayed(trackId, metadata, user?.id).catch(() => {});
    },
    [user?.id],
  );

  const trackLike = useCallback(
    (trackId: string, liked: boolean) => {
      trackEvent({
        eventType: "track_liked",
        metadata: { trackId, liked },
      });
    },
    [trackEvent],
  );

  const trackShare = useCallback(
    (trackId: string, platform: string) => {
      trackTrackShared(trackId, platform, undefined, user?.id).catch(() => {});
    },
    [user?.id],
  );

  const trackFeatureUsed = useCallback(
    (featureName: string, metadata?: Record<string, unknown>) => {
      trackFeatureUsedEvent(featureName, metadata, user?.id).catch(() => {});
    },
    [user?.id],
  );

  const trackButtonClick = useCallback(
    (buttonName: string, metadata?: Record<string, unknown>) => {
      trackButtonClickEvent(buttonName, metadata, user?.id).catch(() => {});
    },
    [user?.id],
  );

  return {
    trackEvent,
    trackGeneration,
    trackPlay,
    trackLike,
    trackShare,
    trackFeatureUsed,
    trackButtonClick,
    sessionId: sessionId.current,
  };
}

/**
 * Hook for admin to view user behavior stats
 */
export function useUserBehaviorStats(timeRange: "1h" | "24h" | "7d" | "30d" = "7d") {
  const getInterval = () => {
    switch (timeRange) {
      case "1h":
        return "1 hour";
      case "24h":
        return "24 hours";
      case "7d":
        return "7 days";
      case "30d":
        return "30 days";
      default:
        return "7 days";
    }
  };

  return useQuery({
    queryKey: ["user-behavior-stats", timeRange],
    queryFn: () => fetchUserBehaviorStats(getInterval()),
    refetchInterval: 60000,
    staleTime: 30000,
  });
}

export type { UserBehaviorStats };

