/**
 * useAudioLevel - Hook for real-time audio level monitoring
 * Provides normalized audio level (0-100) from MediaStream
 */

import { useState, useEffect, useRef } from "react";
import { logger } from "@/lib/logger";

export function useAudioLevel(mediaStream: MediaStream | null, isActive: boolean = true) {
  const [audioLevel, setAudioLevel] = useState(0);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const rafRef = useRef<number | null>(null);
  const dataArrayRef = useRef<Uint8Array | null>(null);

  useEffect(() => {
    if (!mediaStream || !isActive) {
      // Cleanup
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = null;
      }
      if (audioContextRef.current) {
        audioContextRef.current.close();
        audioContextRef.current = null;
      }
      analyserRef.current = null;
      dataArrayRef.current = null;
      setAudioLevel(0);
      return;
    }

    try {
      // Create audio context and analyser
      type WindowWithWebkitAudio = Window & {
        webkitAudioContext?: typeof AudioContext;
      };
      const AudioContextClass = window.AudioContext || (window as WindowWithWebkitAudio).webkitAudioContext;
      if (!AudioContextClass) {
        logger.error("AudioContext is not supported in this browser");
        return;
      }
      const audioContext = new AudioContextClass();
      const analyser = audioContext.createAnalyser();
      const source = audioContext.createMediaStreamSource(mediaStream);

      analyser.fftSize = 256;
      analyser.smoothingTimeConstant = 0.8;
      source.connect(analyser);

      const bufferLength = analyser.frequencyBinCount;
      const dataArray = new Uint8Array(bufferLength);

      audioContextRef.current = audioContext;
      analyserRef.current = analyser;
      dataArrayRef.current = dataArray;

      // Animation loop to update level
      const updateLevel = () => {
        if (!analyserRef.current || !dataArrayRef.current) return;

        analyserRef.current.getByteFrequencyData(dataArrayRef.current as Uint8Array<ArrayBuffer>);

        // Calculate average level
        let sum = 0;
        for (let i = 0; i < dataArrayRef.current.length; i++) {
          sum += dataArrayRef.current[i];
        }
        const average = sum / dataArrayRef.current.length;

        // Normalize to 0-100 range with some amplification for better visualization
        const normalized = Math.min(100, Math.round((average / 255) * 150));
        setAudioLevel(normalized);

        rafRef.current = requestAnimationFrame(updateLevel);
      };

      updateLevel();

      return () => {
        if (rafRef.current) {
          cancelAnimationFrame(rafRef.current);
        }
        source.disconnect();
        if (audioContext.state !== "closed") {
          audioContext.close();
        }
      };
    } catch (error) {
      logger.error("Audio level monitoring error", error instanceof Error ? error : new Error(String(error)));
      setAudioLevel(0);
    }
  }, [mediaStream, isActive]);

  return audioLevel;
}

/**
 * useCloudStorage - React hook for Telegram CloudStorage
 * Provides reactive state management with CloudStorage persistence
 */

import { useState, useEffect, useCallback } from "react";
import { cloudStorage } from "@/lib/cloudStorage";

interface UseCloudStorageOptions<T> {
  /** Default value if key doesn't exist */
  defaultValue: T;
  /** Whether to sync across tabs (localStorage events) */
  syncTabs?: boolean;
}

interface UseCloudStorageReturn<T> {
  /** Current value */
  value: T;
  /** Set new value */
  setValue: (value: T | ((prev: T) => T)) => Promise<void>;
  /** Remove value */
  removeValue: () => Promise<void>;
  /** Whether initial load is complete */
  isLoading: boolean;
  /** Whether CloudStorage is available */
  isCloudStorage: boolean;
}

/**
 * Hook for persisting state in Telegram CloudStorage with localStorage fallback
 *
 * @example
 * const { value: settings, setValue: setSettings } = useCloudStorage('user_settings', {
 *   defaultValue: { theme: 'dark', notifications: true }
 * });
 */
export function useCloudStorage<T>(key: string, options: UseCloudStorageOptions<T>): UseCloudStorageReturn<T> {
  const { defaultValue, syncTabs = true } = options;
  const [value, setValueState] = useState<T>(defaultValue);
  const [isLoading, setIsLoading] = useState(true);
  const isCloudStorage = cloudStorage.isAvailable();

  // Load initial value
  useEffect(() => {
    let mounted = true;

    const loadValue = async () => {
      try {
        const stored = await cloudStorage.getJSON<T>(key, defaultValue);
        if (mounted) {
          setValueState(stored);
        }
      } finally {
        if (mounted) {
          setIsLoading(false);
        }
      }
    };

    loadValue();

    return () => {
      mounted = false;
    };
  }, [key, defaultValue]);

  // Sync across tabs via localStorage events
  useEffect(() => {
    if (!syncTabs) return;

    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === `mvai_${key}` && e.newValue) {
        try {
          setValueState(JSON.parse(e.newValue));
        } catch {}
      }
    };

    window.addEventListener("storage", handleStorageChange);
    return () => window.removeEventListener("storage", handleStorageChange);
  }, [key, syncTabs]);

  // Set value
  const setValue = useCallback(
    async (newValue: T | ((prev: T) => T)) => {
      const valueToSet = typeof newValue === "function" ? (newValue as (prev: T) => T)(value) : newValue;

      setValueState(valueToSet);
      await cloudStorage.setJSON(key, valueToSet);
    },
    [key, value],
  );

  // Remove value
  const removeValue = useCallback(async () => {
    setValueState(defaultValue);
    await cloudStorage.removeItem(key);
  }, [key, defaultValue]);

  return {
    value,
    setValue,
    removeValue,
    isLoading,
    isCloudStorage,
  };
}

/**
 * Simple hook for boolean flags
 */
export function useCloudStorageFlag(key: string, defaultValue = false) {
  const { value, setValue, isLoading } = useCloudStorage(key, { defaultValue });

  const toggle = useCallback(async () => {
    await setValue(!value);
  }, [value, setValue]);

  return { value, toggle, setValue, isLoading };
}

