/**
 * useCreditsLimits Hook
 * Manages free tier credit limits and upgrade prompts
 */

import { useCallback, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useSubscriptionStatus } from "@/hooks/useSubscriptionStatus";
import { ECONOMY } from "@/lib/economy";
import { trackEvent } from "@/services/analytics/events.service";

type SubscriptionTierType = "free" | "pro" | "premium" | "enterprise";

interface CreditsLimitsData {
  balance: number;
  dailyEarnedToday: number;
  dailyEarnedResetAt: string | null;
  subscriptionTier: SubscriptionTierType;
}

export function useCreditsLimits() {
  const { user } = useAuth();
  const { tier } = useSubscriptionStatus({
    userId: user?.id || "",
    enabled: !!user,
  });

  const subscriptionTier: SubscriptionTierType = tier || "free";
  const isFreeUser = subscriptionTier === "free";

  // Fetch current credits and limits
  const { data, isLoading } = useQuery({
    queryKey: ["credits-limits", user?.id],
    queryFn: async (): Promise<CreditsLimitsData> => {
      if (!user?.id) throw new Error("No user");

      const { data: credits, error } = await supabase
        .from("user_credits")
        .select("balance")
        .eq("user_id", user.id)
        .single();

      if (error) throw error;

      // Daily earned will be tracked via the new columns after migration
      // For now, we'll use balance only and add daily tracking later
      return {
        balance: credits?.balance ?? 0,
        dailyEarnedToday: 0, // Will be populated after migration runs
        dailyEarnedResetAt: null,
        subscriptionTier,
      };
    },
    enabled: !!user?.id,
    staleTime: 30 * 1000,
  });

  // Check if daily limit is reached (for free users)
  const isDailyLimitReached = useMemo(() => {
    if (!isFreeUser || !data) return false;
    return data.dailyEarnedToday >= ECONOMY.FREE_DAILY_EARN_CAP;
  }, [isFreeUser, data]);

  // Check if balance limit is reached (for free users)
  const isBalanceLimitReached = useMemo(() => {
    if (!isFreeUser || !data) return false;
    return data.balance >= ECONOMY.FREE_MAX_BALANCE;
  }, [isFreeUser, data]);

  // Calculate remaining daily credits
  const remainingDailyCredits = useMemo(() => {
    if (!isFreeUser || !data) return Infinity;
    return Math.max(0, ECONOMY.FREE_DAILY_EARN_CAP - data.dailyEarnedToday);
  }, [isFreeUser, data]);

  // Calculate credits until balance limit
  const creditsUntilBalanceLimit = useMemo(() => {
    if (!isFreeUser || !data) return Infinity;
    return Math.max(0, ECONOMY.FREE_MAX_BALANCE - data.balance);
  }, [isFreeUser, data]);

  // Check if a reward would be capped
  const wouldBeCapped = useCallback(
    (rewardAmount: number): boolean => {
      if (!isFreeUser || !data) return false;

      // Check daily limit
      if (data.dailyEarnedToday + rewardAmount > ECONOMY.FREE_DAILY_EARN_CAP) {
        return true;
      }

      // Check balance limit
      if (data.balance + rewardAmount > ECONOMY.FREE_MAX_BALANCE) {
        return true;
      }

      return false;
    },
    [isFreeUser, data],
  );

  // Calculate actual reward after caps
  const calculateActualReward = useCallback(
    (requestedAmount: number): number => {
      if (!isFreeUser || !data) return requestedAmount;

      // Apply daily cap
      let amount = Math.min(requestedAmount, ECONOMY.FREE_DAILY_EARN_CAP - data.dailyEarnedToday);

      // Apply balance cap
      amount = Math.min(amount, ECONOMY.FREE_MAX_BALANCE - data.balance);

      return Math.max(0, amount);
    },
    [isFreeUser, data],
  );

  return {
    balance: data?.balance ?? 0,
    dailyEarnedToday: data?.dailyEarnedToday ?? 0,
    subscriptionTier,
    isFreeUser,
    isDailyLimitReached,
    isBalanceLimitReached,
    remainingDailyCredits,
    creditsUntilBalanceLimit,
    wouldBeCapped,
    calculateActualReward,
    isLoading,

    // Limits for display
    limits: {
      dailyCap: isFreeUser ? ECONOMY.FREE_DAILY_EARN_CAP : null,
      balanceCap: isFreeUser ? ECONOMY.FREE_MAX_BALANCE : null,
    },
  };
}

/**
 * Hook to check if welcome bonus should be shown.
 *
 * Sprint 055 P0-5 (idempotency): the localStorage flag is now a JSON envelope
 * `{ shownAt: <iso8601> }` instead of bare `"true"`, so we can let the bonus
 * re-show after TTL_DAYS expire (default 30). Legacy `"true"` strings are
 * treated as shown a long time ago, so users with the old flag get a single
 * re-offer — bounded at one per TTL window, never per-session flood.
 */
export function useWelcomeBonusCheck() {
  const { user } = useAuth();

  const { data: shouldShow, isLoading } = useQuery({
    queryKey: ["welcome-bonus-check", user?.id],
    queryFn: async () => {
      if (!user?.id) return false;

      // Sprint 055 P0-5: parse TTL-aware envelope; missing/invalid → not shown yet.
      const shownEntry = parseWelcomeBonusEntry(localStorage.getItem(`welcome_bonus_shown_${user.id}`));
      if (shownEntry && !isWelcomeBonusExpired(shownEntry, WELCOME_BONUS_TTL_MS)) {
        return false;
      }

      // Check if user just registered (within last 5 minutes)
      const { data: transactions } = await supabase
        .from("credit_transactions")
        .select("created_at")
        .eq("user_id", user.id)
        .eq("action_type", "registration_bonus")
        .limit(1);

      const credits = transactions?.[0];
      if (!credits?.created_at) return false;

      const registrationTime = new Date(credits.created_at).getTime();
      const fiveMinutesAgo = Date.now() - 5 * 60 * 1000;

      return registrationTime > fiveMinutesAgo;
    },
    enabled: !!user?.id,
    staleTime: Infinity, // Only check once per session
  });

  const markWelcomeBonusShown = useCallback(() => {
    if (!user?.id) return;
    // Sprint 055 P0-5: write JSON envelope with shownAt = now.
    const entry: WelcomeBonusEntry = { shownAt: new Date().toISOString() };
    localStorage.setItem(`welcome_bonus_shown_${user.id}`, JSON.stringify(entry));

    // Sprint 055 P0-5 analytics: lets us measure re-offer cadence
    // (post-TTL window). Errors are swallowed by trackEvent itself.
    void trackEvent(
      {
        eventType: "feature_used",
        pagePath: "welcome_bonus",
        metadata: { action: "mark_shown", ttl_days: WELCOME_BONUS_TTL_MS / (24 * 60 * 60 * 1000) },
      },
      user.id,
    );
  }, [user?.id]);

  return {
    shouldShowWelcomeBonus: shouldShow ?? false,
    isLoading,
    markWelcomeBonusShown,
  };
}

/**
 * Welcome Bonus TTL — re-show after 30 days from last shownAt.
 * Exposed for tests. Kept in this module because the constant is part of the
 * contract advertised in SPRINT-055-PLAN.md (DoD: max 1 / 30 days).
 */
export const WELCOME_BONUS_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/**
 * Envelope shape stored in localStorage. Versioned so future fields don't
 * break old reads — unknown versions fall back to "not shown".
 */
interface WelcomeBonusEntry {
  shownAt: string; // ISO 8601, set by `new Date().toISOString()`
}

function parseWelcomeBonusEntry(raw: string | null): WelcomeBonusEntry | null {
  if (!raw) return null;
  // Legacy bare-flag from before Sprint 055: treat as "shown a long time ago"
  // so the user gets one re-offer on the next eligible session, then the new
  // TTL timer starts ticking.
  if (raw === "true") {
    return { shownAt: new Date(0).toISOString() };
  }
  try {
    const parsed = JSON.parse(raw) as Partial<WelcomeBonusEntry>;
    if (typeof parsed?.shownAt === "string") {
      return { shownAt: parsed.shownAt };
    }
    return null;
  } catch {
    return null;
  }
}

function isWelcomeBonusExpired(entry: WelcomeBonusEntry, ttlMs: number): boolean {
  const shownAt = new Date(entry.shownAt).getTime();
  if (Number.isNaN(shownAt)) return true;
  return Date.now() - shownAt > ttlMs;
}

import { useRef, useCallback, useEffect, useState } from "react";
import { drumKits, getKitById, presetPatterns, type DrumKit, type DrumPattern, type DrumSound } from "@/lib/drum-kits";
import { logger } from "@/lib/logger";

// Tone.js types - loaded dynamically to prevent "Cannot access 't' before initialization" error
type ToneType = typeof import("tone");
type MembraneSynthType = import("tone").MembraneSynth;
type MetalSynthType = import("tone").MetalSynth;
type NoiseSynthType = import("tone").NoiseSynth;
type SynthType = import("tone").Synth;
type SequenceType = import("tone").Sequence;
type VolumeType = import("tone").Volume;
type RecorderType = import("tone").Recorder;
type FilterType = import("tone").Filter;
type CompressorType = import("tone").Compressor;
type PannerType = import("tone").Panner;

// Cached Tone module reference
let ToneModule: ToneType | null = null;

export type StepLength = 16 | 32 | 64;

export interface TrackEffects {
  filter: {
    enabled: boolean;
    frequency: number; // 100-20000
    resonance: number; // 0-20
  };
  compressor: {
    enabled: boolean;
    threshold: number; // -60 to 0
    ratio: number; // 1-20
  };
  volume: number; // -40 to 6
  pan: number; // -1 to 1
}

export interface DrumMachineState {
  isReady: boolean;
  isPlaying: boolean;
  currentStep: number;
  bpm: number;
  swing: number;
  volume: number;
  currentKit: DrumKit;
  pattern: Record<string, boolean[]>;
  soloTracks: Set<string>;
  mutedTracks: Set<string>;
  // New enhanced state
  stepLength: StepLength;
  recordingState: "idle" | "recording" | "recorded";
  recordedAudioUrl: string | null;
  recordedAudioBlob: Blob | null;
  trackEffects: Record<string, TrackEffects>;
  patternChain: string[];
  currentChainIndex: number;
}

interface UseDrumMachineReturn extends DrumMachineState {
  initialize: () => Promise<void>;
  play: () => void;
  stop: () => void;
  toggleStep: (soundId: string, step: number) => void;
  triggerSound: (soundId: string, velocity?: number) => void;
  setBpm: (bpm: number) => void;
  setSwing: (swing: number) => void;
  setVolume: (volume: number) => void;
  setKit: (kitId: string) => void;
  loadPattern: (pattern: DrumPattern) => void;
  clearPattern: () => void;
  toggleSolo: (soundId: string) => void;
  toggleMute: (soundId: string) => void;
  getAvailableKits: () => DrumKit[];
  getPresetPatterns: () => DrumPattern[];
  // New enhanced methods
  setStepLength: (length: StepLength) => void;
  startRecording: () => Promise<void>;
  stopRecording: () => Promise<void>;
  clearRecording: () => void;
  setTrackEffect: (soundId: string, effects: Partial<TrackEffects>) => void;
  addToChain: (patternId: string) => void;
  removeFromChain: (index: number) => void;
  clearChain: () => void;
  copyPattern: () => Record<string, boolean[]>;
  pastePattern: (copiedPattern: Record<string, boolean[]>) => void;
  exportToMidi: () => void;
}

// Default effects for a track
const defaultTrackEffects: TrackEffects = {
  filter: { enabled: false, frequency: 5000, resonance: 1 },
  compressor: { enabled: false, threshold: -24, ratio: 4 },
  volume: 0,
  pan: 0,
};

// Create synth for drum sound (requires Tone to be loaded)
function createDrumSynth(
  Tone: ToneType,
  sound: DrumSound,
): MembraneSynthType | MetalSynthType | NoiseSynthType | SynthType {
  switch (sound.type) {
    case "membrane":
      return new Tone.MembraneSynth(sound.params as ConstructorParameters<typeof Tone.MembraneSynth>[0]);
    case "metal":
      return new Tone.MetalSynth(sound.params as ConstructorParameters<typeof Tone.MetalSynth>[0]);
    case "noise":
      return new Tone.NoiseSynth(sound.params as ConstructorParameters<typeof Tone.NoiseSynth>[0]);
    case "synth":
    default:
      return new Tone.Synth(sound.params as ConstructorParameters<typeof Tone.Synth>[0]);
  }
}

export function useDrumMachine(): UseDrumMachineReturn {
  const synthsRef = useRef<Map<string, MembraneSynthType | MetalSynthType | NoiseSynthType | SynthType>>(new Map());
  const sequenceRef = useRef<SequenceType | null>(null);
  const masterVolumeRef = useRef<VolumeType | null>(null);
  const recorderRef = useRef<RecorderType | null>(null);

  // Per-track effects chains
  const trackFiltersRef = useRef<Map<string, FilterType>>(new Map());
  const trackCompressorsRef = useRef<Map<string, CompressorType>>(new Map());
  const trackPannersRef = useRef<Map<string, PannerType>>(new Map());
  const trackVolumesRef = useRef<Map<string, VolumeType>>(new Map());

  const [isReady, setIsReady] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentStep, setCurrentStep] = useState(0);
  const [bpm, setBpmState] = useState(120);
  const [swing, setSwingState] = useState(0);
  const [volume, setVolumeState] = useState(-6);
  const [currentKit, setCurrentKit] = useState<DrumKit>(drumKits[0]);
  const [pattern, setPattern] = useState<Record<string, boolean[]>>({});
  const [soloTracks, setSoloTracks] = useState<Set<string>>(new Set());
  const [mutedTracks, setMutedTracks] = useState<Set<string>>(new Set());

  // Enhanced state
  const [stepLength, setStepLengthState] = useState<StepLength>(16);
  const [recordingState, setRecordingState] = useState<"idle" | "recording" | "recorded">("idle");
  const [recordedAudioUrl, setRecordedAudioUrl] = useState<string | null>(null);
  const [recordedAudioBlob, setRecordedAudioBlob] = useState<Blob | null>(null);
  const [trackEffects, setTrackEffects] = useState<Record<string, TrackEffects>>({});
  const [patternChain, setPatternChain] = useState<string[]>([]);
  const [currentChainIndex, setCurrentChainIndex] = useState(0);

  // Initialize empty pattern with current step length
  const initializePattern = useCallback(
    (kit: DrumKit, steps: StepLength = stepLength) => {
      const emptyPattern: Record<string, boolean[]> = {};
      const defaultEffects: Record<string, TrackEffects> = {};
      kit.sounds.forEach((sound) => {
        emptyPattern[sound.id] = Array(steps).fill(false);
        defaultEffects[sound.id] = { ...defaultTrackEffects };
      });
      setPattern(emptyPattern);
      setTrackEffects(defaultEffects);
    },
    [stepLength],
  );

  // Initialize synths for kit with effects chain
  const initializeSynths = useCallback(
    (kit: DrumKit) => {
      if (!ToneModule) return;
      const Tone = ToneModule;

      // Dispose old synths and effects
      synthsRef.current.forEach((synth) => synth.dispose());
      synthsRef.current.clear();
      trackFiltersRef.current.forEach((f) => f.dispose());
      trackFiltersRef.current.clear();
      trackCompressorsRef.current.forEach((c) => c.dispose());
      trackCompressorsRef.current.clear();
      trackPannersRef.current.forEach((p) => p.dispose());
      trackPannersRef.current.clear();
      trackVolumesRef.current.forEach((v) => v.dispose());
      trackVolumesRef.current.clear();

      // Create master volume if not exists
      if (!masterVolumeRef.current) {
        masterVolumeRef.current = new Tone.Volume(volume).toDestination();
      }

      // Create recorder
      if (!recorderRef.current) {
        recorderRef.current = new Tone.Recorder();
        masterVolumeRef.current.connect(recorderRef.current);
      }

      // Create synths with effects chain for each sound
      kit.sounds.forEach((sound) => {
        const synth = createDrumSynth(Tone, sound);

        // Create effects chain: synth -> filter -> compressor -> panner -> volume -> master
        const filter = new Tone.Filter({ frequency: 5000, type: "lowpass", Q: 1 });
        const compressor = new Tone.Compressor({ threshold: -24, ratio: 4 });
        const panner = new Tone.Panner(0);
        const trackVol = new Tone.Volume(0);

        synth.chain(filter, compressor, panner, trackVol, masterVolumeRef.current!);

        synthsRef.current.set(sound.id, synth);
        trackFiltersRef.current.set(sound.id, filter);
        trackCompressorsRef.current.set(sound.id, compressor);
        trackPannersRef.current.set(sound.id, panner);
        trackVolumesRef.current.set(sound.id, trackVol);
      });
    },
    [volume],
  );

  // Initialize Tone.js with dynamic import
  const initialize = useCallback(async () => {
    if (isReady) return;

    try {
      // Dynamically import Tone.js only when needed
      if (!ToneModule) {
        ToneModule = await import("tone");
      }
      const Tone = ToneModule;

      await Tone.start();
      Tone.getTransport().bpm.value = bpm;

      initializeSynths(currentKit);
      initializePattern(currentKit);

      setIsReady(true);
      logger.info("Drum machine initialized");
    } catch (err) {
      logger.error("Failed to initialize drum machine", err);
    }
  }, [isReady, bpm, currentKit, initializeSynths, initializePattern]);

  // Trigger a sound
  const triggerSound = useCallback(
    (soundId: string, velocity = 1) => {
      if (!ToneModule) return;
      const Tone = ToneModule;

      const synth = synthsRef.current.get(soundId);
      if (!synth) return;

      // Check mute/solo
      const hasSolo = soloTracks.size > 0;
      if (hasSolo && !soloTracks.has(soundId)) return;
      if (mutedTracks.has(soundId)) return;

      try {
        if ("triggerAttackRelease" in synth) {
          if (synth.constructor.name === "NoiseSynth") {
            (synth as NoiseSynthType).triggerAttackRelease("16n", Tone.now(), velocity);
          } else if (synth.constructor.name === "MetalSynth") {
            (synth as MetalSynthType).triggerAttackRelease("16n", Tone.now(), velocity);
          } else if (synth.constructor.name === "MembraneSynth") {
            (synth as MembraneSynthType).triggerAttackRelease("C1", "8n", Tone.now(), velocity);
          } else {
            (synth as SynthType).triggerAttackRelease("C4", "16n", Tone.now(), velocity);
          }
        }
      } catch (err) {
        logger.error("Failed to trigger sound", err);
      }
    },
    [soloTracks, mutedTracks],
  );

  // Create sequence
  const createSequence = useCallback(() => {
    if (!ToneModule) return;
    const Tone = ToneModule;

    if (sequenceRef.current) {
      sequenceRef.current.dispose();
    }

    const steps = Array.from({ length: stepLength }, (_, i) => i);

    sequenceRef.current = new Tone.Sequence(
      (time, step) => {
        setCurrentStep(step);

        // Trigger sounds for this step
        Object.entries(pattern).forEach(([soundId, stepPattern]) => {
          if (stepPattern[step]) {
            const synth = synthsRef.current.get(soundId);
            if (!synth) return;

            // Check mute/solo
            const hasSolo = soloTracks.size > 0;
            if (hasSolo && !soloTracks.has(soundId)) return;
            if (mutedTracks.has(soundId)) return;

            if ("triggerAttackRelease" in synth) {
              if (synth.constructor.name === "NoiseSynth") {
                (synth as NoiseSynthType).triggerAttackRelease("16n", time);
              } else if (synth.constructor.name === "MetalSynth") {
                (synth as MetalSynthType).triggerAttackRelease("16n", time);
              } else if (synth.constructor.name === "MembraneSynth") {
                (synth as MembraneSynthType).triggerAttackRelease("C1", "8n", time);
              } else {
                (synth as SynthType).triggerAttackRelease("C4", "16n", time);
              }
            }
          }
        });
      },
      steps,
      "16n",
    );
  }, [pattern, soloTracks, mutedTracks, stepLength]);

  // Play
  const play = useCallback(() => {
    if (!isReady || !ToneModule) return;
    const Tone = ToneModule;

    createSequence();
    sequenceRef.current?.start(0);
    Tone.getTransport().start();
    setIsPlaying(true);
  }, [isReady, createSequence]);

  // Stop
  const stop = useCallback(() => {
    if (!ToneModule) return;
    const Tone = ToneModule;

    Tone.getTransport().stop();
    sequenceRef.current?.stop();
    setIsPlaying(false);
    setCurrentStep(0);
  }, []);

  // Toggle step
  const toggleStep = useCallback(
    (soundId: string, step: number) => {
      setPattern((prev) => ({
        ...prev,
        [soundId]: prev[soundId]?.map((v, i) => (i === step ? !v : v)) || Array(stepLength).fill(false),
      }));
    },
    [stepLength],
  );

  // Set BPM
  const setBpm = useCallback((newBpm: number) => {
    if (!ToneModule) return;
    const Tone = ToneModule;

    const clampedBpm = Math.max(40, Math.min(220, newBpm));
    setBpmState(clampedBpm);
    Tone.getTransport().bpm.value = clampedBpm;
  }, []);

  // Set Swing
  const setSwing = useCallback((newSwing: number) => {
    if (!ToneModule) return;
    const Tone = ToneModule;

    const clampedSwing = Math.max(0, Math.min(100, newSwing));
    setSwingState(clampedSwing);
    Tone.getTransport().swing = clampedSwing / 100;
  }, []);

  // Set Volume
  const setVolume = useCallback((newVolume: number) => {
    setVolumeState(newVolume);
    if (masterVolumeRef.current) {
      masterVolumeRef.current.volume.value = newVolume;
    }
  }, []);

  // Set Kit
  const setKit = useCallback(
    (kitId: string) => {
      const kit = getKitById(kitId);
      if (!kit) return;

      const wasPlaying = isPlaying;
      if (wasPlaying) stop();

      setCurrentKit(kit);
      initializeSynths(kit);
      initializePattern(kit);

      if (wasPlaying) play();
    },
    [isPlaying, stop, play, initializeSynths, initializePattern],
  );

  // Load Pattern
  const loadPattern = useCallback(
    (presetPattern: DrumPattern) => {
      const wasPlaying = isPlaying;
      if (wasPlaying) stop();

      setBpm(presetPattern.bpm);

      // Merge pattern with empty pattern for current kit
      const newPattern: Record<string, boolean[]> = {};
      currentKit.sounds.forEach((sound) => {
        const presetSteps = presetPattern.steps[sound.id];
        if (presetSteps) {
          // Extend or trim to match current stepLength
          newPattern[sound.id] = Array(stepLength)
            .fill(false)
            .map((_, i) => (i < presetSteps.length ? presetSteps[i] : false));
        } else {
          newPattern[sound.id] = Array(stepLength).fill(false);
        }
      });
      setPattern(newPattern);

      if (wasPlaying) play();
    },
    [isPlaying, stop, play, currentKit, setBpm, stepLength],
  );

  // Clear Pattern
  const clearPattern = useCallback(() => {
    initializePattern(currentKit);
  }, [currentKit, initializePattern]);

  // Toggle Solo
  const toggleSolo = useCallback((soundId: string) => {
    setSoloTracks((prev) => {
      const next = new Set(prev);
      if (next.has(soundId)) {
        next.delete(soundId);
      } else {
        next.add(soundId);
      }
      return next;
    });
  }, []);

  // Toggle Mute
  const toggleMute = useCallback((soundId: string) => {
    setMutedTracks((prev) => {
      const next = new Set(prev);
      if (next.has(soundId)) {
        next.delete(soundId);
      } else {
        next.add(soundId);
      }
      return next;
    });
  }, []);

  // Set step length
  const setStepLength = useCallback((newLength: StepLength) => {
    setStepLengthState(newLength);
    // Resize existing pattern
    setPattern((prev) => {
      const resized: Record<string, boolean[]> = {};
      Object.entries(prev).forEach(([soundId, steps]) => {
        resized[soundId] = Array(newLength)
          .fill(false)
          .map((_, i) => (i < steps.length ? steps[i] : false));
      });
      return resized;
    });
  }, []);

  // Start recording
  const startRecording = useCallback(async () => {
    if (!recorderRef.current || recordingState === "recording") return;

    try {
      await recorderRef.current.start();
      setRecordingState("recording");
      logger.info("Recording started");
    } catch (err) {
      logger.error("Failed to start recording", err);
    }
  }, [recordingState]);

  // Stop recording
  const stopRecording = useCallback(async () => {
    if (!recorderRef.current || recordingState !== "recording") return;

    try {
      const recording = await recorderRef.current.stop();
      const url = URL.createObjectURL(recording);
      setRecordedAudioUrl(url);
      setRecordedAudioBlob(recording);
      setRecordingState("recorded");
      logger.info("Recording stopped", { size: recording.size });
    } catch (err) {
      logger.error("Failed to stop recording", err);
    }
  }, [recordingState]);

  // Clear recording
  const clearRecording = useCallback(() => {
    if (recordedAudioUrl) {
      URL.revokeObjectURL(recordedAudioUrl);
    }
    setRecordedAudioUrl(null);
    setRecordedAudioBlob(null);
    setRecordingState("idle");
  }, [recordedAudioUrl]);

  // Set track effects
  const setTrackEffect = useCallback((soundId: string, effects: Partial<TrackEffects>) => {
    setTrackEffects((prev) => ({
      ...prev,
      [soundId]: { ...prev[soundId], ...effects },
    }));

    // Apply effects to Tone.js nodes
    const filter = trackFiltersRef.current.get(soundId);
    const compressor = trackCompressorsRef.current.get(soundId);
    const panner = trackPannersRef.current.get(soundId);
    const vol = trackVolumesRef.current.get(soundId);

    if (effects.filter && filter) {
      filter.frequency.value = effects.filter.frequency || 5000;
      filter.Q.value = effects.filter.resonance || 1;
    }
    if (effects.compressor && compressor) {
      compressor.threshold.value = effects.compressor.threshold || -24;
      compressor.ratio.value = effects.compressor.ratio || 4;
    }
    if (effects.pan !== undefined && panner) {
      panner.pan.value = effects.pan;
    }
    if (effects.volume !== undefined && vol) {
      vol.volume.value = effects.volume;
    }
  }, []);

  // Pattern chain methods
  const addToChain = useCallback((patternId: string) => {
    setPatternChain((prev) => [...prev, patternId]);
  }, []);

  const removeFromChain = useCallback((index: number) => {
    setPatternChain((prev) => prev.filter((_, i) => i !== index));
  }, []);

  const clearChain = useCallback(() => {
    setPatternChain([]);
    setCurrentChainIndex(0);
  }, []);

  // Copy/paste pattern
  const copyPattern = useCallback(() => {
    return { ...pattern };
  }, [pattern]);

  const pastePattern = useCallback(
    (copiedPattern: Record<string, boolean[]>) => {
      setPattern((prev) => {
        const pasted: Record<string, boolean[]> = {};
        Object.keys(prev).forEach((soundId) => {
          if (copiedPattern[soundId]) {
            pasted[soundId] = [...copiedPattern[soundId]].slice(0, stepLength);
            // Pad if needed
            while (pasted[soundId].length < stepLength) {
              pasted[soundId].push(false);
            }
          } else {
            pasted[soundId] = prev[soundId];
          }
        });
        return pasted;
      });
    },
    [stepLength],
  );

  // Export to MIDI (creates download)
  const exportToMidi = useCallback(() => {
    // Simple MIDI export - create a Blob with MIDI data
    // Using a basic MIDI format
    const midiData = {
      bpm,
      pattern,
      stepLength,
      kit: currentKit.id,
    };

    const blob = new Blob([JSON.stringify(midiData, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `drum-pattern-${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);

    logger.info("Pattern exported");
  }, [bpm, pattern, stepLength, currentKit.id]);

  // Recreate sequence when pattern changes
  useEffect(() => {
    if (isPlaying) {
      createSequence();
    }
  }, [pattern, isPlaying, createSequence]);

  // Cleanup
  useEffect(() => {
    return () => {
      sequenceRef.current?.dispose();
      synthsRef.current.forEach((synth) => synth.dispose());
      masterVolumeRef.current?.dispose();
      recorderRef.current?.dispose();
      trackFiltersRef.current.forEach((f) => f.dispose());
      trackCompressorsRef.current.forEach((c) => c.dispose());
      trackPannersRef.current.forEach((p) => p.dispose());
      trackVolumesRef.current.forEach((v) => v.dispose());
      if (recordedAudioUrl) {
        URL.revokeObjectURL(recordedAudioUrl);
      }
    };
  }, [recordedAudioUrl]);

  return {
    isReady,
    isPlaying,
    currentStep,
    bpm,
    swing,
    volume,
    currentKit,
    pattern,
    soloTracks,
    mutedTracks,
    stepLength,
    recordingState,
    recordedAudioUrl,
    recordedAudioBlob,
    trackEffects,
    patternChain,
    currentChainIndex,
    initialize,
    play,
    stop,
    toggleStep,
    triggerSound,
    setBpm,
    setSwing,
    setVolume,
    setKit,
    loadPattern,
    clearPattern,
    toggleSolo,
    toggleMute,
    getAvailableKits: () => drumKits,
    getPresetPatterns: () => presetPatterns,
    setStepLength,
    startRecording,
    stopRecording,
    clearRecording,
    setTrackEffect,
    addToChain,
    removeFromChain,
    clearChain,
    copyPattern,
    pastePattern,
    exportToMidi,
  };
}

