import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { toast } from "sonner";
import { logger } from "@/lib/logger";
import { notifyProjectChange } from "@/services/notificationManager";
import { useAuditLog } from "./useAuditLog";
import { useEffect, useCallback } from "react";
import type { Tables, TablesInsert, TablesUpdate } from "@/integrations/supabase/types";

// Use database type directly for consistency
export type Project = Tables<"music_projects">;

const RETRY_ATTEMPTS = 3;
const RETRY_DELAY = 1000;

const retryWithBackoff = async <T,>(fn: () => Promise<T>, attempts = RETRY_ATTEMPTS): Promise<T> => {
  try {
    return await fn();
  } catch (error) {
    if (attempts <= 1) throw error;
    await new Promise((resolve) => setTimeout(resolve, RETRY_DELAY * (RETRY_ATTEMPTS - attempts + 1)));
    return retryWithBackoff(fn, attempts - 1);
  }
};

export const useProjects = () => {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const { logProjectCreated, logAction } = useAuditLog();

  const {
    data: projects,
    isLoading,
    error,
    refetch,
  } = useQuery({
    queryKey: ["projects", user?.id],
    queryFn: async () => {
      if (!user?.id) return [];

      return retryWithBackoff(async () => {
        const { data, error } = await supabase
          .from("music_projects")
          .select("*")
          .eq("user_id", user.id)
          .order("created_at", { ascending: false });

        if (error) throw error;
        return data || [];
      });
    },
    enabled: !!user?.id,
    staleTime: 60000, // 1 minute
  });

  // Realtime subscription with debounced cache updates
  useEffect(() => {
    if (!user?.id) return;

    let debounceTimeout: NodeJS.Timeout | null = null;

    const channel = supabase
      .channel(`projects-${user.id}-${Math.random().toString(36).slice(2)}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "music_projects",
          filter: `user_id=eq.${user.id}`,
        },
        (payload) => {
          // Debounce to prevent rapid consecutive updates
          if (debounceTimeout) {
            clearTimeout(debounceTimeout);
          }
          debounceTimeout = setTimeout(() => {
            // Update cache directly for better UX instead of full refetch
            if (payload.eventType === "INSERT" && payload.new) {
              queryClient.setQueryData(["projects", user.id], (old: Project[] | undefined) => {
                if (!old) return [payload.new as Project];
                // Prevent duplicates
                if (old.some((p) => p.id === (payload.new as Project).id)) return old;
                return [payload.new as Project, ...old];
              });
            } else if (payload.eventType === "DELETE" && payload.old) {
              queryClient.setQueryData(["projects", user.id], (old: Project[] | undefined) => {
                if (!old) return [];
                return old.filter((p) => p.id !== (payload.old as Project).id);
              });
            } else if (payload.eventType === "UPDATE" && payload.new) {
              queryClient.setQueryData(["projects", user.id], (old: Project[] | undefined) => {
                if (!old) return [];
                return old.map((p) => (p.id === (payload.new as Project).id ? (payload.new as Project) : p));
              });
            }
          }, 100);
        },
      )
      .subscribe();

    return () => {
      if (debounceTimeout) {
        clearTimeout(debounceTimeout);
      }
      supabase.removeChannel(channel);
    };
  }, [user?.id, queryClient]);

  // Check if user can create more projects
  const checkProjectLimit = useCallback(async (): Promise<{
    allowed: boolean;
    currentCount: number;
    limit: number | null;
    remaining?: number;
    reason?: string;
  }> => {
    if (!user?.id) {
      return { allowed: false, currentCount: 0, limit: 3, reason: "Требуется авторизация" };
    }

    const { data, error } = await supabase.rpc("can_create_project", {
      _user_id: user.id,
    });

    if (error) {
      logger.error("Error checking project limit", error);
      return { allowed: true, currentCount: 0, limit: null }; // Allow on error
    }

    // Cast to proper type since RPC returns Json
    const result = data as {
      allowed?: boolean;
      current_count?: number;
      limit?: number;
      remaining?: number;
      reason?: string;
    } | null;

    return {
      allowed: result?.allowed ?? true,
      currentCount: result?.current_count ?? 0,
      limit: result?.limit ?? null,
      remaining: result?.remaining,
      reason: result?.reason,
    };
  }, [user?.id]);

  const createProject = useMutation({
    mutationFn: async (projectData: Partial<Project> & { title: string }) => {
      if (!user?.id) throw new Error("User not authenticated");

      return retryWithBackoff(async () => {
        // Check project limit for free users
        const limitCheck = await checkProjectLimit();
        if (!limitCheck.allowed) {
          throw new Error(limitCheck.reason || "Достигнут лимит проектов");
        }

        // Check if user is premium or admin to set default is_public
        const { data: isPremium } = await supabase.rpc("is_premium_or_admin", {
          _user_id: user.id,
        });

        const { data, error } = await supabase
          .from("music_projects")
          .insert([
            {
              user_id: user.id,
              is_public: isPremium ? false : true, // Free users create public by default
              ...projectData,
            },
          ])
          .select()
          .single();

        if (error) throw error;
        return data;
      });
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["projects", user?.id] });
      toast.success("Проект создан успешно");
      // Send notification
      if (user?.id) {
        notifyProjectChange(user.id, data.title, "created", data.id);
        // Log to audit
        logProjectCreated(data.id, data.title, {
          projectType: data.project_type,
          genre: data.genre,
          mood: data.mood,
        });
      }
    },
    onError: (error) => {
      logger.error("Error creating project", error);
      const errorMessage =
        error instanceof Error && error.message.includes("лимит") ? error.message : "Ошибка создания проекта";
      toast.error(errorMessage);
    },
  });

  const updateProject = useMutation({
    mutationFn: async ({ id, updates }: { id: string; updates: Partial<Project> }) => {
      return retryWithBackoff(async () => {
        const { data, error } = await supabase.from("music_projects").update(updates).eq("id", id).select().single();

        if (error) throw error;
        return data;
      });
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["projects", user?.id] });
      toast.success("Проект обновлен");
      // Send notification
      if (user?.id) {
        notifyProjectChange(user.id, data.title, "updated", data.id);
        // Log to audit
        logAction({
          entityType: "project",
          entityId: data.id,
          actionType: "updated",
          actorType: "user",
          outputMetadata: { title: data.title },
        });
      }
    },
    onError: (error) => {
      logger.error("Error updating project", error);
      toast.error("Ошибка обновления проекта");
    },
  });

  const deleteProject = useMutation({
    mutationFn: async (projectId: string) => {
      return retryWithBackoff(async () => {
        // Get project title before deletion
        const { data: project } = await supabase.from("music_projects").select("title").eq("id", projectId).single();

        const { error } = await supabase.from("music_projects").delete().eq("id", projectId);

        if (error) throw error;
        return { title: project?.title || "Проект" };
      });
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["projects", user?.id] });
      toast.success("Проект удален");
      // Send notification
      if (user?.id) {
        notifyProjectChange(user.id, data.title, "deleted");
      }
    },
    onError: (error) => {
      logger.error("Error deleting project", error);
      toast.error("Ошибка удаления проекта");
    },
  });

  const generateProjectConcept = useMutation({
    mutationFn: async (params: {
      projectType?: string;
      description?: string;
      genre?: string;
      mood?: string;
      targetAudience?: string;
      theme?: string;
      artistPersona?: string;
    }) => {
      return retryWithBackoff(async () => {
        const { data, error } = await supabase.functions.invoke("project-ai", {
          body: {
            action: "concept",
            ...params,
          },
        });

        if (error) throw error;
        return data;
      });
    },
    onSuccess: () => {
      toast.success("Концепция проекта создана");
    },
    onError: (error) => {
      logger.error("Error generating concept", error);
      toast.error("Ошибка генерации концепции");
    },
  });

  return {
    projects,
    isLoading,
    error,
    // Expose mutate functions directly to allow options (onSuccess, onError)
    createProject: createProject.mutate,
    updateProject: updateProject.mutate,
    deleteProject: deleteProject.mutate,
    generateProjectConcept: generateProjectConcept.mutate,
    // Async versions for await usage
    createProjectAsync: createProject.mutateAsync,
    updateProjectAsync: updateProject.mutateAsync,
    deleteProjectAsync: deleteProject.mutateAsync,
    generateProjectConceptAsync: generateProjectConcept.mutateAsync,
    isCreating: createProject.isPending,
    isUpdating: updateProject.isPending,
    isDeleting: deleteProject.isPending,
    isGenerating: generateProjectConcept.isPending,
    // Project limit check for UI
    checkProjectLimit,
    refetch,
  };
};

/**
 * Hook for automatic cloud upload of microphone recordings
 * Handles upload to Supabase storage with retry logic and logging
 */

import { useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { logger } from "@/lib/logger";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";

const log = logger.child({ module: "RecordingUpload" });

interface UploadResult {
  url: string;
  fileName: string;
  size: number;
}

interface UseRecordingUploadOptions {
  bucket?: string;
  folder?: string;
  maxRetries?: number;
  onSuccess?: (result: UploadResult) => void;
  onError?: (error: Error) => void;
}

export function useRecordingUpload(options: UseRecordingUploadOptions = {}) {
  const { bucket = "reference-audio", folder = "recordings", maxRetries = 3, onSuccess, onError } = options;

  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [lastUploadResult, setLastUploadResult] = useState<UploadResult | null>(null);

  const uploadRecording = useCallback(
    async (blob: Blob, customFileName?: string): Promise<UploadResult | null> => {
      if (!user) {
        log.warn("Upload attempted without authentication");
        toast.error("Необходимо авторизоваться");
        return null;
      }

      if (!blob || blob.size === 0) {
        log.error("Empty blob provided for upload");
        toast.error("Пустая запись");
        return null;
      }

      setIsUploading(true);
      setUploadProgress(0);

      const dateStr = new Date().toISOString().slice(0, 10);
      const timeStr = new Date()
        .toLocaleTimeString("ru-RU", {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
        })
        .replace(/:/g, "-");

      const extension = blob.type.includes("webm")
        ? "webm"
        : blob.type.includes("mp4")
          ? "m4a"
          : blob.type.includes("ogg")
            ? "ogg"
            : "webm";

      const fileName = customFileName || `rec_${dateStr}_${timeStr}.${extension}`;
      const filePath = `${folder}/${user.id}/${fileName}`;

      let attempt = 0;
      let lastError: Error | null = null;

      while (attempt < maxRetries) {
        attempt++;

        try {
          log.info("Starting upload attempt", {
            attempt,
            filePath,
            size: blob.size,
            type: blob.type,
          });

          setUploadProgress(attempt * 20); // Show progress during retries

          const { error: uploadError, data } = await supabase.storage.from(bucket).upload(filePath, blob, {
            contentType: blob.type,
            upsert: true,
          });

          if (uploadError) {
            throw uploadError;
          }

          // Get public URL
          const { data: urlData } = supabase.storage.from(bucket).getPublicUrl(filePath);

          const result: UploadResult = {
            url: urlData.publicUrl,
            fileName,
            size: blob.size,
          };

          setLastUploadResult(result);
          setUploadProgress(100);

          log.info("Upload successful", {
            filePath,
            url: result.url,
            size: blob.size,
          });

          onSuccess?.(result);

          return result;
        } catch (error) {
          lastError = error instanceof Error ? error : new Error(String(error));

          log.error("Upload attempt failed", lastError, {
            attempt,
            maxRetries,
            filePath,
          });

          if (attempt < maxRetries) {
            // Exponential backoff
            const delay = Math.pow(2, attempt) * 500;
            log.info("Retrying upload", { attempt, delay });
            await new Promise((resolve) => setTimeout(resolve, delay));
          }
        }
      }

      // All retries failed
      setIsUploading(false);
      setUploadProgress(0);

      const finalError = lastError || new Error("Upload failed after max retries");
      log.error("Upload failed after all retries", finalError, {
        maxRetries,
        filePath,
      });

      toast.error("Не удалось сохранить запись", {
        description: "Проверьте подключение к интернету",
      });

      onError?.(finalError);
      return null;
    },
    [user, bucket, folder, maxRetries, onSuccess, onError],
  );

  const uploadRecordingQuietly = useCallback(
    async (blob: Blob, customFileName?: string): Promise<UploadResult | null> => {
      // Same as uploadRecording but without toast notifications
      if (!user || !blob || blob.size === 0) {
        return null;
      }

      setIsUploading(true);

      const dateStr = new Date().toISOString().slice(0, 10);
      const timeStr = Date.now().toString(36);
      const extension = blob.type.includes("webm") ? "webm" : "m4a";
      const fileName = customFileName || `rec_${dateStr}_${timeStr}.${extension}`;
      const filePath = `${folder}/${user.id}/${fileName}`;

      try {
        const { error: uploadError } = await supabase.storage.from(bucket).upload(filePath, blob, {
          contentType: blob.type,
          upsert: true,
        });

        if (uploadError) throw uploadError;

        const { data: urlData } = supabase.storage.from(bucket).getPublicUrl(filePath);

        const result: UploadResult = {
          url: urlData.publicUrl,
          fileName,
          size: blob.size,
        };

        // Save to reference_audio table so it appears in "From Cloud" picker
        try {
          const { error: dbError } = await supabase.from("reference_audio").insert({
            user_id: user.id,
            file_name: fileName,
            file_url: urlData.publicUrl,
            file_size: blob.size,
            mime_type: blob.type,
            source: "microphone",
            analysis_status: "pending",
          });

          if (dbError) {
            log.error("Failed to save recording to database", dbError);
            toast.error("Запись не сохранена в библиотеку", {
              description: "Файл загружен, но не добавлен в список облака",
            });
          } else {
            log.debug("Recording saved to reference_audio table", { fileName });
            // Invalidate query cache so CloudAudioPicker updates
            queryClient.invalidateQueries({ queryKey: ["reference-audio"] });
          }
        } catch (dbErr) {
          log.error("Database insert error", dbErr);
          toast.error("Ошибка сохранения записи");
        }

        setLastUploadResult(result);
        setIsUploading(false);
        onSuccess?.(result);

        log.debug("Quiet upload successful", { filePath });
        return result;
      } catch (error) {
        log.error("Quiet upload failed", error, { filePath });
        setIsUploading(false);
        onError?.(error instanceof Error ? error : new Error(String(error)));
        return null;
      }
    },
    [user, bucket, folder, onSuccess, onError],
  );

  return {
    uploadRecording,
    uploadRecordingQuietly,
    isUploading,
    uploadProgress,
    lastUploadResult,
  };
}

/**
 * useReducedMotion - Hook to detect user's motion preference
 *
 * Respects prefers-reduced-motion media query for accessibility.
 * Use this to disable or simplify animations for users who prefer reduced motion.
 *
 * @example
 * const prefersReducedMotion = useReducedMotion();
 *
 * // Disable animation
 * <motion.div animate={prefersReducedMotion ? {} : { scale: 1.1 }} />
 *
 * // Or use simpler animation
 * const animationDuration = prefersReducedMotion ? 0 : 0.3;
 *
 * @example Using useMotionPreference for advanced patterns
 * const { prefersReducedMotion, safeVariants, safeTransition } = useMotionPreference();
 * <motion.div variants={safeVariants(myVariants)} transition={safeTransition(myTransition)} />
 */

import { useState, useEffect, useMemo } from "react";
import type { Variants, Transition } from "@/lib/motion";

const QUERY = "(prefers-reduced-motion: reduce)";

function getInitialState(): boolean {
  // SSR safety check
  if (typeof window === "undefined") {
    return false;
  }
  return window.matchMedia(QUERY).matches;
}

export function useReducedMotion(): boolean {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(getInitialState);

  useEffect(() => {
    const mediaQuery = window.matchMedia(QUERY);

    // Set initial value
    setPrefersReducedMotion(mediaQuery.matches);

    // Listen for changes
    const handleChange = (event: MediaQueryListEvent) => {
      setPrefersReducedMotion(event.matches);
    };

    // Modern browsers
    if (mediaQuery.addEventListener) {
      mediaQuery.addEventListener("change", handleChange);
      return () => mediaQuery.removeEventListener("change", handleChange);
    }
    // Legacy browsers (Safari < 14)
    else {
      mediaQuery.addListener(handleChange);
      return () => mediaQuery.removeListener(handleChange);
    }
  }, []);

  return prefersReducedMotion;
}

// Instant transition for reduced motion
const instantTransition: Transition = { duration: 0 };

// Minimal fade-only variants for reduced motion
const reducedMotionVariants: Variants = {
  initial: { opacity: 0 },
  animate: { opacity: 1, transition: instantTransition },
  exit: { opacity: 0, transition: instantTransition },
};

/**
 * Advanced hook for motion preference with helper utilities
 */
export function useMotionPreference() {
  const prefersReducedMotion = useReducedMotion();

  return useMemo(
    () => ({
      prefersReducedMotion,

      /**
       * Returns motion-safe variants
       * Replaces complex animations with simple fade when reduced motion is preferred
       */
      safeVariants: (variants: Variants): Variants => {
        if (!prefersReducedMotion) return variants;
        return reducedMotionVariants;
      },

      /**
       * Returns motion-safe transition
       */
      safeTransition: (transition: Transition): Transition => {
        if (!prefersReducedMotion) return transition;
        return instantTransition;
      },

      /**
       * Get animation duration (0 if reduced motion preferred)
       */
      safeDuration: (duration: number): number => {
        return prefersReducedMotion ? 0 : duration;
      },

      reducedMotionVariants,
      instantTransition,
    }),
    [prefersReducedMotion],
  );
}

/**
 * Get motion-safe animation values
 * Returns animation values or empty/instant values based on user preference
 */
export function useMotionSafe<T>(animationValues: T, fallback: T): T {
  const prefersReducedMotion = useReducedMotion();
  return prefersReducedMotion ? fallback : animationValues;
}

/**
 * Get motion-safe duration
 * Returns 0 for users who prefer reduced motion
 */
export function useMotionDuration(duration: number): number {
  const prefersReducedMotion = useReducedMotion();
  return prefersReducedMotion ? 0 : duration;
}

// ============================================================================
// CSS ANIMATION UTILITIES
// ============================================================================

/**
 * CSS classes with built-in reduced motion support
 */
export const safeAnimationClasses = {
  fadeIn: "animate-fade-in motion-reduce:animate-none motion-reduce:opacity-100",
  fadeOut: "animate-fade-out motion-reduce:animate-none",
  slideUp: "animate-slide-up motion-reduce:animate-none motion-reduce:opacity-100",
  slideDown: "animate-slide-down motion-reduce:animate-none motion-reduce:opacity-100",
  slideLeft: "animate-slide-left motion-reduce:animate-none motion-reduce:opacity-100",
  slideRight: "animate-slide-right motion-reduce:animate-none motion-reduce:opacity-100",
  scaleIn: "animate-scale-in motion-reduce:animate-none motion-reduce:opacity-100",
  spin: "animate-spin motion-reduce:animate-none",
  pulse: "animate-pulse-subtle motion-reduce:animate-none",
  shimmer: "animate-shimmer motion-reduce:animate-none",
} as const;

/**
 * Get CSS stagger delay style
 * Returns empty object for reduced motion users
 */
export function getStaggerStyle(
  index: number,
  prefersReducedMotion: boolean = false,
  baseDelay: number = 50,
): React.CSSProperties {
  if (prefersReducedMotion) return {};
  return { animationDelay: `${index * baseDelay}ms` };
}

/**
 * Hook to get stagger delay for CSS animations
 */
export function useStaggerDelay(index: number, baseDelay: number = 50): React.CSSProperties {
  const prefersReducedMotion = useReducedMotion();
  return getStaggerStyle(index, prefersReducedMotion, baseDelay);
}

export default useReducedMotion;

// Re-export constants for direct import (used by tests)
export { instantTransition, reducedMotionVariants };

