/**
 * useReferenceStemPlayback - Hook for synchronized stem playback
 *
 * Manages multiple audio elements with mute/solo, volume control, and sync
 * Integrates with studio audio coordination to ensure single playback source
 */

import { useState, useRef, useCallback, useEffect, useId } from "react";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";
import { registerStudioAudio, unregisterStudioAudio, pauseAllStudioAudio } from "@/hooks/studio/useStudioAudio";
import { logger } from "@/lib/logger";

export interface Stem {
  id: string;
  type: string;
  url: string;
  label: string;
}

export interface StemState {
  volume: number;
  muted: boolean;
  solo: boolean;
}

interface UseReferenceStemPlaybackReturn {
  isPlaying: boolean;
  currentTime: number;
  duration: number;
  masterVolume: number;
  stemStates: Record<string, StemState>;
  isLoading: boolean;
  togglePlay: () => void;
  seek: (time: number) => void;
  setMasterVolume: (volume: number) => void;
  toggleMute: (stemId: string) => void;
  toggleSolo: (stemId: string) => void;
  setStemVolume: (stemId: string, volume: number) => void;
  audioRefs: React.MutableRefObject<Map<string, HTMLAudioElement>>;
  pause: () => void;
}

export function useReferenceStemPlayback(stems: Stem[]): UseReferenceStemPlaybackReturn {
  const sourceId = useId();
  const audioRefs = useRef<Map<string, HTMLAudioElement>>(new Map());
  const animationRef = useRef<number | undefined>(undefined);

  const { pauseTrack, isPlaying: globalIsPlaying } = usePlayerStore();

  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [masterVolume, setMasterVolumeState] = useState(0.85);
  const [isLoading, setIsLoading] = useState(stems.length > 0);
  const [stemStates, setStemStates] = useState<Record<string, StemState>>(() => {
    const initial: Record<string, StemState> = {};
    stems.forEach((stem) => {
      initial[stem.id] = { volume: 1, muted: false, solo: false };
    });
    return initial;
  });

  // Check if any stem has solo active
  const hasSolo = Object.values(stemStates).some((s) => s.solo);

  // Calculate effective volume for a stem
  const getEffectiveVolume = useCallback(
    (stemId: string): number => {
      const state = stemStates[stemId];
      if (!state) return masterVolume;
      if (state.muted) return 0;
      if (hasSolo && !state.solo) return 0;
      return state.volume * masterVolume;
    },
    [stemStates, masterVolume, hasSolo],
  );

  // Pause function for external coordination
  const pause = useCallback(() => {
    audioRefs.current.forEach((audio) => audio.pause());
    setIsPlaying(false);
  }, []);

  // Initialize audio elements
  useEffect(() => {
    const newAudioRefs = new Map<string, HTMLAudioElement>();
    let loadedCount = 0;

    stems.forEach((stem) => {
      const audio = new Audio(stem.url);
      audio.preload = "auto";
      audio.volume = getEffectiveVolume(stem.id);

      audio.addEventListener("loadedmetadata", () => {
        loadedCount++;
        if (audio.duration > duration) {
          setDuration(audio.duration);
        }
        if (loadedCount === stems.length) {
          setIsLoading(false);
        }
      });

      audio.addEventListener("ended", () => {
        setIsPlaying(false);
        setCurrentTime(0);
      });

      audio.addEventListener("error", (e) => {
        logger.warn(`Error loading stem ${stem.type}`, { error: e });
        loadedCount++;
        if (loadedCount === stems.length) {
          setIsLoading(false);
        }
      });

      newAudioRefs.set(stem.id, audio);
    });

    audioRefs.current = newAudioRefs;

    // Register with studio audio coordinator
    const studioSourceId = `reference-stems-${sourceId}`;
    registerStudioAudio(studioSourceId, () => {
      audioRefs.current.forEach((audio) => audio.pause());
      setIsPlaying(false);
    });

    // Cleanup
    return () => {
      unregisterStudioAudio(studioSourceId);
      audioRefs.current.forEach((audio) => {
        audio.pause();
        audio.src = "";
      });
      audioRefs.current.clear();
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [stems, sourceId]);

  // Update volumes when state changes
  useEffect(() => {
    audioRefs.current.forEach((audio, stemId) => {
      audio.volume = getEffectiveVolume(stemId);
    });
  }, [getEffectiveVolume]);

  // Pause when global player starts
  useEffect(() => {
    if (globalIsPlaying && isPlaying) {
      audioRefs.current.forEach((audio) => audio.pause());
      setIsPlaying(false);
    }
  }, [globalIsPlaying, isPlaying]);

  // Animation frame for time updates
  useEffect(() => {
    if (isPlaying) {
      const updateTime = () => {
        const firstAudio = audioRefs.current.values().next().value;
        if (firstAudio) {
          setCurrentTime(firstAudio.currentTime);
        }
        animationRef.current = requestAnimationFrame(updateTime);
      };
      animationRef.current = requestAnimationFrame(updateTime);
    } else {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    }

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [isPlaying]);

  const togglePlay = useCallback(() => {
    if (isPlaying) {
      audioRefs.current.forEach((audio) => audio.pause());
    } else {
      // Pause global player and other studio audio first
      pauseTrack();
      pauseAllStudioAudio(`reference-stems-${sourceId}`);

      // Sync all audio elements to the same time before playing
      const targetTime = currentTime;
      audioRefs.current.forEach((audio) => {
        audio.currentTime = targetTime;
        audio.play().catch((err) => logger.warn("Audio play failed", { error: err }));
      });
    }
    setIsPlaying(!isPlaying);
  }, [isPlaying, currentTime, pauseTrack, sourceId]);

  const seek = useCallback((time: number) => {
    audioRefs.current.forEach((audio) => {
      audio.currentTime = time;
    });
    setCurrentTime(time);
  }, []);

  const setMasterVolume = useCallback((volume: number) => {
    setMasterVolumeState(volume);
  }, []);

  const toggleMute = useCallback((stemId: string) => {
    setStemStates((prev) => ({
      ...prev,
      [stemId]: {
        ...prev[stemId],
        muted: !prev[stemId]?.muted,
      },
    }));
  }, []);

  const toggleSolo = useCallback((stemId: string) => {
    setStemStates((prev) => ({
      ...prev,
      [stemId]: {
        ...prev[stemId],
        solo: !prev[stemId]?.solo,
      },
    }));
  }, []);

  const setStemVolume = useCallback((stemId: string, volume: number) => {
    setStemStates((prev) => ({
      ...prev,
      [stemId]: {
        ...prev[stemId],
        volume,
      },
    }));
  }, []);

  return {
    isPlaying,
    currentTime,
    duration,
    masterVolume,
    stemStates,
    isLoading,
    togglePlay,
    seek,
    setMasterVolume,
    toggleMute,
    toggleSolo,
    setStemVolume,
    audioRefs,
    pause,
  };
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

interface ReplacedSection {
  start: number;
  end: number;
  taskId: string;
  createdAt: string;
  audioUrl?: string;
  audioUrlB?: string; // Second variant from Suno API
  status: "pending" | "processing" | "completed" | "failed";
}

export function useReplacedSections(trackId: string) {
  return useQuery({
    queryKey: ["replaced-sections", trackId],
    queryFn: async () => {
      // Query generation_tasks for replace_section mode
      const { data: tasks, error: tasksError } = await supabase
        .from("generation_tasks")
        .select(
          `
          id,
          suno_task_id,
          status,
          prompt,
          created_at,
          completed_at,
          audio_clips
        `,
        )
        .eq("track_id", trackId)
        .eq("generation_mode", "replace_section")
        .order("created_at", { ascending: false });

      if (tasksError) throw tasksError;

      // Query started logs for timing metadata
      const { data: startedLogs, error: startedLogsError } = await supabase
        .from("track_change_log")
        .select("id, created_at, metadata")
        .eq("track_id", trackId)
        .eq("change_type", "replace_section_started")
        .order("created_at", { ascending: false });

      if (startedLogsError) throw startedLogsError;

      // Query completed logs for version audio URLs
      const { data: completedLogs, error: completedLogsError } = await supabase
        .from("track_change_log")
        .select(
          `
          id,
          metadata,
          version_id,
          track_versions (
            audio_url
          )
        `,
        )
        .eq("track_id", trackId)
        .eq("change_type", "replace_section_completed")
        .order("created_at", { ascending: false });

      if (completedLogsError) throw completedLogsError;

      const sections: ReplacedSection[] = [];

      // Match tasks with their log entries for full metadata
      for (const task of tasks || []) {
        // Find matching started log entry for timing
        const matchingStartLog = startedLogs?.find((log) => {
          const metadata = log.metadata as { taskId?: string } | null;
          return metadata?.taskId === task.suno_task_id;
        });

        const startMetadata = matchingStartLog?.metadata as {
          infillStartS?: number;
          infillEndS?: number;
        } | null;

        if (startMetadata?.infillStartS !== undefined && startMetadata?.infillEndS !== undefined) {
          // Get audio URLs from completed log or clips
          let audioUrl: string | undefined;
          let audioUrlB: string | undefined;

          // First try to get from completed log's version
          const matchingCompletedLog = completedLogs?.find((log) => {
            const metadata = log.metadata as { taskId?: string } | null;
            return metadata?.taskId === task.suno_task_id;
          });

          audioUrl = (matchingCompletedLog?.track_versions as { audio_url?: string } | null)?.audio_url;

          // Always check audio_clips for both variants (Suno returns 2 clips)
          if (task.status === "completed" && task.audio_clips) {
            try {
              const clips = typeof task.audio_clips === "string" ? JSON.parse(task.audio_clips) : task.audio_clips;
              // First variant
              if (!audioUrl) {
                audioUrl = clips?.[0]?.source_audio_url || clips?.[0]?.audio_url;
              }
              // Second variant
              audioUrlB = clips?.[1]?.source_audio_url || clips?.[1]?.audio_url;
            } catch {}
          }

          sections.push({
            start: startMetadata.infillStartS,
            end: startMetadata.infillEndS,
            taskId: task.id,
            createdAt: task.created_at || "",
            audioUrl,
            audioUrlB,
            status: task.status as ReplacedSection["status"],
          });
        }
      }

      return sections;
    },
    enabled: !!trackId,
    staleTime: 30000,
    refetchInterval: (query) => {
      // Refetch more often if there are pending tasks
      const data = query.state.data;
      if (data?.some((s) => s.status === "pending" || s.status === "processing")) {
        return 5000;
      }
      return false;
    },
  });
}

