/**
 * Studio Activity Logger Hook
 * Logs user actions in studio for analytics and debugging
 */

import { useCallback, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { logger } from "@/lib/logger";

export type StudioAction =
  | "studio_open"
  | "studio_close"
  | "play"
  | "pause"
  | "seek"
  | "section_select"
  | "section_preview"
  | "replacement_start"
  | "replacement_complete"
  | "replacement_apply"
  | "replacement_discard"
  | "version_switch"
  | "version_compare"
  | "stem_mute"
  | "stem_solo"
  | "stem_volume"
  | "stem_separate_start"
  | "stem_separate_complete"
  | "export_start"
  | "export_complete"
  | "trim_start"
  | "trim_complete"
  | "remix_start"
  | "extend_start";

interface ActivityMetadata {
  trackId?: string;
  versionId?: string;
  sectionStart?: number;
  sectionEnd?: number;
  stemType?: string;
  value?: number | string | boolean;
  [key: string]: unknown;
}

// Important actions that should be logged to track_change_log
const IMPORTANT_ACTIONS = [
  "replacement_apply",
  "replacement_discard",
  "version_switch",
  "stem_separate_complete",
  "export_complete",
  "trim_complete",
];

export function useStudioActivityLogger(trackId: string) {
  const sessionIdRef = useRef<string | null>(null);
  const sessionStartRef = useRef<number>(Date.now());

  const getSessionId = useCallback(() => {
    if (!sessionIdRef.current) {
      sessionIdRef.current = `studio_${trackId}_${Date.now()}`;
      sessionStartRef.current = Date.now();
    }
    return sessionIdRef.current;
  }, [trackId]);

  const logActivity = useCallback(
    async (action: StudioAction, metadata?: ActivityMetadata) => {
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) return;

        const sessionId = getSessionId();
        const sessionDuration = Date.now() - sessionStartRef.current;

        // Log to track_change_log for important actions
        if (IMPORTANT_ACTIONS.includes(action)) {
          await supabase.from("track_change_log").insert({
            track_id: trackId,
            change_type: action,
            changed_by: "user",
            user_id: user.id,
            new_value: JSON.stringify(metadata || {}),
            version_id: metadata?.versionId,
          });
        }

        // Log to console in development
        logger.debug(`[Studio Activity] ${action}`, {
          trackId,
          sessionId,
          sessionDuration,
          ...metadata,
        });
      } catch (error) {
        logger.error("Failed to log studio activity", error);
      }
    },
    [trackId, getSessionId],
  );

  // Convenience methods
  const logPlay = useCallback(() => logActivity("play"), [logActivity]);
  const logPause = useCallback(() => logActivity("pause"), [logActivity]);
  const logSeek = useCallback((time: number) => logActivity("seek", { value: time }), [logActivity]);

  const logSectionSelect = useCallback(
    (start: number, end: number) => logActivity("section_select", { sectionStart: start, sectionEnd: end }),
    [logActivity],
  );

  const logReplacementStart = useCallback(
    (start: number, end: number) => logActivity("replacement_start", { sectionStart: start, sectionEnd: end }),
    [logActivity],
  );

  const logReplacementApply = useCallback(
    (versionId: string) => logActivity("replacement_apply", { versionId }),
    [logActivity],
  );

  const logReplacementDiscard = useCallback(() => logActivity("replacement_discard"), [logActivity]);

  const logVersionSwitch = useCallback(
    (versionId: string) => logActivity("version_switch", { versionId }),
    [logActivity],
  );

  const logStemAction = useCallback(
    (stemType: string, action: "mute" | "solo" | "volume", value?: number) =>
      logActivity(`stem_${action}`, { stemType, value }),
    [logActivity],
  );

  return {
    logActivity,
    logPlay,
    logPause,
    logSeek,
    logSectionSelect,
    logReplacementStart,
    logReplacementApply,
    logReplacementDiscard,
    logVersionSwitch,
    logStemAction,
  };
}

/**
 * useStudioData - Consolidated studio data fetching
 *
 * Combines stems, transcriptions, and waveform prefetching
 * in a single optimized hook to reduce DB queries
 */

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useEffect, useMemo, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { waveformWorkerPool } from "@/lib/waveformWorkerPool";
import { logger } from "@/lib/logger";
import type { TranscriptionNote } from "@/hooks/useStemTranscription";

export interface TrackStem {
  id: string;
  track_id: string;
  stem_type: string;
  audio_url: string;
  separation_mode: string | null;
  version_id: string | null;
  source?: "separated" | "generated" | "uploaded" | string | null;
  generation_prompt?: string | null;
  generation_model?: string | null;
  created_at: string | null;
}

export interface StemTranscription {
  id: string;
  stem_id: string;
  track_id: string;
  user_id: string;
  midi_url: string | null;
  midi_quant_url: string | null;
  mxml_url: string | null;
  gp5_url: string | null;
  pdf_url: string | null;
  model: string;
  notes: TranscriptionNote[] | null;
  notes_count: number | null;
  bpm: number | null;
  key_detected: string | null;
  time_signature: string | null;
  duration_seconds: number | null;
  klangio_log_id: string | null;
  created_at: string;
  updated_at: string;
}

export interface StudioData {
  stems: TrackStem[];
  transcriptions: StemTranscription[];
  transcriptionsByStem: Record<string, StemTranscription>;
}

/**
 * Fetch all studio data in parallel with single queries
 */
export function useStudioData(trackId: string | undefined) {
  const queryClient = useQueryClient();
  const prefetchedRef = useRef(false);

  const query = useQuery({
    queryKey: ["studio-data", trackId],
    queryFn: async (): Promise<StudioData> => {
      if (!trackId) {
        return { stems: [], transcriptions: [], transcriptionsByStem: {} };
      }

      // Fetch stems and transcriptions in parallel
      const [stemsResult, transcriptionsResult] = await Promise.all([
        supabase.from("track_stems").select("*").eq("track_id", trackId).order("created_at", { ascending: false }),
        supabase
          .from("stem_transcriptions")
          .select("*")
          .eq("track_id", trackId)
          .order("created_at", { ascending: false }),
      ]);

      if (stemsResult.error) throw stemsResult.error;
      if (transcriptionsResult.error) throw transcriptionsResult.error;

      const stems = (stemsResult.data || []) as TrackStem[];
      const transcriptions = (transcriptionsResult.data || []) as StemTranscription[];

      // Group transcriptions by stem_id (latest only)
      const transcriptionsByStem: Record<string, StemTranscription> = {};
      transcriptions.forEach((t) => {
        if (!transcriptionsByStem[t.stem_id]) {
          transcriptionsByStem[t.stem_id] = t;
        }
      });

      logger.debug("Studio data loaded", {
        trackId,
        stemsCount: stems.length,
        transcriptionsCount: transcriptions.length,
        stemIds: stems.map((s) => s.id),
        transcriptionStemIds: Object.keys(transcriptionsByStem),
      });

      return { stems, transcriptions, transcriptionsByStem };
    },
    enabled: !!trackId,
    staleTime: 30000, // 30 seconds
    gcTime: 5 * 60 * 1000, // 5 minutes
  });

  // Prefetch waveforms for all stems
  useEffect(() => {
    if (!query.data?.stems || prefetchedRef.current) return;

    const audioUrls = query.data.stems.map((s) => s.audio_url).filter(Boolean);

    if (audioUrls.length > 0) {
      prefetchedRef.current = true;

      // Prefetch waveforms in background
      waveformWorkerPool.prefetchMany(audioUrls).catch((error) => {
        logger.warn("Waveform prefetch failed", { error });
      });
    }
  }, [query.data?.stems]);

  // Reset prefetch flag when track changes
  useEffect(() => {
    prefetchedRef.current = false;
  }, [trackId]);

  // Memoized stems sorted by priority - VOCALS ALWAYS FIRST
  const sortedStems = useMemo(() => {
    if (!query.data?.stems) return [];

    const priority: Record<string, number> = {
      // Vocals always first (priority 0-1)
      vocals: 0,
      vocal: 0,
      voice: 0,
      lead_vocal: 0,
      main_vocal: 0,
      backing_vocals: 1,
      backing_vocal: 1,
      harmonies: 1,
      // Instrumental next
      instrumental: 2,
      // Then by instrument
      bass: 3,
      drums: 4,
      guitar: 5,
      piano: 6,
      keyboard: 6,
      synth: 7,
      strings: 8,
      other: 99,
    };

    return [...query.data.stems].sort((a, b) => {
      const typeA = a.stem_type.toLowerCase();
      const typeB = b.stem_type.toLowerCase();

      // Check if either contains 'vocal' anywhere in the name
      const isVocalA = typeA.includes("vocal") || typeA === "voice";
      const isVocalB = typeB.includes("vocal") || typeB === "voice";

      // Vocals always come first
      if (isVocalA && !isVocalB) return -1;
      if (!isVocalA && isVocalB) return 1;

      // Then sort by priority
      const pA = priority[typeA] ?? 50;
      const pB = priority[typeB] ?? 50;
      return pA - pB;
    });
  }, [query.data?.stems]);

  return {
    ...query,
    stems: query.data?.stems || [],
    sortedStems,
    transcriptions: query.data?.transcriptions || [],
    transcriptionsByStem: query.data?.transcriptionsByStem || {},
    stemsLoading: query.isLoading,
    transcriptionsLoading: query.isLoading,
  };
}

/**
 * useStudioPerformance - Performance monitoring and optimization for studio
 * Tracks memory usage, render counts, and provides optimization utilities
 */

import { useEffect, useRef, useCallback, useMemo, useState } from "react";
import { logger } from "@/lib/logger";

interface PerformanceMetrics {
  renderCount: number;
  lastRenderTime: number;
  averageRenderTime: number;
  memoryUsageMB: number | null;
}

interface UseStudioPerformanceResult {
  metrics: PerformanceMetrics;
  trackRender: () => void;
  logMetrics: () => void;
  isMemoryWarning: boolean;
}

const MEMORY_WARNING_THRESHOLD_MB = 150;
const MAX_RENDER_SAMPLES = 10;

export function useStudioPerformance(componentName: string): UseStudioPerformanceResult {
  const renderCount = useRef(0);
  const renderTimes = useRef<number[]>([]);
  const lastRenderStart = useRef<number>(0);

  // Track render start
  const trackRender = useCallback(() => {
    lastRenderStart.current = performance.now();
  }, []);

  // Measure render completion — only when trackRender() was called
  const [renderCountState, setRenderCountState] = useState(0);

  useEffect(() => {
    if (lastRenderStart.current > 0) {
      const renderTime = performance.now() - lastRenderStart.current;
      renderTimes.current.push(renderTime);
      lastRenderStart.current = 0;

      if (renderTimes.current.length > MAX_RENDER_SAMPLES) {
        renderTimes.current.shift();
      }

      renderCount.current++;
      setRenderCountState(renderCount.current);
    }
  });

  // Get memory usage (when available)
  const getMemoryUsage = useCallback((): number | null => {
    if ("memory" in performance) {
      const memory = (performance as unknown as { memory?: { usedJSHeapSize?: number } }).memory;
      if (memory?.usedJSHeapSize) {
        return Math.round(memory.usedJSHeapSize / (1024 * 1024));
      }
    }
    return null;
  }, []);

  const averageRenderTime = useMemo(() => {
    if (renderTimes.current.length === 0) return 0;
    const sum = renderTimes.current.reduce((a, b) => a + b, 0);
    return sum / renderTimes.current.length;
  }, [renderCountState]);

  const memoryUsageMB = getMemoryUsage();
  const isMemoryWarning = memoryUsageMB !== null && memoryUsageMB > MEMORY_WARNING_THRESHOLD_MB;

  // Log warning if memory is high
  useEffect(() => {
    if (isMemoryWarning) {
      logger.warn(`[${componentName}] High memory usage: ${memoryUsageMB}MB`, {
        threshold: MEMORY_WARNING_THRESHOLD_MB,
      });
    }
  }, [isMemoryWarning, memoryUsageMB, componentName]);

  const logMetrics = useCallback(() => {
    logger.debug(`[${componentName}] Performance metrics`, {
      renderCount: renderCount.current,
      averageRenderTime: `${averageRenderTime.toFixed(2)}ms`,
      memoryUsageMB,
    });
  }, [componentName, averageRenderTime, memoryUsageMB]);

  const metrics: PerformanceMetrics = {
    renderCount: renderCount.current,
    lastRenderTime: renderTimes.current[renderTimes.current.length - 1] || 0,
    averageRenderTime,
    memoryUsageMB,
  };

  return {
    metrics,
    trackRender,
    logMetrics,
    isMemoryWarning,
  };
}

/**
 * useThrottledCallback - Throttle a callback to prevent excessive calls
 */
export function useThrottledCallback<T extends (...args: unknown[]) => unknown>(
  callback: T,
  delay: number,
): (...args: Parameters<T>) => ReturnType<T> | undefined {
  const lastCall = useRef<number>(0);
  const timeoutId = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const lastResult = useRef<ReturnType<T> | undefined>(undefined);

  return useCallback(
    (...args: Parameters<T>) => {
      const now = Date.now();

      if (now - lastCall.current >= delay) {
        lastCall.current = now;
        lastResult.current = callback(...args) as ReturnType<T>;

        return lastResult.current;
      } else {
        // Schedule for later
        if (timeoutId.current) {
          clearTimeout(timeoutId.current);
        }
        timeoutId.current = setTimeout(
          () => {
            lastCall.current = Date.now();
            lastResult.current = callback(...args) as ReturnType<T>;
          },
          delay - (now - lastCall.current),
        );
        return undefined;
      }
    },
    [callback, delay],
  );
}

/**
 * useDeferredValue - Similar to React 18's useDeferredValue but with custom delay
 */
export function useCustomDeferredValue<T>(value: T, delay: number = 100): T {
  const deferredValue = useRef<T>(value);
  const timeoutId = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => {
    if (timeoutId.current) {
      clearTimeout(timeoutId.current);
    }

    timeoutId.current = setTimeout(() => {
      deferredValue.current = value;
    }, delay);

    return () => {
      if (timeoutId.current) {
        clearTimeout(timeoutId.current);
      }
    };
  }, [value, delay]);

  return deferredValue.current;
}

