import { useState, useMemo, useCallback } from "react";
import { Track } from "@/types/track";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";
import { useVideoGenerationStatus } from "@/hooks/useVideoGenerationStatus";
import { useTrackActions } from "@/hooks/useTrackActions";
import { useAudioUpscale } from "@/hooks/useAudioUpscale";
import { useTrackStems } from "@/hooks/useTrackStems";
import { useTrackVersions } from "@/hooks/useTrackVersions";
import { toast } from "sonner";
import { useNavigate } from "react-router";
import { triggerHapticFeedback } from "@/lib/mobile-utils";
import { ActionId } from "@/config/trackActionsConfig";
import { TrackActionState, isActionAvailable, isActionDisabled } from "@/lib/trackActionConditions";

interface UseTrackActionsStateProps {
  track: Track;
  onDelete?: () => void;
  onDownload?: () => void;
  onClose?: () => void;
  /**
   * Gate the initial fetch of stems / versions until the consumer actually
   * needs the data (e.g. menu or sheet is opened). Defaults to `true` for
   * backwards compatibility, but callers rendering the menu/sheet on every
   * track card should pass `false` until user interaction to avoid N+1
   * network storms on library load.
   */
  enabled?: boolean;
}

interface DialogStates {
  details: boolean;
  extend: boolean;
  cover: boolean;
  addToProject: boolean;
  share: boolean;
  addToPlaylist: boolean;
  deleteConfirm: boolean;
  deleteVersionSelect: boolean;
  rename: boolean;
  createArtist: boolean;
  addVocals: boolean;
  addInstrumental: boolean;
  mashup: boolean;
  remix: boolean;
}

export function useTrackActionsState({
  track,
  onDelete,
  onDownload,
  onClose,
  enabled = true,
}: UseTrackActionsStateProps) {
  const navigate = useNavigate();

  // Cached queries — deduped across menu/sheet, cached across re-opens.
  const stemsQuery = useTrackStems(enabled && track?.id ? track.id : "");
  const versionsQuery = useTrackVersions(enabled && track?.id ? track.id : undefined);

  const stems = useMemo(
    () => (stemsQuery.data || []).map((s) => ({ id: s.id, stem_type: s.stem_type, audio_url: s.audio_url })),
    [stemsQuery.data],
  );
  const stemCount = stems.length;
  const versions = versionsQuery.data || [];
  const versionCount = versions.length;

  const activeVersion = useMemo(() => {
    if (!versions.length) return null;
    const sorted = [...versions].sort((a, b) => (a.clip_index ?? 0) - (b.clip_index ?? 0));
    const active = track?.active_version_id
      ? sorted.find((v) => v.id === track.active_version_id) || sorted[0]
      : sorted[0];
    const meta = (active.metadata ?? {}) as { suno_id?: string };
    return {
      versionLabel: active.version_label || "A",
      audioUrl: active.audio_url || track?.audio_url || "",
      sunoId: meta.suno_id || track?.suno_id || undefined,
    };
  }, [versions, track?.active_version_id, track?.audio_url, track?.suno_id]);

  const [dialogs, setDialogs] = useState<DialogStates>({
    details: false,
    extend: false,
    cover: false,
    addToProject: false,
    share: false,
    addToPlaylist: false,
    deleteConfirm: false,
    deleteVersionSelect: false,
    rename: false,
    createArtist: false,
    addVocals: false,
    addInstrumental: false,
    mashup: false,
    remix: false,
  });

  // Hooks - lazy load video status only when needed
  const [shouldFetchVideoStatus, setShouldFetchVideoStatus] = useState(false);
  const videoStatus = useVideoGenerationStatus(shouldFetchVideoStatus ? track?.id : undefined);
  const { isGenerating: isVideoGenerating, hasVideo } = videoStatus;
  const {
    isProcessing,
    handleShare,
    handleSeparateVocals,
    handleTogglePublic,
    handleConvertToWav,
    handleGenerateCover,
    handleGenerateVideo,
    handleSendToTelegram,
  } = useTrackActions();
  const { upscale: upscaleAudio, isLoading: isUpscaling } = useAudioUpscale();
  const { addToQueue, queue } = usePlayerStore();

  const isLoadingActions = stemsQuery.isLoading || versionsQuery.isLoading;

  // Check for specific stem types
  const hasVocalStem = stems.some((s) => s.stem_type === "vocal" || s.stem_type === "vocals");
  const hasInstrumentalStem = stems.some((s) => s.stem_type === "instrumental");

  // Check if track is instrumental:
  // 1. Explicit is_instrumental flag from database
  // 2. has_vocals is explicitly false
  // 3. Style contains "instrumental"
  // 4. Has instrumental stem but no vocal stem
  const isInstrumentalTrack = !!(
    track.is_instrumental === true ||
    track.has_vocals === false ||
    track.style?.toLowerCase().includes("instrumental") ||
    (hasInstrumentalStem && !hasVocalStem)
  );

  // Action state for condition checks
  const actionState: TrackActionState = {
    stemCount,
    versionCount,
    hasVideo,
    isVideoGenerating,
    hasVocalStem,
    hasInstrumentalStem,
    isInstrumentalTrack,
  };

  // Dialog helpers
  // ВАЖНО: лист действий НЕ закрывается при открытии диалога.
  // Карточки треков живут в виртуализированном списке — закрытие листа
  // может размонтировать владельца состояния и диалог никогда не появится.
  // Диалог рендерится поверх листа, а при его закрытии лист снова виден.
  const openDialog = useCallback((key: keyof DialogStates) => {
    setDialogs((prev) => ({ ...prev, [key]: true }));
  }, []);

  const closeDialog = useCallback((key: keyof DialogStates) => {
    setDialogs((prev) => ({ ...prev, [key]: false }));
  }, []);

  // Action handlers
  const executeAction = useCallback(
    async (actionId: ActionId) => {
      if (!track) return;

      // Check if action is available
      if (!isActionAvailable(actionId, track, actionState)) {
        toast.error("Действие недоступно");
        return;
      }

      // Check if action is disabled
      if (isActionDisabled(actionId, track, actionState, isProcessing)) {
        return;
      }

      triggerHapticFeedback("light");

      switch (actionId) {
        // Info actions
        case "details":
          openDialog("details");
          break;
        case "toggle_public":
          await handleTogglePublic(track);
          onClose?.();
          break;
        case "rename":
          openDialog("rename");
          break;

        // Download actions
        case "download_mp3":
          onDownload?.();
          onClose?.();
          break;
        case "download_wav":
          await handleConvertToWav(track);
          onClose?.();
          break;
        case "download_stems":
          // Navigate to studio for stem download
          navigate(`/studio-v2/track/${track.id}`);
          onClose?.();
          break;

        // Share actions
        case "generate_video":
          await handleGenerateVideo(track);
          onClose?.();
          break;
        case "send_telegram":
          await handleSendToTelegram(track);
          onClose?.();
          break;
        case "copy_link":
          await handleShare(track);
          onClose?.();
          break;
        case "add_to_playlist":
          openDialog("addToPlaylist");
          break;
        case "add_to_project":
          openDialog("addToProject");
          break;

        // Studio actions
        case "open_studio":
          navigate(`/studio-v2/track/${track.id}`);
          onClose?.();
          break;
        case "replace_section":
          navigate(`/studio-v2/track/${track.id}?mode=replace`);
          onClose?.();
          break;
        case "stems_simple":
          if (await handleSeparateVocals(track, "simple", activeVersion?.sunoId)) {
            navigate(`/studio-v2/track/${track.id}?stems=pending`);
            onClose?.();
            return true;
          }
          return false;
        case "stems_detailed":
          if (await handleSeparateVocals(track, "detailed", activeVersion?.sunoId)) {
            navigate(`/studio-v2/track/${track.id}?stems=pending`);
            onClose?.();
            return true;
          }
          return false;
        case "transcribe_midi":
          navigate(`/studio-v2/track/${track.id}?mode=midi`);
          onClose?.();
          break;
        case "transcribe_notes":
          navigate(`/studio-v2/track/${track.id}?mode=notes`);
          onClose?.();
          break;

        // Create actions
        case "generate_cover":
          await handleGenerateCover(track);
          onClose?.();
          break;
        case "cover":
          openDialog("cover");
          break;
        case "extend":
          openDialog("extend");
          break;
        case "remix":
          // Открываем форму с параметрами активной версии вместо мгновенного запуска
          openDialog("remix");
          break;
        case "generate_similar":
          // Store track data in sessionStorage and navigate to generation
          sessionStorage.setItem(
            "similarTrackParams",
            JSON.stringify({
              style: track.style,
              prompt: track.prompt,
              tags: track.tags,
              title: track.title,
            }),
          );
          navigate("/?open=generate");
          onClose?.();
          break;
        case "create_artist_persona":
          openDialog("createArtist");
          break;
        case "add_vocals":
          openDialog("addVocals");
          break;
        case "add_instrumental":
          openDialog("addInstrumental");
          break;
        case "mashup":
          // Mashup needs at least one ready source track with audio_url.
          if (!track.audio_url) {
            toast.error("Mashup недоступен — у трека нет готового аудио");
            return;
          }
          openDialog("mashup");
          break;

        // Quality actions
        case "upscale_hd": {
          const upscaleUrl = activeVersion?.audioUrl || track.audio_url;
          if (upscaleUrl) {
            await upscaleAudio({ audioUrl: upscaleUrl, trackId: track.id });
          }
        }
          onClose?.();
          break;

        // Delete actions
        case "delete_version":
          openDialog("deleteVersionSelect");
          break;
        case "delete_all":
          openDialog("deleteConfirm");
          break;
      }
    },
    [
      track,
      actionState,
      isProcessing,
      navigate,
      onClose,
      onDownload,
      openDialog,
      handleSendToTelegram,
      handleSeparateVocals,
      handleGenerateCover,
      handleConvertToWav,
      handleGenerateVideo,
      activeVersion,
      handleTogglePublic,
      handleShare,
      upscaleAudio,
    ],
  );

  const enableVideoStatusFetch = useCallback(() => {
    setShouldFetchVideoStatus((prev) => prev || true);
  }, []);

  const handleConfirmDelete = useCallback(() => {
    triggerHapticFeedback("success");
    onDelete?.();
    closeDialog("deleteConfirm");
  }, [onDelete, closeDialog]);

  return {
    // State
    stemCount,
    versionCount,
    activeVersion,
    actionState,
    isProcessing,
    isLoadingActions,
    stems,

    // Dialogs
    dialogs,
    openDialog,
    closeDialog,

    // Actions
    executeAction,
    handleConfirmDelete,

    // Video status loader (stable identity — consumers use it inside effects)
    enableVideoStatusFetch,

    // Helpers
    isActionAvailable: (actionId: ActionId) => isActionAvailable(actionId, track, actionState),
    isActionDisabled: (actionId: ActionId) => isActionDisabled(actionId, track, actionState, isProcessing),
  };
}

/**
 * Batch Track Counts Hook
 *
 * Fetches version and stem counts for multiple tracks in a single query
 * and subscribes to realtime updates via a single channel.
 * This replaces individual subscriptions per TrackCard to prevent memory leaks.
 */

import { useState, useEffect, useCallback, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { logger } from "@/lib/logger";

const log = logger.child({ module: "TrackCounts" });

export interface TrackCounts {
  versionCount: number;
  stemCount: number;
}

export type TrackCountsMap = Record<string, TrackCounts>;

export function useTrackCounts(trackIds: string[]) {
  const [countsMap, setCountsMap] = useState<TrackCountsMap>({});
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);
  const trackIdsRef = useRef<string[]>([]);

  // Fetch counts for all tracks in batch
  const fetchCounts = useCallback(async (ids: string[]) => {
    if (ids.length === 0) return;

    try {
      // Batch fetch version counts
      const { data: versions } = await supabase.from("track_versions").select("track_id").in("track_id", ids);

      // Batch fetch stem counts
      const { data: stems } = await supabase.from("track_stems").select("track_id").in("track_id", ids);

      // Aggregate counts by track_id
      const newCounts: TrackCountsMap = {};

      ids.forEach((id) => {
        newCounts[id] = {
          versionCount: versions?.filter((v) => v.track_id === id).length || 0,
          stemCount: stems?.filter((s) => s.track_id === id).length || 0,
        };
      });

      setCountsMap((prev) => ({ ...prev, ...newCounts }));
    } catch (error) {
      log.error("Error fetching track counts", { error });
    }
  }, []);

  // Setup realtime subscription for stems and versions
  useEffect(() => {
    if (trackIds.length === 0) return;

    // Only re-subscribe if track IDs changed significantly
    const idsChanged =
      trackIds.length !== trackIdsRef.current.length || trackIds.some((id) => !trackIdsRef.current.includes(id));

    if (!idsChanged && channelRef.current) return;

    trackIdsRef.current = trackIds;

    // Initial fetch
    fetchCounts(trackIds);

    // Cleanup previous channel
    if (channelRef.current) {
      supabase.removeChannel(channelRef.current);
    }

    // Create single channel for all track updates
    const channel = supabase
      .channel("track-counts-updates")
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "track_stems",
        },
        (payload) => {
          const trackId = payload.new.track_id;
          if (trackIds.includes(trackId)) {
            log.info("New stem added for track", { trackId });
            setCountsMap((prev) => ({
              ...prev,
              [trackId]: {
                ...prev[trackId],
                stemCount: (prev[trackId]?.stemCount || 0) + 1,
              },
            }));
            toast.success("Стемы готовы! 🎵");
          }
        },
      )
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "track_versions",
        },
        (payload) => {
          const trackId = payload.new.track_id;
          if (trackIds.includes(trackId)) {
            log.info("New version added for track", { trackId });
            setCountsMap((prev) => ({
              ...prev,
              [trackId]: {
                ...prev[trackId],
                versionCount: (prev[trackId]?.versionCount || 0) + 1,
              },
            }));
          }
        },
      )
      .subscribe();

    channelRef.current = channel;

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [trackIds.join(","), fetchCounts]);

  // Get counts for a specific track
  const getCountsForTrack = useCallback(
    (trackId: string): TrackCounts => {
      return countsMap[trackId] || { versionCount: 0, stemCount: 0 };
    },
    [countsMap],
  );

  return {
    countsMap,
    getCountsForTrack,
    refetchCounts: () => fetchCounts(trackIds),
  };
}

/**
 * useTracks - Main hook for track operations
 * Uses service layer architecture
 */

import { useInfiniteQuery, useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "./useAuth";
import { toast } from "sonner";
import { useCallback, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import * as tracksService from "@/services/tracks.service";
import * as tracksApi from "@/api/tracks.api";
import { useGuestMode } from "@/contexts/GuestModeContext";
import { mockTracks as screenshotMockTracks } from "@/lib/screenshotMockData";

// Re-export Track type for convenience
export type { Track, TrackWithCreator, TrackSummary } from "@/types/track";
export type { EnrichedTrack } from "@/services/tracks.service";

const PAGE_SIZE = 12; // Optimized for faster initial load

export interface UseTracksParams {
  projectId?: string;
  searchQuery?: string;
  sortBy?: "recent" | "popular" | "liked";
  paginate?: boolean;
  pageSize?: number;
  statusFilter?: string[];
  tagFilter?: string; // Filter by specific tag
}

/**
 * Main tracks hook with optional pagination
 */
export function useTracks(params: UseTracksParams = {}) {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const { isScreenshotMode } = useGuestMode();
  const { paginate = false, projectId, searchQuery, sortBy, pageSize = PAGE_SIZE, statusFilter, tagFilter } = params;

  const queryKey = ["tracks", user?.id, projectId, searchQuery, sortBy, paginate, pageSize, statusFilter, tagFilter];

  const infiniteQuery = useInfiniteQuery({
    queryKey: [...queryKey, "infinite"],
    queryFn: async ({ pageParam }) => {
      if (!user?.id) return { tracks: [], totalCount: 0, hasMore: false };
      return tracksService.fetchTracksWithLikes(
        user.id,
        { projectId, searchQuery, sortBy, statusFilter, tagFilter },
        { page: pageParam, pageSize },
      );
    },
    getNextPageParam: (lastPage, allPages) => {
      if (!lastPage || !allPages) {
        return undefined;
      }
      if (typeof lastPage.hasMore === "undefined") {
        return undefined;
      }
      return lastPage.hasMore ? allPages.length : undefined;
    },
    enabled: !!user?.id && paginate === true && !isScreenshotMode,
    staleTime: 60 * 1000,
    gcTime: 15 * 60 * 1000,
    initialPageParam: 0,
    refetchOnWindowFocus: false,
    refetchOnMount: "always",
  });

  const simpleQuery = useQuery({
    queryKey: [...queryKey, "simple"],
    queryFn: async () => {
      if (!user?.id) return [];
      const result = await tracksService.fetchTracksWithLikes(user.id, {
        projectId,
        searchQuery,
        sortBy,
        statusFilter,
        tagFilter,
      });
      return result.tracks;
    },
    enabled: !!user?.id && paginate === false && !isScreenshotMode,
    staleTime: 60 * 1000,
    gcTime: 15 * 60 * 1000,
    refetchOnWindowFocus: false,
    refetchOnMount: "always",
  });

  useEffect(() => {
    if (!user?.id || isScreenshotMode) return;

    const channel = supabase
      .channel(`tracks_${user.id}_${Math.random().toString(36).slice(2)}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "tracks",
          filter: `user_id=eq.${user.id}`,
        },
        (payload) => {
          // Only invalidate on meaningful status transitions to avoid
          // re-fetching all tracks on every incremental update.
          const newStatus = (payload.new as Record<string, unknown>)?.status as string | undefined;
          const oldStatus = (payload.old as Record<string, unknown>)?.status as string | undefined;

          // Always invalidate for INSERT (new track) or DELETE
          // For UPDATE: only if transitioned to completed/failed
          if (
            payload.eventType === "INSERT" ||
            payload.eventType === "DELETE" ||
            newStatus === "completed" ||
            newStatus === "failed" ||
            (oldStatus === "pending" && newStatus === "processing") // first visible transition
          ) {
            queryClient.invalidateQueries({ queryKey: ["tracks", user.id] });
          }
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user?.id, queryClient]);

  // Delete mutation
  const deleteMutation = useMutation({
    mutationFn: tracksService.deleteTrackWithCleanup,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["tracks", user?.id] });
      toast.success("Трек удален");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Ошибка удаления");
    },
  });

  // Like mutation
  const likeMutation = useMutation({
    mutationFn: async ({ trackId, isLiked }: { trackId: string; isLiked: boolean }) => {
      if (!user?.id) throw new Error("Not authenticated");
      return tracksService.toggleLike(trackId, user.id, isLiked);
    },
    onSuccess: (_, { isLiked }) => {
      queryClient.invalidateQueries({ queryKey: ["tracks", user?.id] });
      toast.success(isLiked ? "Удалено из избранного" : "Добавлено в избранное");
    },
    onError: (error: Error) => {
      toast.error(error.message || "Ошибка");
    },
  });

  const logPlayMutation = useMutation({
    mutationFn: tracksService.logTrackPlay,
  });

  const downloadTrack = useCallback((params: { trackId: string; audioUrl: string; coverUrl?: string }) => {
    if (params.audioUrl) {
      window.open(params.audioUrl, "_blank");
    }
  }, []);

  const deleteTrack = useCallback((trackId: string) => deleteMutation.mutate(trackId), [deleteMutation]);
  const toggleLike = useCallback(
    (params: { trackId: string; isLiked: boolean }) => likeMutation.mutate(params),
    [likeMutation],
  );
  const logPlay = useCallback((trackId: string) => logPlayMutation.mutate(trackId), [logPlayMutation]);

  if (isScreenshotMode) {
    return {
      tracks: screenshotMockTracks as unknown as import("@/services/tracks.service").EnrichedTrack[],
      totalCount: screenshotMockTracks.length,
      isLoading: false,
      error: null,
      fetchNextPage: () => Promise.resolve(),
      hasNextPage: false,
      isFetchingNextPage: false,
      refetch: () => Promise.resolve(),
      deleteTrack: () => {},
      toggleLike: () => {},
      logPlay: () => {},
      downloadTrack: () => {},
      isDeleting: false,
      isTogglingLike: false,
    };
  }

  const tracks = paginate
    ? infiniteQuery.data?.pages.flatMap((page) => page.tracks) || []
    : (simpleQuery.data as tracksService.EnrichedTrack[]) || [];

  const totalCount = paginate ? infiniteQuery.data?.pages[0]?.totalCount || 0 : tracks.length;

  return {
    tracks,
    totalCount,
    isLoading: paginate ? infiniteQuery.isLoading : simpleQuery.isLoading,
    error: paginate ? infiniteQuery.error : simpleQuery.error,
    fetchNextPage: paginate ? infiniteQuery.fetchNextPage : () => Promise.resolve(),
    hasNextPage: paginate ? infiniteQuery.hasNextPage : false,
    isFetchingNextPage: paginate ? infiniteQuery.isFetchingNextPage : false,
    refetch: paginate ? infiniteQuery.refetch : simpleQuery.refetch,
    deleteTrack,
    toggleLike,
    logPlay,
    downloadTrack,
    isDeleting: deleteMutation.isPending,
    isTogglingLike: likeMutation.isPending,
  };
}

/**
 * Hook for fetching a single track
 */
export function useTrack(trackId: string | undefined) {
  return useQuery({
    queryKey: ["track", trackId],
    queryFn: () => tracksApi.fetchTrackById(trackId!),
    enabled: !!trackId,
    staleTime: 30000,
  });
}

/**
 * Hook for public tracks (homepage/discovery)
 */
export function usePublicTracks(pageSize = 20) {
  const { user } = useAuth();

  return useInfiniteQuery({
    queryKey: ["public-tracks", user?.id],
    queryFn: async ({ pageParam }) => {
      return tracksService.fetchPublicTracksWithCreators(user?.id ?? null, { page: pageParam, pageSize });
    },
    getNextPageParam: (lastPage, allPages) => {
      // Safely handle undefined or malformed data
      if (!lastPage || !allPages) {
        return undefined;
      }
      if (typeof lastPage.hasMore === "undefined") {
        return undefined;
      }
      return lastPage.hasMore ? allPages.length : undefined;
    },
    staleTime: 30000,
    initialPageParam: 0,
  });
}

/**
 * AI Response Parser - Reliable JSON extraction and validation
 */

import { logger } from "@/lib/logger";
import { FullAnalysisData, ProducerReviewData, QuickAction } from "@/components/lyrics-workspace/ai-agent/types";

export interface ParsedLyricsResponse {
  lyrics: string;
  title?: string;
  style?: string;
  emotionalCore?: {
    mainImage: string;
    journey: string;
  };
  punchlines?: Record<string, string>;
  changes?: string[];
  tagsSummary?: string[];
}

export interface ExpandedAnalysisData extends FullAnalysisData {
  narrative?: {
    start: string;
    conflict: string;
    climax: string;
    resolution: string;
  };
  technicalLyrics?: {
    figurativeDevices: string[];
    phonetics: string;
    wordChoice: string;
  };
  cultural?: {
    influences: string[];
    era: string;
    references: string[];
  };
  keyInsights?: string[];
  uniqueStrength?: string;
}

/**
 * Extract JSON from AI response, handling markdown code blocks and partial JSON
 */
export function extractJSON<T>(content: string): T | null {
  if (!content) return null;

  // Try to find JSON in various formats
  const patterns = [
    // Standard JSON object
    /\{[\s\S]*\}/,
    // JSON in markdown code block
    /```(?:json)?\s*(\{[\s\S]*?\})\s*```/,
    // JSON array
    /\[[\s\S]*\]/,
  ];

  for (const pattern of patterns) {
    const match = content.match(pattern);
    if (match) {
      const jsonStr = match[1] || match[0];
      try {
        // Clean common issues
        const cleaned = jsonStr
          .replace(/[\x00-\x1F\x7F]/g, "") // Remove control characters
          .replace(/,(\s*[}\]])/g, "$1") // Remove trailing commas
          .replace(/'/g, '"') // Replace single quotes
          .trim();

        return JSON.parse(cleaned) as T;
      } catch (e) {
        logger.debug("JSON parse attempt failed", { error: e instanceof Error ? e.message : String(e) });
        continue;
      }
    }
  }

  // Last resort: try to parse the entire content
  try {
    return JSON.parse(content) as T;
  } catch {
    logger.debug("Failed to extract JSON from content");
    return null;
  }
}

/**
 * Parse full analysis response with validation
 */
export function parseFullAnalysis(content: string): ExpandedAnalysisData | null {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Untyped JSON shape from LLM; we narrow field-by-field below
  const data = extractJSON<any>(content);
  if (!data) return null;

  // Validate and normalize required fields
  return {
    meaning: {
      theme: data.meaning?.theme || "Не определена",
      emotions: data.meaning?.emotions || [],
      issues: data.meaning?.issues || [],
      score: data.meaning?.score || 0,
    },
    rhythm: {
      pattern: data.rhythm?.pattern || "",
      issues: data.rhythm?.issues || [],
      score: data.rhythm?.score || 0,
    },
    rhymes: {
      scheme: data.rhymes?.scheme || "",
      weakRhymes: data.rhymes?.weakRhymes || [],
      score: data.rhymes?.score || 0,
    },
    structure: {
      tags: data.structure?.detected || data.structure?.tags || [],
      issues: data.structure?.issues || [],
      score: data.structure?.score || 0,
    },
    overallScore: data.overallScore || 0,
    recommendations: (data.recommendations || []).map((r: Record<string, unknown>) => ({
      type: (r.type as string) || "general",
      text: (r.text as string) || "",
      priority: (r.priority as string) || "medium",
    })),
    quickActions: data.quickActions || [],
    // Extended fields
    narrative: data.meaning?.narrative || data.narrative,
    technicalLyrics: data.technicalLyrics,
    cultural: data.cultural,
    keyInsights: data.keyInsights || [],
    uniqueStrength: data.uniqueStrength || "",
  };
}

/**
 * Parse producer review response with validation
 */
export function parseProducerReview(content: string): ProducerReviewData | null {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Untyped JSON shape from LLM; we narrow field-by-field below
  const data = extractJSON<any>(content);
  if (!data) return null;

  return {
    commercialScore: data.commercialScore || data.overallScore || 0,
    overallScore: data.commercialScore || data.overallScore || 0,
    summary: data.summary || "",
    strengths: data.strengths || [],
    weaknesses: data.weaknesses || [],
    productionNotes: data.productionNotes || "",
    hooks: data.hooks
      ? {
          current: data.hooks.current || "",
          suggestions: data.hooks.suggestions || [],
        }
      : undefined,
    vocalMap: data.vocalMap || [],
    arrangement: data.arrangement
      ? {
          add: data.arrangement.add || [],
          remove: data.arrangement.remove || [],
          dynamics: data.arrangement.dynamics || [],
        }
      : undefined,
    stylePrompt: data.stylePrompt || "",
    suggestedTags: data.suggestedTags || [],
    genreTags: data.genreTags || [],
    topRecommendations: data.topRecommendations || [],
    recommendations:
      data.recommendations ||
      data.topRecommendations?.map((r: Record<string, unknown>, i: number) => ({
        priority: (r.priority as number) || i + 1,
        text: (r.text as string) || "",
      })) ||
      [],
    quickActions: data.quickActions || [],
  };
}

/**
 * Parse lyrics generation response
 */
export function parseLyricsResponse(content: string): ParsedLyricsResponse | null {
  // First try to extract JSON
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Untyped JSON shape from LLM; we narrow field-by-field below
  const data = extractJSON<any>(content);

  if (data?.lyrics) {
    return {
      lyrics: data.lyrics,
      title: data.title,
      style: data.style,
      emotionalCore: data.emotionalCore,
      punchlines: data.punchlines,
      changes: data.changes,
      tagsSummary: data.tagsSummary,
    };
  }

  // If no JSON found, check if content is raw lyrics
  if (content.includes("[Verse") || content.includes("[Chorus") || content.includes("[Intro")) {
    return {
      lyrics: content,
    };
  }

  return null;
}

/**
 * Universal AI response parser based on action type
 */
export function parseAIResponse(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Universal parser accepts heterogeneous LLM payloads
  data: any,
  action: string,

): {
  type: string;
  message: string;
  lyrics?: string;

  data?: unknown;
  expandedAnalysis?: ExpandedAnalysisData;
  keyInsights?: string[];
  uniqueStrength?: string;
} {
  // If data is already structured (from edge function), use it directly
  if (data && typeof data === "object") {
    // Handle deep_analysis
    if (action === "deep_analysis" || data.expandedAnalysis) {
      const expandedAnalysis = data.expandedAnalysis || data.fullAnalysis || data;
      return {
        type: "expanded_analysis",
        message: data.message || "Глубокий анализ завершен",
        expandedAnalysis: expandedAnalysis,
        keyInsights: expandedAnalysis?.keyInsights || data.keyInsights,
        uniqueStrength: expandedAnalysis?.uniqueStrength || data.uniqueStrength,
      };
    }

    // Handle full_analysis
    if (action === "full_analysis" || data.fullAnalysis) {
      return {
        type: "full_analysis",
        message: data.message || "Анализ завершен",
        data: data.fullAnalysis || data,
      };
    }

    // Handle producer_review
    if (action === "producer_review" || data.producerReview) {
      return {
        type: "producer_review",
        message: data.message || "Разбор продюсера готов",
        data: data.producerReview || data,
      };
    }

    // Handle lyrics
    if (data.lyrics) {
      return {
        type: "lyrics",
        message: data.message || "Текст сгенерирован",
        lyrics: data.lyrics,
      };
    }

    // Default: return as-is
    return {
      type: "text",
      message: data.message || data.result || "Готово",
      data: data,
    };
  }

  // If data is string, try to parse
  if (typeof data === "string") {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Recursive parse of LLM-provided string content; shape unknown
    const parsed = extractJSON<any>(data);
    if (parsed) {
      return parseAIResponse(parsed, action);
    }
    return {
      type: "text",
      message: data,
    };
  }

  return {
    type: "text",
    message: "Ответ получен",
  };
}

/**
 * Parse chat response which can contain multiple data types
 */
export function parseChatResponse(content: string): {
  message: string;
  lyrics?: string;
  title?: string;
  style?: string;
  tags?: string[];
  suggestions?: Array<{ label: string; value: string; action?: string }>;
  quickActions?: QuickAction[];
  stylePrompt?: string;
  changes?: string[];
} {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Untyped JSON shape from chat LLM; we narrow field-by-field below
  const data = extractJSON<any>(content);

  if (data) {
    return {
      message: data.response || data.message || "",
      lyrics: data.lyrics,
      title: data.title,
      style: data.style,
      tags: data.tags,
      suggestions: data.suggestions,
      quickActions: data.quickActions,
      stylePrompt: data.stylePrompt,
      changes: data.changes,
    };
  }

  // Return raw content as message
  return {
    message: content,
  };
}

/**
 * Validate that required analysis sections are present
 */
export function validateAnalysis(data: ExpandedAnalysisData): { valid: boolean; missing: string[] } {
  const missing: string[] = [];

  if (!data.meaning?.theme) missing.push("meaning.theme");
  if (!data.overallScore) missing.push("overallScore");
  if (typeof data.meaning?.score !== "number") missing.push("meaning.score");
  if (typeof data.rhythm?.score !== "number") missing.push("rhythm.score");
  if (typeof data.rhymes?.score !== "number") missing.push("rhymes.score");
  if (typeof data.structure?.score !== "number") missing.push("structure.score");

  return {
    valid: missing.length === 0,
    missing,
  };
}

/**
 * Get fallback analysis data when parsing fails
 */
export function getFallbackAnalysis(rawContent: string): ExpandedAnalysisData {
  return {
    meaning: {
      theme: "Анализ не распознан",
      emotions: [],
      issues: ["Не удалось выполнить структурный анализ"],
      score: 0,
    },
    rhythm: {
      pattern: "Не определён",
      issues: [],
      score: 0,
    },
    rhymes: {
      scheme: "Не определена",
      weakRhymes: [],
      score: 0,
    },
    structure: {
      tags: [],
      issues: [],
      score: 0,
    },
    overallScore: 0,
    recommendations: [
      {
        type: "general",
        text: rawContent.slice(0, 200) + "...",
        priority: "medium" as const,
      },
    ],
    quickActions: [],
    keyInsights: [],
    uniqueStrength: "",
  };
}

