/**
 * Lazy-loaded Recharts module
 *
 * This module provides a hook for dynamically importing Recharts
 * to reduce initial bundle size. Recharts is ~200KB and should
 * only be loaded when chart components are actually rendered.
 *
 * Usage:
 * ```tsx
 * import { useRecharts } from '@/lib/recharts-lazy';
 *
 * function MyChart() {
 *   const { recharts, isLoading } = useRecharts();
 *
 *   if (isLoading || !recharts) return <Skeleton />;
 *
 *   const { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer } = recharts;
 *   return (
 *     <ResponsiveContainer>
 *       <LineChart data={data}>
 *         <XAxis dataKey="name" />
 *         <YAxis />
 *         <Tooltip />
 *         <Line type="monotone" dataKey="value" />
 *       </LineChart>
 *     </ResponsiveContainer>
 *   );
 * }
 * ```
 */

import { useState, useEffect } from "react";

// Type for the recharts module
export type RechartsModule = typeof import("recharts");

// Cached module reference to avoid re-importing
let cachedModule: RechartsModule | null = null;
let loadingPromise: Promise<RechartsModule> | null = null;

/**
 * Hook to lazily load Recharts module
 * Returns { recharts, isLoading, error }
 */
export function useRecharts(): {
  recharts: RechartsModule | null;
  isLoading: boolean;
  error: Error | null;
} {
  const [recharts, setRecharts] = useState<RechartsModule | null>(cachedModule);
  const [isLoading, setIsLoading] = useState(!cachedModule);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    // Already cached
    if (cachedModule) {
      setRecharts(cachedModule);
      setIsLoading(false);
      return;
    }

    let mounted = true;

    const loadModule = async () => {
      try {
        // Reuse existing promise if already loading
        if (!loadingPromise) {
          loadingPromise = import("recharts");
        }

        const mod = await loadingPromise;
        cachedModule = mod;

        if (mounted) {
          setRecharts(mod);
          setIsLoading(false);
        }
      } catch (err) {
        if (mounted) {
          setError(err as Error);
          setIsLoading(false);
        }
      }
    };

    loadModule();

    return () => {
      mounted = false;
    };
  }, []);

  return { recharts, isLoading, error };
}

/**
 * Preload Recharts module (call on hover/focus of chart container)
 * Returns a promise that resolves when loaded
 */
export function preloadRecharts(): Promise<RechartsModule> {
  if (cachedModule) {
    return Promise.resolve(cachedModule);
  }

  if (!loadingPromise) {
    loadingPromise = import("recharts").then((mod) => {
      cachedModule = mod;
      return mod;
    });
  }

  return loadingPromise;
}

/**
 * Check if Recharts is already loaded
 */
export function isRechartsLoaded(): boolean {
  return cachedModule !== null;
}

import { createRoot } from "react-dom/client";
import "./i18n";
import App from "./App.tsx";
// Brand fonts (Space Grotesk for display, DM Sans for body)
import "@fontsource/space-grotesk/400.css";
import "@fontsource/space-grotesk/500.css";
import "@fontsource/space-grotesk/600.css";
import "@fontsource/space-grotesk/700.css";
import "@fontsource/dm-sans/400.css";
import "@fontsource/dm-sans/500.css";
import "@fontsource/dm-sans/600.css";
import "@fontsource/dm-sans/700.css";
import "./index.css";
// Feature 032-professional-ui: Design system CSS imports
import "./styles/typography.css";
import "./styles/colors.css";
import "./styles/spacing.css";
import "./styles/shadows.css";
import "./styles/animations.css";
// Feature 033-mobile-ui-improvements: Accessibility and shimmer styles
import "./styles/accessibility.css";
import "./styles/shimmer.css";
// Feature 036-mobile-perf-ux-redesign: Consolidated design tokens
import "./styles/tokens.css";
import { logger } from "./lib/logger";
import { initSentry, captureError } from "./lib/sentry";
import { getErrorScope } from "./lib/errorContext";
import { initTelemetry } from "./lib/telemetry";
import { migrateQueueFromPlayerStore } from "./lib/migration";
import { perfMark, perfMeasure } from "./lib/perfMarks";

perfMark("app:scriptStart");


// === CRITICAL: Early error logging for black screen debugging ===
const BOOT_LOG: string[] = [];
const bootLog = (msg: string) => {
  const timestamp = new Date().toISOString();
  const entry = `[${timestamp}] ${msg}`;
  BOOT_LOG.push(entry);
  if (import.meta.env.DEV) console.log(`[BOOT] ${entry}`);

  // Also save to sessionStorage for persistence
  try {
    sessionStorage.setItem("musicverse_boot_log", JSON.stringify(BOOT_LOG));
  } catch (e) {
    // Ignore storage errors
  }
};

bootLog("main.tsx: Script started");
bootLog(`Platform: ${navigator.userAgent}`);
bootLog(`URL: ${window.location.href}`);
bootLog(`Telegram WebApp available: ${!!window.Telegram?.WebApp}`);

// Expose boot log globally for debugging
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- Debug-only window augmentation for DevTools hooks
(window as any).__BOOT_LOG = BOOT_LOG;
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- Debug-only window augmentation for DevTools hooks
(window as any).__getBootLog = () => BOOT_LOG.join("\n");

// Initialize error tracking
try {
  initSentry();
  initTelemetry();
  bootLog("Sentry and Telemetry initialized");
} catch (e) {
  bootLog(`Init failed: ${e}`);
}

// Global error handlers to prevent app crashes
const mainLogger = logger.child({ module: "main" });

// Handle unhandled promise rejections
window.addEventListener("unhandledrejection", (event) => {
  const errorMsg =
    event.reason instanceof Error ? `${event.reason.name}: ${event.reason.message}` : String(event.reason);

  bootLog(`Unhandled rejection: ${errorMsg}`);

  // Ignore AbortError - these are expected during component cleanup
  if (event.reason?.name === "AbortError") {
    event.preventDefault();
    return;
  }

  const error = event.reason instanceof Error ? event.reason : new Error(String(event.reason));
  const scope = getErrorScope();
  mainLogger.error("Unhandled promise rejection", error, { ...scope });
  captureError(error, { type: "unhandledrejection", ...scope });
  event.preventDefault();
});

// Handle uncaught errors
window.addEventListener("error", (event) => {
  bootLog(`Uncaught error: ${event.message} at ${event.filename}:${event.lineno}`);

  const error = event.error instanceof Error ? event.error : new Error(event.message);
  const scope = getErrorScope();
  mainLogger.error("Uncaught error", error, {
    filename: event.filename,
    lineno: event.lineno,
    colno: event.colno,
    ...scope,
  });
  captureError(error, {
    type: "uncaughterror",
    filename: event.filename,
    lineno: event.lineno,
    ...scope,
  });
  event.preventDefault();
});

// Dynamic viewport height fix for mobile browsers
const setViewportHeight = () => {
  const vh = window.innerHeight * 0.01;
  document.documentElement.style.setProperty("--vh", `${vh}px`);
};

setViewportHeight();
window.addEventListener("resize", setViewportHeight);
window.addEventListener("orientationchange", () => {
  setTimeout(setViewportHeight, 100);
});

// iOS Keyboard height tracking via visualViewport API
// This allows CSS to respond to keyboard appearance
if ("visualViewport" in window && window.visualViewport) {
  const updateKeyboardHeight = () => {
    const keyboardHeight = window.innerHeight - window.visualViewport!.height;
    const safeKeyboardHeight = Math.max(0, keyboardHeight);
    document.documentElement.style.setProperty("--keyboard-height", `${safeKeyboardHeight}px`);

    // Add/remove class for keyboard-open state
    if (safeKeyboardHeight > 100) {
      document.body.classList.add("keyboard-open");
    } else {
      document.body.classList.remove("keyboard-open");
    }
  };

  window.visualViewport.addEventListener("resize", updateKeyboardHeight);
  window.visualViewport.addEventListener("scroll", updateKeyboardHeight);
  updateKeyboardHeight();
}

bootLog("Event listeners registered");

// Run data migrations before app render
try {
  migrateQueueFromPlayerStore();
  bootLog("Queue migration completed");
} catch (e) {
  bootLog(`Queue migration failed: ${e}`);
}

// Register Audio Service Worker for offline caching
if ("serviceWorker" in navigator) {
  // Register after initial render to not block app startup
  window.addEventListener("load", () => {
    navigator.serviceWorker
      .register("/audio-sw.js", { scope: "/" })
      .then((registration) => {
        bootLog(`Audio SW registered: ${registration.scope}`);
      })
      .catch((error) => {
        bootLog(`Audio SW registration failed: ${error}`);
      });
  });
}

// App entry point
try {
  bootLog("Creating React root...");
  const rootElement = document.getElementById("root");

  if (!rootElement) {
    bootLog("CRITICAL: Root element not found!");
    throw new Error("Root element not found");
  }

  bootLog("Root element found, rendering App...");
  const root = createRoot(rootElement);
  perfMark("app:beforeRender");
  perfMeasure("app: scriptStart → beforeRender", "app:scriptStart", "app:beforeRender");
  root.render(<App />);
  perfMark("app:renderCalled");
  bootLog("App render called");

  // Measure first paint / interactive frames after render.
  requestAnimationFrame(() => {
    perfMark("app:firstFrame");
    perfMeasure("app: scriptStart → firstFrame", "app:scriptStart", "app:firstFrame");
    requestAnimationFrame(() => {
      perfMark("app:secondFrame");
      perfMeasure("app: scriptStart → secondFrame", "app:scriptStart", "app:secondFrame");
    });
  });

  // When the browser is idle, log navigation + paint timings to logger.
  const logNavTimings = () => {
    try {
      const [nav] = performance.getEntriesByType("navigation") as PerformanceNavigationTiming[];
      const paints = performance.getEntriesByType("paint");
      const fcp = paints.find((p) => p.name === "first-contentful-paint");
      logger.info("[perf] navigation timings", {
        dom_content_loaded_ms: nav ? Math.round(nav.domContentLoadedEventEnd - nav.startTime) : null,
        load_event_ms: nav ? Math.round(nav.loadEventEnd - nav.startTime) : null,
        first_contentful_paint_ms: fcp ? Math.round(fcp.startTime) : null,
        transfer_size_bytes: nav?.transferSize ?? null,
      });
    } catch {
      /* noop */
    }
  };
  const ric = (window as unknown as { requestIdleCallback?: (cb: () => void) => void }).requestIdleCallback;
  if (typeof ric === "function") {
    ric(logNavTimings);
  } else {
    window.addEventListener("load", () => setTimeout(logNavTimings, 0));
  }


} catch (e) {
  bootLog(`CRITICAL: React render failed: ${e}`);
  captureError(e);

  // Show error on screen
  const root = document.getElementById("root");
  if (root) {
    root.innerHTML = `
      <div style="padding: 20px; color: red; font-family: monospace;">
        <h2>App failed to start</h2>
        <pre>${e}</pre>
        <h3>Boot Log:</h3>
        <pre>${BOOT_LOG.join("\n")}</pre>
      </div>
    `;
  }
}

/**
 * Album view page - displays a published project with its tracks
 */
import { useState } from "react";
import { useParams, useNavigate } from "react-router";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ArrowLeft, Music, Play, Pause, Share2, User, Calendar, Clock, Loader2 } from "@/lib/icons";
import { usePlayerStore } from "@/hooks/audio/usePlayerState";
import { useTelegramBackButton } from "@/hooks/telegram";
import { SEOHead } from "@/components/SEOHead";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { format, ru } from "@/lib/date-utils";
import { formatTime } from "@/lib/formatters";

interface AlbumTrack {
  id: string;
  title: string | null;
  audio_url: string | null;
  cover_url: string | null;
  duration_seconds: number | null;
  style: string | null;
  is_master: boolean | null;
  project_track_id: string | null;
}

interface Album {
  id: string;
  title: string;
  cover_url: string | null;
  description: string | null;
  concept: string | null;
  genre: string | null;
  mood: string | null;
  published_at: string | null;
  user_id: string;
  profiles: {
    username: string | null;
    display_name: string | null;
    photo_url: string | null;
  } | null;
}

export default function AlbumView() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { activeTrack, isPlaying, playTrack, pauseTrack } = usePlayerStore();
  const [playingAll, setPlayingAll] = useState(false);

  // Telegram BackButton - navigates back to library
  const { shouldShowUIButton: showUIBackButton } = useTelegramBackButton({
    visible: true,
    fallbackPath: "/",
  });

  // Fetch album data with profile separately (no FK relationship)
  const { data: album, isLoading: albumLoading } = useQuery({
    queryKey: ["album", id],
    queryFn: async () => {
      if (!id) throw new Error("No album ID");

      // Fetch project first
      const { data: project, error } = await supabase
        .from("music_projects")
        .select("id, title, cover_url, description, concept, genre, mood, published_at, user_id")
        .eq("id", id)
        .eq("is_public", true)
        .eq("status", "published")
        .single();

      if (error) throw error;
      if (!project) return null;

      // Fetch profile separately
      const { data: profile } = await supabase
        .from("profiles")
        .select("username, display_name, photo_url")
        .eq("user_id", project.user_id)
        .single();

      return {
        ...project,
        profiles: profile || null,
      } as Album;
    },
    enabled: !!id,
    staleTime: 1000 * 60 * 5,
  });

  // Fetch master tracks for this album
  const { data: tracks, isLoading: tracksLoading } = useQuery({
    queryKey: ["album-tracks", id],
    queryFn: async () => {
      if (!id) throw new Error("No album ID");
      const { data, error } = await supabase
        .from("tracks")
        .select("id, title, audio_url, cover_url, duration_seconds, style, is_master, project_track_id")
        .eq("project_id", id)
        .eq("is_master", true)
        .order("created_at", { ascending: true });

      if (error) throw error;
      return data as AlbumTrack[];
    },
    enabled: !!id,
    staleTime: 1000 * 60 * 5,
  });

  const handlePlayAll = () => {
    if (!tracks || tracks.length === 0) return;

    const firstTrack = tracks.find((t) => t.audio_url);
    if (firstTrack && firstTrack.audio_url) {
      playTrack({
        id: firstTrack.id,
        title: firstTrack.title || "Без названия",
        audio_url: firstTrack.audio_url,
        cover_url: firstTrack.cover_url || album?.cover_url || undefined,
        duration_seconds: firstTrack.duration_seconds,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any -- First-track shape from album join; player accepts a narrow subset
      } as any);
      setPlayingAll(true);
    }
  };

  const handlePlayTrack = (track: AlbumTrack) => {
    if (!track.audio_url) return;

    const isCurrentTrack = activeTrack?.id === track.id;

    if (isCurrentTrack && isPlaying) {
      pauseTrack();
    } else {
      playTrack({
        id: track.id,
        title: track.title || "Без названия",
        audio_url: track.audio_url,
        cover_url: track.cover_url || album?.cover_url,
        duration_seconds: track.duration_seconds,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Track shape from album join; player accepts a narrow subset
      } as any);
    }
  };

  const handleShare = async () => {
    const url = window.location.href;
    try {
      await navigator.share({
        title: album?.title,
        text: `Послушай альбом "${album?.title}" на MusicVerse`,
        url,
      });
    } catch {
      await navigator.clipboard.writeText(url);
      toast.success("Ссылка скопирована");
    }
  };

  const totalDuration = tracks?.reduce((acc, t) => acc + (t.duration_seconds || 0), 0) || 0;
  const creatorName = album?.profiles?.display_name || album?.profiles?.username || "Автор";

  if (albumLoading || tracksLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!album) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4">
        <Music className="w-16 h-16 text-muted-foreground mb-4" />
        <h2 className="text-xl font-semibold mb-2">Альбом не найден</h2>
        <Button variant="outline" onClick={() => navigate("/")}>
          <ArrowLeft className="w-4 h-4 mr-2" />
          На главную
        </Button>
      </div>
    );
  }

  const albumUrl = `https://aimusicverse.lovable.app/album/${album.id}`;
  const albumDescription =
    album.description ||
    album.concept ||
    `Альбом «${album.title || "Без названия"}» от ${creatorName} — ${tracks?.length || 0} треков на MusicVerse AI.`;

  return (
    <div className="pb-24">
      <SEOHead
        title={album.title || "Альбом"}
        description={albumDescription}
        canonical={albumUrl}
        ogType="music.album"
        ogImage={album.cover_url || undefined}
        jsonLd={{
          "@context": "https://schema.org",
          "@type": "MusicAlbum",
          name: album.title || "Альбом",
          description: albumDescription,
          url: albumUrl,
          image: album.cover_url || undefined,
          numTracks: tracks?.length || 0,
          genre: album.genre || undefined,
          byArtist: { "@type": "Person", name: creatorName },
        }}
      />
      {/* Hero Section */}
      <div className="relative">
        {/* Background blur */}
        <div
          className="absolute inset-0 h-64 bg-gradient-to-b from-primary/20 to-background"
          style={{
            backgroundImage: album.cover_url ? `url(${album.cover_url})` : undefined,
            backgroundSize: "cover",
            backgroundPosition: "center",
            filter: "blur(60px)",
            opacity: 0.5,
          }}
        />

        {/* Header */}
        <div
          className="relative sticky top-0 z-40 bg-background/80 backdrop-blur-md border-b border-border/30 px-4 py-3"
          style={{
            paddingTop:
              "max(calc(var(--tg-content-safe-area-inset-top, 0px) + 0.75rem), calc(env(safe-area-inset-top, 0px) + 0.75rem))",
          }}
        >
          <div className="flex items-center gap-3">
            {showUIBackButton && (
              <Button variant="ghost" size="icon" onClick={() => navigate(-1)}>
                <ArrowLeft className="w-5 h-5" />
              </Button>
            )}
            <span className="font-medium text-sm truncate flex-1">{album.title}</span>
            <Button variant="ghost" size="icon" onClick={handleShare}>
              <Share2 className="w-4 h-4" />
            </Button>
          </div>
        </div>

        {/* Album Info */}
        <div className="relative px-4 pt-6 pb-8">
          <div className="flex flex-col sm:flex-row gap-6 items-center sm:items-end">
            {/* Cover */}
            <div className="w-48 h-48 sm:w-56 sm:h-56 rounded-xl overflow-hidden shadow-2xl shrink-0 bg-secondary">
              {album.cover_url ? (
                <img
                  loading="lazy"
                  decoding="async"
                  src={album.cover_url}
                  alt={album.title}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center">
                  <Music className="w-16 h-16 text-muted-foreground/40" />
                </div>
              )}
            </div>

            {/* Info */}
            <div className="text-center sm:text-left space-y-3 flex-1">
              <Badge variant="secondary" className="text-xs">
                Альбом
              </Badge>
              <h1 className="text-2xl sm:text-3xl font-bold">{album.title}</h1>

              {/* Creator */}
              <div
                className="flex items-center gap-2 justify-center sm:justify-start cursor-pointer hover:opacity-80"
                onClick={() => navigate(`/profile/${album.user_id}`)}
              >
                {album.profiles?.photo_url ? (
                  <img
                    loading="lazy"
                    decoding="async"
                    src={album.profiles.photo_url}
                    alt={creatorName}
                    className="w-6 h-6 rounded-full object-cover"
                  />
                ) : (
                  <User className="w-5 h-5 text-muted-foreground" />
                )}
                <span className="font-medium">{creatorName}</span>
              </div>

              {/* Meta */}
              <div className="flex flex-wrap items-center gap-3 text-sm text-muted-foreground justify-center sm:justify-start">
                {album.genre && <Badge variant="outline">{album.genre}</Badge>}
                <span className="flex items-center gap-1">
                  <Music className="w-3.5 h-3.5" />
                  {tracks?.length || 0} треков
                </span>
                <span className="flex items-center gap-1">
                  <Clock className="w-3.5 h-3.5" />
                  {formatTime(totalDuration)}
                </span>
                {album.published_at && (
                  <span className="flex items-center gap-1">
                    <Calendar className="w-3.5 h-3.5" />
                    {format(new Date(album.published_at), "d MMM yyyy", { locale: ru })}
                  </span>
                )}
              </div>

              {album.description && <p className="text-sm text-muted-foreground line-clamp-2">{album.description}</p>}
            </div>
          </div>

          {/* Play All Button */}
          <div className="mt-6 flex justify-center sm:justify-start">
            <Button size="lg" onClick={handlePlayAll} disabled={!tracks || tracks.length === 0} className="gap-2 px-8">
              <Play className="w-5 h-5 fill-current" />
              Слушать альбом
            </Button>
          </div>
        </div>
      </div>

      {/* Track List */}
      <div className="px-4 space-y-1">
        {tracks?.map((track, index) => {
          const isCurrentTrack = activeTrack?.id === track.id;
          const isTrackPlaying = isCurrentTrack && isPlaying;

          return (
            <div
              key={track.id}
              onClick={() => handlePlayTrack(track)}
              className={cn(
                "flex items-center gap-3 p-3 rounded-lg cursor-pointer transition-colors",
                isCurrentTrack ? "bg-primary/10" : "hover:bg-secondary/50",
              )}
            >
              {/* Track number / Play indicator */}
              <div className="w-8 h-8 flex items-center justify-center shrink-0">
                {isTrackPlaying ? (
                  <Pause className="w-4 h-4 text-primary" />
                ) : isCurrentTrack ? (
                  <Play className="w-4 h-4 text-primary" />
                ) : (
                  <span className="text-sm text-muted-foreground">{index + 1}</span>
                )}
              </div>

              {/* Cover */}
              <div className="w-10 h-10 rounded-md overflow-hidden bg-secondary shrink-0">
                {track.cover_url ? (
                  <img
                    loading="lazy"
                    decoding="async"
                    src={track.cover_url}
                    alt=""
                    className="w-full h-full object-cover"
                  />
                ) : album.cover_url ? (
                  <img
                    loading="lazy"
                    decoding="async"
                    src={album.cover_url}
                    alt=""
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <Music className="w-4 h-4 text-muted-foreground/50" />
                  </div>
                )}
              </div>

              {/* Info */}
              <div className="flex-1 min-w-0">
                <p className={cn("font-medium text-sm truncate", isCurrentTrack && "text-primary")}>
                  {track.title || `Трек ${index + 1}`}
                </p>
                {track.style && <p className="text-xs text-muted-foreground truncate">{track.style}</p>}
              </div>

              {/* Duration */}
              <span className="text-xs text-muted-foreground shrink-0">
                {track.duration_seconds ? formatTime(track.duration_seconds) : "--:--"}
              </span>
            </div>
          );
        })}

        {(!tracks || tracks.length === 0) && (
          <div className="text-center py-12 text-muted-foreground">
            <Music className="w-12 h-12 mx-auto mb-3 opacity-50" />
            <p>Нет треков в альбоме</p>
          </div>
        )}
      </div>
    </div>
  );
}

