import { useState } from "react";
import { useParams, useNavigate } from "react-router";
import { useQuery } from "@tanstack/react-query";
import { motion } from "@/lib/motion";
import {
  Settings,
  Music2,
  FolderOpen,
  Users,
  ListMusic,
  ChevronLeft,
  Share2,
  Heart,
  Play,
  Crown,
  Instagram,
  Twitter,
  Youtube,
  Globe,
  ExternalLink,
} from "@/lib/icons";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { supabase } from "@/integrations/supabase/client";
import { getUserCredits } from "@/api/payments.api";
import { fetchTracks } from "@/api/tracks.api";
import { fetchPublicProfile } from "@/api/profiles.api";
import { useAuth } from "@/hooks/useAuth";
import { useTelegram } from "@/contexts/TelegramContext";
import { useTelegramBackButton } from "@/hooks/telegram";
import { UnifiedTrackCard } from "@/components/track/track-card-new";
import { FollowButton } from "@/components/social/FollowButton";
import { SEOHead } from "@/components/SEOHead";
import { cn } from "@/lib/utils";

interface PublicProfile {
  user_id: string;
  first_name: string;
  last_name: string | null;
  username: string | null;
  photo_url: string | null;
  display_name: string | null;
  bio: string | null;
  banner_url: string | null;
  social_links: {
    instagram?: string;
    twitter?: string;
    youtube?: string;
    spotify?: string;
    soundcloud?: string;
    website?: string;
  } | null;
  is_public: boolean;
  followers_count: number | null;
  following_count: number | null;
}

interface ProfileStats {
  tracksCount: number;
  likesReceived: number;
  projectsCount: number;
  playlistsCount: number;
  totalPlays: number;
}

export default function PublicProfilePage() {
  const { userId } = useParams<{ userId: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const { hapticFeedback } = useTelegram();
  const [activeTab, setActiveTab] = useState("tracks");
  const [showFullBio, setShowFullBio] = useState(false);

  const isOwner = user?.id === userId;

  // Telegram BackButton - navigates back to home
  const { shouldShowUIButton: showUIBackButton } = useTelegramBackButton({
    visible: true,
    fallbackPath: "/",
  });

  // Fetch profile
  const { data: profile, isLoading: profileLoading } = useQuery({
    queryKey: ["public-profile", userId],
    queryFn: async () => {
      if (!userId) return null;
      const { data, error } = await supabase
        .from("profiles")
        .select(
          "user_id, first_name, last_name, username, photo_url, display_name, bio, banner_url, social_links, is_public, followers_count, following_count",
        )
        .eq("user_id", userId)
        .maybeSingle();

      if (error) throw error;
      return data as PublicProfile | null;
    },
    enabled: !!userId,
  });

  // Fetch stats
  const { data: stats } = useQuery({
    queryKey: ["profile-stats", userId],
    queryFn: async () => {
      if (!userId) return null;
      const [tracksRes, projectsRes, playlistsRes, creditsRes, playsRes] = await Promise.all([
        supabase
          .from("tracks")
          .select("id", { count: "exact", head: true })
          .eq("user_id", userId)
          .eq("is_public", true),
        supabase
          .from("music_projects")
          .select("id", { count: "exact", head: true })
          .eq("user_id", userId)
          .eq("is_public", true),
        supabase
          .from("playlists")
          .select("id", { count: "exact", head: true })
          .eq("user_id", userId)
          .eq("is_public", true),
        getUserCredits(userId),
        fetchTracks({ userId, isPublic: true }),
      ]);

      const totalPlays = playsRes.data?.reduce((sum, t) => sum + (t.play_count || 0), 0) || 0;

      return {
        tracksCount: tracksRes.count || 0,
        likesReceived: creditsRes.data?.total_likes_received || 0,
        projectsCount: projectsRes.count || 0,
        playlistsCount: playlistsRes.count || 0,
        totalPlays,
      } as ProfileStats;
    },
    enabled: !!userId,
  });

  // Fetch public tracks
  const { data: tracks, isLoading: tracksLoading } = useQuery({
    queryKey: ["public-tracks", userId],
    queryFn: async () => {
      if (!userId) return [];
      const { data, error } = await fetchTracks(
        { userId, isPublic: true, statusFilter: ["completed"] },
        { page: 0, pageSize: 50 },
      );
      if (error) throw error;
      return data || [];
    },
    enabled: !!userId && activeTab === "tracks",
  });

  // Fetch public projects
  const { data: projects, isLoading: projectsLoading } = useQuery({
    queryKey: ["public-projects", userId],
    queryFn: async () => {
      if (!userId) return [];
      const { data, error } = await supabase
        .from("music_projects")
        .select("*")
        .eq("user_id", userId)
        .eq("is_public", true)
        .order("created_at", { ascending: false })
        .limit(20);

      if (error) throw error;
      return data || [];
    },
    enabled: !!userId && activeTab === "projects",
  });

  // Fetch public artists
  const { data: artists, isLoading: artistsLoading } = useQuery({
    queryKey: ["public-artists", userId],
    queryFn: async () => {
      if (!userId) return [];
      const { data, error } = await supabase
        .from("artists")
        .select("*")
        .eq("user_id", userId)
        .eq("is_public", true)
        .order("created_at", { ascending: false })
        .limit(20);

      if (error) throw error;
      return data || [];
    },
    enabled: !!userId && activeTab === "artists",
  });

  // Fetch public playlists
  const { data: playlists, isLoading: playlistsLoading } = useQuery({
    queryKey: ["public-playlists", userId],
    queryFn: async () => {
      if (!userId) return [];
      const { data, error } = await supabase
        .from("playlists")
        .select("*")
        .eq("user_id", userId)
        .eq("is_public", true)
        .order("created_at", { ascending: false })
        .limit(20);

      if (error) throw error;
      return data || [];
    },
    enabled: !!userId && activeTab === "playlists",
  });

  const handleShare = () => {
    hapticFeedback?.("light");
    if (navigator.share) {
      navigator.share({
        title: `${displayName} на MusicVerse`,
        url: window.location.href,
      });
    }
  };

  const displayName =
    profile?.display_name ||
    [profile?.first_name, profile?.last_name].filter(Boolean).join(" ") ||
    profile?.username ||
    "Пользователь";

  const socialLinks = profile?.social_links || {};

  if (profileLoading) {
    return (
      <div className="min-h-screen bg-background p-4">
        <div className="max-w-2xl mx-auto space-y-6">
          <Skeleton className="h-10 w-10 rounded-full" />
          <Skeleton className="h-32 w-full rounded-xl" />
          <div className="flex flex-col items-center gap-4">
            <Skeleton className="w-24 h-24 rounded-full" />
            <Skeleton className="h-6 w-32" />
            <Skeleton className="h-4 w-24" />
          </div>
        </div>
      </div>
    );
  }

  if (!profile) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center p-4">
        <div className="text-center">
          <h2 className="text-xl font-bold mb-2">Профиль не найден</h2>
          <p className="text-muted-foreground mb-4">Пользователь не существует или профиль скрыт</p>
          <Button onClick={() => navigate("/")}>На главную</Button>
        </div>
      </div>
    );
  }

  const profileUrl = `https://aimusicverse.lovable.app/profile/${userId}`;
  const profileDescription =
    profile.bio || `Профиль ${displayName} на MusicVerse AI — публичные треки, проекты и плейлисты.`;

  return (
    <div className="min-h-screen bg-background pb-24">
      <SEOHead
        title={displayName}
        description={profileDescription}
        canonical={profileUrl}
        ogType="article"
        ogImage={profile.photo_url || undefined}
        jsonLd={{
          "@context": "https://schema.org",
          "@type": "Person",
          name: displayName,
          description: profileDescription,
          url: profileUrl,
          image: profile.photo_url || undefined,
        }}
      />
      {/* Header */}
      <div
        className="sticky top-0 z-30 backdrop-blur-md bg-background/80 border-b border-border/50"
        style={{
          paddingTop:
            "max(calc(var(--tg-content-safe-area-inset-top, 0px) + 0.25rem), calc(env(safe-area-inset-top, 0px) + 0.25rem))",
        }}
      >
        <div className="flex items-center justify-between px-4 py-2">
          {showUIBackButton ? (
            <Button variant="ghost" size="icon" onClick={() => navigate(-1)}>
              <ChevronLeft className="w-5 h-5" />
            </Button>
          ) : (
            <div className="w-9" />
          )}
          <h1 className="font-semibold">Профиль</h1>
          <div className="flex items-center gap-1">
            <Button variant="ghost" size="icon" onClick={handleShare}>
              <Share2 className="w-5 h-5" />
            </Button>
            {isOwner && (
              <Button variant="ghost" size="icon" onClick={() => navigate("/settings")}>
                <Settings className="w-5 h-5" />
              </Button>
            )}
          </div>
        </div>
      </div>

      {/* Banner Section */}
      <div className="relative">
        {profile.banner_url ? (
          <div className="h-32 sm:h-48 overflow-hidden">
            <img
              loading="lazy"
              decoding="async"
              src={profile.banner_url}
              alt="Banner"
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-background via-background/50 to-transparent" />
          </div>
        ) : (
          <div className="h-32 sm:h-48 bg-gradient-to-br from-primary/30 via-primary/10 to-background relative overflow-hidden">
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_20%,rgba(var(--primary-rgb),0.15),transparent_50%)]" />
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_70%_60%,rgba(var(--primary-rgb),0.1),transparent_50%)]" />
          </div>
        )}

        {/* Avatar - overlapping banner */}
        <div className="absolute -bottom-12 left-1/2 -translate-x-1/2">
          <motion.div
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ delay: 0.1 }}
          >
            <Avatar className="w-24 h-24 sm:w-28 sm:h-28 border-4 border-background shadow-xl">
              <AvatarImage src={profile.photo_url || undefined} alt={displayName} />
              <AvatarFallback className="text-2xl bg-gradient-to-br from-primary/20 to-primary/5">
                {displayName[0]?.toUpperCase()}
