          </TabsTrigger>
        </TabsList>

        {/* Tracks Tab */}
        <TabsContent value="tracks" className="mt-4">
          {tracksLoading ? (
            <div className="space-y-2">
              {[...Array(6)].map((_, i) => (
                <Skeleton key={i} className="h-16 rounded-xl" />
              ))}
            </div>
          ) : tracks?.length ? (
            <motion.div className="space-y-1" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
              {tracks.map((track, i) => (
                /* eslint-disable-next-line @typescript-eslint/no-explicit-any -- Profile track may include public-only fields not on base Track type */
                <UnifiedTrackCard key={track.id} variant="compact" track={track as any} index={i} />
              ))}
            </motion.div>
          ) : (
            <EmptyState icon={Music2} text="Нет публичных треков" />
          )}
        </TabsContent>

        {/* Projects Tab */}
        <TabsContent value="projects" className="mt-4">
          {projectsLoading ? (
            <div className="space-y-3">
              {[...Array(3)].map((_, i) => (
                <Skeleton key={i} className="h-20 rounded-xl" />
              ))}
            </div>
          ) : projects?.length ? (
            <div className="space-y-3">
              {projects.map((project) => (
                <motion.div
                  key={project.id}
                  className="p-4 rounded-xl bg-card/50 border border-border/50 hover:border-primary/30 transition-all cursor-pointer"
                  whileTap={{ scale: 0.98 }}
                  onClick={() => navigate(`/project/${project.id}`)}
                >
                  <div className="flex items-start gap-3">
                    {project.cover_url ? (
                      <img
                        loading="lazy"
                        decoding="async"
                        src={project.cover_url}
                        alt={project.title}
                        className="w-16 h-16 rounded-lg object-cover"
                      />
                    ) : (
                      <div className="w-16 h-16 rounded-lg bg-primary/10 flex items-center justify-center">
                        <FolderOpen className="w-6 h-6 text-primary" />
                      </div>
                    )}
                    <div className="flex-1 min-w-0">
                      <h3 className="font-semibold truncate">{project.title}</h3>
                      {project.description && (
                        <p className="text-sm text-muted-foreground mt-0.5 line-clamp-2">{project.description}</p>
                      )}
                      <div className="flex items-center gap-2 mt-2">
                        {project.genre && (
                          <Badge variant="secondary" className="text-xs">
                            {project.genre}
                          </Badge>
                        )}
                        {project.mood && (
                          <Badge variant="outline" className="text-xs">
                            {project.mood}
                          </Badge>
                        )}
                      </div>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>
          ) : (
            <EmptyState icon={FolderOpen} text="Нет публичных проектов" />
          )}
        </TabsContent>

        {/* Artists Tab */}
        <TabsContent value="artists" className="mt-4">
          {artistsLoading ? (
            <div className="grid grid-cols-3 gap-3">
              {[...Array(6)].map((_, i) => (
                <Skeleton key={i} className="aspect-square rounded-xl" />
              ))}
            </div>
          ) : artists?.length ? (
            <div className="grid grid-cols-3 gap-3">
              {artists.map((artist) => (
                <motion.div
                  key={artist.id}
                  className="flex flex-col items-center p-3 rounded-xl bg-card/50 border border-border/50 hover:border-primary/30 transition-all cursor-pointer"
                  whileTap={{ scale: 0.98 }}
                >
                  <Avatar className="w-16 h-16 sm:w-20 sm:h-20">
                    <AvatarImage src={artist.avatar_url || undefined} />
                    <AvatarFallback className="text-lg bg-primary/10">{artist.name[0]}</AvatarFallback>
                  </Avatar>
                  <p className="text-sm font-medium mt-2 text-center line-clamp-1">{artist.name}</p>
                  {artist.genre_tags && artist.genre_tags.length > 0 && (
                    <p className="text-[0.625rem] text-muted-foreground mt-0.5 truncate max-w-full">
                      {artist.genre_tags.slice(0, 2).join(", ")}
                    </p>
                  )}
                </motion.div>
              ))}
            </div>
          ) : (
            <EmptyState icon={Users} text="Нет публичных артистов" />
          )}
        </TabsContent>

        {/* Playlists Tab */}
        <TabsContent value="playlists" className="mt-4">
          {playlistsLoading ? (
            <div className="space-y-3">
              {[...Array(3)].map((_, i) => (
                <Skeleton key={i} className="h-16 rounded-xl" />
              ))}
            </div>
          ) : playlists?.length ? (
            <div className="space-y-3">
              {playlists.map((playlist) => (
                <motion.div
                  key={playlist.id}
                  className="flex items-center gap-3 p-3 rounded-xl bg-card/50 border border-border/50 hover:border-primary/30 transition-all cursor-pointer"
                  whileTap={{ scale: 0.98 }}
                >
                  {playlist.cover_url ? (
                    <img
                      loading="lazy"
                      decoding="async"
                      src={playlist.cover_url}
                      alt={playlist.title}
                      className="w-12 h-12 rounded-lg object-cover"
                    />
                  ) : (
                    <div className="w-12 h-12 rounded-lg bg-primary/10 flex items-center justify-center">
                      <ListMusic className="w-6 h-6 text-primary" />
                    </div>
                  )}
                  <div className="flex-1 min-w-0">
                    <h3 className="font-semibold truncate">{playlist.title}</h3>
                    <p className="text-xs text-muted-foreground">{playlist.track_count || 0} треков</p>
                  </div>
                </motion.div>
              ))}
            </div>
          ) : (
            <EmptyState icon={ListMusic} text="Нет публичных плейлистов" />
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

function StatItem({
  value,
  label,
  icon: Icon,
  color,
}: {
  value: number;
  label: string;
  icon: React.ElementType;
  color?: string;
}) {
  const formatValue = (v: number) => {
    if (v >= 1000000) return `${(v / 1000000).toFixed(1)}M`;
    if (v >= 1000) return `${(v / 1000).toFixed(1)}K`;
    return v.toString();
  };

  return (
    <div className="text-center">
      <div className="flex items-center justify-center gap-1">
        <Icon className={cn("w-4 h-4", color || "text-muted-foreground")} />
        <p className="text-lg font-bold">{formatValue(value)}</p>
      </div>
      <p className="text-xs text-muted-foreground">{label}</p>
    </div>
  );
}

function SocialButton({
  icon: Icon,
  href,
  label,
  className,
}: {
  icon: React.ElementType;
  href: string;
  label: string;
  className?: string;
}) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className={cn(
        "w-9 h-9 rounded-full bg-muted/50 hover:bg-muted flex items-center justify-center transition-colors",
        className,
      )}
      title={label}
    >
      <Icon className="w-4 h-4" />
    </a>
  );
}

function EmptyState({ icon: Icon, text }: { icon: React.ElementType; text: string }) {
  return (
    <div className="py-12 text-center">
      <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-muted/50 flex items-center justify-center">
        <Icon className="w-8 h-8 text-muted-foreground/50" />
      </div>
      <p className="text-sm text-muted-foreground">{text}</p>
    </div>
  );
}

