export default function AdminFeedback() {
  const navigate = useNavigate();
  const isMobile = useIsMobile();
  const { user, loading: authLoading } = useAuth();
  const [feedback, setFeedback] = useState<FeedbackItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedFeedback, setSelectedFeedback] = useState<FeedbackItem | null>(null);
  const [replyText, setReplyText] = useState("");
  const [sending, setSending] = useState(false);
  const [activeTab, setActiveTab] = useState("pending");
  const [isAdmin, setIsAdmin] = useState(false);
  const [detailSheetOpen, setDetailSheetOpen] = useState(false);

  // Define before effects to avoid TDZ / immutability warnings.
  // Kept as plain async functions (not useCallback) because the set-state-in-effect
  // rule would otherwise flag the synchronous setState calls inside them.
  async function checkAdminStatus() {
    if (!user) return;

    const data = await checkAdminRole(user.id);

    if (!data) {
      toast.error("Доступ запрещён");
      navigate("/");
      return;
    }

    setIsAdmin(true);
  }

  async function fetchFeedback() {
    setLoading(true);

    try {
      const data = await fetchUserFeedback({ status: activeTab !== "all" ? activeTab : undefined });

      const userIds = (data?.filter((f) => f.user_id).map((f) => f.user_id) || []).filter(
        (id): id is string => id !== null,
      );

      if (userIds.length > 0) {
        const { data: profiles } = await supabase
          .from("profiles")
          .select("user_id, username, first_name, photo_url")
          .in("user_id", userIds);

        const profileMap = new Map(profiles?.map((p) => [p.user_id, p]) || []);

        const enrichedData =
          data?.map((f) => ({
            ...f,
            profile: f.user_id ? profileMap.get(f.user_id) : undefined,
          })) || [];

        setFeedback(enrichedData);
      } else {
        setFeedback(data || []);
      }
    } catch (error) {
      toast.error("Ошибка загрузки");
      logger.error("Failed to load feedback", error);
    }

    setLoading(false);
  }

  useEffect(() => {
    if (!authLoading && user) {
      // Data-fetching effect: setState is intentional and async (after network calls).
      // eslint-disable-next-line react-hooks/set-state-in-effect
      checkAdminStatus();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user, authLoading]);

  useEffect(() => {
    if (isAdmin) {
      // Data-fetching effect: setState is intentional and async (after network calls).
      // eslint-disable-next-line react-hooks/set-state-in-effect
      fetchFeedback();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isAdmin, activeTab]);

  const handleReply = async () => {
    if (!selectedFeedback || !replyText.trim()) return;

    setSending(true);

    try {
      const { error } = await supabase
        .from("user_feedback")
        .update({
          admin_reply: replyText,
          status: "replied",
          replied_at: new Date().toISOString(),
        })
        .eq("id", selectedFeedback.id);

      if (error) throw error;

      if (selectedFeedback.telegram_id) {
        await supabase.functions.invoke("telegram-bot", {
          body: {
            action: "send_feedback_reply",
            telegram_id: selectedFeedback.telegram_id,
            message: replyText,
            feedback_type: selectedFeedback.type,
          },
        });
      }

      toast.success("Ответ отправлен");
      setReplyText("");
      setSelectedFeedback(null);
      setDetailSheetOpen(false);
      fetchFeedback();
    } catch (error: unknown) {
      logger.error("Failed to send feedback reply", error instanceof Error ? error : new Error(String(error)));
      toast.error("Ошибка отправки");
    } finally {
      setSending(false);
    }
  };

  const handleClose = async (id: string) => {
