// Component
// ---------------------------------------------------------------------------

export default function GenerationMetrics() {
  const [timeRange, setTimeRange] = useState<TimeRange>("7d");
  const { data: metrics, isLoading, refetch, isRefetching } = useGenerationMetrics(timeRange);
  const { data: recentFailures, isLoading: failuresLoading } = useRecentFailedGenerations();

  const summary = metrics?.summary;
  const timeSeries = metrics?.timeSeries || [];
  const errorDistribution = metrics?.errorDistribution || [];
  const modelStats = metrics?.modelStats || [];

  const { recharts, isLoading: rechartsLoading } = useRecharts();
  const chartsReady = !isLoading && !failuresLoading && !rechartsLoading && recharts;

  if (!chartsReady) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-12 w-64" />
        <Skeleton className="h-64" />
      </div>
    );
  }

  const { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, BarChart, Bar, Legend } =
    recharts;

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="min-w-0">
          <h2 className="text-base md:text-xl font-bold flex items-center gap-1.5">
            <BarChart3 className="h-4 w-4 md:h-5 md:w-5 flex-shrink-0" />
            <span className="truncate">Generation Metrics</span>
          </h2>
          <p className="text-[0.625rem] md:text-sm text-muted-foreground">Анализ успешности и ошибок генерации</p>
        </div>
        <div className="flex gap-1.5">
          <Select value={timeRange} onValueChange={(v) => setTimeRange(v as TimeRange)}>
            <SelectTrigger className="w-[100px] md:w-[130px] h-8 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {TIME_RANGES.map((r) => (
                <SelectItem key={r.value} value={r.value} className="text-xs">
                  {r.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button variant="outline" size="sm" className="h-8 w-8 p-0" onClick={() => refetch()}>
            <RefreshCw className={cn("h-3.5 w-3.5", isRefetching && "animate-spin")} />
          </Button>
        </div>
      </div>

      {/* Key Metrics Cards */}
      {isLoading ? (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-2 md:gap-3">
          {[...Array(4)].map((_, i) => (
            <Card key={i}>
              <CardContent className="p-3">
                <Skeleton className="h-14 w-full" />
              </CardContent>
            </Card>
          ))}
        </div>
      ) : (
        <StatGrid columns={4}>
          <StatCard
            title="Генераций"
            value={summary?.totalGenerations?.toLocaleString() || "0"}
            icon={<Activity className="h-4 w-4 text-primary" />}
          />
          <StatCard
            title="Success Rate"
            value={`${(summary?.successRate ?? 0).toFixed(1)}%`}
            icon={<CheckCircle className={cn("h-4 w-4", getSuccessRateColor(summary?.successRate ?? 0))} />}
            variant={
              (summary?.successRate ?? 0) >= 90 ? "success" : (summary?.successRate ?? 0) >= 80 ? "warning" : "error"
            }
          />
          <StatCard
            title="Avg время"
            value={formatDuration(summary?.avgDurationSeconds ?? 0)}
            icon={<Timer className="h-4 w-4 text-purple-500" />}
          />
          <StatCard
            title="Активных"
            value={summary?.activeGenerations ?? 0}
            icon={<Loader2 className="h-4 w-4 text-blue-500" />}
          />
        </StatGrid>
      )}

      {/* Charts Row */}
      <div className="grid gap-3 md:grid-cols-2">
        {/* Success/Failure Over Time */}
        <Card className="md:col-span-2">
          <CardHeader className="pb-2 px-3 pt-3">
            <CardTitle className="text-xs md:text-sm flex items-center gap-1.5">
              <Activity className="h-4 w-4" />
              Генерации по времени
            </CardTitle>
          </CardHeader>
          <CardContent className="px-2 sm:px-4 pb-3">
            {isLoading ? (
              <Skeleton className="h-[200px] w-full" />
            ) : timeSeries.length > 0 ? (
              <ResponsiveContainer width="100%" height={200}>
                <LineChart data={timeSeries}>
                  <XAxis dataKey="label" fontSize={10} tickLine={false} />
                  <YAxis fontSize={10} tickLine={false} width={30} />
                  <Tooltip contentStyle={TOOLTIP_STYLE} />
                  <Legend wrapperStyle={{ fontSize: "11px" }} iconType="circle" iconSize={8} />
                  <Line
                    type="monotone"
                    dataKey="success"
                    stroke={CHART_COLORS.success}
                    strokeWidth={2}
                    dot={false}
                    name="Успешных"
                  />
                  <Line
                    type="monotone"
                    dataKey="failed"
                    stroke={CHART_COLORS.failed}
                    strokeWidth={2}
                    dot={false}
                    name="Ошибок"
                  />
                </LineChart>
              </ResponsiveContainer>
            ) : (
              <p className="text-center text-muted-foreground py-12 text-sm">Нет данных за выбранный период</p>
            )}
          </CardContent>
        </Card>

        {/* Error Distribution */}
        <Card>
          <CardHeader className="pb-2 px-3 pt-3">
            <CardTitle className="text-xs md:text-sm flex items-center gap-1.5">
              <PieChartIcon className="h-4 w-4" />
              Ошибки по категориям
            </CardTitle>
          </CardHeader>
          <CardContent className="px-2 sm:px-4 pb-3">
            {isLoading ? (
              <Skeleton className="h-[200px] w-full" />
            ) : errorDistribution.length > 0 ? (
              <ResponsiveContainer width="100%" height={200}>
                <PieChart>
                  <Pie
                    data={errorDistribution}
                    dataKey="count"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={40}
                    outerRadius={70}
                    paddingAngle={2}
                    label={({ name, percent }) => `${name} ${((percent ?? 0) * 100).toFixed(0)}%`}
                    labelLine={false}
                  >
                    {errorDistribution.map((_, index) => (
                      <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip contentStyle={TOOLTIP_STYLE} />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <p className="text-center text-muted-foreground py-12 text-sm">Нет ошибок</p>
            )}
          </CardContent>
        </Card>

        {/* Generation by Model */}
        <Card>
          <CardHeader className="pb-2 px-3 pt-3">
            <CardTitle className="text-xs md:text-sm flex items-center gap-1.5">
              <BarChart3 className="h-4 w-4" />
              По моделям
            </CardTitle>
          </CardHeader>
          <CardContent className="px-2 sm:px-4 pb-3">
            {isLoading ? (
              <Skeleton className="h-[200px] w-full" />
            ) : modelStats.length > 0 ? (
              <ResponsiveContainer width="100%" height={200}>
                <BarChart data={modelStats}>
                  <XAxis dataKey="model" fontSize={9} tickLine={false} />
                  <YAxis fontSize={10} tickLine={false} width={30} />
                  <Tooltip contentStyle={TOOLTIP_STYLE} />
                  <Legend wrapperStyle={{ fontSize: "11px" }} iconType="circle" iconSize={8} />
                  <Bar
                    dataKey="success"
                    stackId="a"
                    fill={CHART_COLORS.success}
                    name="Успешных"
                    radius={[0, 0, 0, 0]}
                  />
                  <Bar dataKey="failed" stackId="a" fill={CHART_COLORS.failed} name="Ошибок" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <p className="text-center text-muted-foreground py-12 text-sm">Нет данных</p>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Model Success Rate Detail */}
      {!isLoading && modelStats.length > 0 && (
        <Card>
          <CardHeader className="pb-2 px-3 pt-3">
            <CardTitle className="text-xs md:text-sm">Success Rate по моделям</CardTitle>
          </CardHeader>
          <CardContent className="px-3 pb-3">
            <div className="space-y-1.5">
              {modelStats.map((m) => (
                <div key={m.model} className="flex items-center justify-between p-2 rounded-lg bg-muted/50">
                  <div className="flex items-center gap-2 min-w-0">
                    <span className="text-xs font-mono truncate">{m.model}</span>
                    <Badge variant="outline" className="text-[0.625rem] h-5 px-1.5 shrink-0">
                      {m.total}
                    </Badge>
                  </div>
                  <div className="flex items-center gap-2 shrink-0">
                    <div className="w-20 h-1.5 bg-muted rounded-full overflow-hidden">
                      <div
                        className={cn(
                          "h-full rounded-full",
                          m.successRate >= 90 ? "bg-green-500" : m.successRate >= 80 ? "bg-yellow-500" : "bg-red-500",
                        )}
                        style={{ width: `${m.successRate}%` }}
                      />
                    </div>
                    <Badge
                      variant={getSuccessRateVariant(m.successRate)}
                      className="text-[0.625rem] h-5 px-1.5 min-w-[42px] text-center"
                    >
                      {m.successRate.toFixed(0)}%
                    </Badge>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Recent Failed Generations Table */}
      <Card>
        <CardHeader className="pb-2 px-3 pt-3">
          <CardTitle className="text-xs md:text-sm flex items-center gap-1.5">
            <AlertCircle className="h-4 w-4 text-red-500" />
            Последние ошибки генерации
            {recentFailures && (
              <Badge variant="destructive" className="text-[0.625rem] h-5 px-1.5 ml-1">
                {recentFailures.length}
              </Badge>
            )}
          </CardTitle>
        </CardHeader>
        <CardContent className="px-0 pb-3">
          {failuresLoading ? (
            <div className="px-3">
              <Skeleton className="h-[200px] w-full" />
            </div>
          ) : recentFailures && recentFailures.length > 0 ? (
            <ScrollArea className="h-[300px] md:h-[400px]">
              {/* Desktop table header */}
              <div className="hidden md:grid grid-cols-[100px_80px_1fr_1fr_80px_70px] gap-2 px-3 py-1.5 text-[0.625rem] font-medium text-muted-foreground border-b">
                <span>Время</span>
                <span>User</span>
                <span>Промпт</span>
                <span>Ошибка</span>
                <span>Модель</span>
                <span>Длит.</span>
              </div>

              <div className="divide-y">
                {recentFailures.map((failure) => {
                  const duration =
                    failure.completed_at && failure.created_at
                      ? (new Date(failure.completed_at).getTime() - new Date(failure.created_at).getTime()) / 1000
                      : null;

                  return (
                    <div key={failure.id}>
                      {/* Desktop row */}
                      <div className="hidden md:grid grid-cols-[100px_80px_1fr_1fr_80px_70px] gap-2 px-3 py-2 hover:bg-muted/50 items-start">
                        <span className="text-[0.625rem] text-muted-foreground">
                          {format(failure.created_at, "DD.MM HH:mm")}
                        </span>
                        <span className="text-[0.625rem] font-mono truncate">{failure.user_id.slice(0, 8)}</span>
                        <span className="text-[0.625rem] truncate" title={failure.prompt}>
                          {truncatePrompt(failure.prompt, 50)}
                        </span>
                        <span className="text-[0.625rem] text-red-400 truncate" title={failure.error_message || ""}>
                          {failure.error_message ? truncatePrompt(failure.error_message, 50) : "N/A"}
                        </span>
                        <Badge variant="outline" className="text-[0.5625rem] h-4 px-1 w-fit">
                          {failure.model_used || "N/A"}
                        </Badge>
                        <span className="text-[0.625rem] text-muted-foreground">
                          {duration !== null ? formatDuration(duration) : "--"}
                        </span>
                      </div>

                      {/* Mobile card */}
                      <div className="md:hidden p-3 space-y-1">
                        <div className="flex items-center justify-between gap-2">
                          <span className="text-[0.625rem] text-muted-foreground">
                            {formatRelative(failure.created_at)}
                          </span>
                          <Badge variant="outline" className="text-[0.5625rem] h-4 px-1">
                            {failure.model_used || "N/A"}
                          </Badge>
                        </div>
                        <p className="text-xs truncate">{truncatePrompt(failure.prompt, 40)}</p>
                        <p className="text-[0.625rem] text-red-400 line-clamp-2">
                          {failure.error_message || "No error message"}
                        </p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </ScrollArea>
          ) : (
            <p className="text-center text-muted-foreground py-8 text-sm">Нет ошибок генерации</p>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

// ModerationDashboard - Sprint 011 Admin (Enhanced - T099)
import { useState } from "react";
import { useNavigate } from "react-router";
import {
  ArrowLeft,
  Shield,
  AlertTriangle,
  CheckCircle,
  Clock,
  Loader2,
  Search,
  Filter,
  ChevronLeft,
  ChevronRight,
} from "@/lib/icons";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAdminAuth } from "@/hooks/useAdminAuth";
import { toast } from "sonner";
import { motion } from "@/lib/motion";
import { formatDistanceToNow, ru } from "@/lib/date-utils";

type ReportStatus = "pending" | "reviewed" | "resolved" | "dismissed";
type EntityType = "comment" | "track" | "profile" | "all";

const ITEMS_PER_PAGE = 10;

export default function ModerationDashboard() {
  const navigate = useNavigate();
  const { data: adminData, isLoading: isCheckingAdmin } = useAdminAuth();
  const isAdmin = adminData?.isAdmin ?? false;
  const queryClient = useQueryClient();
  const [activeTab, setActiveTab] = useState<ReportStatus>("pending");
  const [entityFilter, setEntityFilter] = useState<EntityType>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedReports, setSelectedReports] = useState<Set<string>>(new Set());
  const [currentPage, setCurrentPage] = useState(1);

  // Fetch reports with pagination and filtering
  const { data: reportsData, isLoading } = useQuery({
    queryKey: ["moderation-reports", activeTab, entityFilter, searchQuery, currentPage],
    queryFn: async () => {
      let query = supabase
        .from("moderation_reports")
        .select(
          "*, reported_user:profiles!moderation_reports_reported_user_id_fkey(display_name, username), reporter:profiles!moderation_reports_reporter_id_fkey(display_name, username)",
          { count: "exact" },
        )
        .eq("status", activeTab);

      // Apply entity type filter
      if (entityFilter !== "all") {
        query = query.eq("entity_type", entityFilter);
      }

      // Apply search filter (search in reason and details)
      if (searchQuery.trim()) {
        query = query.or(`reason.ilike.%${searchQuery}%,details.ilike.%${searchQuery}%`);
      }

      // Apply pagination
      const start = (currentPage - 1) * ITEMS_PER_PAGE;
      const end = start + ITEMS_PER_PAGE - 1;
      query = query.range(start, end);

      query = query.order("created_at", { ascending: false });

      const { data, error, count } = await query;
      if (error) throw error;

      return {
        reports: data || [],
        total: count || 0,
        totalPages: Math.ceil((count || 0) / ITEMS_PER_PAGE),
      };
    },
    enabled: isAdmin,
  });

  const reports = reportsData?.reports || [];
  const totalPages = reportsData?.totalPages || 1;

  const updateStatusMutation = useMutation({
    mutationFn: async ({ reportId, status }: { reportId: string; status: ReportStatus }) => {
      const { error } = await supabase
        .from("moderation_reports")
        .update({
          status,
          reviewed_at: new Date().toISOString(),
        })
        .eq("id", reportId);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["moderation-reports"] });
      toast.success("Статус обновлён");
      setSelectedReports(new Set());
    },
    onError: () => {
      toast.error("Ошибка обновления статуса");
    },
  });

  // Batch update mutation
  const batchUpdateMutation = useMutation({
    mutationFn: async ({ reportIds, status }: { reportIds: string[]; status: ReportStatus }) => {
      const { error } = await supabase
        .from("moderation_reports")
        .update({
          status,
          reviewed_at: new Date().toISOString(),
        })
        .in("id", reportIds);
      if (error) throw error;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["moderation-reports"] });
      toast.success(`Обновлено ${variables.reportIds.length} жалоб`);
      setSelectedReports(new Set());
    },
    onError: () => {
      toast.error("Ошибка пакетного обновления");
    },
  });

  // Toggle report selection
  const toggleReportSelection = (reportId: string) => {
    setSelectedReports((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(reportId)) {
        newSet.delete(reportId);
      } else {
        newSet.add(reportId);
      }
      return newSet;
    });
  };

  // Select all visible reports
  const toggleSelectAll = () => {
    if (selectedReports.size === reports.length) {
      setSelectedReports(new Set());
    } else {
      setSelectedReports(new Set(reports.map((r) => r.id)));
    }
  };

  // Handle batch actions
  const handleBatchAction = (status: ReportStatus) => {
    if (selectedReports.size === 0) {
      toast.error("Выберите жалобы для обновления");
      return;
    }
    batchUpdateMutation.mutate({
      reportIds: Array.from(selectedReports),
      status,
    });
  };

  // Reset filters
  const resetFilters = () => {
    setEntityFilter("all");
    setSearchQuery("");
    setCurrentPage(1);
  };

  if (isCheckingAdmin) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!isAdmin) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Card className="max-w-md">
          <CardContent className="pt-6 text-center">
            <Shield className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
            <h2 className="text-xl font-bold mb-2">Доступ запрещён</h2>
            <p className="text-muted-foreground mb-4">У вас нет прав для просмотра этой страницы</p>
            <Button onClick={() => navigate("/")}>На главную</Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "pending":
        return (
          <Badge variant="outline" className="gap-1">
            <Clock className="w-3 h-3" /> Ожидает
          </Badge>
        );
      case "reviewed":
        return (
          <Badge variant="secondary" className="gap-1">
            <AlertTriangle className="w-3 h-3" /> На проверке
          </Badge>
        );
      case "resolved":
        return (
          <Badge variant="default" className="gap-1 bg-green-600">
            <CheckCircle className="w-3 h-3" /> Решено
          </Badge>
        );
      case "dismissed":
        return (
          <Badge variant="outline" className="gap-1 text-muted-foreground">
            Отклонено
          </Badge>
        );
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  return (
    <div
      className="min-h-screen bg-gradient-to-br from-background via-background to-primary/5 pb-24"
      style={{
        paddingTop:
          "max(calc(var(--tg-content-safe-area-inset-top, 0px) + var(--tg-safe-area-inset-top, 0px) + 0.5rem), calc(env(safe-area-inset-top, 0px) + 0.5rem))",
      }}
    >
      <div className="container max-w-4xl mx-auto px-4 py-4">
        <motion.div
          className="flex items-center gap-3 mb-6"
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <Button variant="ghost" size="icon" onClick={() => navigate("/admin")}>
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold">Модерация</h1>
            <p className="text-sm text-muted-foreground">Управление жалобами и нарушениями</p>
          </div>
        </motion.div>

        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as ReportStatus)}>
          <TabsList className="grid w-full grid-cols-4 mb-6">
            <TabsTrigger value="pending">Ожидает</TabsTrigger>
            <TabsTrigger value="reviewed">На проверке</TabsTrigger>
            <TabsTrigger value="resolved">Решено</TabsTrigger>
            <TabsTrigger value="dismissed">Отклонено</TabsTrigger>
          </TabsList>

          <TabsContent value={activeTab}>
            {/* Filters and Search */}
            <Card className="mb-4">
              <CardContent className="pt-6">
                <div className="flex flex-col md:flex-row gap-4">
                  <div className="flex-1">
                    <div className="relative">
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                      <Input
                        placeholder="Поиск по причине или деталям..."
                        value={searchQuery}
                        onChange={(e) => {
                          setSearchQuery(e.target.value);
                          setCurrentPage(1);
                        }}
                        className="pl-9"
                      />
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <Select
                      value={entityFilter}
                      onValueChange={(v: EntityType) => {
                        setEntityFilter(v);
                        setCurrentPage(1);
                      }}
                    >
                      <SelectTrigger className="w-[180px]">
                        <Filter className="w-4 h-4 mr-2" />
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="all">Все типы</SelectItem>
                        <SelectItem value="comment">Комментарии</SelectItem>
                        <SelectItem value="track">Треки</SelectItem>
                        <SelectItem value="profile">Профили</SelectItem>
                      </SelectContent>
                    </Select>
                    {(entityFilter !== "all" || searchQuery) && (
                      <Button variant="outline" size="sm" onClick={resetFilters}>
                        Сбросить
                      </Button>
                    )}
                  </div>
                </div>

                {/* Batch Actions */}
                {selectedReports.size > 0 && (
                  <motion.div
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mt-4 p-3 bg-primary/10 rounded-lg flex items-center justify-between"
                  >
                    <span className="text-sm font-medium">
                      Выбрано: {selectedReports.size} из {reports.length}
                    </span>
                    <div className="flex gap-2">
                      {activeTab === "pending" && (
                        <>
                          <Button size="sm" variant="outline" onClick={() => handleBatchAction("reviewed")}>
                            Рассмотреть выбранные
                          </Button>
                          <Button size="sm" variant="ghost" onClick={() => handleBatchAction("dismissed")}>
                            Отклонить выбранные
                          </Button>
                        </>
                      )}
                      {activeTab === "reviewed" && (
                        <Button size="sm" onClick={() => handleBatchAction("resolved")}>
                          Пометить решёнными
                        </Button>
                      )}
                    </div>
                  </motion.div>
                )}
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Shield className="w-5 h-5" />
                  Жалобы
                  {reportsData && reportsData.total > 0 && <Badge variant="secondary">{reportsData.total}</Badge>}
                </CardTitle>
                <CardDescription>Список жалоб со статусом "{activeTab}"</CardDescription>
              </CardHeader>
              <CardContent>
                {isLoading ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
                  </div>
                ) : reports?.length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <Shield className="w-12 h-12 mx-auto mb-3 opacity-50" />
                    <p>Нет жалоб с этим статусом</p>
                    {(entityFilter !== "all" || searchQuery) && (
                      <Button variant="link" onClick={resetFilters} className="mt-2">
                        Сбросить фильтры
                      </Button>
                    )}
                  </div>
                ) : (
                  <>
                    {/* Select All Checkbox */}
                    {reports.length > 0 && (
                      <div className="flex items-center gap-2 mb-4 pb-3 border-b">
                        <Checkbox
                          checked={selectedReports.size === reports.length && reports.length > 0}
                          onCheckedChange={toggleSelectAll}
                        />
                        <label className="text-sm text-muted-foreground cursor-pointer" onClick={toggleSelectAll}>
                          Выбрать все на странице
                        </label>
                      </div>
                    )}

                    <div className="space-y-4">
                      {reports?.map((report) => (
                        <motion.div
                          key={report.id}
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          className="p-4 rounded-lg border bg-card"
                        >
                          <div className="flex items-start gap-4">
                            <Checkbox
                              checked={selectedReports.has(report.id)}
                              onCheckedChange={() => toggleReportSelection(report.id)}
                              className="mt-1"
                            />
                            <div className="flex-1">
                              <div className="flex items-center gap-2 mb-2 flex-wrap">
                                {getStatusBadge(report.status)}
                                <Badge variant="outline">{report.entity_type}</Badge>
                                <span className="text-xs text-muted-foreground">
                                  {formatDistanceToNow(new Date(report.created_at), {
                                    addSuffix: true,
                                    locale: ru,
                                  })}
                                </span>
                              </div>
                              <p className="font-medium mb-1">{report.reason}</p>
                              {report.details && <p className="text-sm text-muted-foreground mb-2">{report.details}</p>}
                              {report.reporter && (
                                <p className="text-xs text-muted-foreground">
                                  Жалоба от: @{report.reporter.username || report.reporter.display_name}
                                </p>
                              )}
                            </div>
                            <div className="flex gap-2">
                              {report.status === "pending" && (
                                <>
                                  <Button
                                    size="sm"
                                    variant="outline"
                                    onClick={() =>
                                      updateStatusMutation.mutate({
                                        reportId: report.id,
                                        status: "reviewed",
                                      })
                                    }
                                  >
                                    Рассмотреть
                                  </Button>
                                  <Button
                                    size="sm"
                                    variant="ghost"
                                    onClick={() =>
                                      updateStatusMutation.mutate({
                                        reportId: report.id,
                                        status: "dismissed",
                                      })
                                    }
                                  >
                                    Отклонить
                                  </Button>
                                </>
                              )}
                              {report.status === "reviewed" && (
                                <Button
                                  size="sm"
                                  onClick={() =>
                                    updateStatusMutation.mutate({
                                      reportId: report.id,
                                      status: "resolved",
                                    })
                                  }
                                >
                                  Решено
                                </Button>
                              )}
                            </div>
                          </div>
                        </motion.div>
                      ))}
                    </div>

                    {/* Pagination */}
                    {totalPages > 1 && (
                      <div className="flex items-center justify-between mt-6 pt-4 border-t">
                        <p className="text-sm text-muted-foreground">
                          Страница {currentPage} из {totalPages}
                        </p>
                        <div className="flex gap-2">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                            disabled={currentPage === 1}
                          >
                            <ChevronLeft className="w-4 h-4" />
                          </Button>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                            disabled={currentPage === totalPages}
                          >
                            <ChevronRight className="w-4 h-4" />
                          </Button>
                        </div>
                      </div>
                    )}
                  </>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

/**
 * SunoGenerationStats — admin dashboard visualizing daily Suno generation
 * outcomes (success / failure / rate_limit / insufficient_credits / …) split
 * by day and model, sourced from the `suno_generation_stats_daily` view.
 */
import { useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import {
  ResponsiveContainer,
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  CartesianGrid,
} from "recharts";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { RefreshCw } from "@/lib/icons";
import { Button } from "@/components/ui/button";

type StatsRow = {
  day: string | null;
  outcome: string | null;
  http_status: number | null;
  model_used: string | null;
  event_count: number | null;
  avg_duration_ms: number | null;
  max_retries: number | null;
  fallback_count: number | null;
};

const OUTCOMES = [
  "success",
  "failure",
  "rate_limit",
  "insufficient_credits",
  "validation_error",
  "unauthorized",
  "exception",
] as const;

const OUTCOME_COLORS: Record<string, string> = {
  success: "hsl(142 76% 45%)",
  failure: "hsl(0 84% 60%)",
  rate_limit: "hsl(38 92% 55%)",
  insufficient_credits: "hsl(280 65% 60%)",
  validation_error: "hsl(200 80% 55%)",
  unauthorized: "hsl(340 75% 55%)",
  exception: "hsl(20 90% 55%)",
};

const OUTCOME_LABEL: Record<string, string> = {
  success: "Успех",
  failure: "Ошибка",
  rate_limit: "429",
  insufficient_credits: "402",
  validation_error: "Валидация",
  unauthorized: "Auth",
  exception: "Исключение",
};

const RANGES = [
  { value: "7", label: "7 дней" },
  { value: "14", label: "14 дней" },
  { value: "30", label: "30 дней" },
  { value: "90", label: "90 дней" },
];

function formatDay(iso: string) {
  const d = new Date(iso);
  return `${String(d.getDate()).padStart(2, "0")}.${String(d.getMonth() + 1).padStart(2, "0")}`;
}

export default function SunoGenerationStats() {
  const [days, setDays] = useState<string>("14");
  const [modelFilter, setModelFilter] = useState<string>("all");

  const {
    data: rows,
    isLoading,
    refetch,
    isFetching,
  } = useQuery({
    queryKey: ["suno-generation-stats-daily", days],
    queryFn: async () => {
      const since = new Date();
      since.setDate(since.getDate() - Number(days));
      const { data, error } = await supabase
        .from("suno_generation_stats_daily")
        .select("*")
        .gte("day", since.toISOString())
        .order("day", { ascending: true });
      if (error) throw error;
      return (data ?? []) as StatsRow[];
    },
    staleTime: 60_000,
  });

  const models = useMemo(() => {
    const set = new Set<string>();
    (rows ?? []).forEach((r) => r.model_used && set.add(r.model_used));
    return Array.from(set).sort();
  }, [rows]);

  const filtered = useMemo(
    () => (rows ?? []).filter((r) => modelFilter === "all" || r.model_used === modelFilter),
    [rows, modelFilter],
  );

  // Trend chart: outcome counts per day
  const trend = useMemo(() => {
    const byDay = new Map<string, Record<string, number> & { day: string }>();
    for (const r of filtered) {
      if (!r.day || !r.outcome) continue;
      const key = r.day.slice(0, 10);
      const bucket =
        byDay.get(key) ??
        ({ day: key, ...Object.fromEntries(OUTCOMES.map((o) => [o, 0])) } as never);
      bucket[r.outcome] = (bucket[r.outcome] ?? 0) + Number(r.event_count ?? 0);
      byDay.set(key, bucket);
    }
    return Array.from(byDay.values()).sort((a, b) => a.day.localeCompare(b.day));
  }, [filtered]);

  // Totals + success rate
  const totals = useMemo(() => {
    const acc: Record<string, number> = {};
    let all = 0;
    for (const r of filtered) {
      const key = r.outcome ?? "unknown";
      const n = Number(r.event_count ?? 0);
      acc[key] = (acc[key] ?? 0) + n;
      all += n;
    }
    const successRate = all > 0 ? ((acc.success ?? 0) / all) * 100 : 0;
    return { acc, all, successRate };
  }, [filtered]);

  // Per-model bar chart (success vs failures)
  const perModel = useMemo(() => {
    const byModel = new Map<string, { model: string; success: number; failure: number; rate_limit: number; insufficient_credits: number }>();
    for (const r of filtered) {
      if (!r.model_used) continue;
      const bucket =
        byModel.get(r.model_used) ??
        { model: r.model_used, success: 0, failure: 0, rate_limit: 0, insufficient_credits: 0 };
      const n = Number(r.event_count ?? 0);
      if (r.outcome === "success") bucket.success += n;
      else if (r.outcome === "rate_limit") bucket.rate_limit += n;
      else if (r.outcome === "insufficient_credits") bucket.insufficient_credits += n;
      else bucket.failure += n;
      byModel.set(r.model_used, bucket);
    }
    return Array.from(byModel.values()).sort((a, b) => b.success + b.failure - (a.success + a.failure));
  }, [filtered]);

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-10 w-full" />
        <Skeleton className="h-64 w-full" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="text-xl font-semibold">Suno: генерации</h2>
          <p className="text-sm text-muted-foreground">
            Тренды успехов, ошибок, 429 и 402 по дням и моделям
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Select value={days} onValueChange={setDays}>
            <SelectTrigger className="w-32">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {RANGES.map((r) => (
                <SelectItem key={r.value} value={r.value}>
                  {r.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={modelFilter} onValueChange={setModelFilter}>
            <SelectTrigger className="w-40">
              <SelectValue placeholder="Модель" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Все модели</SelectItem>
              {models.map((m) => (
                <SelectItem key={m} value={m}>
                  {m}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button variant="outline" size="icon" onClick={() => refetch()} disabled={isFetching}>
            <RefreshCw className={isFetching ? "animate-spin" : ""} />
          </Button>
        </div>
      </div>

      {/* KPI cards */}
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm text-muted-foreground">Всего событий</CardTitle>
          </CardHeader>
          <CardContent className="text-2xl font-semibold">{totals.all}</CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm text-muted-foreground">Успех</CardTitle>
          </CardHeader>
          <CardContent className="text-2xl font-semibold text-emerald-500">
            {totals.acc.success ?? 0}
            <div className="text-xs text-muted-foreground">
              {totals.successRate.toFixed(1)}%
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm text-muted-foreground">Ошибки</CardTitle>
          </CardHeader>
          <CardContent className="text-2xl font-semibold text-red-500">
            {(totals.acc.failure ?? 0) + (totals.acc.exception ?? 0)}
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm text-muted-foreground">429 rate limit</CardTitle>
          </CardHeader>
          <CardContent className="text-2xl font-semibold text-amber-500">
            {totals.acc.rate_limit ?? 0}
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm text-muted-foreground">402 credits</CardTitle>
          </CardHeader>
          <CardContent className="text-2xl font-semibold text-fuchsia-500">
            {totals.acc.insufficient_credits ?? 0}
          </CardContent>
        </Card>
      </div>

      {/* Trend by day */}
      <Card>
        <CardHeader>
          <CardTitle>Тренд по дням</CardTitle>
        </CardHeader>
        <CardContent className="h-80">
          {trend.length === 0 ? (
            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
              Нет данных за выбранный период
            </div>
          ) : (
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={trend}>
                <CartesianGrid strokeDasharray="3 3" opacity={0.2} />
                <XAxis dataKey="day" tickFormatter={formatDay} fontSize={12} />
                <YAxis fontSize={12} allowDecimals={false} />
                <Tooltip
                  labelFormatter={(l) => formatDay(String(l))}
                  formatter={(v: unknown, name: unknown) => [v as number, OUTCOME_LABEL[String(name)] ?? String(name)]}
                />
                <Legend formatter={(v) => OUTCOME_LABEL[v] ?? v} />
                {OUTCOMES.map((o) => (
                  <Line
                    key={o}
                    type="monotone"
                    dataKey={o}
                    stroke={OUTCOME_COLORS[o]}
                    strokeWidth={2}
                    dot={false}
                    isAnimationActive={false}
                  />
                ))}
              </LineChart>
            </ResponsiveContainer>
          )}
        </CardContent>
      </Card>

      {/* Per-model breakdown */}
      <Card>
        <CardHeader>
          <CardTitle>По моделям</CardTitle>
        </CardHeader>
        <CardContent className="h-80">
          {perModel.length === 0 ? (
            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
              Нет данных
            </div>
          ) : (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={perModel}>
                <CartesianGrid strokeDasharray="3 3" opacity={0.2} />
                <XAxis dataKey="model" fontSize={12} />
                <YAxis fontSize={12} allowDecimals={false} />
                <Tooltip formatter={(v: unknown, name: unknown) => [v as number, OUTCOME_LABEL[String(name)] ?? String(name)]} />
                <Legend formatter={(v) => OUTCOME_LABEL[v] ?? v} />
                <Bar dataKey="success" stackId="a" fill={OUTCOME_COLORS.success} />
                <Bar dataKey="failure" stackId="a" fill={OUTCOME_COLORS.failure} />
                <Bar dataKey="rate_limit" stackId="a" fill={OUTCOME_COLORS.rate_limit} />
                <Bar dataKey="insufficient_credits" stackId="a" fill={OUTCOME_COLORS.insufficient_credits} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </CardContent>
      </Card>

      {/* Detail table */}
      <Card>
        <CardHeader>
          <CardTitle>Сырые агрегаты</CardTitle>
        </CardHeader>
        <CardContent className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="text-left text-muted-foreground">
              <tr>
                <th className="py-2 pr-4">День</th>
                <th className="py-2 pr-4">Модель</th>
                <th className="py-2 pr-4">Исход</th>
                <th className="py-2 pr-4">HTTP</th>
                <th className="py-2 pr-4">Событий</th>
                <th className="py-2 pr-4">Ср. время (мс)</th>
                <th className="py-2 pr-4">Fallback</th>
              </tr>
            </thead>
            <tbody>
              {filtered.slice(0, 200).map((r, i) => (
                <tr key={i} className="border-t border-border/40">
                  <td className="py-1.5 pr-4">{r.day ? formatDay(r.day) : "—"}</td>
                  <td className="py-1.5 pr-4">{r.model_used ?? "—"}</td>
                  <td className="py-1.5 pr-4">
                    <Badge
                      variant="outline"
                      style={{ borderColor: OUTCOME_COLORS[r.outcome ?? ""] ?? undefined }}
                    >
                      {OUTCOME_LABEL[r.outcome ?? ""] ?? r.outcome}
                    </Badge>
                  </td>
                  <td className="py-1.5 pr-4">{r.http_status ?? "—"}</td>
                  <td className="py-1.5 pr-4">{r.event_count ?? 0}</td>
                  <td className="py-1.5 pr-4">{r.avg_duration_ms ?? "—"}</td>
                  <td className="py-1.5 pr-4">{r.fallback_count ?? 0}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {filtered.length > 200 && (
            <p className="mt-2 text-xs text-muted-foreground">
              Показаны первые 200 строк из {filtered.length}
            </p>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

